\subsection{Weak Sparse Identification of Nonlinear Dynamics (WSINDy)}\label{Sec:WSINDy}

In this section, we extend the WSINDy algorithm to accommodate structured populations. 
This extension is novel as it enables the identification of heterogeneous dynamics and boundary processes directly from the given data. 
In the subsequent section, we introduce a cross-validation procedure designed to leverage the accuracy of the learned boundary processes for hyperparameter tuning.

Let $\textbf{n}:=\{n_{j}\}_{j = 1}^{J}$ denote (after a suitable indexing) a set of possibly noisy observations of the  number density over a disjoint partition $\{\Lambda_j \}_{j = 1}^J \subset \Omega$, i.e., $n_j := \frac{1}{|\Lambda_j|}\int_{\Lambda_j}n(t_j,s) \diff{s}$.
As stated before, we assume the noise-free continuous density $n^\star$ evolves according to a true model of the form \eqref{Eq:GeneralStructured}. 
The WSINDy algorithm utilizes the weak form \eqref{Eq:GeneralWeakForm} to construct a sparse regression problem, selecting the proper model ingredients from a set of given trial functions, known as the ``library''. 
More precisely, we assume the true model ingredients $g^\star$, $f^\star$, and $\beta^\star$ can be represented as a (sparse) linear combination of a given set of trial functions.
The set of these functions is denoted by $\{g_m(s,N) \}_{m=1}^{M^g}$, $\{f_m(s,n,N) \}_{m=1}^{M^f}$, and $\{\beta_m(s,n,N) \}_{m=1}^{M^\beta}$, respectively.
Then, for a given set of test functions $\{ \phi_k\}_{k=1}^K \subset C^p_c((0,T)\times \Omega)$, we construct the linear system 
\begin{equation}\label{Eq:LinSystemPDE}
    \textbf{b}^{\text{pde}} = G^{\text{pde}} \textbf{w} = (G^g | G^f)\left( \frac{\ \textbf{w}^g\ }{\ \textbf{w}^f\ }\right),
\end{equation}
 where the vector $\textbf{b}^{\text{pde}} \in \R^{K \times 1}$  and matrix $G^{\text{pde}} \in \R^{K\times(M^g+M^f)}$ are given by 
\[\textbf{b}_k^{\text{pde}} :=-\langle\p_t \phi_k, n \rangle, \quad G^g_{k,m} := \langle \nabla_s \phi_k, g_m(\cdot,N)n  \rangle ,
\text{ and } G^f_{k,m} := \langle \phi_k, f_m(\cdot,n,N) \rangle.\]

As for the choice of test functions, we opt to make use of piecewise-polynomial test functions of the form $\phi(t,s) = \varphi(t) \prod_{i = 1}^{\diff{}} \psi_i(s_i)$, where
\[ 
\varphi(t) = 
\begin{cases}
    C_t (t - t_1)^p (t_2 - t)^q, &t \in (t_1 , t_2)\\
    0& \text{otherwise}
\end{cases} 
\] 
\text{and}
\[ 
\quad 
\psi_i(s_i) = 
\begin{cases}
    C_{i} (s_i - a_i)^p (s_2 - b_i)^q, & s_i \in (a_1 , b_2)\\
    0& \text{otherwise}
\end{cases}
\]
The constants $C_t$ and the $C_i$ are chosen such that $\|\varphi\|_\infty = \|\psi_i\|_\infty = 1$.
The supports of the test functions are determined from the data in such a way that the intervals $[a_i,b_i]$ or $[t_1,t_2]$ account for a given percentage of the full domain (denoted by $r_s$ and $r_t$, respectively).
For the numerical results to follow, we will set $p = q = 14$ and $r_s = r_t = 0.5$.
These choices were determined through numerical experiments, and properly choosing these parameters from the data is currently a frontier of active research.
We point out that while there exist methods for choosing the support and smoothness of test functions from the given data (such as, e.g., \cite{MessengerBortz2021JComputPhys}), these methods are not tuned for heterogeneous libraries such as those considered here.
Additionally, while this class of test functions is commonly used, we make no claims that it is indeed the best choice. 

As discussed in the previous section, since this choice of test function is compactly supported in $\Omega$, the boundary condition \eqref{Eq:GenStructuredBC1} is absent from the weak form \eqref{Eq:GeneralWeakForm}.
One natural way to account for the boundary is to couple \cref{Eq:GeneralStructured} with the dynamics of the total population $N(t) := \int_{\Omega} n(t,s) \diff{s}$ given by the ordinary differential equation acquired by integrating \cref{Eq:GeneralStructured}:
\begin{equation}\label{Eq:GenTotalPopDE}
    \frac{\diff{}}{\diff{t}}N = \int_{\Omega}\beta^\star[n](s) n(t,s)\diff{s} + \int_{\Omega} f^\star[n](s,n(t,s)) \diff{s},
\end{equation}
with the initial condition $N(0) = \int_\Omega n_0(s) \diff{s}$.
This equation then has the corresponding weak form
\begin{equation}\label{Eq:GenTotalPopWF}
    -\int_0^T \frac{\diff{}}{\diff{t}}\varphi(t) \, N(t) \diff{t} = \langle \varphi , \beta^\star[n] n\rangle + \langle\varphi , f^\star[n](\cdot,n) \rangle,
\end{equation}
for a smooth test function $\varphi$ with compact support in $(0,T)$. 

This allows us to extend or ``stack" the linear system \eqref{Eq:LinSystemPDE} by concatenating it with the linear system
\begin{equation}\label{Eq:LinSystemODE}
    \textbf{b}^{\text{ode}} = \Xi \textbf{v} : = \left(\Xi^f | \Xi^\beta \right) \left( \frac{\ \textbf{w}^f\ }{\ \textbf{w}^\beta\ }\right),
\end{equation}
with $\textbf{b}_k^{\text{ode}} \in \R^{K \times 1}$ and $\Xi \in \R^{K\times (M^f+M^b)}$ given by
\[\textbf{b}_k^{\text{ode}} := -\int_0^T \frac{\diff{}}{\diff{t}} \varphi_k(t) N(t) \diff{t} ,\quad \Xi_{k,m}^f :=   \langle\varphi_k, f_m(\cdot, n,N) \rangle, \quad \text{and} \quad \Xi_{k,m}^\beta := \langle \varphi_k, \beta_m(\cdot,N) n \rangle. \]
We then concatenate the two systems, resulting, finally, in the linear system 
\begin{equation}\label{Eq:FullWFSystem}
    \left(\begin{array}{c}
    \textbf{b}^{\text{pde}} \\
    \hline
     \textbf{b}^{\text{ode}}
\end{array} \right) =:\textbf{b} = G \textbf{w} := \left(\begin{array}{c|c|c}
    G^g & G^f & \textbf{0} \\
    \hline
    \textbf{0} & \Xi^f & \Xi^\beta
\end{array}\right)
\left(\begin{array}{c}
    \textbf{w}^g \\
    \hline
    \textbf{w}^f \\
    \hline
    \textbf{w}^\beta 
\end{array}\right).
\end{equation}

The problem then becomes finding sparse $\textbf{w}  \in \R^{(M^g + M^f+M^\beta) \times 1}$ which minimizes the loss function 
\begin{equation}\label{Eq:WSINDy_LossFunc}
    \mathcal{L}(\textbf{x}; \textbf{b},G, \lambda) := \|\textbf{b} - G \textbf{x}\|_2 + \lambda \|\textbf{x}\|_0, 
\end{equation}
where $\lambda$ is a given sparsity parameter. 
The function $\mathcal{L}$ is minimized using the modified sequential-thresholding least-squares method (MSTLS) provided in \cite{MessengerBortz2021JComputPhys}, which has been successful in a variety of applications of sparse regression techniques.
This method has been studied for differential equation models of various types and contexts, including ordinary differential equations \cite{MessengerBortz2021MultiscaleModelSimul}, partial differential equations \cite{MessengerBortz2021JComputPhys,MinorMessengerDukicEtAl2025arXiv250100738}, and hybrid models with multiple time scales \cite{MessengerDwyerDukic2024JRSocInterface}.

\begin{remark}
When studying population dynamics from an age-structured perspective, it is quite common to know \textit{a priori} the age-time relationship $\alpha$ in \cref{Eq:AgeStructured}.
In that case, one does not need to identify the transport term and can focus all efforts on the identification of the death and birth functions.
One can easily modify the method presented above by simply adding the transport term into the vector $\textbf{b}^{\text{pde}}$ in \cref{Eq:LinSystemPDE}. 
That is, \cref{Eq:LinSystemPDE} would be given by
\[\textbf{b}_k^{\text{pde}} :=-\langle\p_t \phi_k, n \rangle - \langle \nabla_s \phi_k, \alpha n  \rangle
\text{ and } G_{k,m}^{\text{pde}} := \langle \phi_k, f_m(\cdot,n,N) \rangle.\] 
\end{remark}

\subsubsection{Boundary Bagging}
\label{sec:BoundaryBagging}

While sparse regression on system \eqref{Eq:FullWFSystem} often yields accurate identification of PDE terms, in practice, the system tends to be dominated by its PDE component. 
This is due to the significantly greater number of test functions used in the PDE part compared to the ODE part, resulting in many more rows in system \eqref{Eq:LinSystemPDE} than in system \eqref{Eq:LinSystemODE}. 
As a consequence, the PDE residual becomes disproportionately weighted during optimization, causing the method to ``push'' errors into the boundary conditions. 
This typically leads to poor, and generally non-sparse, term selection performance in the boundary equations.

To address this, we introduce a cross-validation procedure for the ODE term selection.
This method is inspired by the library bagging technique used in Ensemble versions of SINDy and WSINDy \cite{FaselKutzBruntonEtAl2022ProcRSocA} (see comments in the discussion in \cref{Sec:Discussion}).
The difference here is in the method of selecting which terms to discard from the boundary process component of the library.
Specifically, we fix the learned source weights $\mathbf{w}^f$ and apply sparse regression to the modified system
\[
\mathbf{b}^{\text{ode}} - \Xi^f \mathbf{w}^f = \Xi^\beta \widehat{\mathbf{w}}^\beta,
\]
solving for $\widehat{\mathbf{w}}^\beta$.
We then compare the supports of the original and cross-validated boundary weights, $\text{supp}(\widehat{\mathbf{w}}^\beta)$ and $\text{supp}(\mathbf{w}^\beta) := \{i \in \{1,2,\dots,M^\beta\} : \textbf{w}^\beta_i \neq 0\}$. 
Often, the ODE-focused component returns a sparser subset of learned boundary terms, which tend to be more accurate representations of the true dynamics when tested against synthetic data. 
The terms that are not common between the methods are then removed from the boundary component of the library before refitting. 
We summarize the method in \cref{alg:WSINDyStructuredPop}.

\begin{algorithm}
\caption{WSINDyStructuredPop}
\label{alg:WSINDyStructuredPop}
\begin{algorithmic}[1] 
\Function{WSINDyStructuredPop}{$n_\text{data}$,$N_\text{data}$, $s$, $t$,$\{\phi_k\}$,$\{g_j,f_j,\beta_j\}$,$\dots$}
    \State Construct $G^g$, $G^f$, $\Xi^f$, $\Xi^\beta$, $\textbf{b}^\text{pde}$, and $\textbf{b}^\text{ode}$ from \cref{Eq:LinSystemPDE} and \cref{Eq:LinSystemODE}
    \State $\textbf{w}^g , \textbf{w}^f,\textbf{w}^\beta \gets $ MSTLS($[G^g,G^f,\Xi^f,\Xi^\beta]$,\textbf{b})
    \State $\widehat{\textbf{w}}^\beta \gets$ MSTLS($\Xi^\beta$, $\textbf{b}^{\text{ode}} - \Xi^f \textbf{w}^f$) 
    \If{supp$(\widehat{\textbf{w}}^\beta) \neq $ supp$({\textbf{w}}^\beta)$ }
    \If{supp$(\widehat{\textbf{w}}^\beta) \bigcap $ supp$({\textbf{w}}^\beta) \neq \emptyset$}
    \State idx $\gets$ supp$(\widehat{\textbf{w}}^\beta) \bigcap $ supp$({\textbf{w}}^\beta)$
    \Else
    \State idx $\gets$ supp$(\widehat{\textbf{w}}^\beta) \bigcup $ supp$({\textbf{w}}^\beta)$
    \EndIf
    \State $\textbf{w}^g , \textbf{w}^f,\textbf{w}^\beta \gets $ MSTLS($[G^g,G^f,\Xi^f,\Xi^\beta(:,\text{idx})]$,\textbf{b})
    \Else 
    \State $\textbf{w}^\beta \gets \arg\min_{\textbf{v} \in \{\textbf{w}^\beta,\widehat{\textbf{w}}^\beta\}} \textbf{R}([\textbf{w}^g;\textbf{w}^f;\textbf{v}])$
    \EndIf
    \State \Return $\textbf{w}^g , \textbf{w}^f,\textbf{w}^\beta$

\EndFunction
\end{algorithmic}
\end{algorithm}


