\includegraphics[width=0.99\textwidth,trim=2.5cm 1.95cm 3.5cm 1.2cm, clip]{Figs/ratio_DM_FLAMINGOHR.png}\\
\includegraphics[width=0.99\textwidth,trim=2.5cm 1.95cm 3.5cm 1.2cm, clip]{Figs/ratio_DM_FLAMINGOJETS.png}\\
