Let $\sigma_1(T)= \sigma_a(T) \setminus \sigma_{uw}(T)$ and $\sigma_2(T)= \sigma(T) \setminus \sigma_a(T)$. The following theorem shows that under certain conditions $T \oplus S$ satisfies property $(UW_E)$ for operators $T$ and $S$.

\begin{theorem}\label{T1}
	Suppose $T  \in B(\mathcal{H})$ has no isolated point in the spectrum and $S \in B(K)$ satisfies property $(UW_E)$. If $\sigma_{uw}(T\oplus S)= \sigma_a(T) \cup \sigma_{uw}(S)$ and $\sigma_2(T)=\emptyset$, then property $(UW_E)$ holds for $T\oplus S$.
\end{theorem}
\begin{proof}
	As 	$\sigma_a(T\oplus S)=\sigma_a(T) \cup \sigma_a(S)$	for any pair of operators $T $ and $S$, we have 
	\begin{equation*}
		\begin{split}
			\sigma_a(T\oplus S)\setminus \sigma_{uw}(T\oplus S) & =[\sigma_a(T) \cup \sigma_a(S)] \setminus[\sigma_a(T) \cup \sigma_{uw}(S)]\\
			& = \sigma_a(S) \setminus [\sigma_a(T)\setminus\sigma_{uw}(S)]\\
			&= [\sigma_a(S) \setminus \sigma_{uw}(S)]\setminus\sigma_a(T)\\
			& = E(S) \cap \rho_a(T).
		\end{split}
	\end{equation*}

	Since	$\text{iso}~ \sigma(T\oplus S)= \rm{iso}~\sigma(S) \cap \rho(T)$,
	\begin{equation*}
		\begin{split}
			E(T \oplus S)&= \text{iso}~  \sigma(T \oplus S) \cap \sigma_p(T \oplus S)\\
			& = [\text{iso}~ \sigma(S) \cap \rho(T)] \cap [\sigma_p(T)\cup \sigma_p(S)]\\
			& = [\text{iso}~ \sigma(S) \cap \rho(T) \cap \sigma_p(T)] \cup [\text{iso}~ \sigma(S) \cap \rho(T) \cap \sigma_p(S)]\\
			& = E(S)\cap \rho(T)\\
			&= E(S)\cap \rho_a(T).
		\end{split}
	\end{equation*}
	Thus, 	$\sigma_a(T \oplus S)\setminus\sigma_{uw}(T \oplus S)= E(T \oplus S)$. Hence $T \oplus S $ satisfies property $(UW_E)$.
	\end{proof}
