\begin{corollary}
	Suppose $T \in B(\mathcal{H})$ is such that $\text{iso}~ \sigma
	(T)= \emptyset$ and  $S \in B(\mathcal{K})$ satisfies property $(UW_E)$ with $E(S)=\sigma_1(T \oplus S)=\sigma_2(T)= \emptyset$. Then $T\oplus S$ satisfies property $(UW_E)$.   
\end{corollary}
\begin{proof}
	Since $S\in(UW_E)$ and $E(S)=\emptyset$, $\sigma_a(S)=\sigma_{uw}(S)$. Since $\sigma_1(T \oplus S)=\emptyset$, it follows that $\sigma_a(T \oplus S)=\sigma_{uw}(T \oplus S)$. Also $\sigma_{uw}(T \oplus S)=\sigma_a(T)\cup\sigma_{uw}(S)=\sigma(T)\cup\sigma_{uw}(S)$. Then from Theorem \ref{T1}, $T\oplus S$ satisfies property $(UW_E)$.
	\end{proof}
\begin{corollary}
Let $T \in B(\mathcal{H})$ and $S \in B(\mathcal{K})$ such that $\text{iso}~ \sigma
(T)\cup\sigma_1(T)= \emptyset$ and  $S$ satisfies property $(UW_E)$. If $\sigma_{uw}(T\oplus S)=\sigma_{uw}(T)\cup\sigma_{uw}(S)$, then $T\oplus S$ satisfies property $(UW_E)$.
\end{corollary}
Tensor product of operators $T \in B(\mathcal{H} )$ and $S \in B(\mathcal{K})$ 
is defined by
\begin{eqnarray*}
	(T \otimes S)\ \Sigma_{i}(x_i \otimes y_i)&=& \Sigma_{i}Tx_i  \otimes Sy_i
\end{eqnarray*}  for each $\Sigma_{i}x_i \otimes y_i \in \mathcal{H} \otimes \mathcal{K}$. Stability of Weyl type theorems and its variations under tensor product has been studied by many authors, for more details see \cite{aponte,dug}.
 The following example shows that if one of the operators satisfies property $(UW_E)$, then $T \otimes S$ may not satisfies property $(UW_E)$.
\begin{example}
	Let $Q \in B(l^2)$ defined by $$Q(x_1,x_2,x_3,...)=(0,\frac{x_1}{2},\frac{x_2}{3},0,0,....),$$ a nilpotent operator  and $T$ be an injective quasi-nilpotent operator. We have $\sigma_{a}(Q)=\sigma_{uw}(Q)=E(Q)=\{0\}$ and $\sigma_{a}(T)=\sigma_{uw}(T)=\{0\}$, $E(T)=\emptyset$. Thus $T\in(UW_E)$, $Q\notin(UW_E)$. Also $\sigma_{a}(T \otimes Q)=\sigma_{a}(T)\sigma_{a}(Q)=\{0\}$. We know that $0\notin \sigma_{a}(T \otimes Q) \setminus \sigma_{uw}(T \otimes Q)$, $0 \in E(T \otimes Q)$. It follows that  $T \otimes Q$ does not satisfies property $(UW_E)$.
\end{example}
The following example shows that even if $T$ and $S$ satisfies property $(UW_E)$, tensor product $T \otimes S$ may not satisfies property $(UW_E)$.
\begin{example}
	Let $Q \in B(l^2)$ be an injective quasi-nilpotent operator and let
	\begin{center} $T=S=(I+Q) \oplus \alpha \oplus \beta$ on $B(l^2) \oplus \mathbb{C} \oplus \mathbb{C},$
			\end{center} where $\alpha \beta=1 \neq \alpha$. This example has been studied in \cite[Example 2]{dug} to show that property $(w)$ does not transfer from $T$ and $S$ to $T \otimes S$. We can see that $ \sigma_a(T)= \sigma_a(S)= \{1,\alpha,\beta\}, \sigma_{uw}(T)= \sigma_{uw}(S)= \{1\}$, $E(T)=\{\alpha,\beta\}=E(S)$, $\sigma_a(T \otimes S)= \{1,\alpha,\beta,\beta^{2},\alpha^{2}\}$, $\sigma_{uw}(T \otimes S)=\{1,\alpha,\beta\}$. Thus $T$ and $S$ satisfies property $(UW_E)$,
	$1 \notin \sigma_{a}(T \otimes S) \setminus \sigma_{uw}(T \otimes S)$ but
	$1 \in E(T \otimes S) $. So, $T \otimes S$ does not satisfies property $(UW_E)$.		
\end{example}
The following theorem shows that for isoloid operators $T$ and $S$ under certain conditions $T \otimes S$ satisfies property $(UW_E)$. This was studied for property $(V_E)$ in \cite{aponte} and for property $(w)$ in \cite{dug}.
\begin{theorem}
	\begin{enumerate}
\item[(i)] 	If $T$ and $S$ satisfies property $(UW_E)$, then $E(T \otimes S) \subseteq \sigma_a(T \otimes S) \setminus \sigma_{uw}(T \otimes S)$.
\item[(ii)] If $T$ and $S$ are isoloid operators and $0 \notin \sigma_p(T \otimes S)$, then $T \otimes S$ satisfies property $(UW_E)$ whenever $\sigma_{uw}(T \otimes S)=\sigma_a(T)\sigma_{uw}(S) \cup \sigma_a(S)\sigma_{uw}(T)$.
\end{enumerate}
\end{theorem}
\begin{proof}
	\begin{enumerate}
	\item[(i)] If $\mu \in E(T \otimes S) \subseteq E(T).E(S)$, then there exists $\lambda$ and $\nu$ in $E(T)$ and $E(S)$ such that $\mu= \lambda \nu$. Then, $\lambda \in \sigma_a(T) \setminus \sigma_{uw}(T)$ and $\nu \in \sigma_a(S) \sigma_{uw}(S)$. Hence $\mu \in \sigma_a(T \otimes S)$. Since $\sigma_{uw}(T \otimes S)=\sigma_a(T)\sigma_{uw}(S) \cup \sigma_a(S)\sigma_{uw}(T)$, $\mu \notin \sigma_{uw}(T \otimes S)$. Therefore,  $E(T \otimes S) \subseteq \sigma_a(T \otimes S) \setminus \sigma_{uw}(T \otimes S)$.\\
	\item[(ii)] Let $\lambda \in \sigma_a(T \otimes S) \setminus \sigma_{uw}(T \otimes S)$. Then $\lambda \neq 0$ and there exists $\mu \in \sigma_a(T) \setminus \sigma_{uw}(T)$ and $\nu \in \sigma_a(S) \setminus \sigma_{uw}(S)$ such that  $\lambda= \nu \mu$. This implies that $ \lambda \in \pi_{00}(T \otimes S) \subseteq E(T\otimes S)$ .
	Thus $ \sigma_a(T \otimes S)= \setminus \sigma_{uw}(T \otimes S) \subseteq E(T \otimes S)$. Hence $T \otimes S$ satisfies property $(UW_E)$.
\end{enumerate}
\end{proof}
\begin{remark}

From Theorem 3.9 and \cite[Thorem 1]{dug}, we see that if 
$T$ and $S$ are isoloid operators satisfying property $(UW_E)$ and $0 \notin \sigma_p(T \otimes S)$. Then $ T \otimes S\in (UW_E)$ is equivalent to $T \otimes S\in (w)$ and  $T \otimes S \in (a-Bt)$ whenever $\sigma_{uw}(T \otimes S)=\sigma_{a}(T )\sigma_{uw}(S )\cup\sigma_{uw}(T)\sigma_{a}(S )$.
\end{remark}
 The commutator of two operators $P$ and $Q$ is defined by $[P,Q]=PQ-QP$. If $Q_1$ and $Q_2$ are two quasi-nilpotent operators such that $[Q_1,A]=[Q_2,A]=0$ for some operators $A \in B(X) $ and $B \in B(Y)$ then, 
\begin{center}
	$(A+Q_1) \otimes (B+Q_2) = A \otimes B +Q$, 
\end{center}

where $Q= Q_1 \otimes B+ A\otimes Q_2+ Q_1 \otimes Q_2\in B(X \otimes Y)$ is a quasi-nilpotent operator. Duggal \cite{dug} studied the stabity of property $(w)$ under Perturbations by Riesz
operators. In \cite{aponte} Aponte, Sanabria, and V´asquez studied it for property $(V_E)$. In a similar manner, we observe that  
	let $Q_1 \in B(\mathcal{H})$ and $Q_2 \in B(\mathcal{K})$ such that $[Q_1,A]=[Q_2,B]=0$ for some operators $A \in B(\mathcal{H})$ and $B \in B(\mathcal{K})$. If $A\otimes B$ is isoloid and satisfies property $(UW_E)$, then $(A+Q_1) \otimes (B+Q_2)$  satisfies property $(UW_E)$. Also if $T,R\in B(\mathcal{H})$ be such that $T$ is isoloid and $R$ is a Riesz operator with $[T,R]=0$, $\sigma_{a}(T+R)=\sigma_{a}(T)$ and $\sigma(T+R)=\sigma(R)$. Then $T$ satisfies property $(UW_E)$ implies $T+R$ satisfies property $(UW_E)$. In addition, if $A$ and $B$ are two isoloid operators satisfying property $(UW_E)$ and $R_1$ and $R_2$ are Riesz operators such that $[A,R_1]=0=[B,R_2]$, $\sigma_a(A+R_1)=\sigma_{a}(A)$ , and $\sigma_{a}(B+R_2)=\sigma_{a}(B)$ and $\sigma(A+R_1)=\sigma(A)$ , and $\sigma(B+R_2)=\sigma(B)$ also $0 \notin \sigma_{p}(A \otimes B)$. Then, $A,B \in (UW_E) \Longrightarrow (A+R_1)\otimes (B+R_2) \in (UW_E)$ if and only if $A,B \in (w) \Longrightarrow (A+R_1)\otimes (B+R_2) \in (w)$.\\

