\subsection{Activity value}

For the rest of the paper, assume that $S$ is a finite subset of $G$ such that $e \in S$. 

\begin{definition}\label{active}
The set of \emph{active transitions} of a local map $\mu : A^S \to A$, with $e \in S$, is defined by 
\[ \mathcal{T} := \{ z \in A^S : \mu(z) \neq z(e) \},  \]
The \emph{activity value} of $\mu : A^S \to A$ is $\alpha(\mu) := \vert \mathcal{T} \vert$. The set of \emph{passive transitions} of $\mu$ is defined by
\[ \mathcal{P} := A^S \setminus \mathcal{T}. \]   
\end{definition}

It is clear that the number of passive transitions $\mathcal{P}$ also determines the activity value of $\mu : A^S \to A$ because
\[ \alpha(\mu) = \vert A^S \setminus \mathcal{P} \vert.  \]

\begin{example}\label{Rule110}
Consider the elementary cellular automaton $\mu : A^{S} \to A$, with $S = \{-1,0,1\}$, given as in Example \ref{Rule110}. We see from the table that defines $\mu$ the set of active transitions is $\mathcal{T} = \{111, 101,001\}$, so $\alpha(\mu) = 3$, and the set of passive transitions is $\mathcal{P} = \{ 110, 100, 011, 010, 000 \}$.
\end{example}

\begin{lemma}
Let $\mu : A^S \to A$ be a local map with active transitions $\mathcal{T}$ and let $\tau : A^G \to A^G$ be the cellular automaton defined by $\mu$. 
\begin{enumerate}
\item $\tau$ is equal to the identity function if and only if $\mathcal{T} = \emptyset$. 
\item The set of fixed points $\Fix(\tau) := \{ x \in A^G : \tau(x) = x \}$ is equal to the subshift $X_\mathcal{T} \subseteq A^G$ with forbidden patterns $\mathcal{T}$, which is defined by
\[ X_\mathcal{T} := \{ x \in A^G : (g \cdot x)\vert_S \notin \mathcal{T}, \forall g \in G \}.   \] 
\end{enumerate}
\end{lemma}
\begin{proof}
Part (1) follows from the definition. For part (2), let $x \in X_{\mathcal{T}}$. Then, $(g \cdot x)\vert_S \not\in \mathcal{T}$, for all $g \in G$, so it follows that $(g \cdot x)\vert_S$ is a passive transition for $\mu$:
\[ \tau(x)(g) = \mu( (g \cdot x) \vert_S) = (g \cdot x)(e) = x(g), \quad \forall g \in G.   \]
Therefore, $x \in \Fix(\tau)$. Conversely, suppose that $x \not \in  X_{\mathcal{T}}$, so there exists $g \in G$ such that $(g \cdot x)\vert_S \in \mathcal{T}$. Then,
\[ \tau(x)(g) = \mu( (g \cdot x) \vert_S)  \neq ( g \cdot x)(e) = x(g).  \]
This shows that $\tau(x) \neq x$, so $x \not \in \Fix(\tau)$.
\end{proof}

