\subsection{Symmetries}\label{sec-sym}

In \cite[Prop. 1]{Pedro1}, it was shown that the activity value preserved under \emph{symmetries} of elementary cellular automata. These so-called \emph{symmetries} are defined by the well-known automorphisms of one-dimensional automata of \emph{reflection} and \emph{complementation} (see \cite{CRG20,Wolfram}). In this section, we present the generalized versions of these symmetries when the universe is an arbitrary group $G$, and we show that both the size of the minimal neighborhood and the the activity value are always preserved under these symmetries. 

For each bijection of the alphabet $f : A \to A$ we may define an invertible cellular automaton $f_* : A^G \to A^G$ by 
 \[ f_*(x) := f \circ x, \quad \forall x \in A^G. \]
 Conjugation by $f_*$ induces an automorphism of the monoid of all cellular automata; explicitly, for any cellular automaton $\tau : A^G \to A^G$ we define a cellular automaton $\tau^f : A^G \to A^G$ by
 \[  \tau^f : = (f_*)^{-1} \circ \tau \circ f_*. \] 
When $A=\{0,1\}$ and $f : A \to A$ is the transposition $f(0)=1$ and $f(1)=0$, the cellular automaton $\tau^f$ is precisely the \emph{complement} of $\tau$. 

For each group automorphism $\phi : G \to G$, we may define a homeomorphism (i.e. continuous bijection with continuous inverse with respect to the prodiscrete topology) $\phi^* : A^G \to A^G$ by
\[ \phi^*(x) := x \circ \phi, \quad \forall x \in A^G. \]
The function $\phi^*$ is not a cellular automaton because it is not $G$-equivariant, but it is a \emph{$\phi$-cellular automaton} as introduced in \cite{GCA}. As shown in \cite[Sec. 4]{GCA}, conjugation by $\phi^*$ induces an automorphism of the monoid of all cellular automata; explicitly, for any cellular automaton $\tau : A^G \to A^G$ we define a cellular automaton $\tau^\phi : A^G \to A^G$ by
 \[  \tau^\phi : = (\phi^*)^{-1} \circ \tau \circ \phi^*. \] 
For the case when $G=\mathbb{Z}$ and $\phi : \mathbb{Z} \to \mathbb{Z}$ is the only non-trivial group automorphism given by $\phi(k) := -k$, for all $k \in \mathbb{Z}$, then the cellular automaton $\tau^\phi$ is known as the \emph{reflection} of $\tau$.  

\begin{lemma}
Let $\tau : A^G \to A^G$ be a cellular automaton, let $f : A \to A$ be a bijection, and let $\phi : G \to G$ be an automorphism. 
\begin{enumerate}
\item If $\mu : A^S \to A$ is a local function that defines $\tau$, then a local function $\mu^f : A^S \to A$ for $\tau^f$ is given by
\[ \mu^f (z) = f^{-1} \circ \mu ( f \circ z), \quad \forall z \in A^S.  \]

\item  If $\mu : A^S \to A$ is a local function that defines $\tau$, then a local function $\mu^\phi : A^{\phi(S)} \to A$ of $\tau^f$ is given by
\[ \mu^\phi (w) = \mu( w \circ \phi \vert_S ), \quad \forall w \in A^{\phi(S)}.  \]
\end{enumerate}
\end{lemma}
\begin{proof}
\begin{enumerate}
\item For all $x \in A^G$ we have
\[ \tau^f(x)(e) = f^{-1} \circ \tau(f \circ x)(e) = f^{-1}(\mu( (f \circ x)\vert_S)).  \]
This shows that the local map $\mu^f : A^S \to A$ defines $\tau^f$. 

\item For all $x \in A^G$ we have
\[ \tau^\phi(x)(e) = \tau(x  \circ \phi) \circ \phi^{-1}(e) = \tau(x \circ \phi)(e) = \mu( (x \circ \phi)\vert_S) =  \mu( x \vert_{\phi(S)} \circ \phi\vert_S ) ,  \]
where we have used the fact that $\phi^{-1}(e)=e$, because $\phi^{-1}$ is an automorphism of $G$. This shows that the local map $\mu^\phi : A^{\phi(S)} \to A$ defines $\tau^f$.
\end{enumerate}
\end{proof}

\begin{proposition}\label{sym-ac}
Let $S$ be a finite subset of $G$ such that $e \in S$. For any local function $\mu : A^S \to A$, any bijection $f : A \to A$ and any automorphism $\phi : G \to G$, we have
\[ \alpha(\mu) = \alpha(\mu^f) = \alpha(\mu^\phi). \]
\end{proposition}
\begin{proof}
Let $\mathcal{P}$, $\mathcal{P}^f$, and $\mathcal{P}^\phi$ be the sets of passive transitions of $\mu$, $\mu^f$, and $\mu^\phi$, respectively. We will show that $f_* : \mathcal{P}^f \to \mathcal{P}^f$ given by $f_*(w) = f \circ w$ for all $w \in \mathcal{P}^f$ is a well-defined bijection. If $w \in \mathcal{P}^f$, then
\[ w(e) =  \mu^f (w) =  f^{-1} \circ \mu ( f \circ w)  \quad \Longrightarrow \quad (f \circ w)(e) = \mu(f \circ w), \] 
which shows that $f \circ w \in \mathcal{P}$. On the other hand, if $z \in \mathcal{P}$, we will show that $f^{-1} \circ z \in \mathcal{P}^f$. Indeed,
\[ \mu^f(f^{-1} \circ z) =  f^{-1} \circ \mu ( f \circ f^{-1} \circ z) = f^{-1} \circ \mu(z) = (f^{-1} \circ z)(e).    \]
This proves that $\vert \mathcal{P} \vert = \vert \mathcal{P}^f \vert$, so $\alpha(\mu) = \alpha(\mu^f)$.  

Now, we will show that $(\phi \vert_S)^* :  \mathcal{P}^\phi \to \mathcal{P}$ given by $(\phi \vert_S)^*(w) = w \circ \phi \vert_S$ for all $w \in A^{\phi(S)}$ is a well-defined bijection. If $w \in \mathcal{P}^\phi$, then
\[  (w \circ \phi \vert_S)(e) =w(e) = \mu^\phi(w) = \mu( w \circ \phi \vert_S ),  \]  
which shows that $w \circ \phi \vert_S \in \mathcal{P}$. On the other hand, we will show that if $z \in \mathcal{P}$, then $z \circ \phi^{-1}\vert_{\phi(S)} \in \mathcal{P}^\phi$. Indeed,
\[ \mu^\phi(z \circ \phi^{-1}\vert_{\phi(S)}) = \mu( z \circ \phi^{-1}\vert_{\phi(S)} \circ \phi \vert_S ) = \mu(z) = z (e) = (z \circ \phi^{-1}\vert_{\phi(S)})(e).    \]
This proves that $\vert \mathcal{P} \vert = \vert \mathcal{P}^\phi \vert$, so $\alpha(\mu) = \alpha(\mu^\phi)$.  
\end{proof}

We finish this section by showing that the size of the minimal neighborhood is also preserved under symmetries. 

\begin{proposition}
For any local function $\mu : A^S \to A$, any bijection $f : A \to A$ and any automorphism $\phi : G \to G$, we have
\[ \MN(\mu) = \MN(\mu^f) \text{ and } \MN(\mu^\phi) = \phi(\MN(\mu)). \]
In particular,
\[ \vert \MN(\mu) \vert = \vert \MN(\mu^f) \vert = \vert \MN(\mu^\phi) \vert.  \]
\end{proposition}
\begin{proof}
Observe first that for any $z,w \in A^S$, we have $\mu(z) = \mu(w)$ if and only if $\mu^f( f^{-1} \circ z) = \mu^f( f^{-1} \circ w)$, and, for any $s \in S$, $[z]_s = [w]_s$ if and only if $[f \circ z]_s = [f \circ w]_s$. This shows that $s \in S$ is essential for $\mu$ if and only if $s$ is essential for $\mu^f$, and the first equality follows. 

For the second equality, note that for any $z,w \in A^S$, we have $\mu(z) = \mu(w)$ if and only if $\mu^\phi( z   \circ \phi^{-1}\vert_{\phi(S)} ) = \mu^\phi( w  \circ \phi^{-1}\vert_{\phi(S)})$, and, for any $s \in S$, $[z]_s = [w]_s$ if and only if $[z  \circ \phi^{-1}\vert_{\phi(S)} ]_{\phi(s)} = [w \circ \phi^{-1}\vert_{\phi(S)}]_{\phi(s)}$. This shows that $s \in S$ is essential for $\mu$ if and only if $\phi(s) \in \phi(S)$ is essential for $\mu^\phi$, and the result follows.   
\end{proof}





