\section{Connecting the minimal neighborhood and the activity value} 

Our first result connects the activity value of a local map $\mu : A^S \to A$ with the activity value of the ``reduced'' local map with respect to the minimal neighborhood of $\mu$. 

\begin{lemma}\label{le-div}
Let $\mu : A^S \to A$ be a local map and let $S_0 := \MN(\mu)$. Let $\mu_0 : A^{S_0} \to A$ be the local map associated to $S_0$ such that $\mu \sim \mu_0$. If $e \in S_0$, then 
\[ \alpha(\mu) = \alpha(\mu_0) \vert A \vert^{|S \setminus S_0|}.  \]
In particular, $ \vert A \vert^{|S \setminus S_0|}$ divides $\alpha(\mu)$. 
\end{lemma}
\begin{proof}
Let $\mathcal{T} \subseteq A^S$ and $\mathcal{T}_0 \subseteq A^{S_0}$ be the sets of active transitions of $\mu$ and $\mu_0$, respectively. Let $f : A^S \to A^{S_0}$ be the restriction function defined by $f(z) := z \vert_{S_0}$, for all $z \in A^S$. This is well-defined because $S_0 \subseteq S$ by Proposition \ref{prop-mn}. Since $\mu \sim \mu_0$, then $f(z) \in \mathcal{T}_0$ if and only if $z \in \mathcal{T}$, so we may consider the restriction $f \vert_{\mathcal{T}} : \mathcal{T} \to \mathcal{T}_0$. Observe that each $w \in \mathcal{T}_0$ has precisely $\vert A \vert^{|S \setminus S_0|}$ preimages under $f \vert_{\mathcal{T}}$. As the preimage sets form a partition of $\mathcal{T}$, we obtain that
\[ \vert \mathcal{T} \vert = \vert \mathcal{T}_0 \vert \vert A \vert^{|S \setminus S_0|}.   \]
The result follows.
\end{proof}

\begin{lemma}\label{le-3}
Let $\mu : A^S \to A$ be a local map with active transitions $\mathcal{T}$ and passive transitions $\mathcal{P}$.
\begin{enumerate}
 \item If there exist $z, w \in \mathcal{P}$, such that $z \neq w$ and $[z]_e = [w]_e$, then $e \in S$ is essential for $\mu$. 
\item For $s \in S \setminus \{e\}$, if there exist $z \in \mathcal{T}$ and $w \in \mathcal{P}$ such that $[z]_s = [w]_s$, then $s$ is essential for $\mu$.
 \end{enumerate}
\end{lemma}
\begin{proof}
For part (1), observe that $z(e) \neq w(e)$ because $z \neq w$ and $[z]_e = [w]_e$. Since $z, w \in \mathcal{P}$, we have
\[ \mu(z) = z(e) \neq w(e) = \mu(w).  \]
It follows that $e$ is essential for $\mu$. 

For point (2), observe that $z(e) = w(e)$ because $[z]_s = [w]_s$ and $s \neq e$. Then,
\[ \mu(z) = z(e) = w(e) \neq \mu(w).   \]
It follows that $s$ is essential for $\mu$.  
\end{proof}

\begin{corollary}\label{cor-1}
Let $\mu : A^S \to A$ be a local map with active transitions $\mathcal{T}$ and passive transitions $\mathcal{P}$.
\begin{enumerate}
\item If $e \in S$ is not essential for $\mu$, then $[z]_e \cap \mathcal{P} = \{ z \}$, for all $z \in \mathcal{P}$.
\item If $s \in S \setminus \{e\}$ is not essential for $\mu$, then $[z]_s \subseteq \mathcal{T}$, for all $z \in \mathcal{T}$.
\end{enumerate}
\end{corollary}
\begin{proof}
This is just the contrapositive of Lemma \ref{le-3}.
\end{proof}



\begin{lemma}\label{le-e}
Let $\mu : A^S \to A$ be a local map with $e \in S$ and with $\vert S \vert \geq 2$. If $e$ is not essential for $\mu$, then 
\[ \alpha(\mu) = \vert A \vert^{\vert S \vert} - \vert A \vert^{\vert S \vert-1}.  \]
\end{lemma}
\begin{proof}
Since $\vert S \vert \geq 2$, we have $A^{S \setminus \{ e\}} \neq \emptyset$. Let $\mathcal{P}$ be the set of passive transitions of $\mu$. We shall prove that the function $\psi : \mathcal{P} \to  A^{S \setminus \{ e\}}$, defined by 
\[ \psi(z) := z \vert_{S \setminus \{e\}}, \quad \forall z \in \mathcal{P}, \]
is a bijection.
\begin{itemize}
\item We will show that $\psi$ is injective. if $\psi(z) = \psi(w)$ for some $z,w \in \mathcal{P}$, then $[z]_e = [w]_e$. If follows by Corollary \ref{cor-1} (1) that
\[  [z]_e \cap \mathcal{P} = \{z\} \quad \text{ and } \quad  [w]_e \cap \mathcal{P} = \{w\} . \]
Therefore, $z=w$. It follows that $\psi$ is injective. 

\item We will show that $\psi$ is surjective. We claim that for every $y \in A^{S \setminus \{e\}}$ there exists $\hat{y} \in \mathcal{P}$ such that $\hat{y}\vert_{S \setminus \{e\}} = y$. First observe that it follows from definition that if $e$ is not essential for $\mu$, then $\mu$ is constant on $[x]_e$ for all $x \in A^S$. Let $w \in A^S$ be any extension of $y$ and suppose that $\mu(w^\prime) = a$ for all $w^\prime \in [w]_e$. Choose $\hat{y} \in [w]_e$ such that $\hat{y}(e) = a$. Then, $\hat{y}$ is a passive transition for $\mu$, so $\hat{y} \in \mathcal{P}$. Clearly, $\hat{y} \vert_{S \setminus \{e\}} = w\vert_{S \setminus \{e\}} = y$, so the function $\psi$ is surjective.      
\end{itemize}     

Since $\psi$ is a bijection, then $\vert \mathcal{P} \vert = \vert A \vert^{\vert S \vert-1}$, which is equivalent to 
\[ \alpha(\mu) = \vert A^S \setminus \mathcal{P} \vert = \vert A \vert^{\vert S \vert} - \vert A \vert^{\vert S \vert-1}. \] 
\end{proof}

\begin{remark}
The case when the activity value is $\alpha(\mu) = \vert A \vert^{\vert S \vert} - \vert A \vert^{\vert S \vert-1}$ seems to be special for other reasons, besides the case when $e$ is not essential for $\mu$. For example, if $A$ is a finite field and $\mu : A^S \to A$ is a local linear map different from the projection to $e$, then we must also have $\alpha(\mu) = \vert A \vert^{\vert S \vert} - \vert A \vert^{\vert S \vert-1}$. This may be been seen as the set of passive transitions $\mathcal{P}$ of $\mu$ is the kernel of the nonzero linear map $\mu - \pi_e$, where $\pi_e : A^S \to A$ is the projection to $e$ defined by $\pi_e(x) = x(e)$, for all $x \in A^G$, so by the Rank-Nullity theorem we deduce that
\[ \dim(\mathcal{P}) = \dim(A^S) - 1 = \vert S \vert - 1.   \]
This shows that $\vert \mathcal{P} \vert = \vert A \vert^{\vert S \vert-1}$, so $\alpha(\mu) = \vert A \vert^{\vert S \vert} - \vert A \vert^{\vert S \vert-1}$.
\end{remark}

\begin{corollary}\label{not-multiple}
Let $\mu : A^S \to A$ be a local map with $\vert S \vert \geq 2$. If $\vert A \vert \nmid \alpha(\mu)$, then $\MN(\mu) =  S$.
\end{corollary}
\begin{proof}
If $e$ is not essential for $\mu$, then Lemma \ref{le-e} shows that $\vert A \vert$ divides $\alpha(\mu)$. Hence, $e$ must be essential for $\mu$. By Lemma \ref{le-div}, $ \vert A \vert^{|S \setminus S_0|}$ divides $\alpha(\mu)$, so we must have $|S \setminus \MN(\mu)|=0$. It follows that $\MN(\mu) =  S$.
\end{proof}

The previous corollary already allows us to improve Algorithm \ref{algo} for $\vert S \vert \geq 2$: we may begin by counting the activity value of $\alpha(\mu)$, and if it is not a multiple of $\vert A \vert$, then $\MN(\mu) =  S$.


For $s \in S$, define the pattern $\delta_s \in A^S$ by $\delta_s(t) = \delta_{s,t}$, for all $t \in S$, where $\delta_{s,t}$ is the Kronecker delta function (i.e. $\delta_s(s)=1$ and $\delta_s(t) = 0$ for all $t \in S \setminus \{s\}$). For $a \in A$, let $a^S \in A^S$ be the constant pattern given by $a^S(s) = a$, for all $s \in S$.

\begin{theorem}\label{th-last}
Let $S \subseteq G$ be a finite subset such that $e \in S$ and $\vert S \vert \geq 2$. For all $0 < k < \vert A \vert^{\vert S \vert}$ there exists a local function $\mu : A^S \to A$ such that
\[ \MN(\mu) = S  \quad \text{ and } \quad \alpha(\mu) = k.  \]
Furthermore, if $\vert A \vert \geq 3$, there exists also a local function $\nu : A^S \to A$ such that
\[ \MN(\nu) = S  \quad \text{ and } \quad  \alpha(\mu) = \vert A \vert^{\vert S \vert}.  \]
\end{theorem}
\begin{proof}
For all the required values of $k$, we will choose a local function $\mu : A^S \to A$ with $k:= \alpha(\mu)$, active transitions $\mathcal{T}$, and passive transitions $\mathcal{P}$, satisfying that $\MN(\mu) = S$  

First assume that $k \neq \vert A \vert^{\vert S \vert}$ and $k \neq \vert A \vert^{\vert S \vert} - \vert A \vert^{\vert S \vert-1}$. By Lemma \ref{le-e}, any choice of $\mu : A^S \to A$ with activity value $k$ satisfies that $e$ is essential for $\mu$. If $k \geq \vert S \vert -1$, we may choose $\mu$ with $\mathcal{T}$ and $\mathcal{P}$ such that 
\[ \{ \delta_s : s \in S \setminus \{e\} \} \subseteq \mathcal{T} \text{ and } 0^S \in \mathcal{P}. \]
By Lemma \ref{le-3} (2), every element of $S \setminus \{e\}$ is essential for $\mu$, so the minimal neighborhood of $\mu$ is $S$.

If $k < \vert S \vert -1$, then
\[ \vert\mathcal{P}\vert = \vert A \vert^{\vert S \vert} - k \geq \vert A \vert^{\vert S \vert } - \vert S \vert +1. \]
In particular, $\vert \mathcal{P} \vert \geq \vert S \vert - 1$, so we may choose $\mu$ with $\mathcal{T}$ and $\mathcal{P}$ such that 
\[ \{ \delta_s : s \in S \setminus \{e\} \} \subseteq \mathcal{P} \text{ and } 0^S \in \mathcal{T}. \]
By Lemma \ref{le-3} (2), every element of $S \setminus \{e\}$ is essential for $\mu$, so the minimal neighborhood of $\mu$ is $S$.

Suppose that $k = \vert A \vert^{\vert S \vert} - \vert A \vert^{\vert S \vert-1}$. Since $\vert S \vert \geq 2$, then $k \geq \vert S \vert - 1$ and $\vert \mathcal{P} \vert = \vert A \vert^{\vert S \vert -1} \geq \vert A \vert \geq 2$. Then, we may choose $\mu$ with $\mathcal{T}$ and $\mathcal{P}$ such that 
\[ \{ \delta_s : s \in S \setminus \{e\} \} \subseteq \mathcal{T} \text{ and } \{ 0^S, \delta_e \} \in \mathcal{P}. \]
By Lemma \ref{le-3} (2), every element of $S \setminus \{e\}$ is essential for $\mu$, any by Lemma \ref{le-3} (1), $e$ is also essential for $\mu$, so $\MN(\mu)=S$.

Finally, assume that $k =  \vert A \vert^{\vert S \vert}$ and $\vert A \vert \geq 3$, so we may suppose that $\{0,1,2 \} \subseteq A$. Choose $\mu : A^S \to A$ such that 
\[ \mu(0^S) = 1, \quad \text{ and } \quad \mu(\delta_s) = 2, \ \forall s \in S. \]
It follows by definition that $\MN(\mu)=S$, and the result follows.
\end{proof}

The following corollary finally explains Figures \ref{fig1} and \ref{fig2}.

\begin{corollary}\label{cor-last}
Let $S \subseteq G$ be a finite subset such that $e \in S$ and $\vert S \vert \geq 2$. For all $0 < r \leq \vert S\vert$ and for all $0 < k < \vert A \vert^{\vert S\vert}$ such that $\vert A \vert^{\vert S \vert - r} \mid k$ there exists a local function $\mu : A^S \to A$ such that
\[ \vert\MN(\mu)\vert = r  \quad \text{ and } \quad \alpha(\mu) = k.  \]
Furthermore, if $\vert A \vert \geq 3$, there exists also a local function $\nu : A^S \to A$ such that
\[ \vert\MN(\nu)\vert = r  \quad \text{ and } \quad  \alpha(\mu) = \vert A \vert^{\vert S \vert}.  \]
\end{corollary}
\begin{proof}
For all $0 < r \leq \vert S\vert$, we may choose a local function $\mu : A^S \to A$ such that $\vert\MN(\mu)\vert = r$ and $e \in S$ (just build a local function with $r$ essential elements from $S$, including $e \in S$). By Lemma \ref{le-div},
\[ \alpha(\mu) = \alpha(\mu_0) \vert A \vert^{|S| - r},  \]
where $\mu_0 : A^{S_0} \to A$ is the reduced local function such that $\mu_0 \sim \mu$ and $S_0 = \MN(\mu)$. The result follows by applying Theorem \ref{th-last} to the local function $\mu_0$. 
\end{proof}



%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\subsection{Binary alphabet}

When $A= \{0,1\}$, the connections between the sizes of minimal neighborhoods and activity values of local functions presents further symmetries. In this case, a local function $\mu : A^S \to A$ is completely defined by its set of active transitions $\mathcal{T}$, because, for all $z \in A^S$, we have
\[ \mu(z) = \begin{cases}
z(e)^c & \text{ if} z \in \mathcal{T} \\
z(e) & \text{ if } z \not\in \mathcal{T} 
\end{cases}\]
where $c$ denotes the complement of the elements in $A=\{0,1\}$.

\begin{lemma}\label{le-4}
Let $A=\{0,1\}$ and let $\mu : A^S \to A$ be a local map with active transitions $\mathcal{T}$ and passive transitions $\mathcal{P}$.
\begin{enumerate}
 \item $e \in S$ is essential for $\mu$ if and only if there exist $z, w \in \mathcal{T}$, or $z,w \in \mathcal{P}$, such that $z \neq w$ and $[z]_e = [w]_e$.  
\item $s \in S \setminus \{e\}$ is essential for $\mu$ if and only if there exist $z \in \mathcal{T}$ and $w \in \mathcal{P}$ such that $[z]_s = [w]_s$.
 \end{enumerate}
\end{lemma}
\begin{proof}
For part (1), suppose that $e$ is essential for $\mu$. By definition, there are $z,w \in A^S$ such that $[z]_e = [w]_e$ and $\mu(z) \neq \mu(w)$. Note that $z(e) \neq w(e)$, as otherwise $z=w$. Since $A=\{0,1\}$, we must have $z(e)^c = w(e)$. If $z \in \mathcal{T}$ and $w \in \mathcal{P}$, then 
\[ \mu(z) = z(e)^c = w(e) = \mu(w),  \]
which is a contradiction. Therefore, either $z, w \in \mathcal{T}$, or $z,w \in \mathcal{P}$. Suppose now that there exist $z, w \in \mathcal{T}$, or $z,w \in \mathcal{P}$, such that $z \neq w$ and $[z]_e = [w]_e$. If $z,w \in \mathcal{P}$, it follows by Lemma \ref{le-3}(2) that $e$ is essential for $\mu$, so assume that $z, w \in \mathcal{T}$. As before, $z(e) \neq w(e)$, so $z(e)^c \neq w(e)^c$. Hence,
\[ \mu(z) = z(e)^c \neq w(e)^c = \mu(w). \]
This shows that $e$ is essential for $\mu$.  

The converse implication of part (2) follows by Lemma \ref{le-3}(2). For the direct implication of part (2), suppose that $[z]_s \subseteq \mathcal{T}$ for all $z \in \mathcal{T}$. Take arbitrary $z_1, z_2 \in A^S$ such that $[z_1]_s = [z_2]_2$. Since $s \neq e$, then $z_1(e) = z_2(e)$. If $z_1 \in \mathcal{T}$, then $z_2 \in \mathcal{T}$ by assumption, so
\[ \mu(z_1) = z_1(e)^c = z_2(e)^c = \mu(z_2), \]
If $z_1 \in \mathcal{P}$, then $z_2 \in \mathcal{P}$ by assumption, so
\[ \mu(z_1) = z_1(e) = z_2(e) = \mu(z_2).  \] 
This shows that $s$ is not essential for $\mu$. 
\end{proof}

The following proposition explains some further symmetries that appear in the case of a binary alphabet.  

\begin{proposition}\label{le-complement}
Let $A=\{0,1\}$ and let $\mu : A^S \to A$ be a local map with active transitions $\mathcal{T}$. Denote by $\mu^\prime : A^S \to A$ the local map with active transitions $A^S \setminus \mathcal{T}$. Then, 
\[ \MN(\mu) = \MN(\mu^\prime). \] 
\end{proposition}
\begin{proof}
By Lemma \ref{le-4} (1), $e$ is essential for $\mu$ if and only if there are $z, w \in \mathcal{T}$, or $z,w \in A^S \setminus \mathcal{T}$, such that $z \neq w$ and $[z]_e = [w]_e$; but again by Lemma \ref{le-4} (1), this holds if and only if $e$ is essential for $\mu^\prime$

By Lemma \ref{le-4} (2), $s \in S \setminus \{e\}$ is essential for $\mu$ if and only if there are $z \in \mathcal{T}$ and $w \in A^S \setminus \mathcal{T}$ such that $[z]_s = [w]_s$; but again by Lemma \ref{le-4} (2), this holds if and only if $s$ is essential for $\mu^\prime$.
\end{proof}

\begin{remark}
The local map $\mu^\prime : A^S \to A$ defined in Proposition \ref{le-complement} is different from the complement $\mu^c : A^S \to A$ defined in Section \ref{sec-sym}. Recall that by Proposition \ref{sym-ac}, $\alpha(\mu)=\alpha(\mu^c)$, but clearly 
\[ \alpha(\mu^\prime) = 2^{|S|} - \alpha(\mu). \]
\end{remark}


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Future work}

In this article, for a finite subset $S \subseteq G$ with $e \in S$, we considered the activity value of a local function $\mu : A^S \to A$ as the number of patterns $z \in A^S$ such that $\mu(z) \neq z(e)$. Since a cellular automaton $\tau : A^G \to A^G$ may be defined by many local functions, it is natural to define the \emph{activity value of $\tau$} by $\alpha(\tau) := \alpha(\mu_0)$, where $\mu_0 : A^{S_0} \to A$ is the local function associated with the minimal neighborhood $S_0 := \MN(\tau)$. However, note that this definition is only possible when $e \in \MN(\tau)$. The following is a list of problems that may be interesting for future work. 

\begin{enumerate}
\item Let $\tau, \sigma : A^G \to A^G$ be two cellular automata such that $e \in \MN(\tau)$ and $e \in \MN(\sigma)$. When does it hold that $e \in \MN(\tau \circ \sigma)$? In case that $e \in \MN(\tau \circ \sigma)$, is there any relation between $\alpha(\tau \circ \sigma)$, $\alpha(\tau)$ and $\alpha(\sigma)$? 

\item Let $\tau : A^G \to A^G$ be an invertible cellular automaton such that $e \in \MN(\tau)$. When does it hold that $e \in \MN(\tau^{-1})$? In case that $e \in \MN(\tau^{-1})$, is there any relation between $\alpha(\tau^{-1})$ and $\alpha(\tau)$? 

\item Count the exact number of local functions with a given activity value and size of minimal neighborhood. 

\item Generalize the definition of activity value as follows: \emph{activity value at $s \in S$} of a local function $\mu : A^S \to A$ is the number of patterns $z \in A^S$ such that $\mu(z) \neq z(s)$. 
\end{enumerate}

