\section{Extending 2HDM Results to the NMSSM}
\label{sec:THDMformulae}
Ref.~\cite{Altmannshofer:2020shb} provides a comprehensive two-loop calculation of the electron EDM and achieves a fully gauge-invariant result in the 2HDM. In what follows, we adapt those findings into the conventional SUSY notation. First, we define the neutral Higgs couplings to quarks and charged leptons as
\begin{equation}
\label{eq:YukawaCoupling}
    \mathcal{L}_{H_i\bar{f}f} = -\frac{m_f}{v}\sum_i H_i \bar{f}\left(g^S_{H_i\bar{f}f} + i g^P_{H_i\bar{f}f} \gamma_5\right)
\end{equation}
where $v =\sqrt{v_u^2 + v_d^2}$. The following 
couplings of neutral Higgs bosons to charged Higgs bosons and gauge bosons 
are also relevant:
\begin{equation}
\label{eq:HiggsGaugeChargedH}
    \mathcal{L} \supset \sum_i 2\frac{m_W^2}{v} a_i W_\mu^+ W^{-\mu} H_i + \frac{m_Z^2}{v} a_i Z_\mu Z^{\mu} H_i - v\lambda_i H_i^0 H^+ H^-
\end{equation}
Let the neutral scalar fields be rotated into the mass-eigenstate basis via $(h_d, h_u, h_s, a, a_s)_i ={O}_{ij}H_j^0$ where $a$ stands for the CP-odd Higgs field. At tree level, the couplings appearing in Eqs.~\eqref{eq:YukawaCoupling} and~\eqref{eq:HiggsGaugeChargedH} can be expressed as,
\begin{equation}
    \begin{aligned}
        &(g^S, g^P) = \left\{\begin{aligned}
            &({O}_{1i}/\cos\beta, -{O}_{4i}\tan\beta), ~~ f = l,d\\
            &({O}_{2i}/\sin\beta, -{O}_{4i}\cot\beta), ~~ f = u
        \end{aligned}\right. \\
        &a_i = O_{1i}\cos\beta + O_{2i}\sin\beta \\
        &\lambda_i = O_{1i}g_{h_d H^+ H^-} + O_{2i}g_{h_u H^+ H^-} \\
        &~~~~~~~~~~~~+ O_{3i}g_{h_s H^+ H^-} + O_{5i}g_{a_s H^+ H^-}
    \end{aligned}
\end{equation}
with 
\begin{equation}
    \begin{aligned}
       & g_{h_d H^+ H^-}= \frac{1}{4} \left(g^2-{g^\prime}^2\right) \cos\beta^3 +\frac{1}{2} g^2\cos\beta \sin\beta^2
       \\
       &~~~~~~~~~~~~~~+\frac{1}{4} \left(g^2+{g^\prime}^2\right) \cos\beta \sin\beta^2-|\lambda|^2\cos\beta
        \sin\beta^2 \\
       &g_{h_u H^+ H^-}=  \frac{1}{4} \left(g^2-{g^\prime}^2\right)\sin\beta^3 +\frac{1}{2} 
       g^2 \sin\beta\cos\beta^2\\
       &~~~~~~~~~~~~~~ +\frac{1}{4}\left(g^2+{g^\prime}^2\right) \sin\beta\cos\beta^2 - |\lambda|^2 \sin\beta\cos\beta^2\\
       &vg_{h_s H^+ H^-} = \sqrt{2} |\lambda A_{\lambda}| \cos\beta  \sin\beta \cos \phi_4 \\
       &~~~~~~~~~~~~~~~~+\sqrt{2} |\lambda\beta| 
       \cos\beta \sin\beta \cos\phi_5 \\
       &~~~~~~~~~~~~~~~~+ 2  v_s | \lambda\kappa|
       \sin\beta \cos\beta\cos\phi_3+|\lambda|^2 v_s\\
       &vg_{a_s H^+ H^-} = -\sqrt{2} |\lambda A_{\lambda}| \cos\beta\sin\beta \sin\phi_4 \\
       &~~~~~~~~~~~~~~~~~+ \sqrt{2} |\lambda \beta|
       \cos\beta \sin\beta \sin\phi_5\\
       &~~~~~~~~~~~~~~~~~+2 v_s |\lambda\kappa |
       \sin\beta\cos\beta  \sin \phi_3
    \end{aligned}
\end{equation}
Then, by making the following substitutions in the results of Ref.~\cite{Altmannshofer:2020shb} for the charged Higgs loop \((d_f^E)^{H^\pm}\), the \(W\)-boson loop \((d_f^E)^{W^\pm}\), and the Kite diagram \((d_f^E)^{\text{Kite}}\), one can directly adapt the 2HDM expressions to the NMSSM framework:
\begin{equation}
    q_{i1} \rightarrow a_i, \qquad c_f \text{Im}(q_{i2}) \rightarrow g^P_{H_i \bar{f}\bar{f}}, \qquad \lambda_{iH^+H^-} \rightarrow \lambda_i
\end{equation}

