\section{Preliminaries}
In this section, we introduce the necessary concepts and definitions that are essential for this article. We collect some spectral properties of the fractional Laplacian on $\mathbb{N}$ proved in \cite{GKS25} and recall standard tools from criticality theory of graph Laplacian \cite{KPP17}. Throughout the article, we use the following notation and convention.
\begin{itemize}
    \item \textit{Kronecker delta function} $\delta_{n,m}=1$ if $n=m$ and $\delta_{n,m}=0$ otherwise.
    \item \textit{Chebyshev polynomials} of second kind $U_n(x)$ with $n\in \mathbb{N}$ and $x\in[-1,1]$.
    \item \textit{Gamma function} $\Gamma(x)=\int_0^\infty t^{x-1}e^{-t}dt$.
    \item \textit{Binomial coefficients} $\left(\begin{matrix} a \\ b \end{matrix} \right)=\frac{\Gamma(a+1)}{\Gamma(b+1)\Gamma(a-b+1)} $ with $a,b\in\mathbb{R}$.
    \item \textit{Pochhammer symbol} $(\beta)_k:=\beta(\beta+1)\ldots(\beta+k-1)$ with $\beta \in \mathbb{R}$.
    \item Since we can regard functions over $\mathbb{N}$ as sequences, we will use the notation $f(n)=f_n$ indistinctively to denote the value of $f$ at $n\in\mathbb{N}$.
    \item For positive functions $f$ and $g$ on $\mathbb{N}$, we denote $f\asymp g$ if there exists $C>0$ such that $C^{-1}f(n)\leq g(n)\leq Cf(n)$ for all $n \in \mathbb{N}$.
    \item For functions $f$ and $g$ we denote $f\lesssim g $ if there exists a universal constant $C>0$ such that $f\leq Cg$.
    \item For a potential $ W: \mathbb{N} \to \mathbb{R} $, $\langle \cdot,\cdot \rangle_{\ell^2(\mathbb{N},W)}$ denotes the weighted $\ell^2$-inner product on $\mathbb{N}$ with respect to the weight $W$, i.e., $\langle \phi, \psi\rangle_{\ell^2(\mathbb{N},W)}= \sum_{\mathbb{N}} \phi(n) \psi(n) W(n)$. For $W\equiv 1$, we simply write $\ell^2(\mathbb{N})$ instead of $\ell^2(\mathbb{N},W)$.
\end{itemize}

\subsection{The fractional Laplacian on half-line.} \label{Sec:graph_Lap}
%references for Chebyshev polynomials and properties

We are going to take advantage of the fact that for a certain range of exponents $\sigma$ the fractional Laplacian $(-\Delta_{\mathbb{N}})^{\sigma}$ on $\mathbb{N}$ can be written as the Laplacian associated with a graph. This will enable us to use the theory of criticality of Schr\"odinger operators on graphs developed in \cite{KPP17}. {\it Graph Laplacian} operators are defined as follows (cf. \cite[Chapter 1.1]{KLW21}).

\begin{definition}[Graph Laplacian]\label{Def:graph-laplacian}
    Let $\{X,b,q\}$ be a graph with $X$ a countable set, $b: X\times X\rightarrow \left[0,\infty\right)$ satisfying
    \begin{itemize}
        \item $b_{n,m}=b_{m,n}$ for all $n,m\in X$.
        \item $b_{n,n}=0$ for all $n\in X$.
        \item $\sum_{n\in X} b_{n,m}<\infty$ for all $m\in X$.
    \end{itemize}
    and  $q: X\rightarrow \left[0,\infty\right)$.
    The {\it graph Laplacian} $\mathcal{L}_{X}$ associated with $\{X,b,q\}$ acting on 
    \begin{equation*}
        \mathcal{F}_{X}=\{f\in C(X)\,|\, \sum_{m\in X}b_{n,m}|f(n)|<\infty\,, \forall\  n\in X\}
    \end{equation*}
    is the operator
    \begin{equation}
        (\mathcal{L}_{X}f)(n):=\sum_{m\in X}b_{n,m}(f(n)-f(m))\,+\,q(n)f(n)\,.
    \end{equation}
\end{definition}
See \cite{KLW21} for general properties of the graph Laplacian and discrete Schr\"odinger operators. The Laplace operator on the discrete half-line $\mathbb{N}:=\{1,2,3,\ldots\}$ is defined as 
\begin{equation}\label{Discrete-Laplacian}
    (-\Delta_\mathbb{N})f(n):=-f(n-1)+2f(n)-f(n+1)
\end{equation}
where $f:\mathbb{N}\rightarrow\mathbb{R}$ with the convention that $f(0)=0$.
Note that (\ref{Discrete-Laplacian}) together with the boundary condition can be written as a graph Laplacian over $X=\mathbb{N}$ 
\begin{equation}
     (-\Delta_{\mathbb{N}})f(n)=\sum_{m\in\mathbb{N}}b_{n,m}\big(f(n)-f(m)\big)\,+\, q_nf(n)
\end{equation}
with $b_{n,m}=1$ if $|n-m|=1$ and $b_{n,m}=0$ otherwise, and $q_n=\delta_{1,n}$. This graph is locally finite, i.e., for any fixed $n\in \mathbb{N}$, $b_{n,m}\neq0$ only for finitely many $m\in \mathbb{N}$.

Since $-\Delta_\mathbb{N}$ is a bounded self-adjoint operator on $\ell^2(\mathbb{N})$ with the spectrum $\sigma(-\Delta_\mathbb{N})=[0,4]$, we can define the positive fractional powers of $-\Delta_\mathbb{N}$ using its spectral representation, following the strategy described in \cite[Section 2.1]{GKS25}. Such a spectral representation is given in terms of Chebyshev polynomials of second kind $\{U_n\}_{\mathbb{N}\cup \{0\}}$, see for example \cite[Chapter 22]{AS} and \cite[Chapter 2]{Sze67} for the definition and properties of these polynomials. Observe that Chebyshev polynomials fulfill the recurrence relation
\begin{equation}
    \label{chev}
    U_{n+1}(x)-2xU_n(x)+U_{n-1}(x)=0
\end{equation}
with $U_0(x):=1$ and $U_1(x):=2x$. It is known that the set of normalized Chebyshev polynomials $\big\{\sqrt{\frac{2}{\pi}}U_n\ | \ n  \in \mathbb{N}\cup \{0\}\big\}$ constitutes an orthonormal basis of the Hilbert space $L^2((-1,1),\sqrt{1-x^2}\ \mathrm{d} x)$. Therefore we can define a map $\mathcal{U}$ such that
\begin{equation} \label{eq:def_U}
    \mathcal{U} e_n:=\sqrt{\frac{2}{\pi}}U_{n-1}
\end{equation}
with $e_n(m)=\delta_{n,m}$, and $\mathcal{U}:\ell^2(\mathbb{N})\rightarrow L^2((-1,1),\sqrt{1-x^2}\ \mathrm{d} x)$ extends to a unitary operator. We point out that in the context of \cite{CR18}, $\mathcal{U}$ will play the role of a Fourier transform.
%and this is the Fourier transform in this setting
Using (\ref{chev}) we get
\begin{equation}\label{spec}
    -\Delta_\mathbb{N}=\mathcal{U}^{-1}M_{2(1-x)}\mathcal{U}
\end{equation}
on $\ell^2(\mathbb{N})$ with $M_{2(1-x)}$ being the multiplication operator on $L^2((-1,1),\sqrt{1-x^2}\ \mathrm{d} x)$ by the function $x \mapsto 2(1-x)$. From (\ref{spec}), we get a spectral definition (cf. \cite[Definition A.21]{KLW21}) of the fractional Laplacian on $\mathbb{N}$ as follows
\begin{align} \label{eq:def_frac}
    (-\Delta_\mathbb{N})^\sigma=\mathcal{U}^{-1}M_{2^\sigma(1-x)^\sigma}\mathcal{U} \,,
\end{align}
for $\sigma >0$. 

In order to write $ (-\Delta_{\mathbb{N}})^\sigma$ as a graph Laplacian, we start from the explicit matrix elements obtained in \cite[Proposition 2.1]{GKS25}:
\begin{equation} \label{Eq:1}
    (-\Delta_{\mathbb{N}})^\sigma f(n) =\sum_{m \in \mathbb{N}} \mathcal{K}^\sigma_{m,n}f(m)  \,,
\end{equation}
where
\begin{align}\label{matrix-element}
\mathcal{K}^\sigma_{m,n}  &= \frac{2^{\sigma+1}}{\pi} \int_{-1}^1 (1 -x)^{\sigma}U_{m-1}U_{n-1} \sqrt{1-x^2} \ dx \nonumber \\
&=  
    (-1)^{m+n} \left[\left(\begin{matrix}
 2\sigma\\
\sigma+m-n
\end{matrix} 	
 \right)-\left(\begin{matrix}
 2\sigma\\
\sigma+m+n
\end{matrix} 	
 \right)\right].
\end{align}
Notice that $\mathcal{K}^\sigma_{m,n}=\mathcal{K}^\sigma_{n,m}$. Define $\widetilde{\mathcal{K}}^\sigma_{m,n}={\mathcal{K}}^\sigma_{m,n}$ if $m \neq n$ and $0$ otherwise.
%Why do you have to put the convention 0 if m=n?
Now we rewrite $ (-\Delta_{\mathbb{N}})^\sigma $ as follows
\begin{equation} \label{Eq:graph_Lap}
    (-\Delta_{\mathbb{N}})^\sigma f(n) =-\sum_{m \in \mathbb{N}} \widetilde{\mathcal{K}}^\sigma_{m,n}(f(n) -f(m) )+f(n) \sum_{m \in \mathbb{N}} \mathcal{K}^\sigma_{m,n} \,.
\end{equation}
If $-\widetilde{\mathcal{K}}^\sigma_{m,n}\geq 0$, this expression can be seen as the graph Laplacian of the graph $ \{\mathbb{N,}-\widetilde{\mathcal{K}}^\sigma,  R^\sigma\}$, with a potential term $$ R^\sigma_n :=\sum_{m \in \mathbb{N}} \mathcal{K}^\sigma_{m,n} \,.$$
Next proposition shows that this is possible when $\sigma \in (0,1]$. 

\begin{proposition} \label{Prop:graphLap}
   Let $\sigma \in (0,1]$. Then $\mathcal{K}^{\sigma}_{m,n} \leq 0$ for all $m\neq n$ \,. In particular,  $ \{\mathbb{N,}-\widetilde{\mathcal{K}}^\sigma,  R^\sigma\}$ is a graph Laplacian.
\end{proposition}
\begin{proof}
If $\sigma =1$, the conclusion follows easily from  \eqref{matrix-element}. Now, consider $\sigma \in (0,1)$.   First notice that, by \eqref{matrix-element} and \cite[Proposition 1]{LR18},
\begin{align*}
        \mathcal{K}^\sigma_{m,n}&=(-1)\left(\frac{(-1)^{m-n+1}\Gamma(2\sigma+1)}{\Gamma(\sigma+m-n+1)\Gamma(\sigma-m+n+1)}-\frac{(-1)^{m+n+1}\Gamma(2\sigma+1)}{\Gamma(\sigma+m+n+1)\Gamma(\sigma-m-n+1)}\right)\\
        &=c_\sigma\left(\frac{\Gamma(m+n-\sigma)}{\Gamma(m+n+\sigma+1)}-\frac{\Gamma(m-n-\sigma)}{\Gamma(m-n+\sigma+1)}\right)=c_\sigma(G(m+n)-G(m-n))
    \end{align*}
    with $c_\sigma$ a constant dependent on $\sigma$ and $G(x)=\frac{\Gamma(x-\sigma)}{\Gamma(x+\sigma+1)}$. Since $ \mathcal{K}^\sigma_{m,n}$ is a symmetric matrix, we assume, without loss of generality, that $m > n$. We now check that $G(x)$ is a decreasing function:
    \begin{align*}
        G'(x)&=\frac{\Gamma(x-\sigma)\psi^{(0)}(x-\sigma)\Gamma(x+\sigma+1)-\Gamma(x-\sigma)\psi^{(0)}(x+\sigma+1)\Gamma(x+\sigma+1)}{\Gamma(x+\sigma+1)^2}\\
        &=\frac{\Gamma(x-\sigma)\Gamma(x+\sigma+1)}{\Gamma(x+\sigma+1)^2}(\psi^{(0)}(x-\sigma)-\psi^{(0)}(x+\sigma+1))
    \end{align*}
    with $\psi^{(0)}(x)$ being the digamma function (see \cite[Chapter 6.3]{AS}). Since $\psi^{(0)}(x)$ is an increasing function for $x>0$ and $\sigma \in (0,1)$, it follows that $G'(x)<0$ for all $x \geq 1$. 
    The explicit form of $c_\sigma$ is
    \begin{equation*}
        c_\sigma=\frac{(-1)\Gamma(\sigma + 1/2)\Gamma(\sigma + 1)4^\sigma \sin(\pi(1+\sigma))}{\sqrt{\pi}\pi}= \frac{(-1)\Gamma(\sigma + 1/2)4^\sigma}{\sqrt{\pi}\Gamma(-\sigma)}>0,
    \end{equation*}
    as $\sigma \in (0,1)$. Hence, $\mathcal{K}^{\sigma}_{m,n} \leq 0$ for all $m\neq n$ \,.

 Now, we compute the potential term \begin{align}\label{Graph-potential}
\begin{split}
     R^\sigma_n&:=\sum_{m \in \mathbb{N}} \mathcal{K}^\sigma_{m,n}=\sum_{m \in \mathbb{N}}(-1)^{m+n} \left[\left(\begin{matrix}
 2\sigma\\
\sigma+m-n
\end{matrix} 	
 \right)-\left(\begin{matrix}
 2\sigma\\
\sigma+m+n
\end{matrix} 	
 \right)\right] \\ &=\sum_{m=-n+1}^\infty (-1)^{m} \left(\begin{matrix}
 2\sigma\\
\sigma+m
\end{matrix} 	
 \right) - \sum_{m=n+1}^\infty (-1)^{m} \left(\begin{matrix}
 2\sigma\\
\sigma+m
\end{matrix} 	
 \right)=\sum_{m=-n+1}^{n} (-1)^{m} \left(\begin{matrix}
 2\sigma\\
\sigma+m
\end{matrix} 	
 \right)\\ &=-2 (-1)^n n \frac{\Gamma(2\sigma)}{\Gamma(1+\sigma-n)\Gamma(1+\sigma+n)}=\frac{2}{\pi}\frac{\Gamma(2\sigma)\Gamma(n-\sigma)}{\Gamma(1+\sigma+n)}n\sin(\pi\sigma),
 %\\ = 2n\frac{\Gamma(2\sigma)}{|\Gamma(1+\sigma-n)|\Gamma(1+\sigma+n)} \overset{n\rightarrow \infty}{\rightarrow} \frac{n}{\pi}\frac{\Gamma(2\sigma)}{|\sqrt{\sigma-n}(\frac{\sigma-n}{e})^{\sigma-n}|\sqrt{\sigma+n}(\frac{\sigma+n}{e})^{\sigma+n}}\\ \rightsquigarrow  \frac{n}{\pi} \frac{\Gamma(2\sigma)e^{2\sigma}}{n\cdot n^{2\sigma}}=\frac{\Gamma(2\sigma)e^{2\sigma}}{\pi} \frac{1}{ n^{2\sigma}}
\end{split}
\end{align}
where we have used Lemma \ref{potential-sum} in the second to last equality to compute the sum. From \eqref{Graph-potential} we can see that $R^{\sigma}$ is non-negative for $\sigma \in (0,1]$. This completes the proof of the proposition.
\end{proof}
