Finally, we define a central object in our discussion, which are the sub/super solutions associated with Schr\"odinger operators.
\begin{definition}[({sub}/{super}) Solution]
A function $u \in \mathcal{F}_{\mathbb{N}}^{\sigma}$ is said to be a ({sub}/{super}) solution of the equation $\mathcal{H}_W[\varphi]=0$ in $\mathbb{N}$ if $\mathcal{H}_W[u]=0$ ($\mathcal{H}_W[u] {\leq}  0$ / $\mathcal{H}_W[u] {\geq}  0$) in $\mathbb{N}$.
\end{definition}

Agmon--Allegretto--Piepenbrink-type theorem relates the existence of positive supersolution to $\mathcal{H}_W[\varphi]=0$ in $\mathbb{N}$ with the positivity of the functional 
$$\mathcal{Q}_{W}(\varphi) := \langle  (-\Delta_{\mathbb{N}})^{\sigma}\varphi, \varphi  \rangle_{\ell^{2}(\mathbb{N})} - \langle W \varphi,\varphi \rangle_{{\ell^{2}(\mathbb{N})}} $$
on $C_{c}(\mathbb{N})$. For a reference on a general graph, see \cite[Theorem 4.2]{KPP17} and \cite[Theorem 2.3]{Florian}. We state it below for our particular case.
\begin{proposition}[Agmon--Allegretto--Piepenbrink-type theorem] \label{Prop:AAP}
Let $\sigma \in (0,1]$ and $W:\mathbb{N} \rightarrow \mathbb{R}$ be a potential. Then $\mathcal{Q}_{W}(\varphi)  \geq 0$ on $C_{c}(\mathbb{N})$ if and only if the equation $$\mathcal{H}_W[\varphi]:=((-\Delta_{\mathbb{N}})^{\sigma} -W)[\varphi]=0$$ admits a strictly positive supersolution on $\mathbb{N}$.
\end{proposition}




\subsection{Criticality theory for graph Laplacian.} \label{Sec:Criticality}

We have seen in the previous section that the fractional Laplacian $(-\Delta_{\mathbb{N}})^{\sigma}$ is a graph Laplacian associated with the graph $-\widetilde{\mathcal{K}}^{\sigma}$ over $\mathbb{N}$ with the non-negative potential term $R^{\sigma}$ as long as $-\widetilde{\mathcal{K}}^{\sigma} \geq 0$. It turns out that this is the case if $\sigma \in (0,1]$ (Remark \ref{Rmk:graphLap}). This allows us to take advantage of the well-developed criticality theory for graph Laplacian, see \cite{KPP17}. In this section, we recall some of the notions and results from criticality theory that are required for our purpose.

% \begin{proposition}[Agmon--Allegretto--Piepenbrink-type theorem] \label{Prop:AAP}
% Let $\sigma \in (0,1]$ and $W:\mathbb{N} \rightarrow \mathbb{R}$ be a potential. Then
% $$\mathcal{Q}_{W}(\varphi) := \langle  (-\Delta_{\mathbb{N}})^{\sigma}\varphi, \varphi  \rangle_{\ell^{2}(\mathbb{N})} - \langle \varphi,\varphi \rangle_{{\ell^{2}(\mathbb{N},W)}} \geq 0 $$ on $C_{c}(\mathbb{N})$ if and only if the Schr\"odinger equation $$\mathcal{H}_W[\varphi]:=((-\Delta_{\mathbb{N}})^{\sigma} -W)[\varphi]=0$$ admits a strictly positive supersolution on $\mathbb{N}$.
% \end{proposition}

In view of Proposition \ref{Prop:AAP}, we define the property of possessing a strictly positive supersolution as the positivity of the underlying operator. We also give the definition of criticality and subcriticality.
\begin{definition}[Positivity of $\mathcal{H}_W$, Sub-criticality, Criticality] Let $\sigma \in (0,1]$ and $W:\mathbb{N} \rightarrow \mathbb{R}$ be a potential.

\begin{enumerate}[label=(\roman*)]
    \item We say that the Schr\"odinger operator $\mathcal{H}_W:=(-\Delta_{\mathbb{N}})^{\sigma} -W$ is positive and write $\mathcal{H}_W \geq 0$ in $\mathbb{N}$ if $\mathcal{H}_W[\varphi]=0$ admits a strictly positive supersolution on $\mathbb{N}$.
    \item $\mathcal{H}_W \geq 0$ is said to be {\it subcritical} if $\mathcal{H}_W - \widetilde{W}  \geq 0$ for some $ \widetilde{W} \gneq 0$ and in this case $\widetilde{W}$ is referred to as a Hardy-weight of $\mathcal{H}_W$.
    \item $\mathcal{H}_W \geq 0$ is called {\it critical} if it is not subcritical.
\end{enumerate}
\end{definition}

Next we recall a characterization of criticality which will be used to prove Theorem \ref{Theorem:Hardy}. See \cite[Theorem 5.3]{KPP17} for a reference.
\begin{proposition}[Criticality $\&$ Null-sequence] \label{Prop:char_cri}
Let $\sigma \in (0,1]$ and $W:\mathbb{N} \rightarrow \mathbb{R}$ be a potential. $\mathcal{H}_W \geq 0$ is critical if and only if it admits a {\it null-sequence}, i.e., $\exists (\phi_n)$ in $C_c(\mathbb{N})$ such that $\phi_n \geq 0$,  $\phi_n(k) \asymp 1$ for some fixed $k \in \mathbb{N}$, and $$\mathcal{Q}_{W}(\phi_n) \rightarrow 0\quad \text{ as } n \rightarrow \infty.
$$   \end{proposition}
\begin{rmk} \rm 
  It turns out that any null-sequence of $\mathcal{H}_W$ converges point-wise, and the point-wise limit of any two null-sequences are positive multiple of each other. We call the pointwise limit of a null-sequence of $\mathcal{H}_W$ an {\it Agmon ground state} of $\mathcal{H}_W$.  Up to scalar multiples, Agmon ground state is a unique strictly positive
 super-solution of $\mathcal{H}_W[\varphi]=0$ on $\mathbb{N}$,
 see \cite[Theorem 5.3]{KPP18}. Thus, we see that $\mathcal{H}_W$ is critical in $\mathbb{N}$ if and only if it admits an Agmon ground state.   We also remark that an Agmon ground state $u$ has {\it minimal growth at infinity} in $\mathbb{N}$, i.e., for any $v>0$ with $\mathcal{H}_W[v] \geq 0$ on $\mathbb{N} \setminus K$ for some finite subset $K$, we have $u \leq v$ on $K$ implies $u \leq v$ on $\mathbb{N}\setminus K$ \cite[Theorem 2.6]{Florian}.

On the other hand, $\mathcal{H}_W$ is sub-critical in $\mathbb{N}$ if and only if it admits a positive {\it minimal Green function}, i.e., $\mathcal{H}_W[\varphi]=\delta_{1,\cdot}$ on $\mathbb{N}$ admits a strictly positive solution which has minimal growth at infinity \cite[Theorem 2.5]{Florian}.
\end{rmk}

Now we define the optimality of a Hardy-weight as follows.
\begin{definition}[Optimal Hardy-weight]
    A Hardy-weight $\widetilde{W}$ of $\mathcal{H}_W$ is said to be an \it{optimal Hardy-weight} if the following conditions hold:
    \begin{enumerate}[label=(\roman*)]
        \item $\mathcal{H}_W-\widetilde{W}$ is critical;
        \item $\Phi \notin l^2(\mathbb{N},\widetilde{W})$, where $\Phi$ is an Agmon ground state of $\mathcal{H}_W-\widetilde{W}$.
    \end{enumerate}
\end{definition}
\begin{rmk} \rm\label{Rmk:Asympt-Optimal}
The second criterion in the above definition is referred to as {\it null-criticality of $\mathcal{H}_W-\widetilde{W}$}. This condition ensures that the Hardy-weight $\widetilde{W}$ is in fact `big' near infinity. In particular it implies that the weight is {\it optimal near infinity}, i.e, if for some $\lambda\geq0$
\begin{equation*}
    \langle (-\Delta)^\sigma f,f\rangle_{\ell^2(\mathbb{N)}}\geq (1+\lambda)\langle \widetilde{W} f,f\rangle_{\ell^2(\mathbb{N)}}
\end{equation*}
for all $f\in C_c(\mathbb{N}\setminus K)$ for some compact $K \subseteq \mathbb{N}$, then $\lambda =0$. Note that this condition ensures that the constant implicitly involved in the Hardy-weight $W_{\sigma}^{\operatorname{op}}$ is optimal.

\end{rmk}

% By obtaining the precise asymptotic behavior of the graph weights $-\widetilde{\mathcal{K}}^\sigma$ and of the Agmon ground state we are able to construct an explicit null-sequence for $\mathcal{H}_W$ and a family of weights $W$. These asymptotics also give us straightforwardly the Hardy-weights that are possible candidates for null-criticality. It turns out only one of our weights can be critical and null-critical.


\subsection{Liouville-type comparison principle.} \label{Sec:LC} The following Liouville-type comparison principle was proved in \cite[Theorem 2.1]{DKP24}, and we include here for the sake of completeness. The continuum analogue was proved earlier by Pinchover \cite{Pinchover_LC}. This principle provides us a way to conclude the criticality of a positive Schrödinger operator from that of another positive Schrödinger operator when they satisfy certain compatible conditions for comparison.
\begin{theorem}[Liouville-type comparison principle]\label{Thrm_Liouville}
    Suppose $\mathcal{H}_W$ and $\mathcal{H}_{W'}$ are positive
Schrödinger operators with potentials $W$, $W'$ over $\mathbb{N}$. Let $u,v \in\mathcal{F}_{\mathbb{N}}^{\sigma}$  be such that
\begin{enumerate}[label=(\alph*)]
\item  $\mathcal{H}_{W'}$ is critical and $v > 0$ is its Agmon ground state,
\item   $\mathcal{H}_{W}[u_+] \leq 0$ with $u_+\neq 0$,
\item $\exists C>0$ such that  $u_+(n)  \leq C v(n)$ for all $n \in \mathbb{N}$.
\end{enumerate}
Then, $\mathcal{H}_W$ is critical and $u > 0$ is an Agmon ground state of $\mathcal{H}_W$.
\end{theorem}


