The following proposition plays a fundamental role in the supersolution construction which is the key for proving our main result. Note that this is the version of \cite[Proposition 2]{KN23} in the half-line $\mathbb{N}$. In \cite[Proposition 2]{KN23}, the authors approximate their corresponding Riesz potential by certain square summable functions. These approximating functions are positive which enables the authors to use monotone convergence theorem to justify a crucial limiting argument in their proof. In our case, such approximating functions of $\mathcal{I}_{\alpha}$ change their sign which causes a difficulty in the limiting argument. We overcome this by analyzing the asymptotic behavior of $\mathcal{I}_{\alpha}$.    
\begin{proposition} \label{Prop:Imp}
 Let $\sigma, \alpha \in (0,3/2)$ and $\sigma < \alpha < 1+\sigma$. Then
 $$(-\Delta_{\mathbb{N}})^{\sigma} \mathcal{I}_{\alpha}=\mathcal{I}_{\alpha-\sigma} \,,$$
 where $\mathcal{I}_{\alpha}$ is given by \eqref{Eq:Riesz}.
 In particular, $\mathcal{I}_{\alpha}$ is a strictly positive supersolution of $(-\Delta_{\mathbb{N}})^{\sigma} \mathcal{I}_{\alpha}=0 $ in $\mathbb{N}$.
\end{proposition}
\begin{proof}
For $\varepsilon>0$, we consider
$$\mathcal{I}_\alpha^{\varepsilon} (n) =\langle \mathcal{U} e_n,[2^{-\alpha}[1+\varepsilon-\cdot]^{-\alpha}]\rangle_{L^2((-1,1),\sqrt{1-x^2}\mathrm{d} x)}  \,.$$
Since the function $[1+\varepsilon-\cdot]^{-\alpha} \in L^2((-1,1),\sqrt{1-x^2}\mathrm{d} x)$, we infer that $\mathcal{U} \mathcal{I}_\alpha^{\varepsilon} = 2^{-\alpha}[1+\varepsilon-\cdot]^{-\alpha}.$ Moreover, if $\alpha < \frac{3}{2}$, an application of dominated convergence theorem implies that $\mathcal{I}_\alpha^{\varepsilon} \rightarrow \mathcal{I}_\alpha$ pointwise as $\varepsilon \rightarrow 0$. Now, we see that
  \begin{align}
   (-\Delta_{\mathbb{N}})^{\sigma} \mathcal{I}_{\alpha}^{\varepsilon}(n) & = \langle  e_n, (-\Delta_{\mathbb{N}})^{\sigma} \mathcal{I}_{\alpha}^{\varepsilon} \rangle_{\ell^2(\mathbb{N})} =    \langle  e_n, [\mathcal{U}^{-1} M_{2^{\sigma}(1-\cdot)^{\sigma}} \mathcal{U}] \mathcal{I}_{\alpha}^{\varepsilon} \rangle_{\ell^2(\mathbb{N})} \nonumber \\
   & = \langle   \mathcal{U} e_n, M_{2^{\sigma}(1-\cdot)^{\sigma}} \mathcal{U} \mathcal{I}_{\alpha}^{\varepsilon} \rangle_{L^2((-1,1),\sqrt{1-x^2})} \nonumber \\
   & = \langle   \mathcal{U} e_n, \frac{2^{\sigma}(1-\cdot)^{\sigma}}{ 2^{\alpha}(1+\varepsilon-\cdot)^{\alpha}} \rangle_{L^2((-1,1),\sqrt{1-x^2})} \nonumber \\
   &  \rightarrow \mathcal{I}_{\alpha-\sigma}(n) \label{lim1}
  \end{align}
  as $\varepsilon \rightarrow 0$, if $\alpha-\sigma<\frac{3}{2}$. On the other hand, 
  \begin{align} \label{Eqn:DCT0}
      (-\Delta_{\mathbb{N}})^{\sigma} \mathcal{I}_{\alpha}^{\varepsilon}(n) = \sum_{m \in \mathbb{N}} {\mathcal{K}^{\sigma}_{m,n} }\mathcal{I}_{\alpha}^{\varepsilon}(m) \,.
  \end{align}
  Recall that $\mathcal{I}_{\alpha}^{\varepsilon} \rightarrow \mathcal{I}_{\alpha}$ pointwise as $\varepsilon \rightarrow 0$. Furthermore, choosing $\beta \in (2\alpha-3/2,1/2+2\sigma)\cap (0,3/2)$  (which is non-empty as $\alpha<1+\sigma$), we use the Cauchy-Schwarz inequality to obtain
\begin{align*}
|\mathcal{I}_{\alpha}^{\varepsilon} (m)| & \leq  2^{-\alpha} \sqrt{\frac{2}{\pi}} \int_{-1}^1 \frac{|U_{m-1}|}{(1+\varepsilon-x)^{\alpha}} \sqrt{1-x^2} dx \\
& \leq 2^{-\alpha} \sqrt{\frac{2}{\pi}} \left[\int_{-1}^1 \frac{U_{m-1}^2}{(1+\varepsilon-x)^{\beta}} \sqrt{1-x^2} dx \right]^{1/2} \left[\int_{-1}^1 \frac{\sqrt{1-x^2}}{(1+\varepsilon-x)^{2\alpha-\beta}}  dx \right]^{1/2} \\
& \leq 2^{-\alpha} \sqrt{\frac{2}{\pi}} \left[\int_{-1}^1 \frac{U_{m-1}^2}{(1-x)^{\beta}} \sqrt{1-x^2} dx \right]^{1/2} \left[\int_{-1}^1 \frac{\sqrt{1-x^2}}{(1-x)^{2\alpha-\beta}}  dx \right]^{1/2} \\
& := C_{\alpha,\beta} \sqrt{J_{\beta}(m)} \,,
\end{align*} 
where $C_{\alpha,\beta}$ is a finite positive constant (as the second integral in the last inequality is finite for $\beta>2\alpha-3/2$) depending only on $\alpha,\beta$ and does not depend on $m$, and 
$$J_{\beta}(m):=\int_{-1}^1 \frac{U_{m-1}^2}{(1-x)^{\beta}} \sqrt{1-x^2} dx \,.$$
It has been shown in \cite[Lemma A.2]{GKS25} that 
$$J_{\beta}(m)=2^{\beta-2} \frac{\Gamma(\beta)^2}{\Gamma(2\beta)} j_{\beta}(m) \,,$$
where \begin{align} \label{Eq:asymp}
    j_{\beta}(m):=\left( 1-\frac{(\beta)_{2m}}{(1-\beta)_{2m}} \tan(\pi \beta)\right) = \begin{cases}
    O(1) \ \ \mbox{if} \ \ \beta \in (0,\frac{1}{2}) \\
    O(\log m) \ \ \mbox{if} \ \ \beta =\frac{1}{2} \\
    O(m^{2\beta-1}) \ \ \mbox{if} \ \ \beta \in (\frac{1}{2},\frac{3}{2}) 
\end{cases} \,.
\end{align} 
This estimate together with the estimate \eqref{Eq:Asmp_K} of $\mathcal{K}_{\cdot, n}^{\sigma}$, we conclude that for each $n \in \mathbb{N}$, the function $\mathcal{K}^{\sigma}_{\cdot,n} \mathcal{I}_{\alpha}^{\varepsilon}(\cdot)$ is dominated outside a finite set by the integrable function
$$ \frac{\sqrt{J_{\beta}(\cdot)}}{|\cdot-n|^{1+2\sigma}} \,.$$
Thus,  using the dominated convergence theorem in \eqref{Eqn:DCT0}, we get
   \begin{align} \label{lim2}
      (-\Delta_{\mathbb{N}})^{\sigma} \mathcal{I}_{\alpha}^{\varepsilon}(n) = \sum_{m \in \mathbb{N}} {\mathcal{K}^{\sigma}_{m,n} }\mathcal{I}_{\alpha}^{\varepsilon}(m) {\rightarrow} \sum_{m \in \mathbb{N}} {\mathcal{K}^{\sigma}_{m,n} }\mathcal{I}_{\alpha}(m) = (-\Delta_{\mathbb{N}})^{\sigma} \mathcal{I}_{\alpha}(n) \,,
  \end{align}
  as $\varepsilon \rightarrow 0$. Thus, it follows from \eqref{lim1} and \eqref{lim2} that $(-\Delta_{\mathbb{N}})^{\sigma} \mathcal{I}_{\alpha}=\mathcal{I}_{\alpha-\sigma} \,.$ This proves the first part of the proposition. The second conclusion is immediate from the fact that both $\mathcal{I}_{\alpha},\mathcal{I}_{\alpha-\sigma}$  are strictly positive as shown in \eqref{riesz}.
\end{proof}








