We consider the following function, for $0<\alpha, \sigma<3/2$,
$$W_{\alpha,\sigma}:=\frac{\mathcal{I}_{\alpha-\sigma}}{\mathcal{I}_{\alpha}} \,, \ \ \ 0<\alpha-\sigma<\frac{3}{2} \,.$$
Clearly, from \eqref{riesz}, it can be seen that $W_{\alpha,\sigma}>0$ for any $0<\alpha, \sigma<3/2$. The forthcoming proposition shows that $W_{\alpha,\sigma}$ is in fact a Hardy-weight for $(-\Delta_{\mathbb{N}})^{\sigma}$ when $\sigma \in (0,1]$, for certain values of $\alpha$.
\begin{proposition}[Construction of Hardy-weights] \label{Prop:HW}
    Let $\sigma \in (0,1]$, $\alpha \in (0,3/2)$ and $\sigma<\alpha<1+\sigma$. Then $W_{\alpha,\sigma}$ is a  Hardy-weight for $(-\Delta_{\mathbb{N}})^{\sigma}$.
\end{proposition}
\begin{proof}
 It is an immediate consequence of Proposition \ref{Prop:AAP}. Indeed, one can see that $\mathcal{I}_{\alpha}$ is a positive solution of 
 $$\left((-\Delta_{\mathbb{N}})^{\sigma}-W_{\alpha,\sigma}\right)[\varphi]=0 \,,$$
 which by Proposition \ref{Prop:AAP} implies $(-\Delta_{\mathbb{N}})^{\sigma}-W_{\alpha,\sigma} \geq 0$.
\end{proof}
Observe that the above proposition ensures the positivity of $(-\Delta_{\mathbb{N}})^{\sigma}-W_{\alpha,\sigma}$ qualitatively. In the next proposition, we quantify this positivity by proving a {\it Hardy-type identity}, which can be viewed as a {\it ground state representation} of $(-\Delta_{\mathbb{N}})^{\sigma}$ [cf. \cite{FLS06}]. We mainly follow the ideas from \cite[Theorem 2.1]{CR18}.
\begin{proposition}[Ground state representation] \label{Prop:HW_Alt}  Let $\sigma \in (0,1]$, $\alpha \in (0,3/2)$ and $\sigma<\alpha<1+\sigma$. Then
    \begin{equation}
    \langle  [(-\Delta_{\mathbb{N}})^\sigma-W_{\alpha,\sigma}] \varphi, \varphi \rangle_{\ell^2(\mathbb{N})} = \sum_{n\in\mathbb{N}}\sum_{m\in\mathbb{N}}-\mathcal{K}^\sigma_{m,n}\left(\left(\frac{\varphi(n) }{\mathcal{I}_{\alpha}(n) }-\frac{\varphi(m) }{\mathcal{I}_{\alpha}(m) }\right)^2 \mathcal{I}_{\alpha}(n) \mathcal{I}_{\alpha}(m) \right) \,, \ \ \forall \varphi \in C_c(\mathbb{N}) \,,
\end{equation}
where $\mathcal{K}^\sigma_{m,n}$ is given by \eqref{matrix-element}.
% for $n\neq m$ \begin{equation}
%     \mathcal{K}^\sigma_{m,n}=(-1)^{m+n} \left[\left(\begin{matrix}
%  2\sigma\\
% \sigma+m-n
% \end{matrix} 	
%  \right)-\left(\begin{matrix}
%  2\sigma\\
% \sigma+m+n
% \end{matrix} 	
%  \right)\right] \leq 0.
% \end{equation}
In particular, $W_{\alpha,\sigma}$ is a Hardy-weight of $(-\Delta_{\mathbb{N}})^\sigma$.
\end{proposition}
\begin{proof}
For a given $\varphi \in C_c(\mathbb{N})$, we take $u(n) =\varphi(n)^2 /\mathcal{I}_{\alpha}(n) $. Then
\begin{equation}\label{weight-construction}
     \langle (-\Delta_{\mathbb{N}})^\sigma u,\mathcal{I}_{\alpha}\rangle_{\ell^2(\mathbb{N})}= \langle u,\mathcal{I}_{\alpha-\sigma}\rangle_{\ell^2(\mathbb{N})}=\sum_{n\in\mathbb{N}}\frac{\mathcal{I}_{\alpha-\sigma}}{\mathcal{I}_\alpha} \varphi(n)^2.
\end{equation}
