We can polarize \eqref{q_form} with $f=u$ and $g=\mathcal{I}_{\alpha}$  to get
\begin{align*}\label{ground}
\begin{split}
& \, \langle  f,(-\Delta_{\mathbb{N}})^\sigma g\rangle_{\ell^2(\mathbb{N})}=-\frac{1}{2}\sum_{n\in\mathbb{N}}\sum_{m\in\mathbb{N}}\mathcal{K}^\sigma_{m,n}(f_m -f_n )(g_m -g_n )+\sum_{n\in\mathbb{N}}R^\sigma_nf_n g_n \\&=-\frac{1}{2}\sum_{n\in\mathbb{N}}\sum_{m\in\mathbb{N}}\mathcal{K}^\sigma_{m,n}\left((\varphi(n) -\varphi(m) )^2-\left(\frac{\varphi(n) }{\mathcal{I}_{\alpha}(n) }-\frac{\varphi(m) }{\mathcal{I}_{\alpha}(m) }\right)^2 \mathcal{I}_{\alpha}(n) \mathcal{I}_{\alpha}(m) \right)+\sum_{n\in\mathbb{N}}R^\sigma_n \varphi(n)^2 \\&= \langle  \varphi,(-\Delta_{\mathbb{N}})^\sigma \varphi \rangle_{\ell^2(\mathbb{N})}+\frac{1}{2}\sum_{n\in\mathbb{N}}\sum_{m\in\mathbb{N}}\mathcal{K}^\sigma_{m,n}\left(\left(\frac{\varphi(n) }{\mathcal{I}_{\alpha}(n) }-\frac{\varphi(m) }{\mathcal{I}_{\alpha}(m) }\right)^2 \mathcal{I}_{\alpha}(n) \mathcal{I}_{\alpha}(m) \right)\\& =\sum_{n\in\mathbb{N}}\frac{\mathcal{I}_{\alpha-\sigma}}{\mathcal{I}_\alpha} \varphi(n)^2.
