\subsection[Criticality of the quadratic form]{Criticality of $(-\Delta_{\mathbb{N}})^{\sigma}-W_{\alpha,\sigma}$.}
In this section, we will show the criticality of $(-\Delta_{\mathbb{N}})^{\sigma}-W_{\alpha,\sigma}$ for $\sigma \in (0,1]$ and $\alpha \in (\sigma, \frac{3+2\sigma}{4}]$, where $W_{\alpha,\sigma}$ is the Hardy-weight constructed in the previous subsection. For $\sigma \in (0,1)$, we use the criticality characterization (Proposition \ref{Prop:char_cri}) for this purpose. That is, we will construct a null-sequence for $\mathcal{Q}_{W_{\alpha,\sigma}}$ (recall \eqref{eq:quadratic}). On the other hand, for $\sigma =1$, we use the Liouville-type comparison principle (Theorem \ref{Thrm_Liouville}).


While dealing with the energy functional $\mathcal{Q}_{W_{\alpha,\sigma}}$, it is often convenient to consider the following {\it simplified energy functional}:
\begin{equation} \label{Eq:SEF}
Q_{\alpha}^\sigma\left(\varphi\right):=\frac{1}{2} \sum_{n, m \in \mathbb{Z}} (- \widetilde{\mathcal{K}}^\sigma_{m,n}) \mathcal{I}_\alpha(n) \mathcal{I}_\alpha(m)(\varphi(n)-\varphi(m))^2 \,, \ \ \ \varphi \in C_c(\mathbb{N})
\end{equation}
as it is equivalent to  $\mathcal{Q}_{W_{\alpha,\sigma}}$ in the following sense  \cite[Proposition 4.8]{KPP17}
\begin{equation} \label{Eq:GST}
\mathcal{Q}_{W_{\alpha,\sigma}}\left(\varphi\mathcal{I}_\alpha\right)=Q_{\alpha}^\sigma(\varphi)\,, \ \ \ \forall \varphi \in C_c(\mathbb{N}) \,.
\end{equation}
Note that (\ref{Eq:GST}) is just a way to rewrite (\ref{Eq:GSR}) in terms of quadratic forms.
\begin{proposition} \label{Prop:crit}
    Let $\sigma \in (0,1)$. Then $(-\Delta_{\mathbb{N}})^{\sigma} - W_{\alpha,\sigma}$ is critical for all $\alpha \in (\sigma, \frac{3+2\sigma}{4}]$.
\end{proposition}
\begin{proof}
In the view of Proposition \ref{Prop:char_cri}, we aim to construct a null-sequence for $\mathcal{Q}_{W_{\alpha,\sigma}}$.
  For $k\in \mathbb{N}$, we define $\varphi_k:\mathbb{N}\rightarrow\mathbb{R}$,
    \begin{equation*}
       \varphi_k(n)=\left\{\begin{matrix}
           1\\
           2-\frac{\log n}{\log k}\\
           0
       \end{matrix}\right.
       \begin{matrix}
         \ ,\ \\
         \ ,\ \\
          ,
       \end{matrix}
       \begin{matrix}
           n\leq k\\
           k<n\leq k^2\\
           k^2<n
       \end{matrix}
   \end{equation*}
   This sequence is in $C_c(\mathbb{N})$ and $\varphi_k \overset{k\rightarrow\infty}{\longrightarrow} 1$ pointwise. Furthermore, we claim that
   \begin{equation} \label{Eq:claim}
    (\varphi_k(n)-\varphi_k(m))^2 \leq \left(\frac{\log (m/n)}{\log k}\right)^2.
\end{equation}
Due to symmetry, it is enough to prove the above inequality only for $n<m$. If $k^2\leq n<m$, then the inequality is obvious.
If $n < k^2 < m$, then there can be two situations $(i)$ $n<k$ and $(ii)$ $n \geq k$. In situation $(i)$, we have
\begin{equation*}
    (\varphi_k(n)-\varphi_k(m))^2=1= (2-1)^2 \leq\left(\frac{\log m}{\log k}-\frac{\log n}{\log k}\right)^2=\left(\frac{\log (m/n)}{\log k}\right)^2.
\end{equation*}
For situation $(ii)$
\begin{equation*}
    (\varphi_k(n)-\varphi_k(m))^2=(2-\frac{\log n}{\log k})^2= \leq\left(\frac{\log m}{\log k}-\frac{\log n}{\log k}\right)^2=\left(\frac{\log (m/n)}{\log k}\right)^2.
\end{equation*}
Now, consider $n<m \leq k^2$. Three cases may occur $(i)$ $k \leq n <m \leq k^2$, $(ii)$ $n < k <m \leq k^2$ and $(iii)$ $n<m \leq k$. For case $(i)$, 
\begin{equation*}
    (\varphi_k(n)-\varphi_k(m))^2=\left(\frac{\log n}{\log k}-\frac{\log m}{\log k}\right)^2=\left(\frac{\log (m/n)}{\log k}\right)^2 \,.
\end{equation*}
In case $(ii)$, we have
\begin{equation*}
    (\varphi_k(n)-\varphi_k(m))^2=\left(1-\frac{\log m}{\log k}\right)^2 \leq \left(\frac{\log n}{\log k}-\frac{\log m}{\log k}\right)^2 =\left(\frac{\log (m/n)}{\log k}\right)^2 \,.
\end{equation*}
When case $(iii)$ occurs, \eqref{Eq:claim} holds trivially.


We will use the estimate \eqref{Eq:claim} to show that $Q_{\alpha}^\sigma\left(\varphi_k\right) \rightarrow 0$ as $k \rightarrow \infty$, where $Q_{\alpha}^\sigma$ is the simplified energy functional defined in \eqref{Eq:SEF}.
Using \eqref{Eq:Asmp_K}, we get
\begin{align} \label{Eq:split}
\begin{split}
    Q_{\alpha}^\sigma\left(\varphi_k\right)&\lesssim \sum_{1\leq n <m}\frac{(\varphi_k(n)-\varphi_k(m))^2}{(m-n)^{2\sigma+1}m^{2-2\alpha}n^{2-2\alpha}} \\
    &= \sum_{1\leq n<m\leq k^2}\frac{(\varphi_k(n)-\varphi_k(m))^2}{(m-n)^{2\sigma+1}m^{2-2\alpha}n^{2-2\alpha}}+\sum_{1\leq n\leq k^2<m}\frac{(\varphi_k(n)-\varphi_k(m))^2}{(m-n)^{2\sigma+1}m^{2-2\alpha}n^{2-2\alpha}} \,.
    \end{split}
\end{align}
Let us first deal with the first sum. We use \eqref{Eq:claim} to obtain
\begin{align*}
    &\sum_{1\leq n<m\leq k^2}\frac{(\varphi_k(n)-\varphi_k(m))^2}{(m-n)^{2\sigma+1}m^{2-2\alpha}n^{2-2\alpha}}\leq 
    \frac{1}{(\log k )^2}\sum_{1\leq n<m\leq k^2}\frac{(\log (m/n))^2}{(m-n)^{2\sigma+1}m^{2-2\alpha}n^{2-2\alpha}}\\
    &\leq\frac{1}{(\log k )^2}\sum_{n\leq k^2}\frac{1}{n^{2(2-2\alpha)+1+2\sigma}}\sum_{n<m\leq k^2}\frac{(\log (m/n))^2}{(m/n-1)^{2\sigma+1}(m/n)^{2-2\alpha}}\\
    &\leq\frac{1}{(\log k )^2}\sum_{n\leq k^2}\frac{1}{n^{2(2-2\alpha)+2\sigma}}\int_{\frac{n+1}{n}}^{\frac{k^2}{n}}\frac{(\log t)^2\ \mathrm{d}t}{(t-1)^{2\sigma+1}(t)^{2-2\alpha}} \\
    &\leq\frac{1}{(\log k )^2} \left[\int_{1}^{\infty}\frac{(\log t)^2\ \mathrm{d}t}{(t-1)^{2\sigma+1}(t)^{2-2\alpha}} \right] \left[\sum_{n\leq k^2}\frac{1}{n^{2(2-2\alpha)+2\sigma}} \right]  \\
    &\leq\frac{1}{(\log k )^2} \left[\int_{1}^{\infty}\frac{(\log t)^2\ \mathrm{d}t}{(t-1)^{2\sigma+1}(t)^{2-2\alpha}} \right] \left[\int_1^{k^2} \frac{\mathrm{d}t}{t^{2(2-2\alpha)+2\sigma}} \right]  \,. 
\end{align*} 
For the second sum in \eqref{Eq:split}, we use \eqref{Eq:claim} to obtain
\begin{align*}
    &\sum_{1\leq n\leq k^2<m}\frac{(\varphi_k(n)-\varphi_k(m))^2}{(m-n)^{2\sigma+1}m^{2-2\alpha}n^{2-2\alpha}}\leq 
    \frac{1}{(\log k )^2}\sum_{1\leq n\leq k^2<m}\frac{(\log (m/n))^2}{(m-n)^{2\sigma+1}m^{2-2\alpha}n^{2-2\alpha}}\\
    &\leq\frac{1}{(\log k )^2}\sum_{n\leq k^2}\frac{1}{n^{2(2-2\alpha)+1+2\sigma}}\sum_{k^2<m}\frac{(\log (m/n))^2}{(m/n-1)^{2\sigma+1}(m/n)^{2-2\alpha}}\\
    &\leq\frac{1}{(\log k )^2}\sum_{n\leq k^2}\frac{1}{n^{2(2-2\alpha)+2\sigma}}\int_{\frac{k^2}{n}}^{\infty}\frac{(\log t)^2\ \mathrm{d}t}{(t-1)^{2\sigma+1}(t)^{2-2\alpha}} \\
    &\leq\frac{1}{(\log k )^2} \left[\int_{1}^{\infty}\frac{(\log t)^2\ \mathrm{d}t}{(t-1)^{2\sigma+1}(t)^{2-2\alpha}} \right] \left[\sum_{n\leq k^2}\frac{1}{n^{2(2-2\alpha)+2\sigma}} \right]  \\
    &\leq\frac{1}{(\log k )^2} \left[\int_{1}^{\infty}\frac{(\log t)^2\ \mathrm{d}t}{(t-1)^{2\sigma+1}(t)^{2-2\alpha}} \right] \left[\int_1^{k^2} \frac{\mathrm{d}t}{t^{2(2-2\alpha)+2\sigma}} \right]   \,.
\end{align*} 
Using the preceding two estimates in \eqref{Eq:split}, we conclude that
$$ Q_{\alpha}^\sigma\left(\varphi_k\right) \leq \frac{1}{(\log k)^2 } \left[\int_{1}^{\infty}\frac{(\log t)^2\ \mathrm{d}t}{(t-1)^{2\sigma+1}(t)^{2-2\alpha}} \right] \left[\int_1^{k^2} \frac{\mathrm{d}t}{t^{2(2-2\alpha)+2\sigma}} \right]\rightarrow 0 \,,$$
as $k \rightarrow \infty$. Notice that here we use the fact that $\int_{1}^{\infty}\frac{(\log t)^2\ \mathrm{d}t}{(t-1)^{2\sigma+1}(t)^{2-2\alpha}}< \infty $, which is true if $\sigma \in (0,1)$. By \eqref{Eq:GST}, it follows that $\mathcal{Q}_{W_{\alpha,\sigma}}\left(\varphi_k\mathcal{I}_\alpha\right) \rightarrow 0$ as $k \rightarrow \infty$. This implies $(\varphi_k\mathcal{I}_\alpha)$ is a null-sequence for $\mathcal{Q}_{W_{\alpha,\sigma}}$ which converges to $\mathcal{I}_\alpha$ pointwise as $k \rightarrow \infty$. Hence, $(-\Delta_{\mathbb{N}})^{\sigma}-W_{\alpha,\sigma}$ is critical with $\mathcal{I}_\alpha$ as its Agmon ground state.
\end{proof}

