\begin{proposition}\label{prop:crit_laplacian}
    $-\Delta_{\mathbb{N}} - W_{\alpha,1}$ is critical for all $\alpha \in (1, \frac{5}{4}]$.
\end{proposition}
\begin{proof}
    From \cite[Theorem 7.3]{KPP18} we know that $W^{\operatorname{KPP}}(n)=2-\sqrt{\frac{n+1}{n}}-\sqrt{\frac{n-1}{n}}$ is an optimal Hardy-weight for the operator $-\Delta_{\mathbb{N}}$. In particular, the Schr\" odinger operator $-\Delta_{\mathbb{N}}-W^{\operatorname{KPP}}$ is critical with corresponding Agmon ground state $v(n)=n^{1/2}$. On the other hand, from Proposition \ref{Prop:HW}, we see that $-\Delta_{\mathbb{N}}-W_{\alpha,1} \geq 0$ and $\mathcal{I}_\alpha$ is a positive solution of $(-\Delta_{\mathbb{N}}-W_{\alpha,1})[\varphi] = 0$ on $\mathbb{N}$. From Remark \ref{Eq:Asymp_Riesz} we know the asymptotic behaviour of $\mathcal{I}_\alpha$, which implies that
    \begin{equation*}
        \mathcal{I}_\alpha(n)\leq C v(n) 
    \end{equation*}
    for all $n\in\mathbb{N}$ and some $C>0$, if $\alpha\leq 5/4$. Thus, taking $\mathcal{H}_{W'}=-\Delta_{\mathbb{N}}-W^{\operatorname{KPP}}$ and $\mathcal{H}_{W}=-\Delta_{\mathbb{N}}-W_{\alpha,1}$ on $\mathbb{N}$, we verify that the hypotheses of Theorem \ref{Thrm_Liouville} are fulfilled. Therefore, $-\Delta_{\mathbb{N}}-W_{\alpha,1}$ is critical and $\mathcal{I}_\alpha$ is its Agmon ground state.
\end{proof}

\subsection[Null criticality of the quadratic form]{Null criticality of $(-\Delta_{\mathbb{N}})^{\sigma}-W_{\alpha,\sigma}$.}
In the earlier subsection, we have seen that the Hardy-weights $W_{\alpha,\sigma}$ are critical Hardy-weights for $(-\Delta_{\mathbb{N}})^{\sigma}$ if $\sigma \in \left(0,1\right]$ and $\alpha \in (\sigma,\frac{3+2\sigma}{4}]$, and the corresponding Agmon ground state of $(-\Delta_{\mathbb{N}})^{\sigma}-W_{\alpha,\sigma}$ is $\mathcal{I}_{\alpha}$. Now we show that, for $\alpha=\frac{3+2\sigma}{4}$, the Hardy-weight $W_{\alpha,\sigma}$ is in fact null-critical.

\begin{proposition}\label{Prop:null-crit}
 Let $\sigma \in \left(0,1\right]$ and $\sigma<\alpha<\min\{3/2,1+\sigma\}$.   The function $\mathcal{I}_\alpha\in \ell^2(\mathbb{N}, W_{\alpha,\sigma})$ if and only if $\alpha<\frac{3+2\sigma}{4}$. In particular, for $\alpha=\frac{3+2\sigma}{4}$, the Hardy-weight $W_{\alpha,\sigma}$ of $(-\Delta_{\mathbb{N}})^{\sigma}$ is null-critical, i.e. $\mathcal{I}_{\alpha} \notin l^2(\mathbb{N},W_{\alpha,\sigma})$.
\end{proposition}
\begin{proof}
First, recall that $W_{\alpha, \sigma}$ is a Hardy-weight by Proposition \ref{Prop:HW}.
Using the asymptotic of $\mathcal{I}_{\alpha}$ and $W_{\alpha,\sigma}$ given by \eqref{Eq:Asmp_I} and \eqref{Eq:Asmp_W} resp., we see that
    \begin{equation*}
        \sum_{n\in\mathbb{N}}\mathcal{I}_\alpha^2(n)W_{\alpha,\sigma}(n)\asymp\sum_{n\in\mathbb{N}}n^{4\alpha-4-2\sigma}<+\infty
    \end{equation*}
    if and only if ${4\alpha-4-2\sigma}<-1\iff\alpha<\frac{3+2\sigma}{4}$.
\end{proof}
\subsection{A necessary condition for criticality.}
We saw in Proposition \ref{Prop:crit} that $W_{\alpha,\sigma}$ are critical Hardy-weights when $0<\alpha\leq\frac{3+2\sigma}{4}$. We will also show that, in fact, this is also a necessary condition for criticality, i.e. the Hardy-weights $W_{\alpha,\sigma}$ are not critical for $\frac{3+2\sigma}{4}<\alpha<\min\{3/2,1+\sigma\}$. We follow an analogous strategy to the one shown in \cite{KN23}. First, we prove the following result on asymptotic optimality. The proof is completely analogous to Lemma 6 in \cite{KN23} and Theorem 4.3 in \cite{DKPM}. Nevertheless, we state and prove here the result for the sake of reading.

\begin{lemma}{(Optimality near infinity).}\label{Lemma:asympt-crit}
 Let $\sigma \in \left(0,1\right]$ and $\sigma<\alpha<\min\{3/2,1+\sigma\}$. Assume $W_{\alpha,\sigma}$ is a critical Hardy-weight of the form (\ref{weight}). If for a finite set $K\subseteq\mathbb{N}$ and $W':\mathbb{N}\rightarrow\left[0,\infty\right)$
\begin{equation*}
    \langle(-\Delta)^\sigma\varphi,\varphi\rangle\geq  \langle(W_{\alpha,\sigma}+W')\varphi,\varphi\rangle
\end{equation*}
for all $\varphi\in C_c(\mathbb{N}\setminus K)$, then $\mathcal{I}_\alpha$ satisfies $\mathcal{I}_\alpha\in\ell^2(\mathbb{N},W')$.

In particular, if we choose $W'=\lambda W_{\alpha,\sigma}$, we see that the weight is optimal near infinity if it is also null-critical.
\end{lemma}

\begin{proof}
    The assumption gives us
    \begin{equation*}
        \langle W'\varphi,\varphi\rangle\leq \langle((-\Delta)^\sigma-W_{\alpha,\sigma})\varphi,\varphi\rangle=\left(Q^\sigma-W_{\sigma, \alpha}\right)\left(\varphi\right).
    \end{equation*}
    Let $\varphi=\mathcal{I}_\alpha\eta1_{\mathbb{N}\setminus K}$ with $\eta\in C_c(\mathbb{N})$ and $0\leq\eta\leq1$. By the ground state transform
    \begin{equation*}
        \sum_{n\in\mathbb{N}\setminus K}W'(n)(\mathcal{I}_\alpha\eta)^2(n)\leq \left(Q^\sigma-W_{\sigma, \alpha}\right)\left(\mathcal{I}_\alpha\eta1_{\mathbb{N}\setminus K}\right)=Q_{-\alpha}^\sigma(\eta(1-1_K))\leq 2Q_{-\alpha}^\sigma(\eta)+2Q_{-\alpha}^\sigma(1_K)
    \end{equation*}
    Now we replace $\eta$ by a null-sequence which exists since we assumed criticality (Proposition \ref{Prop:char_cri}). Then by Fatou's lemma we get
    \begin{equation*}
         \sum_{n\in\mathbb{N}\setminus K}W'(n)(\mathcal{I}_\alpha)^2(n)<\infty.
    \end{equation*}
    The statement about null-criticality comes directly by choosing $W'=\lambda W_{\alpha,\sigma}$
\end{proof}


Now we see that, if we assume that $W_{\alpha,\sigma}$ are critical for $\frac{3+2\sigma}{2}<\alpha<\min\{3/2,1+\sigma\}$, then Lemma \ref{Lemma:asympt-crit} leads to a contradiction of the null criticality described in Proposition \ref{Prop:null-crit}.

\begin{proposition}\label{Prop:necess}
    Let $0<\sigma\leq1$, $\sigma<\alpha<1+\sigma$, and $\frac{3+2\sigma}{4}<\alpha<3/2$. Then the Hardy-weights $W_{\alpha,\sigma}$ are not critical.
\end{proposition}

\begin{proof}
    As can be observed from (\ref{Eq:Asmp_W}), all weights $W_{\alpha,\sigma}$ share the same asymptotic decay, $n^{-2\sigma}$, but differ in the constants, which are given by 
    \begin{equation*}
        \Psi_\sigma(\alpha)=4^\sigma\frac{\Gamma(\frac{3}{2}-\alpha+\sigma)\Gamma(\alpha)}{\Gamma(\alpha-\sigma)\Gamma(\frac{3}{2}-\alpha)}.
    \end{equation*}

    To study the monotonicity of $\Psi_\sigma(\alpha)$ with respect to $\alpha$, we compute $\Psi'_\sigma(\alpha)$

    \begin{equation*}
        \Psi'_\sigma(\alpha)=4^\sigma\frac{\Gamma(\frac{3}{2}-\alpha+\sigma)\Gamma(\alpha)}{\Gamma(\alpha-\sigma)\Gamma(\frac{3}{2}-\alpha)}[\psi^{(0)}(\alpha)-\psi^{(0)}(\alpha-\sigma)-\psi^{(0)}(\frac{3}{2}-\alpha+\sigma)+\psi^{(0)}(\frac{3}{2}-\alpha)].
    \end{equation*}    
    using $\Gamma'(x)=\Gamma(x)\psi^{(0)}(x)$. We can write the terms inside of the brackets as
    \begin{equation*}
        \int_{\alpha-\sigma}^{\alpha}[\psi^{(1)}(t)+\psi^{(1)}(3/2-t)]\ \mathrm{d}t= \int_{\alpha-\sigma}^{\alpha}\psi^{(1)}(t)\ \mathrm{d}t - \int_{3/2-\alpha}^{3/2-\alpha+\sigma}\psi^{(1)}(t)\ \mathrm{d}t.
    \end{equation*}
    Since $\psi^{(1)}$ is a strictly decreasing positive function on the positive real axis, both intervals of integration are of measure $\sigma$ and by assumption $\alpha-\sigma>3/2-\alpha$, then $ \Psi'_\sigma(\alpha)<0$ in $(\frac{3+2\sigma}{4},\frac{3}{2})$. Therefore, $\Psi_\sigma(\alpha)$ is strictly decreasing in that interval and $\Psi_{\sigma,3}(\frac{3+2\sigma}{4})=4^{\sigma}\frac{\Gamma\left(\frac{3+2\sigma}{4}\right)^2}{\Gamma\left(\frac{3-2\sigma}{4}\right)^2}=:C_\sigma$.    
    Now we argue by contradiction. Assume $W_{\alpha,\sigma}$ is critical for some $\alpha>\frac{3+2\sigma}{4}$. By the above analysis of $ \Psi_\sigma$ we can choose a positive $\lambda$ such that
    \begin{equation*}
        \frac{C_\sigma - \Psi_\sigma(\alpha)}{\Psi_\sigma(\alpha)}>\lambda\implies C_\sigma>(1+\lambda)\Psi_\sigma(\alpha).
    \end{equation*}
    As the asymptotic behavior of the weights differs only in their constants, we can choose a finite set $K\subseteq\mathbb{N}$ such that outside of $K$ we get
    \begin{equation*}
        W_{\sigma,\frac{3+2\sigma}{4}}\geq (1+\lambda)W_{\alpha,\sigma}
    \end{equation*}
    Since $\mathcal{I}_{\alpha}$ is the unique ground state of $(Q^\sigma-W_{\alpha,\sigma})$, the weight $W'=\lambda W_{\alpha,\sigma}$ fulfills the hypotheses of lemma \ref{Lemma:asympt-crit}, so we conclude 
    \begin{equation*}
        \mathcal{I}_{\alpha}\in\ell^2(\mathbb{N},W_{\alpha,\sigma}).
    \end{equation*}
    However this contradicts Proposition \ref{Prop:null-crit}.
\end{proof}
\subsection{Proof of Theorem \ref{Theorem:Hardy}.}
We conclude the on-going section with the proof of Theorem \ref{Theorem:Hardy}.

\begin{proof}
Proposition \ref{Prop:HW} shows that $W_{\alpha,\sigma}$ is a Hardy-weight for $(-\Delta)^{\sigma}$ if $\sigma \in \left(0,1\right]$, $0<\alpha-\sigma<\frac{3}{2} $ and $\alpha\in(\sigma,1+\sigma)$. Propositions \ref{Prop:crit} and \ref{Prop:necess} ensure that $(-\Delta)^{\sigma}-W_{\alpha,\sigma}$ is critical if and only if $\alpha \in \left(\sigma,\frac{3+2\sigma}{4}\right]$. Finally, Proposition \ref{Prop:null-crit}, implies that the Hardy-weight $W_{\alpha,\sigma}$ of $(-\Delta)^{\sigma}$ is null-critical if $\alpha=\frac{3+2\sigma}{4}$. Hence,  we prove the optimality of the Hardy-weight $W_{\frac{3+2\sigma}{4},\sigma}$ for $(-\Delta)^{\sigma}$.    
\end{proof}

\section{An application to unique continuation at infinity} \label{Sec:UCP}
As an immediate application to the above study of optimal Hardy-weights, here we derive some unique continuation results as stated in Theorem \ref{Thm:UCP}.

We define $\mathcal{G}_{\sigma}= \sqrt{2/\pi}  \mathcal{I}_{\sigma}$. 
Then, for $\sigma \in {(0,\frac{3}{2})}$, \begin{align*} 
    \mathcal{G}_{\sigma} (n) &=\langle \mathcal{U} e_n,[2^{-\sigma}[1-\cdot]^{-\sigma}]\rangle_{L^2((-1,1),\sqrt{1-x^2}\mathrm{d} x)} \\
  & = \frac{2}{\pi} \int_{-1}^1 \frac{U_{n-1}}{2^{\sigma}[1-x]^{\sigma}} \sqrt{1-x^2} \ dx \\
  & = \frac{2}{\pi} \lim_{\lambda \rightarrow 0_+} \int_{-1}^1 \frac{U_{n-1}}{2^{\sigma}[1-x+\lambda]^{\sigma}} \sqrt{1-x^2} \ dx =  \lim_{\lambda \rightarrow 0_+} [(-\Delta_{\mathbb{N}})^{\sigma}+\lambda]^{-1}_{1,n} \,,
\end{align*}
where the third equality uses the dominated convergence theorem and the fourth one follows from \cite[Corollary 2.2]{GKS25}. Restricting $\sigma \in (0,1]$, it follows from \cite[Theorem 6.26]{KLW21} that $(-\Delta_{\mathbb{N}})^{\sigma} \mathcal{G}_{\sigma} = \delta_{1,\cdot}$ and $\mathcal{G}_{\sigma}$ is  the smallest positive $u \in \mathcal{F}_{\mathbb{N}}^{\sigma}$ such that  $(-\Delta_{\mathbb{N}})^{\sigma}u \geq  \delta_{1,\cdot}$ on $\mathbb{N}$.  Hence, $\mathcal{G}_{\sigma}$ is a positive  minimal Green function of $(-\Delta_{\mathbb{N}})^{\sigma}$, i.e., for any $v>0$ with  $(-\Delta_{\mathbb{N}})^{\sigma}v \geq  0$ outside a finite set in $\mathbb{N}$, there exists $C>0$ such that $\mathcal{G}_{\sigma} \leq C v$ on $\mathbb{N}$.



\begin{proof}[Proof of Theorem \ref{Thm:UCP}]
The proof follows from \cite[Theorem 3.1]{DKP24}. We give the details for reader´s convenience. Let $ u $ be a solution of $\left[ (-\Delta_{\mathbb{N}})^{\sigma} + V\right] \varphi =0$ on $\mathbb{N}$, and assume without loss of generality $ u_{+}\neq 0 $ (otherwise consider $ -u$). Then, by \cite[Lemma 3.2]{DKP24}, we have
\begin{align*}
	\left[ (-\Delta_{\mathbb{N}})^{\sigma} + V\right] u_{+} \le 0 
\end{align*}
on $\mathbb{N}$. Now, in the Liouville comparison principle (Theorem \ref{Thrm_Liouville}), we take $\mathcal{H}_{W'}= (-\Delta_{\mathbb{N}})^{\sigma} - W^{\mathrm{op}}_{\sigma}$ and $\mathcal{H}_{W}= (-\Delta_{\mathbb{N}})^{\sigma} +V$, where $W^{\mathrm{op}}_{\sigma}$ is the optimal Hardy-weight of $(-\Delta_{\mathbb{N}})^{\sigma}$ given in Theorem \ref{Theorem:Hardy}. Then, due to the first decay assumption on $u$, it is not difficult to verify that the hypothesis of Theorem \ref{Thrm_Liouville} are satisfied. Hence, we can infer that $\mathcal{H}_{W}= (-\Delta_{\mathbb{N}})^{\sigma} +V$ is in fact critical and $u=u_+>0$ is the corresponding Agmon ground state. Since $u>0$ and $V \leq 0$, it follows that
$$(-\Delta_{\mathbb{N}})^{\sigma} u \geq \left[(-\Delta_{\mathbb{N}})^{\sigma} +V \right] u =0 $$
outside a finite set in $\mathbb{N}$. Since $\mathcal{G}_{\sigma}$ is a positive minimal Green function of $(-\Delta_{\mathbb{N}})^{\sigma}$, it follows that there exists $C>0$ such that $\mathcal{G}_{\sigma} \leq C u$ on $\mathbb{N}$. As $\mathcal{G}_{\sigma}$ has the asymptotics $\mathcal{G}_{\sigma}(n) \asymp n^{2\sigma -2}$ for large $n$, we get a contradiction to our second decay assumption. Therefore, $u \equiv 0$.  
\end{proof}

\begin{rmk}
\rm There exists $C>0$ such that $(-\Delta_{\mathbb{N}})^{\sigma} - C \delta_{1,\cdot}$ is critical in $\mathbb{N}$ \cite[Lemma 4.4.]{DKPM}. Let $u$ be its Agmon ground state. In particular, $\left[(-\Delta_{\mathbb{N}})^{\sigma} - C \delta_{1,\cdot}\right] u =0$ in $\mathbb{N}$. Moreover, it is not difficult to see that $u \asymp \mathcal{G}_{\sigma}$ outside a finite set (as both are positive solution of minimal growth at infinity of the same equation). This shows that the decay assumption in Theorem \ref{Thm:UCP} is sharp.   
\end{rmk}




\section{Final Remarks}\label{Sec:Final-Rem}



In Theorem \ref{Theorem:Hardy}, we provide an optimal Hardy-weight for the fractional Laplacian $(-\Delta_{\mathbb{N}})^{\sigma}$ over $\mathbb{N}$ for the exponents $\sigma\in\left(0,1\right]$. As a simple consequence (using Theorem \ref{Theorem:Hardy} and \eqref{eq:asympga}), we obtain admissible range of  $\gamma$ such that \eqref{Eq:HW} describes a Hardy-weight for $(-\Delta_\mathbb{N})^\sigma$. From Theorem \ref{Theorem:Hardy} and Remark \ref{Rmk:weight-asympt}, we have
$$W^{\mathrm{op}}_{\sigma} \asymp 4^{\sigma}\frac{\Gamma\left(\frac{3+2\sigma}{4}\right)^2}{\Gamma\left(\frac{3-2\sigma}{4}\right)^2} n^{-2\sigma} \,.$$
Thus, it follows from the null criticality of $W^{\mathrm{op}}_{\sigma}$ that $\gamma$ in \eqref{Eq:HW} must satisfy
\begin{equation*}   0<\gamma\leq4^{\sigma}\frac{\Gamma\left(\frac{3+2\sigma}{4}\right)^2}{\Gamma\left(\frac{3-2\sigma}{4}\right)^2}=:C_{\sigma},
\end{equation*}
addressing the first question proposed by the authors in \cite[Remark 1.5]{GKS25}. One can see that the best Hardy constant $\gamma_{\rm{H}}$ in the Hardy inequality $(-\Delta_{\mathbb{N}})^{\sigma}-\gamma |n|^{-2\sigma} \geq 0$ on $\mathbb{N}$, which can be defined as
$$ \gamma_{\rm{H}}= \inf \left \{\frac{(-\Delta_{\mathbb{N}})^{\sigma}  f,f\rangle_{\ell^2(\mathbb{N})}}{\langle f,f\rangle_{\ell^2(\mathbb{N},|n|^{-2\sigma})}}\,, f \in C_c(\mathbb{N})  \right\} \,,
$$
is bounded from above by $C_{\sigma}$. Finding $\gamma_{\mathrm{H}}$ explicitly seems to be challenging and remains open for future investigation. In this context, it is relevant to also point out that the constant  $C_{\sigma}$ is in fact the best Hardy constant at infinity, which is defined by $$ \gamma_{\rm{H}}^{\infty}= \sup_{K \Subset \mathbb{N}}\inf \left \{\frac{(-\Delta_{\mathbb{N}})^{\sigma}  f,f\rangle_{\ell^2(\mathbb{N})}}{\langle f,f\rangle_{\ell^2(\mathbb{N},|n|^{-2\sigma})}}\,, f \in C_c(\mathbb{N}\setminus K)  \right\} \,.
$$
 In fact $\gamma_{\rm{H}}^{\infty}$ is the bottom of the (essential) spectrum of the weighted operator $|n|^{2\sigma}(-\Delta_{\mathbb{N}})^{\sigma}$ in $\ell^2(\mathbb{N},|n|^{-2\sigma})$. Both the constants $\gamma_{\rm{H}}$, $\gamma_{\rm{H}}^{\infty}$ and their estimates play a significant role in the analysis of Hardy-type inequalities; for instance, see \cite{DDP} and the references therein. 



Another interesting remark is that the optimal weight $W_{1}^{\text{op}}$ we find in Theorem \ref{Theorem:Hardy} for $\sigma=1$ is different from the one obtained in \cite[Theorem 7.3]{KPP18}, and the ones obtained in \cite[Corollary 12]{KLS}, all of them are also optimal. Recall that
\begin{equation}
    W^{\operatorname{KPP}}(n)=2-\sqrt{1+\frac{1}{n}}-\sqrt{1-\frac{1}{n}}=\frac{1}{4n^2}+\frac{5}{64n^4}+O(n^{-6})
\end{equation}
\begin{equation}
    W_{1}^{\text{op}}(n)=\frac{1}{4}\frac{1}{n^2-\frac{9}{16}}=\frac{1}{4n^2}+\frac{9}{64n^4}+O(n^{-6})\,.
\end{equation}
Note that the weights are not comparable as $W^{\operatorname{KPP}}(1)>W_{1}^{\text{op}}(1)$ and $W_{1}^{\text{op}}(n)> W^{\operatorname{KPP}}(n)$ for large $n$. This fact highlights the non-uniqueness of optimal Hardy-weights, and raises the question of finding the complete class of optimal Hardy-weights.
% This fact highlights the non-uniqueness of the definition of optimality described in this paper, and raises the question of finding the complete class of functions that fulfil our criteria.
Even though $ W_{1}^{\text{op}}$ is asymptotically larger than $W^{\operatorname{KPP}}$ at order $n^{-4}$, it does not conflict with the fact that $W^{\operatorname{KPP}}$ is optimal at infinity as well, since Remark \ref{Rmk:Asympt-Optimal} remains true for both weights.

Finally, it is surprising that the optimal constant $C_{\sigma}$ appearing in the discrete fractional Hardy inequality on the discrete half-line does not coincide with its continuum counterpart obtained in \cite{BD}: 
\begin{equation*}
    \gamma_{\operatorname{BD}}=\frac{2\Gamma(1-\sigma)\Gamma(\sigma+1/2)-4^\sigma}{4^\sigma\sigma \sqrt{\pi}}.
\end{equation*}
This contrasts with the full-line case, where the best constant in the Hardy inequality for discrete fractional Laplacian is equal to the one corresponding to the continuum case (see \cite{KN23} and \cite{Herbst} respectively).
% Together with the different criticality transition found in \cite{GKS25}, the situation for the fractional Laplacian in the half-line contrasts with the full-line case, where the criticality transition and the best constant for the Hardy-weight are the same for the continuous and discrete fractional Laplacian.

{\textbf{Open Question.}}  We  know from \cite{GKS25} that $(-\Delta_\mathbb{N})^\sigma$ is subcritical for $\sigma\in(0,3/2)$, but we obtain optimal Hardy-weights for $\sigma\in(0,1]$.  So the next natural question is to find an optimal Hardy-weight for the remaining exponents in the range of subcriticality. The main obstacle we face when using our approach is that the operator no longer behaves as a graph Laplacian, since the kernel $-\widetilde{\mathcal{K}}^\sigma_{m,n}$ is no longer nonnegative for $\sigma>1$. 
% In this case, the lack of maximum principle for the operator hinders the development of the criticality theory. 
A different strategy is thus needed in order to tackle this problem for $\sigma\in(1,3/2)$.




