\section{Computations}{\label{comp}}
This appendix is devoted to proving several facts about Gamma functions and binomial coefficients to aid us in our computations. See \cite{AR} for general properties of Gamma functions. %cite NIST chap 5
\begin{lemma}
\label{sum1}
    Let $\sigma\in\mathbb{R}$ and $n\in\mathbb{N}$. Then:
    \begin{equation}
        \sum_{m=0}^{n-1}(-1)^{m}\left(\begin{matrix} 2\sigma\\\sigma+m\end{matrix}\right)=\frac{\Gamma(2\sigma)}{\Gamma(\sigma)\Gamma(\sigma+1)}+(-1)^{n-1}\frac{\Gamma(2\sigma)}{\Gamma(\sigma+n)\Gamma(\sigma-n+1)}
    \end{equation}
\end{lemma}
\begin{proof}
    By induction, for $n=1$:
    \begin{equation*}
        \left(\begin{matrix} 2\sigma\\\sigma\end{matrix}\right)=\frac{\Gamma(2\sigma+1)}{\Gamma(\sigma+1)\Gamma(\sigma+1)}=\frac{2 \sigma \Gamma(2\sigma)}{\sigma \Gamma(\sigma)\Gamma(\sigma+1)}=\frac{2  \Gamma(2\sigma)}{\Gamma(\sigma)\Gamma(\sigma+1)}.
    \end{equation*}
    Now assume
    \begin{equation*}
         \sum_{m=0}^{n-2}(-1)^{m}\left(\begin{matrix} 2\sigma\\\sigma+m\end{matrix}\right)=\frac{\Gamma(2\sigma)}{\Gamma(\sigma)\Gamma(\sigma+1)}+(-1)^{n-2}\frac{\Gamma(2\sigma)}{\Gamma(\sigma-n+2)\Gamma(\sigma+n-1)},
    \end{equation*}
    then
    \begin{align*}
         &\sum_{m=0}^{n-1}(-1)^{m}\left(\begin{matrix} 2\sigma\\\sigma+m\end{matrix}\right)\\
         &=\frac{\Gamma(2\sigma)}{\Gamma(\sigma)\Gamma(\sigma+1)}+(-1)^{n-2}\frac{\Gamma(2\sigma)}{\Gamma(\sigma-n+2)\Gamma(\sigma+n-1)}+(-1)^{n-1}\frac{\Gamma(2\sigma+1)}{\Gamma(\sigma+n)\Gamma(\sigma-n+2)}\\
         &=\frac{\Gamma(2\sigma)}{\Gamma(\sigma)\Gamma(\sigma+1)}+(-1)^{n-2}\frac{\Gamma(2\sigma)(\sigma+n-1)}{\Gamma(\sigma-n+2)\Gamma(\sigma+n)}+(-1)^{n-1}\frac{2\sigma\Gamma(2\sigma)}{\Gamma(\sigma+n)\Gamma(\sigma-n+2)}\\
         &=\frac{\Gamma(2\sigma)}{\Gamma(\sigma)\Gamma(\sigma+1)}+(-1)^{n-1}\frac{\Gamma(2\sigma)}{\Gamma(\sigma+n)\Gamma(\sigma-n+2)}\left(\sigma-n+1\right)\\
         &=\frac{\Gamma(2\sigma)}{\Gamma(\sigma)\Gamma(\sigma+1)}+(-1)^{n-1}\frac{\Gamma(2\sigma)}{\Gamma(\sigma+n)\Gamma(\sigma-n+1)},
    \end{align*}
    as desired.
\end{proof}

\begin{lemma}
\label{sum2}
    Let $\sigma\in\mathbb{R}$ and $n\in\mathbb{N}$. Then:
    \begin{equation}
        \sum_{m=0}^{n-1}(-1)^{m+1}\left(\begin{matrix} 2\sigma\\\sigma+m+1\end{matrix}\right)=-\frac{\Gamma(2\sigma)}{\Gamma(\sigma)\Gamma(\sigma+1)}+(-1)^{n}\frac{\Gamma(2\sigma)}{\Gamma(\sigma-n)\Gamma(\sigma+n+1)}.
    \end{equation}
\end{lemma}
\begin{proof}
    Repeat the computation for Lemma \ref{sum1}.
\end{proof}
We also have the following.


\begin{lemma}\label{potential-sum}
   Let $\sigma\in\mathbb{R}$ and $n\in\mathbb{N}$. Then:
\begin{equation}
\label{eq:A3}
     \sum_{m=-n+1}^{n} (-1)^{m} \left(\begin{matrix}
 2\sigma\\
\sigma+m
\end{matrix} 	
 \right)= -2 (-1)^n n \frac{\Gamma(2\sigma)}{\Gamma(1+\sigma-n)\Gamma(1+\sigma+n)}.
\end{equation}
\end{lemma}
\begin{proof} 
We expand the left hand side of \eqref{eq:A3} to obtain
    \begin{align*}
    &\sum_{m=-n+1}^{n} (-1)^{m} \left(\begin{matrix}
 2\sigma\\
\sigma+m
\end{matrix} 	
 \right) =\sum_{m=0}^{n-1} (-1)^{m+1} \left(\begin{matrix}
 2\sigma\\
\sigma+m+1
\end{matrix} 	
 \right)+\sum_{m=0}^{n-1} (-1)^{m} \left(\begin{matrix}
 2\sigma\\
\sigma+m
\end{matrix} 	
 \right)\\
 &\quad= (-1)^{n}\left(\frac{\Gamma(2\sigma)}{\Gamma(\sigma-n)\Gamma(\sigma+n+1)}-\frac{\Gamma(2\sigma)}{\Gamma(\sigma+n)\Gamma(\sigma-n+1)}\right)\\
 &\quad= (-1)^{n}\Gamma(2\sigma)\frac{\Gamma(\sigma+n)\Gamma(\sigma-n+1)-\Gamma(\sigma-n)\Gamma(\sigma+n+1)}{\Gamma(\sigma-n)\Gamma(\sigma+n+1)\Gamma(\sigma+n)\Gamma(\sigma-n+1)}\\
 &\quad=(-1)^{n}\Gamma(2\sigma)\frac{(\sigma-n)-(\sigma+n)}{\Gamma(\sigma+n+1)\Gamma(\sigma-n+1)}=-2(-1)^{n}n\frac{\Gamma(2\sigma)}{\Gamma(\sigma+n+1)\Gamma(\sigma-n+1)}
\end{align*}
where we used Lemmas \ref{sum1} and \ref{sum2} in the second equality.
\end{proof}

\begin{lemma}\label{simpriesz}
     Let $\alpha\in\mathbb{R}$ and $n\in\mathbb{N}$. Then:
     \begin{equation*}
          \left[\frac{\Gamma(\alpha-n-1)}{\Gamma(-n-\alpha)}-\frac{\Gamma(\alpha+n-1)}{\Gamma(n-\alpha)}\right]=\frac{\Gamma(n+\alpha-1)}{\Gamma(n-\alpha+2)}2n(2\alpha-1).
     \end{equation*}
\end{lemma}
\begin{proof}
    We start with the first term
    \begin{equation*}
        \frac{\Gamma(\alpha-n-1)}{\Gamma(-n-\alpha)}=\frac{\sin(\pi(\alpha+n+1))\Gamma(\alpha+n+1)}{\sin(\pi(2+n-\alpha))\Gamma(2+n-\alpha)}=\frac{(-1)^{n+1}}{(-1)^{-n-1}}\frac{\sin\pi\alpha}{\sin\pi\alpha}\frac{\Gamma(\alpha+n+1)}{\Gamma(2+n-\alpha)}.
    \end{equation*}
    Now we put everything together
    \begin{align*}
         &\left[\frac{\Gamma(\alpha-n-1)}{\Gamma(-n-\alpha)}-\frac{\Gamma(\alpha+n-1)}{\Gamma(n-\alpha)}\right]= \left[\frac{\Gamma(\alpha+n+1)}{\Gamma(2+n-\alpha)}-\frac{\Gamma(\alpha+n-1)}{\Gamma(n-\alpha)}\right]\\
         &=\frac{\Gamma(\alpha+n+1)\Gamma(n-\alpha)-\Gamma(\alpha+n-1)\Gamma(2+n-\alpha)}{\Gamma(2+n-\alpha)\Gamma(n-\alpha)}\\
         &=\frac{(n+\alpha)(n+\alpha-1)\Gamma(\alpha+n-1)\Gamma(n-\alpha)-(n-\alpha+1)(n-\alpha)\Gamma(\alpha+n-1)\Gamma(n-\alpha)}{\Gamma(2+n-\alpha)\Gamma(n-\alpha)}\\
         &=\frac{\Gamma(\alpha+n-1)}{\Gamma(2+n-\alpha)}\left[(n+\alpha)(n+\alpha-1)-(n-\alpha+1)(n-\alpha)\right]=\frac{\Gamma(n+\alpha-1)}{\Gamma(n-\alpha+2)}2n(2\alpha-1),
    \end{align*}
    as desired.
\end{proof}

