A widely used approach in the modeling of these processes is based on rate equations, which track the time evolution of cluster size distributions. The first equation of this kind, modeling the coagulation phenomenon, was introduced by the Polish physicist M.~Smoluchowski in his seminal papers \cite{SMOL 1916, SMOL 1917}. The coagulation equation, both with and without linear fragmentation, has been extensively studied over the past few decades, the size variable being either discrete or continuous; for a detailed and thorough review, see \cite{BLL 2019} and the references therein.

In \cite{PhL 2001}, Lauren\c{c}ot and Wrzosek studied the discrete coagulation equation with nonlinear breakage, marking it as the first mathematical study addressing nonlinear breakage. More precisely, denoting by $\psi_i(t)$, $i \ge 1$, the number density of $i$-clusters at time $t \geq 0$, the discrete coagulation equation with nonlinear breakage reads
 \begin{subequations} \label{FNLDCCBE}
\begin{align}
\frac{d\psi_i}{dt}  &=\frac{1}{2} \sum_{j=1}^{i-1} p_{j,i-j} \Gamma_{j,i-j} \psi_j \psi_{i-j}-\sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i \psi_j\nonumber\\
&\quad + \frac{1}{2} \sum_{j=i+1}^{\infty} \sum_{k=1}^{j-1}(1-p_{j-k,k}) \Phi_{j-k,k}^i \Gamma_{j-k,k} \psi_{j-k} \psi_k ,  \hspace{.5cm} i \ge 1, \label{NLDCCBE}\\
\psi_i(0) &= \psi_i^{\rm{in}}, \hspace{.5cm} i \ge 1. \label{NLDCCBEIC}
\end{align}
\end{subequations}
Here, $\Gamma_{i,j}$ denotes the rate of collisions between $i$-clusters and $j$-clusters, while $p_{i,j}$ represents the probability that two colliding clusters with respective sizes $i$ and $j$ merge into a single $i+j$-cluster. The complementary probability, $(1 - p_{i,j})$, corresponds to cluster fragmentation, possibly involving a transfer of matter. The coefficients $(\Gamma_{i,j})$ and $(p_{i,j})$ satisfy the following symmetry property
\begin{equation*}
	0\le p_{i,j} = p_{j,i} \le 1, \qquad \Gamma_{i,j}=\Gamma_{j,i} \geq 0,\qquad i,j\ge 1, %\label{ASYMM}
\end{equation*}
 while  $\{\Phi_{i,j}^s, s=1,2,...,i+j-1\}$  is the size distribution function of the fragments resulting from the collision between a $i$-cluster and a $j$-cluster and satisfies 
\begin{equation}
	\begin{split}
		\Phi_{i,j}^s = \Phi_{j,i}^s & \geq 0, \quad 1\le s \le i+j-1,  \\ 
		\sum_{s=1}^{i+j-1} s \Phi_{i,j}^s & = i+j,
	\end{split} \hspace{1cm} i,j\ge 1. \label{LMC}
\end{equation}
The second identity in~\eqref{LMC} ensures mass conservation during each collisional breakage event, so that conservation of matter is expected throughout time evolution. In terms of the number densities $(\psi_i)_{i\ge 1}$, mass conservation reads
\begin{equation}
	\sum_{i=1}^{\infty} i\psi_i(t) = \sum_{i=1}^{\infty} i\psi_i^{\rm{in}}, \qquad t\ge 0. \label{MCC}
\end{equation}
The first term in~\eqref{NLDCCBE} accounts for the formation of $i$-clusters through coagulation, with a rate determined by the effective coagulation kernel $(p_{i,j}\Gamma_{i,j})$, whereas the second term represents the depletion of $i$-mers due to collisions with other clusters in the system. Finally, the third term describes the creation of $i$-clusters resulting from the collision and subsequent breakup of larger clusters. It is worth noting that the assumption~\eqref{LMC} allows for mass transfer between the colliding clusters, meaning that some of the resulting particles may be larger than either of the incoming particles. In other words, mass transfer between the colliding clusters may occur and the mean size of the system of clusters does not necessarily decrease during the time evolution. Let us also mention here that, when $p_{i,j} = 1$, the equation~\eqref{FNLDCCBE} reduces to the classical Smoluchowski coagulation equation.  In \cite{PhL 2001}, the authors investigate the existence, uniqueness, mass conservation, and long term behavior of weak solutions to~\eqref{FNLDCCBE} under reasonable assumptions on the collision kernel and the daughter distribution function. The study performed in \cite{PhL 2001} also explores the occurrence of the gelation phenomenon; that is, the breakdown of the identity~\eqref{MCC} in finite time. In \cite{AG 24}, the previous work is extended to investigate classical solutions and explore various additional properties. The continuous counterpart of~\eqref{FNLDCCBE} has undergone significant study in recent years; see \cite{PKB 2020, PKB 2020I, AKG 2021}.

In the absence of coagulation ($p_{i,j}=0$), the equation~\eqref{FNLDCCBE} becomes the discrete nonlinear fragmentation equation and reads 
\begin{subequations} \label{FNLDCBE}
\begin{align}
	\frac{d\psi_i}{dt}  &=\frac{1}{2} \sum_{j=i+1}^{\infty} \sum_{k=1}^{j-1} \Phi_{j-k,k}^i \Gamma_{j-k,k} \psi_{j-k} \psi_k -\sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i \psi_j,  \qquad i \ge 1, \label{NLDCBE}\\
	\psi_i(0) &= \psi_i^{\rm{in}}, \qquad i \ge 1. \label{NLDCBEIC}
\end{align}
\end{subequations}
In \cite{AGP 24}, the well-posedness of~\eqref{FNLDCBE} is studied for a broad class of collision kernels and daughter distribution functions which does not exclude mass transfer. In addition, non-trivial stationary solutions are constructed, a result which is closely related to mass exchange during collisions. The continuous version of~\eqref{FNLDCBE} is investigated in \cite{JG 2025}.

A condition on the daughter distribution function $(\Phi_{i,j}^s)$ excluding mass tranfer is provided in \cite{CHNG 90} and reads  
\begin{equation*}
\Phi_{i,j}^s = \textbf{1}_{[s, \infty)} (i) \varphi_{s,i;j} + \textbf{1}_{[s, \infty)} (j) \varphi_{s,j;i} %\label{NMT}
\end{equation*}
for $i,j\ge 1$ and $1\le s\le i+j-1$, where $\textbf{1}_{[s, \infty)}$ denotes the characteristic function of the interval $[s,\infty)$. In that case, the system~\eqref{FNLDCBE} reduces to
\begin{subequations} \label{FSNLBE}
\begin{align}
	\frac{d\psi_i}{dt} &= \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty}   \varphi_{i,j;k}\Gamma_{j,k} \psi_j \psi_k - (1-\delta_{i,1}) \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i \psi_j, \qquad i\ge 1, \label{SNLBE}\\
	\psi_i(0) &=\psi_{i}^{\rm{in}}, \hspace{.5cm} i\ge 1,\label{SNLBEIC}
\end{align}
\end{subequations}
where $\delta_{1,1}=1$, $\delta_{i,1}=0$, $i\ge 2$, and $\{\varphi_{i,j;k}, 1\leq i \leq j-1\}$ denotes the distribution function of the fragments resulting from the collision of a $j$-cluster with a $k$-cluster and satisfies the conservation of matter
\begin{equation}
	\sum_{i=1}^{j-1} i \varphi_{i,j;k} = j, \hspace{.5cm} j\geq 2,~~~ k\geq 1. \label{LMC1}
\end{equation}
 Since each cluster fragments into smaller clusters after a collision, see Figure~\ref{Frag3}, it is expected that, in the large time, only $1$-clusters will remain.

Considerable attention has been given to the study of the continuous version of~\eqref{FSNLBE}, focusing on its analytical solutions. In \cite{CHNG 90}, Cheng and Redner investigate the asymptotic behavior of various classes of models, demonstrating that certain models can be transformed into the linear fragmentation equation through a suitable rescaling of time. This transformation is extensively applied in \cite{EP 2007} to examine the nonlinear fragmentation equation with product collision kernels, addressing the existence and non-existence of solutions, as well as the emergence of finite time singularities. Further insights into the dynamics of the models analyzed in \cite{CHNG 90} are provided by Krapivsky and Ben-Naim in \cite{Krapivsky 2003}. Additionally, the nonlinear fragmentation equation with both product and sum collision kernels is studied by Kostoglou and Karabelas in \cite{Kostoglou 2000}, employing a combination of analytical solutions and asymptotic expansions; see also \cite{Kostoglou 2006}. From a mathematical perspective, the continuous version has been examined in \cite{AKG 2021I, AKG 2024}, with a focus on the analysis of existence, non-existence, and the occurrence of the shattering phenomenon.

As for the discrete setting, the existence of classical solutions to~\eqref{FSNLBE} is established in \cite{AGP 24I} for collision kernels having at most quadratic growth
\begin{equation}
	\Gamma_{i,j} \le A i j, \qquad i,j\ge 1, \label{QG}
\end{equation}
 and a broad class of fragment distribution functions. Various other properties, including uniqueness, differentiability, moment propagation, and large time behavior, are also investigated. Motivated by the recent study \cite{PhL 25}, where the Redner–ben-Avraham–Kahng cluster system, also known as the cluster eating system, is investigated without imposing growth conditions on the kinetic coefficients, the aim of this work is to show that the growth condition~\eqref{QG} can be relaxed and that global mild solutions to~\eqref{FSNLBE} can be constructed assuming only the collision kernel $(\Gamma_{i,j})$ to be non-negative and symmetric; that is,
 \begin{equation}  
 	0\le \Gamma_{i,j} =\Gamma_{j,i}, \qquad i,j\ge 1. \label{ACond}
 \end{equation}
 However, this sole assumption does not seem to be sufficient to derive an existence result for~\eqref{FSNLBE} and, as in \cite{AGP 24I}, it requires to be supplemented with an additional assumption on the fragment distribution function, besides~\eqref{LMC1}: there exist non-negative constants $\alpha_0$ and $\alpha_1$ such that
\begin{equation}
	\varphi_{i,j;k} \leq \alpha_0 + \alpha_1 \varphi_{i,k;j} \quad \text{for all } 1 \leq i \leq j-1, \,\, k \geq j. \label{bCond}
\end{equation}

%%%%%%%%%%
\begin{remark}\label{RMK2}
	It is important to note that the assumption~\eqref{bCond} holds for a wide range of fragment distribution functions. Indeed, typical examples include bounded fragment distribution functions such as 
	\begin{equation}
		\varphi_{i,j;k} = \frac{i^\nu j}{\displaystyle{\sum_{l=1}^{j-1} l^{1+\nu}}}, \qquad 1 \le i \le j-1, \quad j \ge 2, \quad k \ge 1, \label{FDF:EX1}
	\end{equation}
	for $\nu\ge -1$, which reduces to the uniform distribution 
	\begin{equation*}
		\varphi_{i,j;k} = \frac{2}{j - 1}, \qquad 1 \le i \le j-1, \quad j \ge 2, \quad k \ge 1,
	\end{equation*}
	for $\nu=0$. It also includes unbounded fragment distribution functions like
	\begin{equation*}
		\varphi_{i,j;k} = j \delta_{i,1}, \qquad 1 \le i \le j-1, \quad j \ge 2, \quad k \ge 1,
	\end{equation*}
	which satisfies~\eqref{bCond} with $(\alpha_0,\alpha_1)=(0,1)$, the fragment distribution function~\eqref{FDF:EX1} for $\nu<-1$, which satisfies~\eqref{bCond} with 
	\begin{equation*}
		\alpha_0 = 0, \quad \alpha_1 = \left\{ \begin{array}{ll}
			2^{2+\nu}, & \nu\in [-2,-1), \\
			\displaystyle{\sum_{l=1}^\infty l^{1+\nu}}, & \nu<-2,
		\end{array} \right.
	\end{equation*} 
	and
	\begin{equation}
		\varphi_{i,j;k} = \frac{1}{2^i} \frac{j 2^{j-1}}{2^j - j - 1}, \qquad 1 \le i \le j-1, \quad j \ge 2, \quad k \ge 1, \label{FDF:EX2}
	\end{equation}
	which satisfies~\eqref{bCond} with $\alpha_0=\alpha_1=1$, see \Cref{LEM:EX2} below.
\end{remark}
%%%%%%%%%%

As we shall see below, assumptions~\eqref{LMC1}, \eqref{ACond}, and~\eqref{bCond} allow us to construct mild solutions to~\eqref{FSNLBE} for a large class of initial conditions, including all non-negative sequences having a finite superlinear moment. To be more precise, for $\sigma\ge 0$, let us define the Banach space
\begin{equation*}
	Y_{\sigma} := \left\{ \psi =(\psi_i)_{i\ge 1} :~~~~~ \psi_i \in \mathbb{R}, \ \sum_{i=1}^{\infty} i^{\sigma} |\psi_i| < \infty \right\}
\end{equation*}
with the norm  
\begin{equation*}
	\|\psi\|_{\sigma} := \sum_{i=1}^{\infty} i^{\sigma} |\psi_i|, \qquad \psi\in Y_\sigma,
\end{equation*}
along with its positive cone 
\begin{equation*}
	Y_{\sigma, +} := \left\{ \psi \in Y_{\sigma} : \psi_i \geq 0 \text{ for each } i \ge 1 \right\}.
\end{equation*}
In particular, for a non-negative cluster distribution $\psi$, the norm $\|\psi\|_0$ represents the total number of clusters, while the norm $\|\psi\|_1$ accounts for the total mass of the clusters, so that the conservation of mass~\eqref{MCC} is equivalent to $\|\psi(t)\|_1=\|\psi^{\rm{in}}\|_1$ for all $t\ge 0$. We next introduce the set $\mathcal{G}_1$ of non-negative and convex functions $G \in C^2([0,\infty))$ such that $G(0)=G'(0)=0$ and $G'$ is a concave function, as well as 
\begin{equation*}
	\mathcal{G}_{1,\infty} := \left\{ G\in \mathcal{G}_1\ :\ \lim_{\zeta\to\infty} \frac{\zeta G'(\zeta) - G(\zeta)}{\zeta} = \infty \right\}.
\end{equation*}
It readily follows from the definition of $\mathcal{G}_{1, \infty}$ and l'Hospital rule that any $G\in\mathcal{G}_{1, \infty}$ satisfies
\begin{equation}
	\lim_{\zeta \to \infty} G'(\zeta) = \lim_{\zeta\to \infty} \frac{G(\zeta)}{\zeta} = \infty. \label{G0:Cond0}
\end{equation} 

%%%%%%%%%%
\begin{remark} \label{RMK3}
	One can check that the functions $z\mapsto z^m$ with $m\in (1,2]$ and $z\mapsto z \big[\ln\big(e^{m-1}+z\big)\big]^m$ with $m>1$ belong to $\mathcal{G}_{1,\infty}$, but not $z\mapsto \ln(1+z)$ (though it belongs to $\mathcal{G}_1$ and satisfies~\eqref{G0:Cond0}).
\end{remark}
%%%%%%%%%%

With this notation, we may summarize the main contribution of this work as follows: given a collision kernel satisfying the symmetry and non-negativity condition~\eqref{ACond} and a fragment distribution function satisfying~\eqref{LMC1} and~\eqref{bCond}, we construct a global mild solution to~\eqref{FSNLBE} for any initial condition $\psi^{\rm{in}} \in Y_{1,+}$ such that
\begin{equation*}
	\sum_{i=1}^\infty G_0(i) \psi_i^{\rm{in}}< \infty
\end{equation*}
for some function $G_0\in \mathcal{G}_{1,\infty}$. In particular, the price to pay for having no growth condition on the collision kernel is that we cannot handle arbitrary initial data in $Y_{1,+}$. Still, the existence result applies to any initial condition $\psi^{\rm{in}}$ which belongs to $Y_{\sigma,+}$ for some $\sigma>1$.

Before presenting the existence result, we first recall the definition of a global mild solution to~\eqref{FSNLBE} in $Y_{1,+}$.

%%%%%%%%%%
\begin{definition} \label{DEF}
Consider $\psi^{\rm{in}} \in  Y_{1,+}$. A global mild solution $\psi=(\psi_i)_{i\ge 1}$ to~\eqref{FSNLBE} is a sequence of non-negative functions in $L^{\infty}((0,\infty),Y_{1,+})$ satisfying, for each $i\ge 1$ and $t>0$,
\begin{itemize}
\item[(i)] $\psi_i\in C([0,\infty))$;
\item[(ii)] 
\begin{equation*}
	 \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} \psi_j \psi_k \in L^1((0,t)), \qquad  \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i \psi_j \in L^1((0,t));
\end{equation*}
\item[(iii)] 
\begin{equation}
\begin{split}
	\psi_i(t) & = \psi_i^{\rm{in}} + \int_0^t \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) ds \\
	& \qquad - (1-\delta_{i,1}) \int_0^t \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i(s) \psi_j(s) ds. 
\end{split} \label{IF}
\end{equation}
\end{itemize}
\end{definition}
%%%%%%%%%%

%%%%%%%%%%
 \begin{theorem} \label{TH1}
Assume that the kinetic coefficients $(\Gamma_{i,j})$  and $(\varphi_{i,j;k})$ satisfy the assumptions~\eqref{ACond}, \eqref{LMC1}, and~\eqref{bCond}. Consider $\psi^{\rm{in}}\in Y_{1,+}$ such that 
\begin{equation}
		\mathcal{J}_0 := \sum_{i=1}^{\infty} G_0(i) \psi_i^{\rm{in}} < \infty \label{G0:Cond1}
\end{equation}
for some $G_0\in \mathcal{G}_{1,\infty}$. Then there exists at least one global mild solution $\psi$ to~\eqref{FSNLBE} in the sense of Definition~\ref{DEF} which additionally satisfies the mass conservation~\eqref{MCC}
\begin{equation*}
	\|\psi(t)\|_1 = \|\psi^{\rm{in}}\|_1, \qquad t\ge 0.
\end{equation*}.

Moreover, for any non-negative sequence $(\Lambda_i)_{i\ge 1}$ such that the sequence $(\Lambda_i/i)_{i\ge 1}$ is non-decreasing and 
\begin{equation}
	M_{\Lambda}(\psi^{\mathrm{in}}) := \sum_{i = 1}^\infty \Lambda_i \psi_i^{\mathrm{in}} < \infty, \label{LambdaMom}
\end{equation}
then the mild solution $\psi = (\psi_i)_{i \ge 1}$ constructed above satisfies the uniform-in-time tail estimate
\begin{equation}
	\sum_{i = r}^\infty \Lambda_i \psi_i(t) \le \sum_{i = r}^\infty \Lambda_i \psi_i^{\mathrm{in}} \quad \text{for all } t > 0 \;\text{ and }\; r \ge 1. \label{TailIneq}
\end{equation}
\end{theorem}
%%%%%%%%%%

We next identify an additional simple structure condition on the kinetic coefficients $(\Gamma_{i,j})_{i,j \ge 1}$ which, along with the boundedness of the fragment distribution function, allows us to show that the mild solution to~\eqref{SNLBE} constructed in \Cref{TH1} is actually a classical solution.

%%%%%%%%%%
 \begin{theorem} \label{TH2}
 	Assume that there is a non-negative sequence $(\Lambda_i)_{i\ge 1}$ with $\Lambda_1\ge 1$ such that the sequence $(\Lambda_i/i)_{i\ge 1}$ is non-decreasing and the kinetic coefficients $(\Gamma_{i,j})$ satisfies
 	\begin{equation}
 		0 \le \Gamma_{i,j} = \Gamma_{j,i} \le \Lambda_i \Lambda_j, \qquad i,j\ge 1. \label{ACond1}
 	\end{equation}
 	Assume also that $(\varphi_{i,j;k})$ satisfy the assumptions~\eqref{LMC1} and~\eqref{bCond} with $\alpha_1=0$; that is,
 	\begin{equation}
 		\varphi_{i,j;k} \leq \alpha_0, \qquad 1 \leq i \leq j-1, \quad j \geq 2, \quad k \geq 1. \label{bCond3}
 	\end{equation}
 	Finally, assume that the initial condition $\psi^{\rm{in}}\in Y_{1,+}$ satisfies~\eqref{G0:Cond1} for some function $G_0\in\mathcal{G}_{1,\infty}$, as well as~\eqref{LambdaMom}. Then there is at least one mass conserving classical solution $\psi = (\psi_i)_{i \ge 1}$ to~\eqref{FSNLBE}; that is, for each $i\ge 1$, $\psi_i \in C^1([0,\infty))$,
	\begin{equation}
		(1-\delta_{i,1}) \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_{i} \psi_j \in C([0,\infty)), \qquad \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k}\Gamma_{j,k} \psi_j \psi_k \in C([0,\infty)),\label{CNT}
\end{equation}
and~\eqref{SNLBE} is satisfied pointwise for all $i \ge 1$. Furthermore, $\psi$ satisfies 
\begin{equation}
	M_{\Lambda}(\psi(t)) := \sum_{i=1}^{\infty}\Lambda_i\psi_i(t) \le M_{\Lambda}(\psi^{\rm{in}}), \qquad t\ge 0. \label{HMB}
\end{equation}
\end{theorem}
%%%%%%%%%%

The significant role of the structural assumption~\eqref{ACond1} in the existence theory for coagulation-fragmentation equations is already observed in \cite{PhL 1999, PhL 25}. Taking $\Lambda_i=\sqrt{A} i$, $i\ge 1$, the collision rate satisfies~\eqref{QG} and we recover the existence result established in \cite[Theorem~2.1]{AGP 24I} by a different approach, but for a smaller set of initial conditions.

We supplement \Cref{TH2} with a uniqueness result under the assumption of the finiteness of a higher moment of the initial condition. The proof relies on an estimate on the difference of two solutions in a suitably chosen weighted space, a classical approach to uniqueness for coagulation-fragmentation equations, see \cite[Section~8.2.5]{BLL 2019} and the references therein.

%%%%%%%%%%
\begin{theorem} \label{TH3}
Assume that the hypotheses of Theorem \ref{TH2} hold, and let $\psi^{\mathrm{in}} \in Y_{1,+}$ satisfy
\begin{equation}
M_{\Lambda^2}(\psi^{\mathrm{in}}) := \sum_{i=1}^{\infty} \Lambda_i^2 \psi_i^{\mathrm{in}} < \infty. \label{UNIC}
\end{equation}
Then there exists a unique classical solution $\psi = (\psi_i)_{i \ge 1}$ to~\eqref{FSNLBE} such that
\begin{equation}
M_{\Lambda^2}(\psi(t)) := \sum_{i=1}^\infty \Lambda_i^2 \psi_i(t) \le M_{\Lambda^2}(\psi^{\mathrm{in}}), \quad \text{for all } t \ge 0. \label{UNME}
\end{equation}
\end{theorem}
%%%%%%%%%%

\medskip

The paper is organized as follows. \Cref{SEC2} is dedicated to establishing the proof of \Cref{TH1}, employing a compactness method and the approximation of the system~\eqref{FSNLBE} by finite systems of ordinary differential equations. \Cref{SEC3} is devoted to establishing the existence of classical solutions, which is derived from \Cref{TH1} and appropriate moment estimates. The uniqueness of classical solutions is then dealt with in \Cref{SEC4}. In \Cref{SEC5}, we investigate the asymptotic behavior of solutions. Finally, \Cref{SEC6} presents the results of numerical simulations.

%%%%%%%%%%
%%%%%%%%%%
\section{\textbf{Existence of Mild Solutions}} \label{SEC2}
%%%%%%%%%%
%%%%%%%%%%

We fix $\psi^{\rm{in}}\in Y_{1,+}$ satisfying~\eqref{G0:Cond1} for some $G_0\in\mathcal{G}_{1,\infty}$. We then define 
\begin{align*}
	G_1(\zeta) =\frac{G_0(\zeta)}{\zeta}, \quad \zeta>0, \qquad G_1(0) =0,
\end{align*}
and recall that the properties of $G_0$ implies that $G_1$ is non-negative, increasing, and concave. In addition,
\begin{equation}
	\lim_{\zeta\to \infty} \zeta G_1'(\zeta) = \lim_{\zeta\to \infty} \frac{\zeta G_0'(\zeta) - G_0(\zeta)}{\zeta} = \infty,  \label{G0:Cond2}
\end{equation}
since $G_0\in\mathcal{G}_{1,\infty}$.


 For $p\ge 3$, let us next introduce the truncated version of~\eqref{FSNLBE} as
 \begin{subequations} \label{FTSNLBE}
 \begin{equation} 
 \frac{d\psi_i^p}{dt} = \sum_{j=i+1}^{p} \sum_{k=1}^{p}  \Gamma_{j,k} \varphi_{i,j;k} \psi_j^p \psi_k^p - (1-\delta_{i,1}) \sum_{j=1}^{p} \Gamma_{i,j} \psi_i^p \psi_j^p, \label{TSNLBE}
 \end{equation}
 \begin{equation}
 \psi_i^p(0) = \psi_i^{\rm{in}},\label{TSNLBEIC}
 \end{equation}
 \end{subequations}
where  $ i\in \{1,2,\cdots,p\}$. We first report the well-posedness of~\eqref{FTSNLBE} which is a classical consequence of the Cauchy-Lipschitz (or Picard-Lindel\"of) theorem, together with the mass conservation~\eqref{TMC}.

%%%%%%%%%%
\begin{lemma} \label{LEM1}
Let $p \geq 3$. There is a unique solution 
$\psi^p = (\psi^p_i)_{1 \leq i \leq p} \in C^1\big([0,\infty), [0,\infty)^p\big)$ to~\eqref{FTSNLBE}. For any sequence of non-negative real numbers $(\upsilon_i)_{i \geq 1}$, there holds
\begin{equation}
	\frac{d}{dt} \sum_{i=1}^{p} \upsilon_i \psi^p_i + \sum_{j=2}^{p} \sum_{k=1}^{p} \Big(\upsilon_j - \sum_{i=1}^{j-1} \upsilon_i \varphi_{i,j;k}\Big) \Gamma_{j,k} \psi^p_j \psi^p_k = 0. \label{TR:WF}
\end{equation}
In particular,
\begin{equation}
	\sum_{i=1}^p i \psi_i^p(t) = \sum_{i=1}^p i \psi_i^{\rm{in}} \le \|\psi^{\rm{in}}\|_1, \qquad t\in [0,\infty). \label{TMC}
\end{equation}
\end{lemma}
%%%%%%%%%%

\begin{proof}
	As already mentioned, the local well-posedness of~\eqref{FTSNLBE} and the componentwise non-negativity of the solution are straightforward consequences of the Cauchy-Lipschitz theorem since the right-hand side of~\eqref{FTSNLBE} is locally Lipschitz continuous and quasi-positive in $\mathbb{R}^p$. Next, a simple computation leads to the identity~\eqref{TR:WF} which, in turn, gives the mass conservation~\eqref{TMC} (with the choice $\upsilon_i=i$, $i\ge 1$) and thereby excludes finite time blowup of the solution.
\end{proof} 

Exploiting~\eqref{TR:WF} for a particular class of sequences $(\upsilon_i)_{i\ge 1}$ provides addition information on $\psi^p$.

%%%%%%%%%%
\begin{lemma}\label{LEM1B}
Let $p\ge 3$ and consider a sequence of non-negative real numbers $(\upsilon_i)_{i \geq 1}$ such that $(\upsilon_i/i)_{i \geq 1}$ is non-decreasing. Then, for $t\ge 0$, 
\begin{subequations}
\begin{equation}
    0 \leq \sum_{i=1}^{p} \upsilon_i \psi^p_i (t) \leq \sum_{i=1}^{p} \upsilon_i \psi^{\rm{in}}_i\label{LEM1:EST1},
\end{equation}
\begin{equation}
    0 \leq \int_0^t \sum_{j=2}^{p} \sum_{k=1}^{p} \Bigg(\upsilon_j - \sum_{i=1}^{j-1}\upsilon_i \varphi_{i,j;k}\Bigg) \Gamma_{j,k} \psi^p_j (s) \psi^p_k (s) \, ds \leq \sum_{i=1}^{p} \upsilon_i \psi^{\rm{in}}_i. \label{LEM1:EST2}
\end{equation}
\end{subequations}
 \end{lemma}
%%%%%%%%%%

\begin{proof}
Let $j\ge 2$ and $k\ge 1$. Since $(\upsilon_i)_{i\ge 1}$ is a non-negative sequence such that $(\upsilon_i/i)_{i\ge 1}$ is non-decreasing, we infer from~\eqref{LMC1} that
\begin{align*}
\upsilon_j-\sum_{i=1}^{j-1} \upsilon_i \varphi_{i,j;k}&= \upsilon_j- \sum_{i=1}^{j-1} \frac{\upsilon_i}{i} i \varphi_{i,j;k}\\
& \ge \upsilon_j-\frac{\upsilon_j}{j} \sum_{i=1}^{j-1} i \varphi_{i,j;k} = \upsilon_j - \upsilon_j = 0.
\end{align*}
Each term on the right hand side of~\eqref{TR:WF} is therefore non-negative and we obtain~\eqref{LEM1:EST1} and~\eqref{LEM1:EST2} after integration with respect to time.
\end{proof}

Several estimates on the solutions to~\eqref{FTSNLBE} can then be deduced from \Cref{LEM1}. Let us begin with a uniform control on the tail of the first moment.

%%%%%%%%%%
 \begin{lemma} \label{LEM2}
 For $p\ge 3$, $2 \le r\le p$, and $t\ge 0$, 
 \begin{align*}
 \sum_{i=r}^p i \psi_i^p(t) \le \sum_{i=r}^p i \psi_i^{\rm{in}} \le \sum_{i=r}^\infty i \psi_i^{\rm{in}}.
 \end{align*}
\end{lemma}
%%%%%%%%%%

\begin{proof}
We note that the sequence defined by 
\begin{align*}
\upsilon_i =0, \quad 1\le i \le r-1, \qquad \upsilon_i = i, \quad i\ge r,
\end{align*}
is non-negative and $(\upsilon_i/i)_{i \geq 1}$ is non-decreasing. We then apply \Cref{LEM1} with this sequence and deduce \Cref{LEM2} from~\eqref{LEM1:EST1}.
\end{proof}

We next turn to estimates on the reaction terms.

%%%%%%%%%%
\begin{lemma}\label{LEM3}
For $p> i\ge 1$ , there is $C_i := \mathcal{J}_0/[i G_1'(i+1)]>0$ such that
\begin{subequations}
\begin{equation}
	(1-\delta_{i,1}) \int_0^t \sum_{j=1}^p \Gamma_{i,j} \psi_i^p(s) \psi_j^p(s) ds \le C_i, \quad t\ge 0, \label{LEM3:EST1}
\end{equation}
\begin{equation}
\int_0^t \sum_{j=i+1}^p \sum_{k=1}^p \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \le C_i, \quad t\ge 0. \label{LEM3:EST2}
\end{equation}
\end{subequations}
\end{lemma}
%%%%%%%%%%

\begin{proof}
Since $(G_1(i))_{i\ge 1}= \Big(G_0(i)/i\Big)_{i\ge 1}$ is a non-decreasing sequence, we infer from~\eqref{G0:Cond1} and \Cref{LEM1} with $\upsilon_i = G_0(i)$, $i\ge 1$, that, for $t\ge 0$,
\begin{equation}
	\sum_{i=1}^p G_0(i) \psi_i^p(t) \le \mathcal{J}_0   \label{G:EST0}
\end{equation}
and
\begin{equation*}
	0\le \int_0^t \sum_{j=2}^p \sum_{k=1}^p \Bigg(G_0(j) - \sum_{i=1}^{j-1} G_0(i) \varphi_{i,j;k}\Bigg) \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \le \mathcal{J}_0,
\end{equation*}
which also reads, according to~\eqref{LMC1} and the definition of $G_1$,
\begin{equation}
	0\le \int_0^t \sum_{j=2}^p \sum_{k=1}^p \sum_{i=1}^{j-1} (G_1(j) -  G_1(i))i \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \le \mathcal{J}_0. \label{G:EST1}
\end{equation}
Owing to the concavity of $G_1$, 
\begin{equation}
	G_1(j) - G_1(l) \ge (j-l) G_1'(j), \quad 1\le l\le j-1, \label{G:ESTC}
\end{equation}
so that, using once more~\eqref{LMC1}, we have 
\begin{align*}
	\sum_{i=1}^{j-1} \big(G_1(j) - G_1(i)\big) i \varphi_{i,j;k} &\ge \sum_{i=1}^{j-1} i(j - i) G_1'(j) \varphi_{i,j;k} \\
	& = G_1'(j) \left( j^2 - \sum_{i=1}^{j-1} i^2 \varphi_{i,j;k} \right) \\
	& \ge G_1'(j) \left( j^2 - (j-1) \sum_{i=1}^{j-1} i \varphi_{i,j;k} \right) \\
	& = j G_1'(j).
\end{align*}
Combining the above lower bound with~\eqref{G:EST1}, we find
\begin{equation}
	\int_0^t \sum_{j=2}^p \sum_{k=1}^p j G_1'(j) \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) \, ds \le \mathcal{J}_0. \label{G:EST2}
\end{equation}
In particular, for $p\ge i\ge 2$ and $t>0$, we deduce from~\eqref{G:EST2} that
\begin{equation*}
	\mathcal{J}_0 \ge \int_0^t \sum_{k=1}^p i G_1'(i) \Gamma_{i,k} \psi_i^p(s) \psi_k^p(s) \, ds,
\end{equation*}
whence~\eqref{LEM3:EST1} since $G_1'(i) \ge G_1'(i+1)$.

We next infer from~\eqref{G:EST1}, \eqref{G:ESTC}, and the monotonicity of $G_1$ that, for $p\ge i\ge 1$ and $t\ge 0$, 
\begin{align*}
	\mathcal{J}_0 \ge & \int_0^t \sum_{j=i+1}^p \sum_{k=1}^p \sum_{l=1}^{j-1} (G_1(j)-G_1(l)) l \varphi_{l,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds\\
	&\ge  \int_0^t \sum_{j=i+1}^p \sum_{k=1}^p (G_1(j)-G_1(i)) i \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds\\
	&\ge i [G_1(i+1)- G_1(i)] \int_0^t \sum_{j=i+1}^p \sum_{k=1}^p \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds\\
	&\ge i G_1'(i+1) \int_0^t \sum_{j=i+1}^p \sum_{k=1}^p \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds,
\end{align*}
which completes the proof.
\end{proof}

An immediate consequence of \Cref{LEM3} is the following bound on the time derivative of $\psi_i^p$.

%%%%%%%%%%
\begin{corollary}\label{Cor1}
For  $p\ge i \ge 1$ and $t\ge 0$, we have
\begin{equation}
	\int_0^t \Bigg| \frac{d\psi_i^p}{dt}(s)\Bigg| ds \leq 2C_i. \label{DERVBOUND}
\end{equation}
\end{corollary}
%%%%%%%%%%

We now turn to the derivation of additional estimates on the reaction terms. Following the strategy outlined in \cite[Proof of Theorem~2.1]{AGP 24I}, we arrive at the main estimate of this section, which provides control over the contributions arising from the tails of the two infinite series on the right-hand side of~\eqref{IF}.

%%%%%%%%%%
\begin{proposition}\label{Prop1}
For $i\ge 1$, $t>0$ and $i\le m<p$,
\begin{equation}
	(1-\delta_{i,1}) \int_0^t \sum_{j=m+1}^p \Gamma_{i,j}\psi_i^p(s) \psi_j^p(s) ds \le  \varepsilon_{m}, \label{Prop1:EST1}
\end{equation}
\begin{align}
	& \int_0^t \sum_{j=m+1}^p \sum_{k=1}^p \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \le \omega_m(i), \label{G:EST4} \\
	& \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \le \alpha_0 \varepsilon_m + \alpha_1 \omega_m(i), \label{Prop1:EST2}
\end{align}
with 
\begin{equation}
	\varepsilon_{m} := \frac{\mathcal{J}_0}{\displaystyle \inf\limits_{z \geq m} \{zG_1'(z)\}} \;\text{ and }\; \omega_m(i) := \frac{\alpha_1 \mathcal{J}_0}{G_1(m+1)-G_1(i)}. \label{VEM}
\end{equation}
\end{proposition}
%%%%%%%%%%

\begin{proof}
 Consider first $i\ge 2$ and $i\le m<p$. Then, by~\eqref{G:EST2},
\begin{align*}
	\mathcal{J}_0 \ge& \int_0^t \sum_{j=2}^p j G_1'(j) \Gamma_{j,i} \psi_j^p(s) \psi_i^p(s) ds\\
	&\ge \int_0^t \sum_{j=m+1}^p jG_1'(j) \Gamma_{i,j} \psi_i^p(s) \psi_j^p(s) ds\\
	&\ge \inf_{z\ge m} \{z G_1'(z)\} \int_0^t \sum_{j=m+1}^p \Gamma_{i,j} \psi_i^p(s) \psi_j^p(s) ds,
\end{align*}
and we have proved~\eqref{Prop1:EST1}.

Next, for $1\le i \le m <p$, we infer from~\eqref{G:EST1} and the monotonicity of $G_1$ that
\begin{align*}
	\mathcal{J}_0 \ge& \int_0^t \sum_{j=m+1}^p \sum_{k=1}^p \sum_{l=1}^{j-1} (G_1(j)-G_1(l)) l \varphi_{l,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \\
	&\ge \int_0^t \sum_{j=m+1}^p \sum_{k=1}^p (G_1(j)-G_1(i)) i \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \\
	&\ge i[G_1(m+1)-G_1(i)] \int_0^t \sum_{j=m+1}^p \sum_{k=1}^p \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds,
\end{align*}
which gives~\eqref{G:EST4}. Now, by~\eqref{bCond},
\begin{align*}
	\int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \le \alpha_0& \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \\
	& + \alpha_1 \int_0^t\sum_{j=i+1}^m \sum_{k=m+1}^p \varphi_{i,k;j} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds. 
\end{align*}
We estimate each of the terms on the right-hand side separately and begin with the first one. Owing to the monotonicity of $G_1$,
\begin{align*}
	\alpha_0 \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p \Gamma_{j,k}& \psi_j^p(s) \psi_k^p(s) ds = \alpha_0 \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p \frac{kG_1'(k)}{kG_1'(k)} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \\
	&\le \frac{\alpha_0}{\displaystyle \inf\limits_{z \geq m} \{zG_1'(z)\}} \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p kG_1'(k) \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \\
	&\le \frac{\alpha_0}{\displaystyle \inf\limits_{z \geq m} \{zG_1'(z)\}} \int_0^t \sum_{j=1}^p \sum_{k=2}^p kG_1'(k) \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds.
\end{align*}
Applying the substitution $j\leftrightarrow k$ and invoking~\eqref{G:EST2}, we obtain
\begin{equation*}
	\alpha_0 \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \le \frac{\alpha_0\mathcal{J}_0}{\displaystyle \inf\limits_{z \geq m} \{zG_1'(z)\}}. 
\end{equation*}

We next deal with the second term and use once more the monotonicity of $G_1$ to obtain
\begin{align*}
	\alpha_1 & \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p \varphi_{i,k;j}  \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \\
	&= \alpha_1 \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p \frac{G_1(k) - G_1(i)}{G_1(k) - G_1(i)} \varphi_{i,k;j} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \\
	&\le \frac{\alpha_1}{[G_1(m+1) - G_1(i)]} \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p \sum_{l=1}^{k-1} [G_1(k) - G_1(l)] \varphi_{l,k;j} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \\
	& \le \frac{\alpha_1}{[G_1(m+1) - G_1(i)]} \int_0^t \sum_{j=1}^p \sum_{k=2}^p \sum_{l=1}^{k-1} [G_1(k) - G_1(l)] l \varphi_{l,k;j} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds.
\end{align*}
Applying estimate~\eqref{G:EST1}, we end up with
\begin{equation*}
	\alpha_1 \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^p \varphi_{i,k;j} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \le \frac{\alpha_1 \mathcal{J}_0}{[G_1(m+1) - G_1(i)]}, 
\end{equation*}
which completes the proof.
\end{proof}

\begin{proof}[Proof of \Cref{TH1}] Owing to~\eqref{TMC} and~\eqref{DERVBOUND}, we are in a position to apply Helly’s selection principle \cite[Theorem~2.35]{Leoni 2009}, combined with a diagonal process, and conclude that there exist a subsequence of $(\psi^p)_{p \geq 3}$, still denoted by $(\psi^p)_{p \geq 3}$, and a sequence of functions $\psi = (\psi_i)_{i \geq 1}$ such that
\begin{equation} \label{Psi:Lim}
    \lim_{p \to \infty} \psi^{p}_i (t) = \psi_i (t) \quad \text{for all } t \geq 0 \text{ and } i \geq 1.
\end{equation}
Clearly, $\psi_i(t) \geq 0$ for $i \geq 1$ and $t \geq 0$, and it follows from~\eqref{TMC}, \Cref{LEM2}, and~\eqref{Psi:Lim} that, for $r\ge 1$, $p\ge q \ge r+1$ and $t \geq 0$,
\begin{equation*}
	\sum_{i=r}^q i \psi_i(t) = \lim_{p \to \infty} \sum_{i=r}^q i \psi_i^p(t) \le \sum_{i=r}^\infty i \psi_i^{\rm{in}}.
\end{equation*}
By letting $q \to \infty$, we obtain
\begin{equation}
	\sum_{i=r}^\infty i \psi_i(t) \le \sum_{i=r}^\infty i \psi_i^{\rm{in}}, \quad r\ge 1, \ t \geq 0. \label{Psi:L1Lim}
\end{equation}
A similar argument allows us to deduce that 
\begin{equation}
	\sum_{i=1}^{\infty} G_0(i) \psi_i(t) \le \mathcal{J}_0,  \quad t\ge 0, \label{THM1:EST5}
\end{equation}
from~\eqref{G:EST0} and~\eqref{Psi:Lim}. Next, let $t\ge 0$, $i\ge 1$, and $r > i$. It follows from \Cref{LEM3} and~\eqref{Psi:Lim} that 
\begin{equation*}
	(1-\delta_{i,1}) \int_0^t \sum_{j=1}^r \Gamma_{i,j} \psi_i(s) \psi_j(s) ds =(1-\delta_{i,1}) \lim_{p\to \infty}  \int_0^t \sum_{j=1}^r \Gamma_{i,j} \psi_i^p(s) \psi_j^p(s) ds \le C_i
\end{equation*}
and
\begin{equation*}
	\int_0^t \sum_{j=i+1}^r \sum_{k=1}^r \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) ds = \lim_{p\to \infty} \int_0^t \sum_{j=i+1}^r \sum_{k=1}^r \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \le C_i.
\end{equation*}
Letting $r \to \infty$ and using Fatou's lemma, we obtain
\begin{equation}
	(1-\delta_{i,1}) \int_0^t \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i(s) \psi_j(s) ds \le C_i, \quad t\ge 0, \label{THM1:EST6}
\end{equation}
and
\begin{equation}
	\int_0^t \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) ds \le C_i, \quad t\ge 0. \label{THM1:EST7}
\end{equation}
In the same way, we infer from \Cref{Prop1} and~\eqref{Psi:Lim} that, for $m\ge i \ge 1$,
\begin{equation}
	(1-\delta_{i,1}) \int_0^t \sum_{j=m+1}^\infty \Gamma_{i,j} \psi_i(s) \psi_j(s) ds \le \varepsilon_{m}  \label{THM1:EST1}
\end{equation}
and
\begin{align}
	& \int_0^t \sum_{j=m+1}^\infty \sum_{k=1}^\infty \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) ds \le \omega_m(i), \label{THM1:EST3} \\
	& \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^\infty \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) ds \le \alpha_0\varepsilon_{m} + \alpha_1 \omega_m(i). \label{THM1:EST2}
\end{align}

We are now ready to complete the proof of \Cref{TH1} and first observe that it follows from the estimates~\eqref{THM1:EST6} and~\eqref{THM1:EST7} that \Cref{DEF}(ii) is satisfied. Besides, the convergence~\eqref{Psi:Lim} and the tail control~\eqref{Psi:L1Lim} imply that, for any $t\ge 0$ and $p\ge r\ge 2$,
\begin{align*}
	\| \psi^p(t) - \psi(t) \|_1 \le & \sum_{j=1}^{r-1} i |\psi_j^p(t) - \psi_i(t)| + \sum_{i=r}^\infty i \psi_i(t) + \sum_{i=r}^p i \psi_i^p(t) \\
	& \le \sum_{j=1}^{r-1} i |\psi_j^p(t) - \psi_i(t)| + 2\sum_{i=r}^\infty i \psi_i^{\rm{in}}.
\end{align*}
Consequently, 
\begin{equation*}
	\limsup_{p\to\infty} \| \psi^p(t) - \psi(t) \|_1 \le 2\sum_{i=r}^\infty i \psi_i^{\rm{in}},
\end{equation*}
and we take the limit $r\to\infty$ in the above inequality and use the summability properties of $\psi^{\rm{in}}$ to conclude that
\begin{equation}
	\lim_{p \to \infty} \| \psi^p(t) - \psi(t) \|_1 = 0. \label{THM1:EST10}
\end{equation} 
In particular, we infer from~\eqref{TMC} and~\eqref{THM1:EST10} that, for all $t \geq 0$, we have  
\begin{equation*}
	\| \psi(t) \|_1 = \lim_{p \to \infty} \| \psi^p(t) \|_1 = \lim_{p \to \infty} \| \psi^p(0) \|_1 = \| \psi^{\rm{in}} \|_1,
\end{equation*} 
which shows that $\psi$ satisfies the mass conservation property~\eqref{TMC}.

\noindent We next fix $i \ge 1$ and $t\ge 0$. On the one hand, it follows from~\eqref{Prop1:EST1}, \eqref{Psi:Lim}, and~\eqref{THM1:EST1} that, for $i+1\le m< p$, we have
\begin{align*}
	(1-\delta_{i,1}) \int_0^t & \Bigg| \sum_{j=1}^{p} \Gamma_{i,j} \psi_i^p(s) \psi_j^p(s) - \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i(s) \psi_j(s)\Bigg| ds\\
	&\le \int_0^t \sum_{j=1}^{m} \Gamma_{i,j} |\psi_i^p(s) \psi_j^p(s) - \psi_i(s) \psi_j(s)| ds + \int_0^t \sum_{j=m+1}^{p} \Gamma_{i,j} \psi_i^p(s) \psi_j^p(s) ds\\
	&\qquad + \int_0^t \sum_{j=m+1}^{\infty} \Gamma_{i,j} \psi_i(s) \psi_j(s) ds \\
	& \le \int_0^t \sum_{j=1}^{m} \Gamma_{i,j} |\psi_i^p(s) \psi_j^p(s) - \psi_i(s) \psi_j(s)| ds + 2 \varepsilon_m,
\end{align*}
recalling that $\varepsilon_{m}$ is defined in~\eqref{VEM}. By virtue of~\eqref{TMC}, \eqref{Psi:Lim}, and~\eqref{Psi:L1Lim}, together with the Lebesgue dominated convergence theorem, we may pass to the limit as $p \to \infty$ in the above inequality to obtain
\begin{equation*}
	\limsup_{p\to \infty}\ (1-\delta_{i,1}) \int_0^t \Bigg| \sum_{j=1}^{p} \Gamma_{i,j} \psi_i^p(s) \psi_j^p(s) - \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i(s) \psi_j(s)\Bigg| ds \le 2 \varepsilon_m.
\end{equation*}
Since $G_0\in\mathcal{G}_{1,\infty}$, the function $G_1$ satisfies~\eqref{G0:Cond2}, so that the right hand side of the above inequality converges to zero as $m\to \infty$. We thus let $m\to \infty$ in the above inequality to conclude that
\begin{equation}
	\lim_{p\to \infty} (1-\delta_{i,1}) \int_0^t\Bigg| \sum_{j=1}^{p} \Gamma_{i,j} \psi_i^p(s) \psi_j^p(s) - \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i(s) \psi_j(s) \Bigg| ds=0. \label{IF:ST}
\end{equation}
We next turn to the convergence of the first term on the right hand side of~\eqref{TSNLBE}. For $p>m\ge i+1$, we infer from~\eqref{Prop1:EST2}, \eqref{THM1:EST3}, and~\eqref{THM1:EST2} that
\begin{align}
	\int_0^t\Bigg|\sum_{j=i+1}^{p} \sum_{k=1}^{p} & \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) - \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) \Bigg| ds \nonumber \\
	&\le \int_0^t \Bigg| \sum_{j=i+1}^{m} \sum_{k=1}^m \varphi_{i,j;k} \Gamma_{j,k} \big(\psi_j^p(s) \psi_k^p(s) - \psi_j(s) \psi_k(s) \big)\Bigg| ds \nonumber \\
	& \quad + \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^{p} \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \nonumber \\ 
	& \quad +\int_0^t \sum_{j=m+1}^p \sum_{k=1}^{p} \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) ds \nonumber \\
	& \quad + \int_0^t \sum_{j=i+1}^m \sum_{k=m+1}^{\infty}  \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) ds \nonumber \\
	& \quad +\int_0^t \sum_{j=m+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) ds \nonumber \\
	& \le \int_0^t \Bigg| \sum_{j=i+1}^{m} \sum_{k=1}^m \varphi_{i,j;k} \Gamma_{j,k} \big(\psi_j^p(s) \psi_k^p(s) - \psi_j(s) \psi_k(s) \big)\Bigg| ds \label{THM1:EST13} \\
	& \quad + 2 \big( \alpha_0\varepsilon_{m} + \alpha_1 \omega_m(i) \big) +  2 \omega_m(i). \nonumber
\end{align}
On the one hand, it follows from~\eqref{TMC}, \eqref{Psi:Lim}, \eqref{Psi:L1Lim} and the Lebesgue dominated convergence theorem that
\begin{equation}
	\lim_{p\to \infty} \int_0^t\Bigg| \sum_{j=i+1}^p \sum_{k=1}^p \varphi_{i,j,k} \Gamma_{j,k}(\psi_j^p \psi_k^p - \psi_j \psi_k) \Bigg |d\tau =0. \label{THM1:EST11}
\end{equation}
On the other hand, it follows from the properties~\eqref{G0:Cond0} and~\eqref{G0:Cond2} that
\begin{equation}
	 \lim_{m\to \infty} \varepsilon_{m} = \lim_{m\to\infty} \omega_m(i) = 0. \label{THM1:EST12}
\end{equation}
Consequently, using~\eqref{THM1:EST11}, we may take the limit $p\to \infty$ in~\eqref{THM1:EST13} and find
\begin{align*}
	\limsup_{p\to \infty}\int_0^t\Bigg|\sum_{j=i+1}^{p} \sum_{k=1}^{p} \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) & - \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) \Bigg| ds \\ & \le 2 \big( \alpha_0\varepsilon_{m} + \alpha_1 \omega_m(i) \big) +  2 \omega_m(i).
\end{align*}
We next let $m\to \infty$ and deduce from~\eqref{THM1:EST12} that
\begin{equation}
	\lim_{p\to \infty}\int_0^t\Bigg|\sum_{j=i+1}^{p} \sum_{k=1}^{p} \varphi_{i,j;k} \Gamma_{j,k} \psi_j^p(s) \psi_k^p(s) - \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) \Bigg| ds = 0. \label{IF:FT}
\end{equation}
Owing to~ \eqref{Psi:Lim}, \eqref{IF:ST}, and~\eqref{IF:FT}, we may pass to the limit as $p \to \infty$ in the integral formulation of the equation satisfied by $\psi_i^p$, thereby concluding that $\psi_i$ satisfies~\eqref{IF}. Moreover, since the right-hand side of~\eqref{IF} lies in $L^1_{\mathrm{loc}}([0, \infty))$, it follows that $\psi_i \in C([0, \infty))$, and we have proved the existence part of \Cref{TH1}. 

\medskip

Finally, we assume that the initial condition $ \psi^{\rm{in}}$ satisfies~\eqref{LambdaMom}. Let $ r\ge 1$ and $t\ge 0$. Since the sequence defined by $\upsilon_i = 0$ for $1 \leq i \leq r-1$ and $\upsilon_i = \Lambda_i$ for $i \geq r$ satisfies the assumptions of \Cref{LEM1B}, we infer from~\eqref{LEM1:EST1} that, for $p > m > r$,  the solution $\psi^p$ to~\eqref{FTSNLBE} satisfies
\begin{equation*}
	\sum_{i=r}^m \Lambda_i \psi_i^{p}(t) \leq \sum_{i=r}^p \Lambda_i \psi_i^{p}(t) \leq \sum_{i=r}^p \Lambda_i \psi_i^{\mathrm{in}} \leq \sum_{i=r}^{\infty} \Lambda_i \psi_i^{\mathrm{in}}.
\end{equation*}
Thanks to~\eqref{Psi:Lim}, we first take the limit as $p \to \infty$ and subsequently let $m \to \infty$  in the above inequality to derive~\eqref{TailIneq} and complete the proof of \Cref{TH1}.
\end{proof}

