\begin{proof}[Proof of \Cref{TH2}]
In this section, we assume that the kinetic coefficients $(\Gamma_{i,j})$, $(\varphi_{i,j,k})$, and the initial condition $\psi^{\rm{in}}$ satisfy~\eqref{ACond1}, \eqref{LMC1}, \eqref{bCond3}, \eqref{G0:Cond1}, and~\eqref{LambdaMom}, respectively. It follows from \Cref{TH1} that~\eqref{FSNLBE} admits a global mass-conserving mild solution satisfying~\eqref{TailIneq}. Our goal is to demonstrate that the additional assumptions~\eqref{ACond1} and~\eqref{bCond3} ensure the continuity properties~\eqref{CNT} as well as the $C^1$-regularity of $\psi_i$ for each $i\ge 1$. To this end, for $(s, t) \in [0, \infty)^2$ and $m \ge i \ge 2$, we deduce from~\eqref{MCC}, \eqref{TailIneq} and~\eqref{ACond1} that
\begin{align*}
	\Big| \sum_{j=1}^{\infty} \Gamma_{i,j} & \psi_i(t) \psi_j(t) - \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i(s) \psi_j(s)\Big| \le \sum_{j=1}^{\infty} \Gamma_{i,j} |\psi_i(t) \psi_j(t) - \psi_i(s) \psi_j(s)|\\
	&\le \sum_{j=1}^{m}\Gamma_{i,j} |(\psi_i \psi_j)(t) - (\psi_i \psi_j)(s)| + \Lambda_i \sum_{j=m+1}^{\infty} \Lambda_j [(\psi_i\psi_j)(t)+ (\psi_i\psi_j)(s)]\\
	& \le \sum_{j=1}^{m}\Gamma_{i,j}|(\psi_i\psi_j)(t) - (\psi_i\psi_j)(s)| + 2 \Lambda_i \|\psi^{\rm{in}}\|_1\sum_{j=m+1}^{\infty} \Lambda_j \psi_j^{\rm{in}}. 
\end{align*}
Due to the continuity of $\psi_j$ for all $j \ge 1$,
\begin{align*}
	\limsup_{s\to t} \Big| \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i(t) \psi_j(t) - \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i(s) \psi_j(s)\Big| \le 2 \Lambda_i \|\psi^{\rm{in}}\|_1\sum_{j=m+1}^{\infty} \Lambda_j \psi_j^{\rm{in}},
\end{align*}
and, applying~\eqref{LambdaMom}, we can let $m \to \infty$ in the above inequality to conclude that
\begin{equation}
	\lim_{s\to t} \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i(s) \psi_j(s) = \sum_{j=1}^{\infty} \Gamma_{i,j} \psi_i(t) \psi_j(t). \label{FTC}
\end{equation}

Similarly, consider $(s,t) \in [0, \infty)^2$ and $m > i \ge 1$. By making use of~\eqref{LMC1}, \eqref{LambdaMom}, \eqref{TailIneq}, and~\eqref{ACond1}, we obtain
\begin{align*}
	\Bigg|\sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} & \varphi_{i,j;k} \Gamma_{j,k} \psi_j(t) \psi_k(t) -\sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} \psi_j(s) \psi_k(s) \Bigg|\\
	& \le \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j,k} \Gamma_{j,k} |(\psi_j\psi_k)(t) - (\psi_j\psi_k)(s)| \\
	& \le \sum_{j=i+1}^{m} \sum_{k=1}^{m} \varphi_{i,j;k} \Gamma_{j,k} |(\psi_j\psi_k)(t) - (\psi_j\psi_k)(s)| \\
	& \quad + \sum_{j=i+1}^{m} \sum_{k=m+1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} [(\psi_j \psi_k)(t)+ (\psi_j \psi_k)(s)] \\
	& \quad + \sum_{j=m+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} [(\psi_j \psi_k)(t)+ (\psi_j \psi_k)(s)|.
\end{align*}
Thanks to~\eqref{TailIneq}, \eqref{ACond1}, and~\eqref{bCond3}, 
\begin{align*}
	\sum_{j=i+1}^{m} \sum_{k=m+1}^{\infty} & \varphi_{i,j;k} \Gamma_{j,k} [(\psi_j \psi_k)(t)+ (\psi_j \psi_k)(s)]\\
	& \le \alpha_0 \sum_{j=i+1}^{m} \sum_{k=m+1}^{\infty} \Lambda_j \Lambda_k[(\psi_j \psi_k)(t)+ (\psi_j \psi_k)(s)]\\
	& \le \alpha_0 \Bigg(M_{\Lambda}(\psi(t)) \sum_{k=m+1}^{\infty} \Lambda_k \psi_k(t) + M_{\Lambda}(\psi(s)) \sum_{k=m+1}^{\infty} \Lambda_k \psi_k(s)\Bigg)\\
	& \le 2\alpha_0 M_{\Lambda}(\psi^{\rm{in}})\sum_{k=m+1}^{\infty} \Lambda_k \psi_k^{\rm{in}}.
\end{align*}
In a similar way we can evaluate 
\begin{equation*}
	\sum_{j=m+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j;k} \Gamma_{j,k} [(\psi_j \psi_k)(t)+ (\psi_j \psi_k)(s) \le 2\alpha_0 M_{\Lambda}(\psi^{\rm{in}}) \sum_{j=m+1}^{\infty} \Lambda_j \psi_j^{\rm{in}}.
\end{equation*}
Gathering the above estimates, we finally obtain
\begin{align*}
	\Bigg|\sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} & \varphi_{i,j,k} \Gamma_{j,k} \psi_j(t) \psi_k(t) -\sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j,k} \Gamma_{j,k} \psi_j(s) \psi_k(s) \Bigg|\\
	& \le \sum_{j=i+1}^{m} \sum_{k=1}^{m} \varphi_{i,j,k} \Gamma_{j,k} |(\psi_j\psi_k)(t) - (\psi_j\psi_k)(s)| + 4 \alpha_0 M_{\Lambda}(\psi^{\rm{in}}) \sum_{j=m+1}^{\infty} \Lambda_j \psi_j^{\rm{in}}
\end{align*}
and proceed as in the derivation of~\eqref{FTC} to find
\begin{align}
\lim_{s\to t}\sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j,k} \Gamma_{j,k} \psi_j(s) \psi_k(s)= 
\sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \varphi_{i,j,k} \Gamma_{j,k} \psi_j(t) \psi_k(t). \label{STC}
\end{align}
The continuity properties~\eqref{CNT} follow directly from~\eqref{FTC} and~\eqref{STC}. Moreover, applying \Cref{DEF}(iii) in conjunction with~\eqref{CNT}, we deduce that $\psi_i \in C^1([0, \infty))$ for all $i \ge 1$. Finally, the bound~\eqref{HMB} is an immediate consequence of~\eqref{TailIneq} with $r = 1$.
\end{proof}

%%%%%%%%%%
%%%%%%%%%%
\section{\textbf{Uniqueness of Classical Solutions}}\label{SEC4}
%%%%%%%%%%
%%%%%%%%%%

\begin{proof}[Proof of \Cref{TH3}]
To begin with, we observe that the non-negativity and monotonicity of $(\Lambda_{i}/i)_{i\ge 1}$ entail that
\begin{equation*}
	\frac{\Lambda_{i+1}^2}{i+1} = (i+1) \left( \frac{\Lambda_{i+1}}{i+1} \right)^2 \ge i \left( \frac{\Lambda_{i}}{i} \right)^2 = \frac{\Lambda_{i}^2}{i}, \qquad i\ge 1,
\end{equation*}	
so that $(\Lambda_{i}^2/i)_{i\ge 1}$ is also a non-negative and non-decreasing sequence. Moreover,	
$\Lambda_i^2 \ge \Lambda_1 \Lambda_i \ge \Lambda_i$ for $i \ge 1$ with $\Lambda_1^2 \ge 1$, so that~\eqref{ACond1} implies that $(\Gamma_{i,j})$ also satisfies~\eqref{ACond1} with $\Lambda_i^2$ instead of $\Lambda_i$. Taking into account~\eqref{UNIC}, we are in a position to apply \Cref{TH2} to deduce the existence of at least one mass-conserving global classical solution $\psi$ to~\eqref{FSNLBE} which satisfies the estimate~\eqref{UNME}. 

We now establish the uniqueness result stated in \Cref{TH3}. To this end, we follow the classical approach to uniqueness for coagulation-fragmentation equations, see \cite[Section~8.2.5]{BLL 2019} for instance and the references therein, and derive an estimate on the difference between two solutions in a suitably chosen weighted space. Such an approach is already used in \cite[Corollary~3.1]{AGP 24I} with a power weight and we adapt it here in the more general setting of \Cref{TH3}, the appropriate weight being the sequence $(\Lambda_i)_{i \ge 1}$. It is worth noting that, as usual, the proof requires slightly stronger conditions on the collision coefficients compared to those assumed for the existence result. 

Let us thus consider two classical solutions $\psi=(\psi_i)_{i\ge 1}$ and $\phi = (\phi_i)_{i\ge 1}$ to~\eqref{FSNLBE} satisfying~\eqref{UNME} and set $H := \psi- \phi$. Then, for $i \ge 1$, $H_i$ solves
\begin{align*}
	\frac{dH_i}{dt} = \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \Gamma_{j,k} \varphi_{i,j;k} [\psi_k H_j + \phi_j H_k] - (1-\delta_{i,1}) \sum_{k=1}^{\infty} \Gamma_{i,k} [\psi_k H_i + \phi_i H_k],
\end{align*}
from which we deduce that
\begin{align*}
	\frac{d}{dt}\sum_{i=1}^{\infty} \Lambda_i |H_i| &= \sum_{i=1}^{\infty} \sum_{j=i+1}^{\infty} \sum_{k=1}^{\infty} \Lambda_i \sgn(H_i) \varphi_{i,j;k} \Gamma_{j,k} \big[\psi_k H_j + \phi_j H_k\big] \\
	& \quad - \sum_{i=2}^{\infty} \sum_{k=1}^{\infty} \Lambda_i \sgn(H_i)\Gamma_{i,k} \big[\psi_k H_i + \phi_i H_k\big]\\
	& = \sum_{j=2}^{\infty} \sum_{k=1}^{\infty} \sum_{i=1}^{j-1} \Lambda_i \sgn(H_i) \varphi_{i,j;k} \Gamma_{j,k} \big[\psi_k H_j + \phi_j H_k\big] \\
	& \quad - \sum_{j=2}^{\infty} \sum_{k=1}^{\infty} \Lambda_j \sgn(H_j)\Gamma_{j,k} \big[\psi_k H_j + \phi_j H_k\big]\\
	& \le \sum_{j=2}^{\infty} \sum_{k=1}^{\infty} \sum_{i=1}^{j-1} \Lambda_i \varphi_{i,j;k} \Gamma_{j,k} \big[\psi_k |H_j| + \phi_j |H_k|\big] \\
	& \quad + \sum_{j=2}^{\infty} \sum_{k=1}^{\infty} \Lambda_j \Gamma_{j,k} \big[- \psi_k |H_j| + \phi_j |H_k|\big].
\end{align*}
Owing to~\eqref{LMC1} and the monotonicity of $(\Lambda_{i}/i)_{i\ge 1}$, we obtain
\begin{align*}
	\sum_{i=1}^{j-1} \Lambda_{i} \varphi_{i,j;k} \le \frac{\Lambda_j}{j} \sum_{i=1}^{j-1} i \varphi_{i,j;k} = \Lambda_j.
\end{align*}
Applying this bound gives
\begin{align*}
	 \frac{d}{dt}\sum_{i=1}^{\infty} \Lambda_i|H_i| & \le \sum_{j=2}^{\infty} \sum_{k=1}^{\infty} \Lambda_j \Gamma_{j,k} \big[\psi_k |H_j| + \phi_j |H_k|\big] \\
	 & \quad + \sum_{j=2}^{\infty} \sum_{k=1}^{\infty} \Lambda_j \Gamma_{j,k} \big[- \psi_k |H_j| + \phi_j |H_k|\big]\\
	 & = 2 \sum_{j=2}^{\infty} \sum_{k=1}^{\infty} \Lambda_j \Gamma_{j,k} \phi_j |H_k|
\end{align*}
Finally, we conclude from~\eqref{ACond1}, \eqref{UNME}, and the above inequality that
\begin{equation*}
	\frac{d}{dt} \sum_{i=1}^{\infty} \Lambda_i |H_i| \le 2 \sum_{j=2}^{\infty} \sum_{k=1}^{\infty} \Lambda_j^2 \Lambda_k \phi_j |H_k| 
\le 2 M_{\Lambda^2}(\psi^{\rm{in}}) \sum_{i=1}^{\infty} \Lambda_i |H_i|,
\end{equation*}
and an application of Gronwall's lemma completes the proof.
\end{proof}

%%%%%%%%%%
%%%%%%%%%%
\section{\textbf{Large Time Behavior}}\label{SEC5}
%%%%%%%%%%
%%%%%%%%%%

We now examine the asymptotic behavior of solutions in the long-time regime. As previously noted, the dynamics of this model ensure that clusters fragment solely into smaller components upon collision. This structural constraint suggests that, as $t \to \infty$, the system evolves toward a state where only $1$-clusters persist.

%%%%%%%%%%
\begin{proposition}\label{Prop:LTB}
Suppose that $(\Gamma_{i,j})$ and $(\varphi_{i,j;k})$ satisfy~\eqref{ACond}, \eqref{LMC1}, and~\eqref{bCond}. For any $\psi^{\rm{in}} \in Y_{1,+}$ satisfying~\eqref{G0:Cond1} for some $G_0\in\mathcal{G}_{1,\infty}$, the mass-conserving global mild solution $\psi$ to~\eqref{FSNLBE} constructed in \Cref{TH1} satisfies
\begin{equation*}
	\lim_{t \to \infty} \|\psi(t) - \psi^{\infty}\|_1 = 0,
\end{equation*} 
for some limiting sequence $\psi^{\infty} = (\psi^{\infty}_i)_{i\ge 1} \in Y_{1,+}$. Furthermore, if $\Gamma_{i,i} > 0$ for some $i \geq 2$, then $\psi^{\infty}_i = 0$.
\end{proposition}
%%%%%%%%%%

\begin{proof}
The proof proceeds along the same lines as that of \cite[Proposition~4.1]{PhL 2001}; see also \cite{ZHENG 2005}.
\end{proof}
%%%%%%%%%%

%%%%%%%%%%
%%%%%%%%%%
\section{\textbf{Numerical Simulations}} \label{SEC6}
%%%%%%%%%%
%%%%%%%%%%

The final section is devoted to numerical simulations to illustrate the time evolution of the total number of clusters $\|\psi(t)\|_0$ of solutions to~\eqref{FSNLBE} and the large time behavior stated in \Cref{TH1} and \Cref{Prop:LTB}, respectively. For the numerical simulations of the nonlinear breakage system~\eqref{FSNLBE} provided below, we employ an implicit numerical scheme with a truncation parameter $p = 40$ in~\eqref{FTSNLBE}, and use the initial condition
\begin{equation}
	\psi_i^{\rm{in}} = \frac{1}{2^i}, \quad i \ge 1. \label{ICD}
\end{equation}
The simulations are performed for varying final times $T$, collision kernels $(\Gamma_{i,j})$, and daughter distribution functions $(\varphi_{i,j;k})$, using a fixed time step size $dt = 0.01$.

Among the chosen daughter distribution functions $(\varphi_{i,j;k})$ in the numerical simulations, we shall use that given by~\eqref{FDF:EX2}, which is unbounded. We first verify that it satisfies the condition~\eqref{bCond}.

%%%%%%%%%%
\begin{lemma}\label{LEM:EX2}
	The fragment distribution function 
	\begin{equation*}
		\varphi_{i,j;k} = \frac{1}{2^i} \frac{j 2^{j-1}}{2^j - j - 1}, \qquad 1 \le i \le j-1, \quad j \ge 2, \quad k \ge 1, 
	\end{equation*}
	defined in~\eqref{FDF:EX2}, satisfies~\eqref{bCond} with $\alpha_0=\alpha_1=1$.
\end{lemma}
%%%%%%%%%%

\begin{proof}
Introducing the function
\begin{equation*}
	\xi(z) := \frac{z 2^{z-1}}{2^z - z - 1}, \qquad z\ge 2,
\end{equation*}
we note that
\begin{equation*}
	\varphi_{i,j;k} = \frac{\xi(j)}{2^i}, \qquad 1 \le i \le i-1, \quad j\ge 2, \quad k\ge 1.
\end{equation*}
A tedious computation reveals that $\xi$ is increasing on $[4,\infty)$ with $\xi(2) = 4$, $\xi(3) = 3$ and $\xi(4) = 32/9$. As $\xi(3)<\xi(4)$, there holds
\begin{equation*}
	\varphi_{1,2;k} = \frac{\xi(2)}{2} \le \frac{1+\xi(3)}{2} \le 1 + \frac{\xi(k)}{2} = 1 + \varphi_{1,k;2}
\end{equation*}
for $k> j=2$ and
\begin{equation*}
	\varphi_{i,j;k} = \frac{\xi(j)}{2^i} \le \frac{\xi(k)}{2^i} \le 1 + \varphi_{i,k;j}, \qquad 1\le i \le j-1,
\end{equation*}
for $k>j\ge 3$. We complete the proof by noticing that~\eqref{bCond} with $\alpha_1=1$ is obviously satisfied for $k=j\ge 2$.
\end{proof}

Coming back to numerical simulations, we first mention that the total mass $\|\psi(t)\|_1$ is conserved during the computation, which is expected in view of~\eqref{TMC}.

