\subsection{Deep Neural Networks Initial Estimation\label{sec:The-estimation-of}}


Based on \eqref{eq:indentification of beta0},
a natural method of estimating $\bs{\beta}^{*}$ is first estimating
the nuisance function $\pi_{0}(T,\bs X)$ nonparametrically, denoted
by $\widehat{\pi}(T,\bs X)$, then constructing the estimator of $\bs{\beta}^{*}$
by 
\begin{equation}
\widehat{\bs{\beta}}=\underset{\bs{\beta}\in\R^{p}}{\arg\min}\sum_{i=1}^n\widehat{\pi}(T_{i},\bs X_{i})L(Y_{i},g(T_{i};\bs{\beta})).\label{eq:naive minimization step}
\end{equation}
%
%A good estimator of the stabilized weighting function $\pi_{0}$ is important for the estimation of $\bs{\beta}^{*}$. Based on the definition \eqref{eq:desity ratio expression}, one may estimate the numerator $dF_{T}$ and denominator $dF_{T|X}$ separately and then form a ratio estimator of $\pi_{0}$. However, estimating the conditional distribution of $T$ given $\bs X$ poses significant challenges, particularly when $T$ is continuous and the dimensionality of $\bs X$ is large. For example, the conventional kernel smoothing methods \citep{li2006Nonparametric} tend to perform poorly when the dimensionality of $\bs X$ exceeds three, largely due to the severe “curse of dimensionality”. Furthermore, most machine learning methods focus on studying the conditional mean function \citep{farrell2021Deepa,jiao2023Deep,bauer2019Deep} but barely talk about estimation of the conditional distribution function. Moreover, the ratio-type estimator is known to be unstable due to its sensitivity to the denominator's estimation \citep{kang2007demystifying}. To address these challenges, this section proposes to estimate $\pi_{0}$ as a whole based on the deep neural network (DNN) regression.
%
To estimate $\pi_{0}$ as a whole with a DNN, we note that $\pi_{0}$ can be identified as the unique solution of the following minimization problem:
\begin{align}
\pi_{0}(\cdot,\cdot) & =\underset{\pi}{\arg\min}\,\e\left[(\pi(T,\bs X)-\pi_{0}(T,\bs X))^{2}\right]\nonumber \\
& =\underset{\pi}{\arg\min}\left\{ \e\left[\pi^{2}(T,\bs X)\right]-2\int_{\mathcal{T}}\int_{\mathcal{X}}\pi(t,\bs x)dF_{T}(t)dF_{X}(\bs x)+\e\left[\pi_{0}^{2}(T,\bs X)\right]\right\} \nonumber \\
&=\underset{\pi}{\arg\min}\left[\e\left\{\pi^{2}(T,\bs X)\right\}-2\int_{\mathcal{T}}\int_{\mathcal{X}}\pi(t,\bs x)dF_{T}(t)dF_{X}(\bs x)\right] =:\underset{\pi}{\arg\min}\,R(\pi),\label{eq:population minimize of pi}
\end{align}
where the definition of $R(\pi)$ is clear.
%\begin{align*}
%R(\pi):=\e\left[\pi^{2}(T,\bs X)\right]-2\int_{\mathcal{T}}\int_{\mathcal{X}}\pi(t,\bs x)dF_{T}(t)dF_{X}(\bs x),
%\end{align*}
%and \eqref{eq:population minimize of pi} holds by ignoring the constant term $\mathbb{E}[\pi_{0}(T,\bs X)^{2}]$ that does not depend on $\pi(\cdot,\cdot)$.

Let  $\f_{\mathrm{DNN}}(\mathcal{W},\mathcal{D})$ be a class of transformed DNNs with depth $\mathcal{D}$
and width $\mathcal{W}$ defined as:
\begin{align*}
& {\f_{\mathrm{DNN}}(\mathcal{W},\mathcal{D})=  \Bigl\{\bs z\in\R^{d+1}\mapsto\phi\left( W_{\mathcal{D}}\boldsymbol{\sigma}\Big(\cdots\boldsymbol{\sigma}\big(W_{1}\boldsymbol{\sigma}(W_{0}\boldsymbol{z}+b_{0})+b_{1}\big)+\cdots\Big)+b_{\mathcal{D}}\right) :}\\
&{\qquad\quad W_{l}\in\R^{d_{l+1}\times d_{l}},b_{l}\in\R^{d_{l+1}},0\leq l\leq\mathcal{D},d_{0}=d+1,d_{\mathcal{D}+1}=1,\max\{d_{1},\ldots,d_{\mathcal{D}}\}\leq\mathcal{W}\Bigl\}\,,}
\end{align*}
where $\sigma(z):=\max\{z,0\}$ is the rectified linear unit (ReLU) activation function for $z\in\mathbb{R}$, $\boldsymbol{\sigma}:\mathbb{R}^{d_l}\to \mathbb{R}^{d_l}$ denotes the function applying $\sigma(\cdot)$ componentwisely, and $\phi(\cdot):\mathbb{R}\to [0,\infty)$ is a user-specified transformation function such that  the output of the neural network  $\f_{\mathrm{DNN}}(\mathcal{W},\mathcal{D})$ is non-negative. In simulation studies and real applications, we  adopt the exponential function $\phi(z)=\exp(z)$.  We refer to \citet[Section 2.1]{farrell2021Deepa} for more discussion on the construction of a DNN.

Based on \eqref{eq:population minimize of pi}, the initial DNN estimator of $\pi_{0}$
is defined by 
\begin{equation}
\widehat{\pi}_{\mathrm{DNN}}=\underset{\pi\in\f_{\mathrm{DNN}}(\mathcal{W},\mathcal{D})%,\left\Vert \pi\right\Vert _{\infty}\leq M
}{\arg\min}\widehat{R}(\pi),\label{eq:estimation of pi definition}
\end{equation}
where 
\[
\widehat{R}(\pi):=\frac{1}{n}\sum_{i=1}^n\pi^{2}(T_{i},\bs X_{i})-\frac{2}{n(n-1)}\sum_{j=1}^{n}\sum_{l=1,l\neq j}^{n}\pi(T_{j},\bs X_{l})\,.
\]
%and $M>0$ is a sufficiently large constant satisfying Assumption~\ref{assu:ass for estimate of pi}. The bounded restriction on the DNN space is a commonly used technique to prevent the solution of \eqref{eq:estimation of pi definition} from exploding and stabilize the algorithm, see also \citet{farrell2021Deepa} and \citet{colangelo2023double}.
%
Then the DNNW estimator of $\bs{\beta}^{*}$ is defined by 
\begin{align}
\widehat{\bs{\beta}}_{\mathrm{DNNW}}=\underset{\bs{\beta}\in\R^{p}}{\arg\min}\sum_{i=1}^n\widehat{\pi}_{\mathrm{DNN}}(T_{i},\bs X_{i})L(Y_{i},g(T_{i};\bs{\beta})).\label{def:beta_DNN}
\end{align}

\subsection{Debias using Balanced Neural Networks Weighting\label{sec:bell}}

This section introduces the main idea of our debiased BNNW method. First, note that $\pi_0$ satisfies the following covariate balancing property: %Figure~\ref{fig:compare_dnn_bnn} presents a numerical demonstration of (i) the adverse effects arising from the non-negligible bias inherent in the DNN estimator $\widehat{\pi}_{\mathrm{DNN}}$, and (ii) the superior performance achieved by the proposed BNNW estimator.
%Note that $\pi_{0}(T,\bs X)$ satisfies the following covariate balancing property:
\begin{equation}
\e\left[\pi_{0}(T,\bs X)\bs{\xi}(T,\bs X)\right]=\int_{\mathcal{X}}\int_{\mathcal{T}}\bs{\xi}(t,\bs x)dF_{T}(t)dF_{X}(\bs x)\label{eq:property of pi0}
\end{equation}
for any integrable function $\bs{\xi}:\mathcal{T}\times\mathcal{X}\mapsto\mathbb{R}^{d_\xi}$ for some integer $d_\xi\geq 1$.\footnote{It shows that $\pi_0$ balances the confounders across different treatment levels. Take the binary treatment case as an example, \eqref{eq:property of pi0} is equivalent to $\e\{\pi_0(1,\bs{X})u(\bs{X})T\} = \e\{\pi_0(0,\bs{X})u(\bs{X})(1-T)\}=\e\{u(\bs{X})\}$ for any integrable function $u(\cdot)$.}
A good estimator of $\pi_{0}(T,\bs X)$ (debiases for estimating $\bs{\beta}^*$ or not) should satisfy the empirical analogue of \eqref{eq:property of pi0}.
Second, we found that selecting an appropriate $\bs{\xi}(T,\bs X)$ can give a debiased estimator for $\bs{\beta}^{*}$. However, the construction of the DNN estimator $\widehat{\pi}_{\mathrm{DNN}}$ defined in \eqref{eq:estimation of pi definition} does not guarantee these. %However, for the DNN estimator $\widehat{\pi}_{\mathrm{DNN}}$ defined in \eqref{eq:estimation of pi definition},
%\begin{align*}
%\frac{1}{n}\sum_{i=1}^n\widehat{\pi}_{\mathrm{DNN}}(T_{i},\bs X_{i})\bs{\xi}(T_{i},\bs X_{i})\neq\frac{1}{n(n-1)}\sum_{j=1}^{n}\sum_{l=1,l\neq j}^{n}\bs{\xi}(T_{j},\bs X_{l})\,,
%\end{align*}
%for some $\bs{\xi}(T,\bs X)$. 
We propose to calibrate the DNN estimator $\widehat{\pi}_{\mathrm{DNN}}$ based on \eqref{eq:property of pi0} as follows. 

Let $D(\cdot,\cdot):\mathbb{R}^2\to \R$ be a discrepancy measure such that $D(v):=D(v,1)$ is twice continuously
differentiable and strictly convex in $v\in\R$, i.e. $ D'(1)=0$
and $D''(1)>0$. With a given instrumental
function $\bs{\xi}(t,\bs x)$ and the initial estimator
$\widehat{\pi}_{\mathrm{DNN}}$, we define the BNN estimator of $\pi_0$ as $$\widehat{\pi}_{\mathrm{BNN}}(T_{i},\bs X_{i}):=\widehat{w}_{i}\cdot\widehat{\pi}_{\mathrm{DNN}}(T_{i},\bs X_{i}) \ \text{for}\ i\in \{1,...,n\}\,,$$ where the calibration weights $(\widehat{w}_1,\ldots,\widehat{w}_n)$ solve the following optimization problem:
\begin{align}
\begin{cases}
\min_{w_{i}:1\leq i\leq n}\sum_{i=1}^nD(w_{i}) \ \text{subject to}\\
\frac{1}{n}\sum_{i=1}w_{i}\widehat{\pi}_{\mathrm{DNN}}(T_{i},\bs X_{i})\bs{\xi}(T_{i},\bs X_{i})=\frac{1}{n(n-1)}\sum_{j=1}^{n}\sum_{l=1,l\neq j}^{n}\bs{\xi}(T_{j},\bs X_{l}).
\end{cases}\label{eq:intro empirical constraints}
\end{align}

In Section \ref{sec: proof of EL calibration step} of the Appendix, we show that the dual solution of~\eqref{eq:intro empirical constraints} is given
by\footnote{\textcolor{black}{In our numerical studies, we take $D(v)=v\log v -v$, i.e., $\rho^{\prime}(v)=e^{-v}$, ensuring the weights $\widehat{w}_i$, $i=1,\ldots,n$, always non-negative, and preventing pathological solutions of \eqref{def:betabell} due to negative weighting.}}
\[
\widehat{w}_{i}=\rho^{\prime}\left\{\widehat{\pi}_{\mathrm{DNN}}(T_{i},\bs X_{i})\hat{\bs{\lambda}}^{\trans}\bs{\xi}(T_{i},\bs X_{i})\right\}\ \text{for}\ i\in \{1,...,n\},
\]
where $\rho(v):=D\left\{ (D^{\prime})^{-1}(-v)\right\} +v\cdot(D^{\prime})^{-1}(-v)$ is a strictly concave function,  $\rho^{\prime}(v)$ is the derivative of $\rho(v)$, and $\hat{\bs{\lambda}}$ is the unique maximizer of  the following concave function 
\[
\hat{G}(\bs{\lambda}):=\frac{1}{n}\sum_{i=1}^n\rho\{\widehat{\pi}_{\mathrm{DNN}}(T_{i},\bs X_{i})\bs{\lambda}^{\trans}\bs{\xi}(T_{i},\bs X_{i})\}-\frac{1}{n(n-1)}\sum_{j=1}^{n}\sum_{l=1,l\neq j}^{n}\bs{\lambda}^{\trans}\bs{\xi}(T_{j},\bs X_{l})\,.
\]
Then, the BNNW estimator of $\bs{\beta}^{*}$ is 
\begin{align}
\widehat{\bs{\beta}}_{\mathrm{BNNW}}=\underset{\bs{\beta}\in\R^{p}}{\arg\min}\ \sum_{i=1}^n\widehat{\pi}_{\mathrm{BNN}}(T_{i},\bs X_{i})L(Y_{i},g(T_{i};\bs{\beta})).\label{def:betabell}
\end{align}

The remaining problem is how to choose the instrumental function $\bs{\xi}(t,\bs x)$ to ensure $\widehat{\bs{\beta}}_{\mathrm{BNNW}}$ a debiased estimator. Let $\mu_{0}(t,\bs x;\bs{\beta}^{*}):=\e\left[L^{\prime}(Y,g(T;\bs{\beta}^{*}))\cdot\partial g(T;\bs{\beta}^{*})/\partial\bs{\beta}|T=t,\bs X=\bs x\right]$.
 In Appendix~\ref{sec: intuition on the choice of xi}, we illustrate that, for any integrable  $\bs{\xi}$, the bias of the resulting $\widehat{\bs{\beta}}_{\mathrm{BNNW}}$ can be bounded by $\left\Vert \widehat{\pi}_{\mathrm{BNN}}(T_{i},\bs X_{i})-\pi_{0}(T_{i},\bs X_{i})\right\Vert _{P,2}\times\inf_{\mathbf{Q}\in\mathbb{R}^{p\times d_{\xi}}}\left\Vert \mu_{0}(T,\bs X;\bs{\beta}^{*})-\mathbf{Q}\bs{\xi}(T,\bs X)\right\Vert_{P,2}$, and $\left\Vert \widehat{\pi}_{\mathrm{BNN}}(T_{i},\bs X_{i})-\pi_{0}(T_{i},\bs X_{i})\right\Vert _{P,2}\lesssim \left\Vert \widehat{\pi}_{\mathrm{DNN}}(T_{i},\bs X_{i})-\pi_{0}(T_{i},\bs X_{i})\right\Vert _{P,2}$ holds under suitable conditions. Thus, in order to eliminate bias, the most desirable choice is $\bs{\xi}(t,\bs x)=\mu_{0}(t,\bs x;\bs{\beta}^{*})$,
which is unknown in practice.%\footnote{Alternative choices of $\bs{\xi}(T,\bs X)$ may mitigate the bias but not guarantee asymptotically normal distribution of the resulting $\widehat{\bs{\beta}}_{\text{BNNW}}$. Specifically, in Appendix~\ref{sec: intuition on the choice of xi}, we illustrate that, for any integrable  $\bs{\xi}$, the bias of $\widehat{\bs{\beta}}_{\mathrm{BNNW}}$ can be bounded by $\left\Vert \widehat{\pi}_{\mathrm{BNN}}(T_{i},\bs X_{i})-\pi_{0}(T_{i},\bs X_{i})\right\Vert _{P,2}\times\inf_{\mathbf{Q}\in\mathbb{R}^{p\times d_{\xi}}}\left\Vert \mu_{0}(T,\bs X;\bs{\beta}^{*})-\mathbf{Q}\bs{\xi}(T,\bs X)\right\Vert_{P,2}$. Under suitable conditions, $\left\Vert \widehat{\pi}_{\mathrm{BNN}}(T_{i},\bs X_{i})-\pi_{0}(T_{i},\bs X_{i})\right\Vert _{P,2}\lesssim \left\Vert \widehat{\pi}_{\mathrm{DNN}}(T_{i},\bs X_{i})-\pi_{0}(T_{i},\bs X_{i})\right\Vert _{P,2}$. If $\inf_{\mathbf{Q}\in\mathbb{R}^{p\times d_{\xi}}}\left\Vert \mu_{0}(T,\bs X;\bs{\beta}^{*})-\mathbf{Q}\bs{\xi}(T,\bs X)\right\Vert _{P,2} =o_P(1)$, then the resulting BNNW estimator exhibits smaller bias than the DNNW estimator.} 
~By Taylor's expansion, $\mu_{0}(t,\bs x;\bs{\beta}^{*})\approx\mu_{0}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})+\partial_{\bs{\beta}}\mu_{0}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})(\bs{\beta}^{*}-\widehat{\bs{\beta}}_{\mathrm{DNNW}})$. We thus consider the following instrumental function: 
\begin{align*}
\widehat{\bs{\xi}}(t,\bs x)=\begin{pmatrix}\widehat{\mu}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})\\
\vec{\left\{ \widehat{\partial_{\bs{\beta}}\mu}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})\right\} }
\end{pmatrix},
\end{align*}
where $\widehat{\mu}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})$ and $\widehat{\partial_{\bs{\beta}}\mu}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})$
are some machine learning-based estimators of $\mu_{0}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})$
and $\partial_{\bs{\beta}}\mu_{0}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})$
respectively, and $\vec{\left\{ \widehat{\partial_{\bs{\beta}}\mu}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})\right\} }$
denotes the vector collecting all elements of the matrix $\widehat{\partial_{\bs{\beta}}\mu}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})$.\footnote{Without loss of generality, we assume that the elements in $\widehat{\bs{\xi}}(t,\bs x)$ are linearly independent. Otherwise, we can remove the redundant elements from $\widehat{\bs{\xi}}(t,\bs x)$, which will not affect the results.} Specifically, $\widehat{\mu}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})$ and $\widehat{\partial_{\bs{\beta}}\mu}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})$ can be constructed by either state-of-the-art machine learning methods or regularized approaches, depending on the situation; See Section~\ref{sec:nuisance estimation} in the supplementary material for construction of estimates of $\mu_0$ and $\partial_{\bs{\beta}}\mu_0$ for different treatment models.


\subsection{Full BNNW Algorithm\label{sec:cross-fitting}}

Building on the procedures in Sections~\ref{sec:The-estimation-of} and~\ref{sec:bell}, we now present the complete BNNW algorithm. To incorporate flexible machine learning estimators $\widehat{\mu}_{0}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})$
and $\partial_{\bs{\beta}}\widehat{\mu}_{0}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}})$, while avoiding potential overfitting, we employ cross-fitting. 

Specifically, we partition the sample into $K\geq 2$ equal folds. For simplicity, from now on, we denote the total sample size by $N$, and assume $N=nK$ for some $n\in\mathbb{N}^+$. Let $I_k = \{(k-1)\cdot n +1,\ldots, kn\}$ for $k=1,\ldots, K$ be 
the indices of the $k$-th fold, and $I_{-k}=\{1,\ldots,N\}\backslash I_{k}$
be the indices of the remaining data excluding the $k$-th fold.
The proposed BNNW algorithm proceeds as follows.
\begin{myalgorithm}[BNNW Algorithm]\label{alg:BNNW} 
\begin{enumerate}
\item for every $k=1,\ldots,K$, 
\begin{enumerate}
\item using the sample in $I_{-k}$ to construct an estimator $\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(\cdot,\cdot)$
following \eqref{eq:estimation of pi definition};
\item splitting $I_{-k}$ into two parts $I_{-k}^{(1)}$ and $I_{-k}^{(2)}$
with equal size; using the sample in $I_{-k}^{(1)}$ to construct
an initial estimator $\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)}$ following
\eqref{def:beta_DNN}; using the sample in $I_{-k}^{(2)}$ to construct
estimators $\widehat{\mu}^{(-k)}(\cdot,\cdot;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})$
and $\widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(\cdot,\cdot;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})$
respectively;
\item Calculate the solution of the proposed balanced calibration problem: 
\[
\widehat{w}^{(k)}_{i}=\rho^{\prime}\left(\widehat{\pi}^{(-k)}_{\mathrm{DNN}}(T_{i},\bs X_{i})\hat{\bs{\lambda}}_k^{\trans}\widehat{\bs{\xi}}^{(k)}(T_{i},\bs X_{i})\right)\ \text{for}\ i\in I_k,
\]
where $\hat{\bs{\lambda}}_k$ is the unique maximizer of the refined concave function 
\[
\hat{G}(\bs{\lambda}):=\frac{1}{n}\sum_{i\in I_k}\rho\left\{\widehat{\pi}^{(-k)}_{\mathrm{DNN}}(T_{i},\bs X_{i})\bs{\lambda}^{\trans}\widehat{\bs{\xi}}^{(k)}(T_{i},\bs X_{i})\right\}-\frac{1}{n(n-1)}\sum_{j\neq l \in I_{k}}\bs{\lambda}^{\trans}\widehat{\bs{\xi}}^{(k)}(T_{j},\bs X_{l})\,,
\]
with $\hat{\bs{\xi}}^{(k)}(t,\bs x):=\left(\widehat{\mu}^{(-k)}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})^{\trans},\vec{\left\{ \widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})\right\} }^{\trans}\right)^{\trans}$.
%\[
%\begin{cases}
%(\widehat{w}_{i}^{(k)})_{i\in I_{k}}=\arg\min_{w_i:i\in I_k} \sum_{i\in I_{k}}D(w_{i})\text{ s.t.}\\
%\frac{1}{n}\sum_{i\in I_{k}}w_{i}\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(T_{i},\bs X_{i})\widehat{\mu}^{(-k)}(T_{i},\bs X_{i};\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})=\frac{1}{n(n-1)}\sum_{j\neq l\in I_{k}}\widehat{\mu}^{(-k)}(T_{j},\bs X_{l};\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)});\\
%\frac{1}{n}\sum_{i\in I_{k}}w_{i}\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(T_{i},\bs X_{i})\widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(T_{i},\bs X_{i};\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})=\frac{1}{n(n-1)}\sum_{j\neq l\in I_{k}}\widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(T_{j},\bs X_{l};\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)}),
%\end{cases}
%\]
Then obtaining the BNN weights $\widehat{\pi}_{\mathrm{BNN}}^{(k)}(T_{i},\bs X_{i})=\widehat{w}_{i}^{(k)}\cdot\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(T_{i},\bs X_{i})$
for $i\in I_{k}$; 
\item solving the optimization problem: 
\begin{equation}
\widehat{\bs{\beta}}_{\mathrm{BNNW}}^{(k)}=\underset{\bs{\beta}\in\R^{p}}{\arg\min}\sum_{i\in I_{k}}\widehat{\pi}_{\mathrm{BNN}}^{(k)}(T_{i},\bs X_{i})L(Y_{i},g(T_{i};\bs{\beta})).\label{eq:minimization step}
\end{equation}
\end{enumerate}
\item estimating $\bs{\beta}^{*}$ by 
\begin{equation}
\widehat{\bs{\beta}}_{\mathrm{BNNW}}=\frac{1}{K}\sum_{k=1}^{K}\widehat{\bs{\beta}}_{\mathrm{BNNW}}^{(k)}.\label{eq:main estimator}
\end{equation}
\end{enumerate}
%
\end{myalgorithm}


\begin{rem}
The BNNW method takes a similar sample-splitting and cross-fitting
approaches as \citet{kallus2022Localized}. Their empirical results suggest that setting $K=5$ provides sufficiently good performance. Figure \ref{fig:cross-fitting} sketches the BNNW algorithm
for $\widehat{\bs{\beta}}_{\mathrm{BNNW}}^{(1)}$ when $K=5$.
\end{rem}
