\section{Large Sample Properties\label{sec:Theoretical-Properties}}

\subsection{Convergence Rates of $\widehat{\pi}_{\mathrm{DNN}}$ and $\widehat{\bs{\beta}}_{\mathrm{DNNW}}$ \label{subsec:initial pi and betaDNN}}

This subsection establishes the convergence rates of the DNN
weights $\widehat{\pi}_{\mathrm{DNN}}$ and the initial estimator $\widehat{\bs{\beta}}_{\mathrm{DNNW}}$
defined in \eqref{eq:estimation of pi definition} and \eqref{def:beta_DNN}
respectively. Without loss of generality, we focus on the case that
$T$ is continuously distributed and assume that $\mathcal{X}=[0,1]^{d}$
and $\mathcal{T}=[0,1]$. The theory for discretely distributed $T$
can be similarly established.
\begin{assumption}
\label{assu:ass for estimate of pi} Let $M>1$ be a finite constant.
\begin{enumerate}[label=(\alph*)]
\item $\underset{(t,\bs x)\in[0,1]^{d+1}}{\inf}\pi_{0}(t,\bs x)\geq1/M$.
\item The stabilized weighting function $\pi_{0}(t,\bs x)$ lies in the
smooth function space $C^{s_{\pi}}\left([0,1]^{d+1}\right)$ with
smoothness $s_{\pi}\in\N^{+}$: 
\[
\pi_{0}(t,\bs x)\in C^{s_{\pi}}\left([0,1]^{d+1}\right):=\left\{ \pi:\max_{\bs{\alpha}\in\mathbb{\N}^{d+1},\left\Vert \bs{\alpha}\right\Vert _{1}\leq s_{\pi}}\underset{(t,\bs x)\in[0,1]^{d+1}}{\sup}\left|\partial^{\bs{\alpha}}\pi(t,\bs x)\right|\leq M\right\} ,
\]
where $\left\Vert \bs{\alpha}\right\Vert _{1}:=\alpha_{1}+\cdots+\alpha_{d+1}$
and $\partial^{\bs{\alpha}}\pi$ is the partial derivative.
\end{enumerate}
\end{assumption}
%
\begin{assumption}
\label{assu:regularity conditions} Recall $h(Y,T;\bs{\beta})=L^{\prime}(Y,g(T;\boldsymbol{\beta}))\cdot\partial g(T;\bs{\beta})/\partial\bs{\beta}$.
\begin{enumerate}[label=(\alph*)]
\item The parameter space $\varTheta\subset\R^{p}$ is a compact set and
the true parameter $\bs{\beta}^{*}$ is an interior point of $\varTheta$. 
\item For all $\delta>0$, there exists $\epsilon(\delta)>0$ such that
$\inf_{\left\Vert \bs{\beta}-\bs{\beta}^{*}\right\Vert >\delta}\left\Vert \e\left[\pi_{0}(T,\bs X)h(Y,T;\bs{\beta})\right]\right\Vert \geq\epsilon(\delta)>0$.
\item Define $\Sigma(\bs{\beta}):=\partial\e\left[\pi_{0}(T,\bs X)h(Y,T;\bs{\beta})\right]/\partial\bs{\beta}^{\trans}$
and $\Sigma_{0}:=\Sigma(\bs{\beta}^{*})$. The singular values of
$\Sigma_{0}$ are bounded between $c_{1}$ and $c_{2}$, where $0<c_{1}\leq c_{2}<\infty$
are constants. Furthermore, $\Sigma(\bs{\beta})$ is continuous at
$\bs{\beta}=\bs{\beta}^{*}$.
\end{enumerate}
\end{assumption}
%

\begin{assumption}
\label{assu:estimation of init DNN beta} Consider $\widehat{\bs\beta}_{\mathrm{DNN}}$ nearly minimizes the objective function in the sense that
\[
\left\Vert \frac{1}{n}\sum_{i=1}^{n}\widehat{\pi}_{\mathrm{DNN}}(T_{i},\bs X_{i})h(Y_{i},T_{i};\widehat{\bs{\beta}}_{\mathrm{DNNW}})\right\Vert \leq\left\Vert \frac{1}{n}\sum_{i=1}^{n}\widehat{\pi}_{\mathrm{DNN}}(T_{i},\bs X_{i})h(Y_{i},T_{i};\bs{\beta}^{*})\right\Vert +o_{P}(n^{-1/2}).
\]

\end{assumption}

\begin{assumption}
\label{assu:VC type class}For any $1\leq j\leq p$, let $h_{j}(Y,T;\bs{\beta})$
be the $j$-th component of $h(Y,T;\bs{\beta})$. The function class
$\mathcal{H}_{j}:=\left\{ h_{j}(Y,T;\bs{\beta}):\bs{\beta}\in\varTheta\right\} $
attached with the measurable envelop $H_{j}(Y,T):=\sup_{\bs{\beta}\in\varTheta}\left|h_{j}(Y,T;\bs{\beta})\right|$ has the covering number 
\[
\sup_{Q}\log N\left(\epsilon\left\Vert H_{j}\right\Vert _{Q,2},\mathcal{H}_{j},\left\Vert \cdot\right\Vert _{Q,2}\right)\leq\nu\log\left(a/\epsilon\right)\text{ uniformly over }0<\epsilon\leq1,
\]
where $a,\nu>0$ are constants and $\sup_{Q}$ is taken over all finitely
discrete probability measures. Furthermore, $\left\Vert \sup_{\bs{\beta}\in\varTheta}\left\Vert h(Y,T;\bs{\beta})\right\Vert \right\Vert _{P,2}<\infty$.
\end{assumption}
%
Assumption~\ref{assu:ass for estimate of pi} is a standard smoothness
condition for functional approximation, see also \citet{farrell2021Deepa}
and \citet{colangelo2023double}. The second part of this assumption
essentially implies the bounded restriction $\sup_{(t,\bs x)\in\mathcal{T}\times\mathcal{X}}\pi_{0}(t,\bs x)\leq M$. Assumptions~ \ref{assu:regularity conditions} and~\ref{assu:estimation of init DNN beta} are standard in M-estimation theory, see, e.g., \cite{chen2003Estimation,vaart1998Asymptotic}. Assumption~\ref{assu:VC type class} assumes $\mathcal{H}_{j}$ to
be VC type. Typically, this assumption is verified by showing that
$\mathcal{H}_{j}$ is a VC-subgraph class (\citet{vaart1996Weak}).
It can be shown that this assumption holds for a large variety of
the loss function $L(y,z)$ and the response model $g(t;\bs{\beta})$,
e.g., $g(t;\bs{\beta})=t\beta_{1}+(1-t)\beta_{0}$ with $L(y,z)=(y-z)^{2}/2$,
$L(y,z)=(y-z)(\tau-1(y-z\leq0))$ or $L(y,z)=(y-z)^{2}\left|\tau-1(y-z\leq0)\right|$.
Similar assumptions are also imposed by \citet{chernozhukov2018Double}
and \citet{kallus2022Localized}. 
%
%

\begin{proposition}
\label{thm:rate for init DNN beta}Suppose that Assumptions \ref{assu:unconfounded}-\ref{assu:VC type class}
hold. If the DNN class $\f_{\mathrm{DNN}}(\mathcal{W},\mathcal{D})$
is constructed with width $\mathcal{W}\geq17s_{\pi}^{d+2}3^{d+3}(d+1)$
and depth $\mathcal{D}\geq108s_{\pi}^{2}+2(d+1)$ satisfying $\mathcal{W}\mathcal{D}\asymp n^{(d+1)/(4s_{\pi}+2d+2)}\left(\log n\right)^{2}$ and $\left\Vert\widehat{\pi}_{\mathrm{DNN}}\right\Vert_{\infty}\leq M$, then, with probability approaching one, we have
\[
\left\Vert \widehat{\pi}_{\mathrm{DNN}}(T,\bs X)-\pi_{0}(T,\bs X)\right\Vert _{P,2}\lesssim n^{-\frac{s_{\pi}}{2s_{\pi}+d+1}}\log^{5}n
\]
and 
\[
\left\Vert \widehat{\bs{\beta}}_{\mathrm{DNNW}}-\bs{\beta}^{*}\right\Vert \lesssim n^{-\frac{s_{\pi}}{2s_{\pi}+d+1}}\log^{5}n\,.
\]
\end{proposition}


Proposition \ref{thm:rate for init DNN beta} gives the convergence rates of $\widehat{\pi}_{\mathrm{DNN}}(T,\bs X)$ and $\widehat{\bs{\beta}}_{\mathrm{DNNW}}$,
whose proof is relegated to Section~\ref{Proof:thm:rate for pi} of the supplementary material. It can be seen from the proof that $\widehat{\pi}_{\mathrm{DNN}}$ has a non-negligible bias, and thus, it is not root-$n$ consistent. Furthermore, the bias of $\widehat{\pi}_{\mathrm{DNN}}$ is carried over to $\widehat{\bs{\beta}}_{\mathrm{DNNW}}$. 


\subsection{Asymptotic Distribution of $\widehat{\bs{\beta}}_{\mathrm{BNNW}}$}

In this section, we establish the consistency and asymptotic normality
of our proposed BNNW estimator. Furthermore, we show that the asymptotic
variance of our estimator reaches the semiparametric efficiency bound
(\citealp{bickel1993Efficient,tsiatis2006Semiparametric}). We first state the assumptions.

\begin{assumption}
\label{assu:near zero ass}Recall that $h(Y,T;\bs{\beta})=L^{\prime}(Y,g(T;\boldsymbol{\beta}))\cdot\partial g(T;\bs{\beta})/\partial\bs{\beta}$. 
For any $k=1,\ldots,K$, 
\[
\left\Vert \frac{1}{n}\sum_{i\in I_{k}}\hat{\pi}_{\mathrm{BNN}}^{(k)}(T_{i},\bs X_{i})h(Y_{i},T_{i};\hat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})\right\Vert =\inf_{\bs{\beta}\in\varTheta}\left\Vert \frac{1}{n}\sum_{i\in I_{k}}\hat{\pi}_{\mathrm{BNN}}^{(k)}(T_{i},\bs X_{i})h(Y_{i},T_{i};\bs{\beta})\right\Vert +o_{P}(N^{-1/2}).
\]
\end{assumption}
%
\begin{assumption}
\label{assu:VC type class-mu} Recall that $\mu_{0}(T,\bs X;\bs{\beta})=\e\left[h(Y,T;\bs{\beta})\mid T,\bs X\right]$.
For any $1\leq j\leq p$, let $\mu_{0j}(T,\bs X;\bs{\beta})$ be the
$j$-th component of $\mu_{0}(T,\bs X;\bs{\beta})$. The function class
$\mathcal{F}_{j}:=\left\{ (T,\bs X)\mapsto\mu_{0j}(T,\bs X;\bs{\beta}):\bs{\beta}\in\varTheta\right\} $
attached with measurable envelop $F_{j}:=\sup_{\bs{\beta}\in\varTheta}\left|\mu_{0j}(T,\bs X;\bs{\beta})\right|$
satisfies 
\[
\sup_{Q}\log N\left(\epsilon\left\Vert F_{j}\right\Vert _{Q,2},\mathcal{F}_{j},\left\Vert \cdot\right\Vert _{Q,2}\right)\leq\nu\log\left(a/\epsilon\right)\text{ uniformly over }0<\epsilon\leq1,
\]
where $a,\nu>0$ are constants and $\sup_{Q}$ is taken over all finitely
discrete probability measures. 
\end{assumption}
%
\begin{assumption}
\label{assu:L2 continuous}For any $1\leq j\leq p$, let $h_{j}(Y,T;\bs{\beta})$
be the $j$-th component of $h(Y,T;\bs{\beta})$ and the function class
$\left\{ h_{j}(Y,T;\bs{\beta}):\bs{\beta}\in\varTheta\right\} $ satisfies
\[
\sup_{\bs{\beta}:\left\Vert \bs{\beta}-\bs{\beta}^{*}\right\Vert <\delta}\e\left[\left|h_{j}(Y,T;\bs{\beta})-h_{j}(Y,T;\bs{\beta}^{*})\right|^{2}\right]^{1/2}\leq a\cdot\delta^{b}
\]
for any small $\delta>0$ and for some finite positive constants $a$
and $b$. 
\end{assumption}

\begin{assumption}[Rate doubly robust]
\label{assu:conver rate for nuisance}Let $\zeta_{\mu},\zeta_{\pi},\zeta_{u},\zeta_{\beta},c^{*}\geq0$
be some finite constants.
\begin{enumerate}[label=(\alph*)]
\item For any $1\leq j\leq p$, let $\mu_{0j}(t,\bs x;\bs{\beta})$ be
the $j$-th component of $\mu_{0}(t,\bs x;\bs{\beta})$. $\mu_{0j}(t,\bs x;\bs{\beta})$
is twice continuously differentiable in $\bs{\beta}\in\varTheta$
and $\e\left[\sup_{\bs{\beta}\in\varTheta}\left\Vert \partial^{2}\mu_{0j}(T,\bs X;\bs{\beta})/(\partial\bs{\beta}\partial\bs{\beta}^{\trans})\right\Vert ^{2}\right]^{1/2}$ $\leq c^{*}$.
\item Either one of the following conditions holds:
\begin{enumerate}[label=(\roman*)]
\item $c^{*}\neq0$, $\zeta_{\pi}+\zeta_{\mu}\geq1/2$, $\zeta_{\pi}+\zeta_{u}+\zeta_{\beta}\geq1/2$,
$\zeta_{\pi}+2\zeta_{\beta}\geq1/2$, $\zeta_{\beta}>0$;
\item $c^{*}=0$, $\zeta_{\pi}+\zeta_{\mu}\geq1/2$, $\zeta_{\pi}+\zeta_{u}+\zeta_{\beta}\geq1/2$,
$\zeta_{\beta}+\zeta_{u}>0$;
\end{enumerate}
\item For a constant $\rho_{0}>0$ and a sequence of non-negative numbers
$\rho_{N}$ satisfying $\rho_{N}=o((\log N)^{-1})$ as $N\to\infty$,
it holds that, for any $1\leq k\le K$, with probability approaching
one,
\begin{align*}
\left\Vert \widehat{\mu}^{(-k)}(T,\bs X;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})-\mu_{0}(T,\bs X;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})\right\Vert _{P,2} & \leq\rho_{N}N^{-\zeta_{\mu}},\\
\left\Vert \widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(T,\bs X;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})-\partial_{\bs{\beta}}\mu_{0}(T,\bs X;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})\right\Vert _{P,2} & \leq\rho_{0}N^{-\zeta_{u}},\\
\left\Vert \widehat{\pi}_{\mathrm{DNN}}^{(-k)}(T,\bs X)-\pi_{0}(T,\bs X)\right\Vert _{P,2}\leq\rho_{N}N^{-\zeta_{\pi}},\ \left\Vert \widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)}-\bs{\beta}^{*}\right\Vert  & \leq\rho_{0}N^{-\zeta_{\beta}}.
\end{align*}
\end{enumerate}
\end{assumption}
%
\begin{assumption}
\label{assu:moment bound conditions}Let $M>0$ and $q>2$ be some
finite constants. For any $1\leq k\le K$, 
\begin{enumerate}[label=(\alph*)]
\item $\sup_{(t,\bs x)\in\mathcal{T}\times\mathcal{X}}\pi_{0}(t,\bs x)\leq M$;
\item it holds that $\sup_{t\in\mathcal{T},\bs x\in\mathcal{X}}\left|\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(t,\bs x)\right|\leq M$,
$\left\Vert \widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(T,\bs X;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})\right\Vert _{P,(2q)\vee(1/\zeta_{\pi})}\leq M$,
$\left\Vert \widehat{\mu}^{(-k)}(T,\bs X;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})\right\Vert _{P,(2q)\vee(1/\zeta_{\pi})}\leq M$
with probability approaching one, where $\zeta_{\pi}$ is from Assumption
\ref{assu:conver rate for nuisance};
\item %For any $1\leq k\le K$, define $\hat{\bs{\xi}}^{(k)}(t,\bs x):=\left(\widehat{\mu}^{(-k)}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})^{\trans},\vec{\left\{ \widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(t,\bs x;\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})\right\} }^{\trans}\right)^{\trans}$.
the minimum singular value of $\e\left[\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(T,\bs X)^{2}\hat{\bs{\xi}}^{(k)}(T,\bs X)\hat{\bs{\xi}}^{(k)}(T,\bs X)^{\trans}\mid(T_{i},\bs X_{i},Y_{i})_{i\notin I_{k}}\right]$
is larger than some constant $c_{\xi}>0$ with probability approaching
one;
\item $\e\left[\sup_{\bs{\beta}\in\varTheta}\left\Vert \partial_{\bs{\beta}}\mu_{0}(T,\bs X;\bs{\beta})\right\Vert ^{2}\right]<\infty$,
$\e\left[\sup_{\bs{\beta}\in\varTheta}\left\Vert h(Y,T;\bs{\beta})\right\Vert ^{2q}\right]<\infty$.
\end{enumerate}
\end{assumption}
%
Assumption~\ref{assu:near zero ass} allows for an approximate minimizer solution of (\ref{eq:minimization step}), which is useful if the empirical
minimization problem (\ref{eq:minimization step}) has no exact minimizer.
Similar assumptions are also employed by \citet{ai2003Efficient,chernozhukov2018Double,kallus2022Localized,chen2003Estimation}. Similar to Assumption \ref{assu:VC type class}, Assumption \ref{assu:VC type class-mu}
can be verified for a large variety of the loss function $L(y,z)$
and the outcome model $g(t;\bs{\beta})$. Assumption \ref{assu:L2 continuous} only requires $h_{j}(Y,T;\bs{\beta})$
to be $L_{2}$-continuous at $\bs{\beta}^{*}$, it still allows $h_{j}(Y,T;\bs{\beta})$
to be discontinuous so that our theory is applicable to estimating
the QTE. Assumption~\ref{assu:conver rate for nuisance} imposes conditions
on the convergence rate of the nuisance estimators. It can be verified
by Proposition~\ref{thm:rate for init DNN beta} and many other existing results on machine learning convergence rates \citep[e.g.,][]{chi2022Asymptotic,jiao2023Deep}.
This assumption implies that our estimator
is ``rate doubly robust'' in that we require the product of the
convergence rates of $\hat{\pi}_{\mathrm{DNN}}^{(-k)}(\cdot,\cdot)$ and $\hat{\mu}^{(-k)}(\cdot,\cdot;\bs{\beta})$
(or $\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)}$) to be $o(N^{-1/2})$.\footnote{Our method also enjoys the doubly robustness property in the sense of \cite{bang2005Doubly}, see Section~\ref{sec:doubly robust} in the supplementary material.} For binary ATE,
where $L(y,z)=(y-z)^{2}/2$ and $g(t;\bs{\beta})=\beta_{1}t+\beta_{0}(1-t)$,
it can be shown that $\partial_{\bs{\beta}}\mu_{0}(t,\bs x;\bs{\beta})=\diag\{1-t,t\}$
(see Section~\ref{subsec:The-discussion-of}), giving $c^{*}=0$ in Assumption \ref{assu:conver rate for nuisance}(a) and corresponding to Assumption \ref{assu:conver rate for nuisance}(b)(ii). Then, we can take $\widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(t,\bs x;\bs{\beta})=\diag\{1-t,t\}$, achieving $\zeta_u = \infty$. Thereby,  Assumption~\ref{assu:conver rate for nuisance}
reduces to requiring $\zeta_{\mu},\zeta_{\pi}\geq0$ and $\zeta_{\pi}+\zeta_{\mu}\geq1/2$, which is consistent with the ``rate doubly robust'' result in the
literature \citep{chernozhukov2018Double}, and does not impose any rate requirements on $\zeta_\beta$ of the initial estimator $\bs{\widehat{\beta}}_{\mathrm{DNNW}}^{(-k)}$. Thus, we can simply take $\bs{\widehat{\beta}}_{\mathrm{DNNW}}^{(-k)}=\bs 0$
and use samples in $I_{-k}$ to construct estimator $\widehat{\mu}^{(-k)}(\cdot,\cdot;\bs 0)$
in our BNNW Algorithm \ref{alg:BNNW}. We next consider the estimation of binary QTE.
Provided that we have a consistent estimator $\widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(\cdot,\cdot;\bs{\beta})$
for $\partial_{\bs{\beta}}\mu_{0}(\cdot,\cdot;\bs{\beta})$, Assumption
\ref{assu:conver rate for nuisance} is less restrictive than condition
vii of Theorem 3 in \citet{kallus2022Localized}, which requires that
$\zeta_{\pi}+\zeta_{\mu}\geq1/2$ and $\zeta_{\pi}+\zeta_{\beta}\geq1/2$.
If a consistent estimator for $\partial_{\beta}\mu_{0}(\cdot,\cdot;\bs{\beta})$
is unavailable, Assumption \ref{assu:conver rate for nuisance} reduces
to the same condition as vii of Theorem 3 in \citet{kallus2022Localized}. Assumption \ref{assu:moment bound conditions} imposes some moment conditions concerning $\pi_{0}(\cdot,\cdot)$, $\mu_{0}(\cdot,\cdot;\bs{\beta})$
and $\partial_{\bs{\beta}}\mu_{0}(\cdot,\cdot;\bs{\beta})$ and their
estimates. 
\begin{thm}
\label{thm:asymptotic normal} Recall the definitions of $\Sigma_0$ and $\psi(Y,T,\bs X;\bs{\beta}^{*},\pi_0, \mu_0(T,\bs{X};\bs{\beta}^*))$ in Section~\ref{sec:problem}. Re-denote the latter as  $\psi(Y,T,\bs X;\bs{\beta}^{*})$ for notational simplicity.
%\begin{align*}
%\psi(Y,T,\bs X;\bs{\beta}^{*}) & :=\pi_{0}(T,\bs X)h(Y,T;\bs{\beta}^{*})-\pi_{0}(T,\bs X)\mu_{0}(T,\bs X;\bs{\beta}^{*})\\
 %& \qquad+\e\left[\mu_{0}(T,\bs X;\bs{\beta}^{*})\pi_{0}(T,\bs X)\mid T\right]+\e\left[\mu_{0}(T,\bs X;\bs{\beta}^{*})\pi_{0}(T,\bs X)\mid\bs X\right].
%\end{align*}
Under Assumptions~\ref{assu:unconfounded}, \ref{assu:regularity conditions}-\ref{assu:VC type class},
and \ref{assu:near zero ass}-\ref{assu:moment bound conditions},
the BNNW estimator defined in (\ref{eq:main estimator}) admits 
\[
\hat{\bs{\beta}}_{\mathrm{BNNW}}-\bs{\beta}^{*}=-\frac{1}{N}\sum_{i=1}^{N}\Sigma_{0}^{-1}\psi(Y_{i},T_{i},\bs X_{i};\bs{\beta}^{*})+o_{P}(N^{-1/2}),
\]
and $\sqrt{N}\left(\hat{\bs{\beta}}_{\mathrm{BNNW}}-\bs{\beta}^{*}\right)\tod N(\bs 0,V_{\mathrm{eff}})$,
where $V_{\text{eff}}:=\Sigma_{0}^{-1}\e\left[\psi(Y,T,\bs X;\bs{\beta}^{*})\psi(Y,T,\bs X;\bs{\beta}^{*})^{\trans}\right]\Sigma_{0}^{-1}$
attains the semiparametric efficiency bound, the least possible variance achievable by a regular estimator.
\end{thm}
Theorem \ref{thm:asymptotic normal} implies that our BNNW
algorithm yields a semiparametric efficient estimator for $\bs{\beta}^{*}$
under relatively mild conditions. It is worth noting that if the stabilized
weighting function $\pi_0$ is known, one can replace $\widehat{\pi}$ in the minimization \eqref{eq:naive minimization step} by $\pi_0$ to obtain an estimator of $\bs{\beta}^*$. Note that the estimator proposed by \citet[p.786]{ai2021Unified} is a special case of \eqref{eq:naive minimization step}. Using their argument, it can be shown that the resulting estimator is inefficient. On the contrary,
Theorem~\ref{thm:asymptotic normal} shows that the BNNW
estimator remains semiparametric efficient even when replacing the initial weighting $\widehat{\pi}_{\text{DNN}}$ by the true
$\pi_0$. Therefore, calibrating the stabilized weighting function is not just for reducing bias, but also for increasing the robustness of the resulting estimator.

\section{Inference \label{sec:Inference}}

In this section, we employ the weighted bootstrap method to conduct
the inference for $\bs{\beta}^{*}$. 

\begin{myalgorithm}[Weighted Bootstrap]Let $B>1$ be a constant.
The weighted bootstrap procedure has the following steps: for $b=1,2,\ldots,B$, 
\begin{enumerate}
\item Generate independent and identically distributed non-negative sub-exponential random variables $U_{1},\ldots,U_{N}$,
independent of $\{(T_{i},\bs X_{i},Y_{i})\}_{i=1}^{N}$,
with $\e(U_{1})=\var(U_{1})=1$; 
\item For $k=1,2,\ldots,K$, 
\begin{enumerate}
\item Calculate
\[
\widehat{w}^{(k)}_{i}=\rho^{\prime}\left\{U_i\widehat{\pi}^{(-k)}_{\mathrm{DNN}}(T_{i},\bs X_{i})\hat{\bs{\lambda}}_k^{\trans}\widehat{\bs{\xi}}^{(k)}(T_{i},\bs X_{i})\right\}\ \text{for}\ i\in \{1,...,n\},
\]
where $\hat{\bs{\lambda}}_k$ is the unique maximizer of the refined concave function 
{\small\[
\hat{G}(\bs{\lambda}):=\frac{1}{n}\sum_{i\in I_k}\rho\left\{U_i\widehat{\pi}^{(-k)}_{\mathrm{DNN}}(T_{i},\bs X_{i})\bs{\lambda}^{\trans}\widehat{\bs{\xi}}^{(k)}(T_{i},\bs X_{i})\right\}-\frac{1}{n(n-1)}\sum_{j\neq l \in I_{k}}U_jU_l\bs{\lambda}^{\trans}\widehat{\bs{\xi}}^{(k)}(T_{j},\bs X_{l})\,,
\]}
%Solve the minimization problem: 
%\[
%\begin{cases}
%(\widehat{w}_{i}^{(k)})_{i\in I_{k}}=\arg\min_{w_i:i\in I_k} \sum_{i\in I_{k}}D(w_{i})\text{ s.t.}\\
%\frac{1}{n}\sum_{i\in I_{k}}w_{i}U_{i}\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(T_{i},\bs X_{i})\hat{\mu}^{(-k)}(T_{i},\bs X_{i};\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})=\frac{1}{n(n-1)}\sum_{j\neq l\in I_{k}}U_{j}U_{l}\hat{\mu}^{(-k)}(T_{j},\bs X_{l};\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})\\
%\frac{1}{n}\sum_{i\in I_{k}}w_{i}U_{i}\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(T_{i},\bs X_{i})\widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(T_{i},\bs X_{i};\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})=\frac{1}{n(n-1)}\sum_{j\neq l\in I_{k}}U_{j}U_{l}\widehat{\partial_{\bs{\beta}}\mu}^{(-k)}(T_{j},\bs X_{l};\widehat{\bs{\beta}}_{\mathrm{DNNW}}^{(-k)})
%\end{cases}
%\]
where the nuisances estimates are taken from Step 1 in Algorithm~\ref{alg:BNNW}; 
\item solve $\hat{\bs{\beta}}_{b}^{(k)}$ by the minimization problem: 
$$
\hat{\bs{\beta}}_{b}^{(k)}=\underset{\bs{\beta}\in\R^{p}}{\arg\min}\sum_{i\in I_{k}}\widehat{w}_{i}^{(k)}U_{i}\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(T_{i},\bs X_{i})L(Y_{i},g(T_{i};\bs{\beta}))\,;$$
\end{enumerate}
\item Define the weighted bootstrap estimator as $\hat{\bs{\beta}}_{b}=K^{-1}\sum_{k=1}^{K}\hat{\bs{\beta}}_{b}^{(k)}$.
\end{enumerate}
\end{myalgorithm}

In our simulation studies and real applications, we take $U_i\sim 2\cdot\mathrm{Bernoulli}(0.5) $ for $1\leq i \leq N$. Our weighted bootstrap method does not require estimating the nuisances
for every $1\leq b\leq B$, but uses the estimates from our BNNW Algorithm~\ref{alg:BNNW}.
Therefore, our inference procedure is time-efficient. Before validating our weighted bootstrap procedure, we need an assumption, which is
similar to Assumption~\ref{assu:near zero ass}. 
\begin{assumption}
\label{assu:bootstra near zero}For any $b=1,2,\ldots,B$ and $k=1,2,\ldots,K$,
{\footnotesize\[
\left\Vert \frac{1}{n}\sum_{i\in I_{k}}\widehat{w}_{i}^{(k)}U_{i}\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(T_{i},\bs X_{i})h(Y_{i},T_{i};\hat{\bs{\beta}}_{b}^{(k)})\right\Vert =\inf_{\bs{\beta}\in\varTheta}\left\Vert \frac{1}{n}\sum_{i\in I_{k}}\widehat{w}_{i}^{(k)}U_{i}\widehat{\pi}_{\mathrm{DNN}}^{(-k)}(T_{i},\bs X_{i})h(Y_{i},T_{i};\bs{\beta})\right\Vert +o_{P}(N^{-1/2})\,.
\]}
\end{assumption}
%
\begin{thm}
\label{thm:MB theorem}Under Assumptions \ref{assu:unconfounded},
\ref{assu:regularity conditions}-\ref{assu:VC type class}, and \ref{assu:VC type class-mu}-\ref{assu:bootstra near zero},
for any $b=1,2,\ldots,B$, 
\[
\hat{\bs{\beta}}_{b}-\bs{\beta}^{*}=-\frac{1}{N}\sum_{i=1}^{N}U_{i}\Sigma_{0}^{-1}\psi(Y_{i},T_{i},\bs X_{i};\bs{\beta}^{*})+o_{P}(N^{-1/2}).
\]
This, combined with Theorem \ref{thm:asymptotic normal} yields that
\[
\hat{\bs{\beta}}_{b}-\hat{\bs{\beta}}_{\mathrm{BNNW}}=-\frac{1}{N}\sum_{i=1}^{N}\left(U_{i}-1\right)\Sigma_{0}^{-1}\psi(Y_{i},T_{i},\bs X_{i};\bs{\beta}^{*})+o_{P}(N^{-1/2}).
\]
\end{thm}
%
Theorem \ref{thm:MB theorem} suggests that for any vector $\bs{\nu}\in\R^{p}$,
the $(1-\alpha)$ bootstrapped equitailed confidence interval for
$\bs{\nu}^{\trans}\bs{\beta}^{*}$ can be constructed as 
$
\left[\widehat{c}_{\alpha/2},\widehat{c}_{1-\alpha/2}\right]$, where $\widehat{c}_{\alpha/2}$ and $\widehat{c}_{1-\alpha/2}$ are the empirical quantiles of $\{ \bs{\nu}^{\trans}\hat{\bs{\beta}}_{b}:1\leq b\leq B\} $ at level $\alpha/2$ 
 and $1-\alpha/2$, respectively.
\begin{rem}
Section \ref{sec:Theoretical-Properties} establishes the asymptotic
normality of our BNNW estimator under mild conditions. This
suggests that a valid confidence
interval can also be constructed given a consistent estimate of the asymptotic variance. A direct way to estimate the asymptotic
variance $V$ is based on the influence function ${\Sigma}_{0}^{-1}\psi(Y,T,\bs X;\bs{\beta}^{*})$.
Specifically, one can estimate $V$ by 
\[
\hat{V}=\frac{1}{N}\sum_{i=1}^{N}\widehat{\Sigma}_{0}^{-1}\hat{\psi}(Y_{i},T_{i},\bs X_{i};\hat{\bs{\beta}})\hat{\psi}(Y_{i},T_{i},\bs X_{i};\hat{\bs{\beta}})^{\trans}\widehat{\Sigma}_{0}^{-1},
\]
where $\hat{\psi}(Y,T,\bs X;\hat{\bs{\beta}})$ and $\widehat{\Sigma}_{0}^{-1}$ are the estimates of
$\psi(Y,T,\bs X;\bs{\beta}^{*})$ and $\Sigma_{0}^{-1}$, respectively. This method, however, generally
yields poorly-performed estimator since estimating $\Sigma_{0}^{-1}\psi(Y,T,\bs X;\bs{\beta}^{*})$
requires additional estimates for $\e\left[\mu_{0}(T,\bs X;\bs{\beta}^{*})\pi_{0}(T,\bs X)\mid T\right]$,
$\e\left[\mu_{0}(T,\bs X;\bs{\beta}^{*})\pi_{0}(T,\bs X)\mid\bs X\right]$
and $\Sigma_{0}$, which is more challenging compared to the bootstrap-based
method, especially when the dimension of the covariates $\bs X$ is
large. 
\end{rem}

\section{Monte Carlo Studies \label{sec:Monte-Carlo-studies}}
To assess the performance of the BNNW estimator, we conduct Monte Carlo simulations under various scenarios. In Section \ref{sec:SimBinary}, we investigate the estimator’s performance with a binary treatment, followed by an analysis of its behavior with a continuous treatment in Section \ref{sec:SimContinuous}. %The comparisons are carried out with the corresponding benchmarks.

\subsection{Scenario 1: Binary Treatment \label{sec:SimBinary}}

%\subsubsection{Data Generating Process with a Binary Treatment}

For binary treatment, we consider a setting similar to that in \citet{donald2014}.
Let $U_{xj},U_{t},U_{y_{0}},U_{y_{1}}$ ($1\leq j\leq d$) be
independent uniform random variables over $[0,1]$, and $\bs X=(X_{1},\ldots,X_{d})^{\trans}$
be a vector of covariates with dimension $d$, $\bs{\gamma}_{b}\in\R^{d}$
be a predetermined constant that ensures $\bs X^{\trans}\bs{\gamma}_{b}\in(0,1)$.
The data-generating process with a binary treatment (DGP-B) is as follows:
\\
\textbf{DPG-B} : 
\[
\begin{aligned} & X_{j}=0.3+0.4U_{xj},\ j=1,\ldots,d\ \ \text{and}\ \ T=1(U_{t}<\bs X^{\trans}\bs{\gamma}_{b});\\
	& Y(0)=1(U_{y_{0}}\le\bs X^{\trans}\bs{\gamma}_{b})\frac{U_{y_{0}}^{2}}{\bs X^{\trans}\bs{\gamma}_{b}}+1(U_{y_{0}}>\bs X^{\trans}\bs{\gamma}_{b})U_{y_{0}};\\
	& Y(1)=1(U_{y_{1}}\le1-\bs X^{\trans}\bs{\gamma}_{b})\frac{2U_{y_{1}}^{2}}{1-\bs X^{\trans}\bs{\gamma}_{b}}+1(U_{y_{1}}>1-\bs X^{\trans}\bs{\gamma}_{b})2U_{y_{1}}.
\end{aligned}
\]


%\subsubsection{Effects of Binary Treatment Dataset}

To evaluate the performance of our method under setting with a binary
treatment, we estimate the ATE and QTE over samples simulated by DPG-B, with dimension of covariates $d=50$, sample size $N$ varies from 300 to 5000, and different quantiles. For each combination of configurations, we generate $S=100$ replications. We assess the performance of the point estimation by computing the bias, standard error (SE), and root mean squared error
(RMSE) of the $S=100$ estimates; see Section~\ref{sec:Num_details} of the supplementary materials for the formal definitions of these metrics.
For interval estimation,
the coverage probability (CP) and average width (AW) of 95\% confidence intervals are calculated 
over the $S=100$ replications.
We compare the ATE and QTE estimation results between our BNNW method and alternative ones.

\subsubsection{ATE}
We first compare our method to a double machine learning method in the literature \citep{chernozhukov2018Double}, which leverages a cross-fitted augmented inverse probability weighting (AIPW) as defined below, for ATE estimation. 
$$
{\small \hat{\tau}_{\text{AIPW}}  =\frac{1}{N}\sum_{k=1}^{K}\sum_{i\in I_{k}}\left(\hat{m}_{1}^{(-k)}(\boldsymbol{X}_{i})-\hat{m}_{0}^{(-k)}(\boldsymbol{X}_{i})+T_{i}\frac{Y_{i}-\hat{m}_{1}^{(-k)}(\boldsymbol{X}_{i})}{\hat{e}^{(-k)}(\boldsymbol{X}_{i})}-(1-T_{i})\frac{Y_{i}-\hat{m}_{0}^{(-k)}(\boldsymbol{X}_{i})}{1-\hat{e}^{(-k)}(\boldsymbol{X}_{i})}\right)\,,}
$$

where $\hat{e}^{(-k)}(\boldsymbol{X})$ and $\hat{m}_{t}^{(-k)}(\boldsymbol{X})$ are some estimates of the propensity score $P(T=1\lvert\boldsymbol{X})$ and the outcome regression $\e(Y|\bs{X}, T=t)$, respectively, 
using the sample in $I_{-k}$.
For both BNNW and AIPW methods, we split the sample into $K=5$ folds for cross-fitting. We compute $\hat{e}^{(-k)}(\boldsymbol{X})$ and $\hat{m}_{t}^{(-k)}(\boldsymbol{X})$ for AIPW and estimate $\bs\xi(T,\bs X)$ for BNNW using LightGBM with the number of boosted
trees as $300$ and maximum tree leaves as 10. To obtain $95\%$ confidence
intervals, the weighted bootstrap is conducted with $B=599$.

\begin{table}[!htbp]
  \caption{Bias, SE, RMSE of estimated ATE and coverage probability (CP), average width (AW) of the respective $95\%$ confidence interval, using BNNW or AIPW estimators over $100$ replications of simulated dataset with a binary treatment across different sample sizes.}
