\section{Proofs} \label{ap:proofs}

\subsection{Proof of Proposition \ref{prop:AMEDelta}}
Note that $\mathbbm{E}[Y_i(\bar{x})|X_i=x] = \E[Y_i|X_i=x]-ATT(x)$. The limit $\E[Y_i|X_i=\bar{x}^+]$ exists by Assumption \ref{as:continuoussupport} (ii) and $ATT(\bar{x}^+)$ exists by Assumption \ref{as:continuoussupport} (iii). Therefore,  $\E[Y_i(\bar{x})|X_i=\bar{x}^+]$ exists as well. Then, by $ATT(\bar{x}^+)=0,$ it must be equal to $\E[Y_i|X_i=\bar{x}^+]$. Therefore, 
\begin{align*}
    \text{ATT}(x)&=\E[Y_i|X_i=x]-\E[Y_i(\bar{x})|X_i=x]
    \\
    &=(\E[Y_i|X_i=x]-\E[Y_i|X_i=\bar{x}^+])-(\E[Y_i(\bar{x})|X_i=x])+\E[Y_i(\bar{x})|X_i=\bar{x}^+]):=m(x)-s(x),
\end{align*} 
which completes the result for the $\text{ATT}(x)$.

  Using again that $\mathbbm{E}[Y_i(\bar{x})|X_i=\bar{x}^+] = \E[Y_i|X_i=\bar{x}^+],$
    \begin{align*}
        \text{AME}_{\bar{x}}^+&:=\lim_{x\downarrow \bar{x}}\frac{\E[Y_i|X_i=x]-\E[Y_i(\bar{x})|X_i=x]}{x-\bar{x}}\\
        &=\lim_{x\downarrow \bar{x}} \left\{\frac{\E[Y_i|X_i=x]-\E[Y_i|X_i=\bar{x}^+]}{x-\bar{x}}-\frac{\E[Y_i(\bar{x})|X_i=x]+\E[Y_i(\bar{x})|X_i=\bar{x}^+]}{x-\bar{x}}\right\}\\
        &=\lim_{x\downarrow \bar{x}}\frac{\E[Y_i|X_i=x]-\E[Y_i|X_i=\bar{x}^+]}{x-\bar{x}}-\lim_{x\downarrow \bar{x}}\frac{\E[Y_i(\bar{x})|X_i=x]+\E[Y_i(\bar{x})|X_i=\bar{x}^+]}{x-\bar{x}}\\
        &=\lim_{x\downarrow \bar{x}}\frac{m(x)-m(\bar{x}^+)}{x-\bar{x}}-\lim_{x\downarrow \bar{x}}\frac{s(x)-s(\bar{x}^+)}{x-\bar{x}}:=m'(\bar{x}^+)-s'(\bar{x}^+),
    \end{align*}
    where the third line follows from the two limits existing separately, and the final line by $m(\bar{x}^+)=s(\bar{x}^+)=0$ (which follows immediately from their definitions), and then the definitions of $m'(\bar{x}^+)$ and $s'(\bar{x}^+)$ (see beginning of Section \ref{sec:model} for the introduction of this notation). 

    That the two limits above exist follows from parts (ii) and (iii) from Assumption \ref{as:continuoussupport} and the mean value theorem. Specifically, because $\E[Y_i|X_i=\bar{x}^+]$ exists and is finite and $\E[Y_i|X_i=x]$ is differentiable by part (ii) of Assumption \ref{as:continuoussupport}, the mean-value theorem applies, and therefore
    \begin{align} \label{eq:allisoneohm}
        \frac{\E[Y_i|X_i=x]-\E[Y_i|X_i=\bar{x}^+]}{x-\bar{x}}=\frac{d}{dx}\E[Y_i|X_i=x]\Big|_{x=\zeta(x)},
    \end{align}
    for some $\zeta(x)\in (\bar{x},x)$. The limit of the right-hand side exists by part (ii) of Assumption \ref{as:continuoussupport}, thus the limit of the left-hand side also exists. The argument for $s$ is analagous using part (iii) of Assumption \ref{as:smoothcounterfactual}. Note that \eqref{eq:allisoneohm} implies that $m'(\bar{x}) = \lim_{x \downarrow \bar{x}} m'(x)$ and $s'(\bar{x}) = \lim_{x \downarrow \bar{x}} s'(x)$, which will be useful in later proofs.

\subsection{Proof of Theorem \ref{thm:changeofvariables}}
    We begin by establishing local (strict) monotonicity of $s(x)$ on an interval $I = (\bar{x}, \bar{x}+\delta)$ where $\delta > 0$. By part (iii) of Assumption \ref{as:smoothcounterfactual} $\lim_{x \downarrow \bar{x}} s'(x) \ne 0$, or equivalently that for any $\epsilon > 0$, there exists a $\delta > 0$ such that $x \in (\bar{x},\bar{x}+\delta)$ implies $|s'(x)-k| \le \epsilon$, where we let $k:=s'(\bar{x}^+) \ne 0$. Now, consider $\epsilon = |k|/2,$ and define $I_\delta  = (\bar{x},\bar{x}+\delta)$ for the corresponding value of $\delta$. Then, $x \in I_\delta \implies |s'(x) - k| \le k/2$, which implies that $s'(x)$ has the same (non-zero) sign as $k$ does for all $x \in I_\delta$.

    Thus, $s$ admits an inverse function $u^{-1}(t)$ for all $t \in s(I_\delta)$. Given part (iii) of Assumption \ref{as:smoothcounterfactual}, $s'(x)$ exists for all $x \in (\bar{x},\bar{x}+\delta')$, where $\delta':=\min\{\delta, \varepsilon_3\}$. This implies that $s^{-1}$ admits the derivative function $\frac{d}{dt} s^{-1}(t) = 1/s'(s^{-1}(t))$ on $s(I)$, where we define $I:=(\bar{x},\bar{x}+\delta')$.

    Suppose first that $s$ is strictly increasing. Then, for any $t$,
    \begin{align*}
       P(s(X_i) \le t|X_i \in I) = P(X_i \le s^{-1}(t)|X_i \in I)
    \end{align*}
    Since $f_{X|I}(x) = \frac{d}{dx} P(X_i \le x|X_i \in I) = f_X(x)/P(X_i \in I)$ exists for all $x \in I$, this implies that $f_{s(X)|I}(t)$ exists for any $t \in s(I)$ and is equal to $\frac{d}{dt}P(X_i \le s^{-1}(t)|X_i \in I) = f_{X|I}(s^{-1}(t))/s'(s^{-1}(t))$, using the chain rule. Note that $P(X_i \in I)>0$ by part (i) of Assumption \ref{as:continuoussupport}. The case in which $s$ is decreasing is the same aside from the introduction of a minus sign. Combining both cases, we have that $|s'(x)| = f_{X|I}(x)/f_{s(X)|I}(s(x))$ for any $x \in I$.

\subsection{Proof of Theorem \ref{thm:extensivemargin}}  
    We have by Theorem \ref{thm:changeofvariables} that $s'(x)=\text{sgn}(s'(x)) \cdot f_{X|I}(x)/f_{s(X)|I}(s(x))$ for any $x \in I$. The limit $s'(\bar{x}^+)$ exists (and differs from zero) by part (iii) of Assumption \ref{as:continuoussupport}, and thus 
    $$s'(\bar{x}^+)= \lim_{x \downarrow \bar{x}} \left\{\text{sgn}(s'(x)) \cdot f_{X|I}(x)/f_{s(X)|I}(s(x))\right\}$$
    where $s'(\bar{x}^+) = \lim_{x \downarrow \bar{x}}s'(x)$ by the discussion following Eq. \eqref{eq:allisoneohm}. 

    Since $\text{sgn}(s'(x))$ is constant for $x\in I$ (see proof of Theorem \ref{thm:changeofvariables} above), $\theta= \text{sgn}(s'(\bar{x}^+))$ exists. The limit $f_{X|I}(x) = \frac{f_X(\bar{x}^+)}{P(X_i \in I)}$ exists by part (i) of Assumption \ref{as:continuoussupport}. Thus $f_{s(X)|I}(s(\bar{x}^+))$ must also exist, and
    $$s'(\bar{x}^+)= \theta \cdot f_{X|I}(\bar{x}^+)/f_{s(X)|I}(s(\bar{x}^+))$$
    Then by Proposition \ref{prop:AMEDelta}, we obtain the expression in Theorem \ref{thm:extensivemargin}.

\subsection{Proof of Lemma \ref{lem:theta}}
Under Assumption \ref{as:continuoussupport}, $\text{ATT}(\bar{x}^+)=0,$ so $\E[Y_i|X_i=\bar{x}^+]=\E[Y_i(\bar{x})|X_i=\bar{x}^+]$. Denote $y_{\bar{x}}:=\E[Y_i(\bar{x})|X_i^*=\bar{x}]$. Now consider first $\E[Y_i|X_i=\bar{x}] = \E[Y_i(\bar{x})|X_i^* \le \bar{x}] = \mathbbm{E}[\E[Y_i(\bar{x})|X_i^*]|X_i^* \le \bar{x}]$. The inner expectation is $\E[Y_i(\bar{x})|X_i^*] = y_{\bar{x}} + s(X^*_i)$, and thus $$\E[Y_i|X_i=\bar{x}^+]-\E[Y_i|X_i=\bar{x}] = -\mathbbm{E}[s(X_i^*)|X_i^* \le \bar{x}]$$
By part (ii) of Assumption \ref{as:smono}, $\text{sgn}(s(x))=-\theta$. Suppose that $\theta = 1$. Then $s(x) < 0$ for all $x \le \bar{x}$, and $\text{sgn}\left(\E[Y_i|X_i=\bar{x}^+]-\E[Y_i|X_i=\bar{x}]\right)=1$. If on the other hand $\theta = -1$, then $s(x) > 0$ for all $x \le \bar{x}$, and $\text{sgn}\left(\E[Y_i|X_i=\bar{x}^+]-\E[Y_i|X_i=\bar{x}]\right)=-1$.

Finally, suppose that in violation of part (iii) of Assumption \ref{as:smoothcounterfactual}, $s'(\bar{x})=0,$ so that $\theta = 0$. In this case, $s(x)=0$ for all $x < \bar{x}$ by Assumption \ref{as:smono}, and the expression of Lemma \ref{lem:theta} still holds. This is useful in establishing that the expression in Theorem \ref{thm:AMEid} holds even when there is no selection at $\bar{x}$.

\subsection{Proof of Theorem \ref{cor:AMEbunching}}
We first give a shorter proof that relies on a strengthening of Assumption \ref{as:bunchingcontinuousnew1}, as it is more intuitive. Specifically, suppose we add to Assumption \ref{as:bunchingcontinuousnew1} that $s'(x)$ and $f_{X^*}(x)$ are both continuous at $x=\bar{x}$. Then, paralleling the proof of Theorem \ref{thm:changeofvariables}, we could establish local monotonicity of $s(x)$ on an interval $I^* = (\bar{x}-\delta, \bar{x}+\delta)$ that now straddles both sides of the bunching point. To see this, let $k:=s'(\bar{x}) \ne 0$. Then by $\lim_{x \rightarrow \bar{x}} s'(x) = s'(\bar{x}) \ne 0$, we know that for $\epsilon =|k|/2$, there exists a $\delta > 0$ such that $|x-\bar{x}| < \delta$ implies $|s'(x)-k| \le |k|/2$, which implies that $s'(x)$ has the same (non-zero) sign as $k$ does for all $x \in I^*$. Then we would have, exactly as in the case of Theorem \ref{thm:changeofvariables}, that for any $x \in I^*$,
\begin{equation}\label{eq:changeofvariablesbunchingclosure}
s'(x)= \theta \cdot \frac{f_{X^*|I^*}(x)}{f_{s(X^*)|I^*}(s(x))},
\end{equation}
and in particular since $\bar{x} \in I^*$, $s'(\bar{x})= \theta \cdot \frac{f_{X^*|I^*}(\bar{x})}{f_{s(X^*)|I^*}(0)}$ using that $s(\bar{x})=0$ by continuity of $s$ at $\bar{x}$. We can now transform this expression so that it no longer depends on $f_{s(X^*)|I^*}(0),$ but it depends instead on $f_{s(X^*)|X^*\le \bar{x}}(0)$. Note that the point $\bar{x}$ belongs to the intersection of $I^*$ and the set $(-\infty,\bar{x}]$, so
$$f_{s(X^*)|I^*}(0) = \frac{P(X_i^* \le \bar{x})}{P(X_i^* \in I^*)} \cdot f_{s(X^*)|X^* \le \bar{x}}(0). $$
Meanwhile, $f_{X^*|I^*}(\bar{x}^+) = f_{X^*}(\bar{x})/P(X_i^* \in I^*)=f_{X^*}(\bar{x}^+)/P(X_i^* \in I^*)$. Thus, all together we have:
\begin{equation}\label{eq:sprimexnoi}
s'(\bar{x})=\theta\cdot \frac{f_{X^*}(\bar{x}^+)/F_X(\bar{x})}{f_{s(X^*)|X=\bar{x}}(0)}, 
\end{equation}
noting that $f_{s(X^*)|X^*\leq \bar{x}}=f_{s(X^*)|X=\bar{x}}$ and $P(X^* \le \bar{x}) = P(X=\bar{x}) = F_{X}(\bar{x}),$ since $X=\bar{x}$ if and only if $X^* \le \bar{x}$. Eq. \eqref{eq:sprimexnoi} is useful because the quantity $P(X_i^* \in I^*)$ for the unknown interval $I^*$ has canceled out. The final result then follows by Proposition \ref{prop:AMEDelta}, and using that $X_i=\bar{x} \iff X_i^* \le \bar{x}$.\\

Now, we show that the result holds under the weaker version of Assumption \ref{as:bunchingcontinuousnew1} made before the statement of Theorem \ref{cor:AMEbunching}. To begin, note that Assumptions \ref{as:continuoussupport}-\ref{as:bunchingcontinuousnew1} do not require $s(x)$ to be differentiable exactly at $\bar{x}$, though they do guarantee that $s'(\bar{x}^+)$ and $f_{X^*}(\bar{x}^+)$ exist. Without $s'(\bar{x})$, we cannot necessarily construct the interval $I^*$ used above that extends on either side of $\bar{x}$ whose width is based upon the value of $s'(\bar{x})$.

Instead, we can use Assumption \ref{as:smono} and the existence of $f_{s(X^*)}(0)$ by Assumption \ref{as:bunchingcontinuousnew1} to allow our logic to ``cross'' the bunching point: existence of $f_{s(X^*)}(0)$ implies that $\lim_{h \downarrow 0} h^{-1}\{P(s(X_i^* \le t+h)-P(s(X_i^* \le t)\}$ and $\lim_{h \uparrow 0} h^{-1}\{P(s(X_i^* \le t+h)-P(s(X_i^* \le t)\}$ both exist and are equal to one another. Let $I^-:=(-\infty, \bar{x}] \cup I = (-\infty,\bar{x}+\delta')$ denote the interval in part (i) of Assumption \ref{as:bunchingcontinuousnew1} upon which $f_{s(X^*)}(s(\cdot))$ is assumed to exist, which includes $\bar{x}$. Note that by part (ii) of Assumption \ref{as:bunchingcontinuousnew1}, $s(\bar{x}) = s(\bar{x}^+)=0$. Note that $0$ belongs to the interior of $s(I^-)$, and the existence of $f_{s(X^*)}(0)$ implies the existence of $f_{s(X^*)|I^-}(0)=f_{s(X^*)}(0)/P(X_i^* \in I^-)$.

Suppose first that $s'(\bar{x}^+) > 0$ so that $s$ is strictly increasing on $I$. In this case, Assumption \ref{as:smono} implies that $s(x) < 0$ for all $x < \bar{x}$. Let $s^{-1}(\cdot)$ continue to denote the inverse of $s$ on the interval $I$, which is well-defined as a function from $s(I)$ to $I$. Therefore, conditional on the event $X_i^* \in I^-$, $s(X^*_i) \le t$ occurs if and only if $X_i^* \le s^{-1}(t)$ for any $t \in s(I)$, even though $s(\cdot)$ need not be invertible on all of $I^{-}$. Thus:
\begin{align*}
    f_{s(X^*)|I^-}(0)=\lim_{t \downarrow \bar{x}} \frac{d}{dv} P(s(X^*_i) \le t|X_i^* \in I^-) = \lim_{t \downarrow \bar{x}} \frac{d}{dv} P(X^*_i \le s^{-1}(t)|X_i^* \in I^-) = \lim_{t \downarrow \bar{x}} \frac{f_{X^*|I^-}(s^{-1}(t))}{s'(s^{-1}(t))}.
\end{align*}
 By differentiability of $s$ on $I$ (part (iii) of Assumption \ref{as:continuoussupport}), $s^{-1}$ is continuous on $I$ and thus we have that $\lim_{t \downarrow \bar{x}} f_{X^*|I^-}(s^{-1}(t)) =\lim_{t \downarrow \bar{x}} f_{X^*}(s^{-1}(t))/P(X_i^* \in I^-) = f_{X^*}(\bar{x}^+)/P(X_i^* \in I^-)$, where the limit $f_{X^*}(\bar{x}^+)$ exists by part (i) of Assumption \ref{as:continuoussupport}. Similarly, $\lim_{t \downarrow \bar{x}} s'(s^{-1}(t)) = \lim_{x \downarrow \bar{x}} s'(x)$, where the limit exists and differs from zero by part (iii) of Assumption \ref{as:continuoussupport}. Thus, using right continuity of $f_{s(X^*)}(t)$ at $t=0$ by part (i) of Assumption \ref{as:bunchingcontinuousnew1}:
\begin{equation} \label{eq:fsx0}
f_{s(X^*)|I^-}(0) = \frac{\lim_{t \downarrow \bar{x}} f_{X^*|I^-}(s^{-1}(t))}{\lim_{t \downarrow \bar{x}} s'(s^{-1}(t))} = \frac{f_{X^*}(\bar{x}^+)/P(X_i^* \in I^-)}{\lim_{x \downarrow \bar{x}} s'(x)}= \frac{f_{X^*}(\bar{x}^+)/P(X_i^* \in I^-)}{s'(\bar{x}^+)},
\end{equation}
using in the last equality that $s'(\bar{x}^+) = \lim_{x \downarrow \bar{x}}s'(x)$ by the discussion following Eq. \eqref{eq:allisoneohm}.

Now, again given the existence of $f_{s(X^*)}(0)$ and hence of $f_{s(X^*)|I^{-}}(0)$, we can also use the derivative from the left to write:
\begin{align*}
    f_{s(X^*)|I^-}(0)&=\lim_{h \uparrow 0} \frac{P(s(X_i^*) \le h|X_i^* \in I^-)-P(s(X_i^*) \le 0|X_i^* \in I^-)}{h}\\
    &= \frac{P(X_i^* \le \bar{x})}{P(X_i^* \in I^-)} \cdot \lim_{h \uparrow 0} \frac{P(s(X_i^*) \le h|X_i^* \le \bar{x})-P(s(X_i^*) \le 0|X_i^* \le \bar{x})}{h}\\
    &= \frac{P(X_i^* \le \bar{x})}{P(X_i^* \in I^-)} \cdot f_{s(X^*)|X^* \le 0}(0).
\end{align*}
Combining with Eq. \eqref{eq:fsx0}, we have that $s'(\bar{x}^+)=\frac{f_{X^*}(\bar{x}^+)}{f_{s(X^*)|X_i^* \le \bar{x}}(0)},$ using that $P(X_i^* \in I^-) \ge P(X_i^* \le \bar{x}) \ne 0$. 

The case in which $s$ is decreasing on $I$ proceeds analogously, aside from the introduction of a minus sign. We then have that in either case, $s'(\bar{x}^+)=\theta \cdot \frac{f_{X^*}(\bar{x}^+)}{f_{s(X^*)|X_i^* \le \bar{x}}(0)}.$ The final result then follows by Proposition \ref{prop:AMEDelta}, and using that $X_i=\bar{x} \iff X_i^* \le \bar{x}$.

\subsection{Proof of Theorem \ref{thm:AMEid}}
Combining Eq. \eqref{eq:AMEbunching} with Lemma \ref{lem:u(D*)}, we have
\begin{equation*}
    \text{AME}_{\bar{x}}^+=m'(\bar{x}^+)-2\pi\theta \left(\int \frac{\E[e^{\textbf{i}\xi Y_i}|X_i=\bar{x}]}{\E[e^{\textbf{i}\xi Y_i}|X_i=\bar{x}^+]}d\xi\right)^{-1}\cdot \frac{f_X(\bar{x}^+)}{F_X(\bar{x})}.
\end{equation*}
To see that $m'(\bar{x}^+)=\lim_{x\downarrow \bar{x}}\frac{d}{dx}\E[Y_i|X_i=x]$, take the limit of Eq. \eqref{eq:allisoneohm} in the proof of Proposition \ref{prop:AMEDelta} as $x \downarrow \bar{x}$. The expression for $\theta$ follows from Lemma \ref{lem:theta}.

\subsection{Proof of Lemma \texorpdfstring{\ref{lem:u(D*)}}{2}}
Conditional on $X_i=\bar{x}$, Equation \eqref{eq:equationzero} holds, so:
\begin{align*}
    F_{Y-y_{\bar{x}}|X=\bar{x}}(y)&=\mathbb{P}(s(X_i^*)+\epsilon_i\leq y|X_i=\bar{x})\\
    &=\int F_{s(X^*)|X=\bar{x},\epsilon=e}(y-e)dF_{\epsilon|X=\bar{x}}(e)=\int F_{s(X^*)|X=\bar{x},\epsilon=e}(y-e)dF_{\epsilon|X^*=\bar{x}}(e)
    \\
    &=\int F_{s(X^*)|X=\bar{x}}(y-e)dF_{\epsilon|X=\bar{x}^+}(e),
\end{align*}
where the second equality follows from part (iii) of  Assumption \ref{as:deconvregularity}. The third equality uses part (ii) and the Helly-Bray Theorem, due to the fact that $F_{s(X^*)|X=\bar{x}}(y-e-y_{\bar{x}})$ is bounded and continuous.

Then, by part (i) of Assumption \ref{as:deconvregularity}, $F_{Y-y_{\bar{x}}|X=\bar{x}}(y)$ is differentiable, and by part (i) of Assumption \ref{as:bunchingcontinuousnew1}, $ F_{s(X^*)|X=\bar{x}}$ is differentiable. By the Dominated Convergence Theorem,  we can write the convolution inverse problem
\begin{equation}\label{eq:convolution}
f_{Y-y_{\bar{x}}|X=\bar{x}}(y)=\int f_{s(X^*)|X=\bar{x}}(y-e)dF_{\epsilon|X=\bar{x}^+}(e).
\end{equation}
Equation \eqref{eq:convolution} has a well-known closed form solution using the Fourier representation (see e.g. \citealt{schennachmeasurement}): 
\begin{align} 
    f_{s(X^*)|X=\bar{x}}(v)&=\frac{1}{2\pi}\int \frac{\E[e^{\textbf{i}\xi (Y_i-y_{\bar{x}})}|X_i=\bar{x}]}{\E[e^{\textbf{i}\xi \epsilon_i}|X_i=\bar{x}^+]}e^{-\textbf{i}\xi v} d\xi=\frac{1}{2\pi}\int \frac{\E[e^{\textbf{i}\xi Y_i}|X_i=\bar{x}]}{\E[e^{\textbf{i}\xi (\epsilon_i+y_{\bar{x}})}|X_i=\bar{x}^+]}e^{-\textbf{i}\xi v} d\xi \nonumber \\
    &=\frac{1}{2\pi}\int \frac{\E[e^{\textbf{i}\xi Y_i}|X_i=\bar{x}]}{\E[e^{\textbf{i}\xi Y_i}|X_i=\bar{x}^+]}e^{-\textbf{i}\xi v} d\xi, \label{eq:deconvgeneralpointvappendix}
\end{align}
where the second equality follows because, for $X_i>\bar{x},$ $\epsilon_i=Y_i-\E[Y_i|X_i],$ and thus $\E[e^{\textbf{i}\xi (\epsilon_i+y_{\bar{x}})}|X_i=x]=\E[e^{\textbf{i}\xi (Y_i-\E[Y_i|X_i]+y_{\bar{x}})}|X_i=x]=e^{-\textbf{i}\xi(\E[Y_i|X_i=x]-y_{\bar{x}})}\E[e^{\textbf{i}\xi Y_i}|X_i=x],$ and then $\E[Y_i|X_i=x]$ converges to $y_{\bar{x}}$ as $x\downarrow 0.$

The result then follows if we evaluate the expression in Equation \eqref{eq:deconvgeneralpointvappendix} above at $v=0$. The integral in Eq. \eqref{eq:deconvgeneralpointvappendix} must converge for $v=0$ by existence of $f_{s(X^*)|X=\bar{x}}(0)$, which is guaranteed by part (i) of Assumption \ref{as:bunchingcontinuousnew1}.

\subsection{Proof of Theorem \ref{thm:localexpansion}}
Assumption \ref{as:analytic} implies that $s$ is also analytic on $I'$. Let $\bar{I}=[\bar{x},\bar{x}+\epsilon_5]$, the closure of $I'$ in $\mathbbm{R}$. Taking a direct analytic continuation from $I'$ to $\bar{I}$, we can take $s$ to be analytic on all of $\bar{I}$ with $s(\bar{x})=0$. Then, there exists an $\varepsilon>0$ such that $s(x)= \sum_{k=1}^\infty s^{(k)}(\bar{x})\cdot \frac{(x-\bar{x})^k}{k!}$ for any $x \in [\bar{x},\bar{x}+\varepsilon]$. Analyticity of $s$ on $\bar{I}$ implies that $s^{(k)}(x)$ is continuous on $\bar{I}$ for each $k$ and thus $s^{(k)}(\bar{x})=s^{(k)}(\bar{x}^+)$. The expression for the remainder follows from the Taylor theorem.

\subsection{Proof of Corollary \ref{cor:extrapolation}}
Since $s$ is analytic on the set $\bar{I}$ defined in the Proof of Theorem \ref{thm:localexpansion}, it is continuously differentiable and we can use Equation \eqref{eq:changeofvariablesbunchingclosure} from the proof of Theorem \ref{cor:AMEbunching}
\begin{equation*}
s'(x)= \theta \cdot \frac{f_{X^*|I^*}(x)}{f_{s(X^*)|I^*}(s(x))},
\end{equation*}
for any $x \in I^*$, where $I^*$ is a set that includes a neighborhood of $\bar{x}$. Differentiating with respect to $x$, we obtain: 
$$s^{(k)}(x)=\theta \cdot \frac{d^{k-1}}{dx^{k-1}}\frac{f_{X^*|I^*}(x)}{f_{s(X^*)|I^*}(s(x))}.$$
Following the same steps as the proof of Theorem \ref{cor:AMEbunching}, we can replace the conditioning on $X_i^* \in I^*$ with conditioning on $X_i^* \le \bar{x}$ and evaluate at $\bar{x}$ to obtain
$$s^{(k)}(\bar{x})=\frac{\theta}{F_X(\bar{x})}\cdot \frac{d^{k-1}}{dx^{k-1}}\frac{f_{X^*}(\bar{x})}{f_{s(X^*)|X=\bar{x}}(s(\bar{x}))}.$$
Working out the derivatives and and evaluating at $\bar{x}$, we have
\begin{align*}
s^{(k)}(x)&=\frac{\theta}{F_X(\bar{x})}\cdot \sum_{\ell = 0}^{k-1} \begin{pmatrix} k-1 \\ \ell \end{pmatrix} f^{(k-1-\ell)}_{X^*}(\bar{x}) \cdot \left.\frac{d^\ell}{dx^{\ell}} \{f_{s(X^*)|X=\bar{x}}(s(x))\}^{-1}\right|_{x=\bar{x}}.
\end{align*}
The derivatives of $1/f_{s(X^*)|X=\bar{x}}(s(x))$ evaluated at $x=\bar{x}$ can be worked out recursively knowing $f_{s(X^*)|X=\bar{x}}(s(\bar{x}))$ and $f^{(\ell)}_{s(X^*)|X=\bar{x}}(s(\bar{x}))$ for each $\ell$. These derivatives are identified since by Eq. \eqref{eq:deconvgeneralpointvappendix}, $f_{s(X^*)|X=\bar{x}}(v)$ is identified for every $v \in s((-\infty, \bar{x}))$, e.g.:
\begin{equation*}
    \frac{d}{dv}f_{s(X^*)|X=\bar{x}}(v)=\frac{1}{2\pi} \cdot \frac{d}{dv}\int \frac{\E[e^{\textbf{i}\xi Y_i}|X_i=\bar{x}]}{\E[e^{\textbf{i}\xi Y_i}|X_i=\bar{x}^+]}e^{-\textbf{i}\xi v} d\xi,
\end{equation*}
which can be differentiated again and again as needed. The power series converges for each $x \in I_{\varepsilon}$ by analyticity of $s(x)$. Finally, $f_{X^*}^{(k)}(\bar{x})$ is identified for each $k$ as $f_{X^*}^{(k)}(\bar{x}) = f_X^{(k)}(\bar{x}^+)$.

\subsection{Proof of Corollary \ref{cor:extrapolationfar}}
Given Equation \eqref{eq:taylorexpression},
$$\text{ATT}(x)=m(x)-\sum_{k=1}^\infty s^{(k)}(\bar{x}^+)\cdot  \frac{(x-\bar{x})^k}{k!}.$$
The Cauchy–Hadamard formula gives that the radius of convergence of the power series appearing on the right-hand side is $R = \left( \limsup_{k \to \infty} \left| \frac{s^{(k)}(c)}{k!} \right|^{1/k} \right)^{-1} $.

\section{Constructing \texorpdfstring{$X_i^*$}{Xi*}} \label{sec:xstarappendix}

In this appendix, we detail the models and results mentioned in Section \ref{sec:xstar}. When not provided in-line, proofs are found in the Supplementary Appendix \ref{sec:xstarproofs}.

\subsection{Models with scalar heterogeneity}\label{sec:economic}
In this section, we consider models in which individuals' choice problems are parameterized by a scalar parameter $\rho_i$, and we obtain a choice rule $X_i = \max \{h(\rho_i),\bar{x}\}$ for a strictly increasing and differentiable function $h$. This is equivalent to Eq. \eqref{eq:xbarmax} with $X_i^*=h(\rho_i)$. Since such settings arise naturally due to physical positivity constraints (the quantity of a good consumed, the time spent on an activity, etc.), we take $\bar{x}=0$ for simplicity. This is without loss of generality because we can always redefine $X_i$ as $X_i - \bar{x}$.

In this class of examples, we suppose individuals have two scalar choice variables $x$ and $r$, with individual $i$'s utility denoted as $V(x,r;\theta_i)$ for a family of utility functions parametrized by $\theta$. We suppose that individuals' choices are made subject to the budget constraint that $p\cdot x+r=W$, where $p$ indicates the relative price of $x$ versus $r$, and $W$ a budget common to all individuals. This, for example, nests the class of Example \ref{ex:cigarettes} in the time use case (e.g., hours spent on TV watching), where $p=1$ and $W=24$: all individuals have 24 hours in a day and can swap time one-for-one between watching TV, $x,$ and spending time on other activities, $r$. Note that the budget constraint can be relaxed to $p\cdot x+r \le W$, provided that utility is strictly increasing in at least one of the two goods for all individuals.
\begin{proposition} \label{prop:transformationexistence}
    Suppose $V:\mathbb{R}^+\times \mathbb{R}^+\rightarrow \mathbb{R}$ is a twice differentiable function of $(x,r),$ with heterogeneity parameterized by a scalar $\theta_i$ such that, with probability one,
    $$X_i = X(\theta_i):= \text{argmax}_x\{V(x,r;\theta_i) \text{ subject to }  p\cdot x+r=W\}.$$
    Define $MRS(x,\theta) := V_{x}(x,W-px;\theta)/V_{r}(x,W-px;\theta),$ and suppose that $MRS(x,\theta)$ is strictly decreasing in $x$ and continuously differentiable on $[0,W] \times \Theta$. Finally, suppose that $P(X_i=W)=0$ (nobody spends their entire budget on $X_i$). Then, with probability one, there exists a strictly increasing and differentiable function $h$ such that $$X_i = \max\{h(\rho_i),0\},$$ 
    where $\rho_i = MRS(0,\theta_i)$.
\end{proposition}

Note that $V(x,r;\theta)$ need be defined only for positive values of $x$ (and not e.g. on all of $\mathbbm{R}^2$). Thus, we do not need to conceive the utility that an individual would receive from a negative amount of cigarettes, or from watching TV for a negative amount of time. The variable $\theta_i$ regulates the relative preference for $x$ over $r,$ in the sense that $V_x(x,r;\theta)/V_r(x,r;\theta)$ is strictly increasing in $\theta$ for all $x,r$. 

The assumptions invoked in Proposition \ref{prop:transformationexistence} are natural if preferences are convex over $(x,r)$, can be parameterized by a scalar $\theta_i$, and utility is smooth in that scalar. While an assumption that the relative price $p$ of $x$ and $r$ is homogeneous across individuals is relatively weak (within e.g. a given market), the restriction that budgets $W$ are homogeneous across individuals $i$ is much stronger. This can be relaxed by assuming that the demand for $x$ does not depend on $W$, which is reasonable if preferences are approximately quasi-linear, $r$ is a good, or $W$ is suitably high. We can proceed without these assumptions by controlling for income in estimation, such that the assumptions of Proposition \ref{prop:transformationexistence} and Theorem \ref{thm:AMEid} need only hold conditional on income. This strategy can be helpful in motivating Proposition \ref{prop:transformationexistence} more generally by also controlling for other proxies of preference heterogeneity, making the scalar heterogeneity assumption less restrictive. Supplementary Appendix \ref{sec:controls} discusses the use of control variables in our approach.

\subsection{Monotonic transformations of \texorpdfstring{$X_i^*$}{Xi*}}
\label{sec:generalization AME}
In this section, we show that we can generalize Theorem \ref{thm:AMEid} to the case where $X^*_i$ is not the primitive source of selection, but instead there exists some (possibly unobserved) index of heterogeneity $\rho_i$ such that $X^*_i = h(\rho_i)$. In this case, we can make Assumptions \ref{as:smono}-\ref{as:deconvregularity} with $\rho_i$ replacing $X_i^*$, while maintaining the constructive estimand of Theorem \ref{thm:AMEid} for $\text{AME}_{\bar{x}}^+$, even if $\rho_i$ is unobserved and the function $h$ is unknown. The index $\rho_i$ will therefore not be unique. For example, in the case of Proposition \ref{prop:transformationexistence} we could make Assumptions \ref{as:smono}-\ref{as:deconvregularity} about $\rho_i:=\theta_i$ or about $\rho_i:=MRS(0,\theta_i)$, rather than on $X_i^*$.

\begin{proposition} \label{prop:transformation}
    Suppose that Assumption \ref{as:smoothcounterfactual} holds, and Assumptions \ref{as:smono}-\ref{as:deconvregularity} all hold for a variable $\rho_i$ such that $X^*_i = h(\rho_i),$ where $h$ is a strictly increasing and differentiable function. Let $\bar{\rho} = h^{-1}(\bar{x}),$ and suppose that $h'(\bar{\rho}) \ne 0.$ Then, Equation \eqref{eq:u'} holds.
\end{proposition}
Equation \eqref{eq:u'} is the expression for $\text{AME}_{\bar{x}}^+$ from Theorem \ref{thm:AMEid}. This expression still holds unchanged. Note that $h$ does not need to be known or identified, and hence $\rho_i$ may be unobserved for all $i$. 
\subsection{Models with unrestricted heterogeneity}\label{sec:unrestrictedheterigeneity}
In this section, we show that $X_i^*$ can be explicitly constructed in choice models with unrestricted heterogeneity -- i.e., if $X_i$ is chosen using the (unrestrictedly heterogeneous) utility $ u_i(x)$. To simplify the exposition, suppose that $\bar{x}=0$, which is without loss of generality, since one may always redefine $X_i$ to be $X_i - \bar{x}$.

In contrast to the model of Section \ref{sec:economic}, this model considers choice over a scalar $x$ only. This may reflect a profiled utility function incorporating any other choice variables that have been maximized over for a given value of $x$. This allows us to remain agnostic about agents' margins of choice and the constraints (e.g. budget) that they may face in addition to $X_i \ge 0$.\footnote{For instance, let $(X_i,R_i)=\text{argmax}_{\substack{(x,r): x \ge 0\\ (x,r) \in \mathcal{S}_i}} V_i(x,r)$ for some set $\mathcal{S}_i$, where $r$ may now be a vector. Then $X_i = \text{argmax}_{x \ge 0} u_i(x),$ where we define $u_i(x):= \max_{r: (x,r) \in \mathcal{S}_i} V_i(x,r)$.}


\begin{proposition} \label{prop:marginalutilitynegative}
    Suppose that, with probability one,  $X_i = \text{argmax}_{x \ge 0} u_i(x),$ and $u_i(\cdot)$ is differentiable at $x=0.$ Then, $\mathbb{P}(u_i'(0) \le 0|X_i=0)=1$.
\end{proposition}
\begin{proof}
The proof is by contradiction: if $u_i'(0)>0$, then $u_i(x)$ cannot be maximized at $x=0.$ This is because $i$ could strictly increase their utility by choosing $x$ to be slightly larger than $0$. It follows that, with probability one, if $X_i=0,$ then $u_i'(0)\leq 0$.
\end{proof}

Define
\begin{equation} \label{eq:defxstar}
    X_i^*:=\begin{cases} X_i & \text{ if } X_i > 0\\ u_i'(0) & \text{ if } X_i = 0. \end{cases}
\end{equation}
Given Proposition \ref{prop:marginalutilitynegative},  $X_i^*$ as defined above satisfies Eq. \eqref{eq:xbarmax} -- i.e., with probability one, $X_i = \max\{0,X_i^*\}$.

\begin{proposition} \label{prop:qc}
    Suppose that, with probability one, $X_i = \text{argmax}_{x \ge 0} u_i(x),$ and $u_i(\cdot)$ is differentiable and quasiconcave, then $\mathbb{P}(u_i'(0) \geq 0|X_i>0)=1.$
\end{proposition}
\begin{proof}
    If $X_i>0$ then $u_i(X_i) > u_i(0)$. If $u_i'(0) < 0,$ there exists an $x \in (0,X_i)$ such that $u_i(x) < u_i'(0)$. Thus the set $\{x': u_i(x') > u_i(x)\}$ includes both $0$ and $X_i$, but does not include $x$. Therefore, it is not convex, which contradicts the quasi-concavity of $u_i$. It follows that,  with probability one, if $X_i>0,$ then $u_i'(0)\geq 0.$
\end{proof}

Given Propositions \ref{prop:marginalutilitynegative} and \ref{prop:qc}, all individuals who strictly prefer $x=0$ to a positive amount are bunched (i.e., $X_i=0$) with a selection variable that is different from the treatment (i.e., $X_i^*<0$). The bunching point may also contain individuals who are exactly indifferent between $x=0$ and a marginally positive amount (i.e. $X_i^*=u_i'(0)=0$). 

We also have that
$$s(x) = \E[Y_i(0)|X_i^*=x]= \begin{cases} \E[Y_i(0)|X_i=x] & \text{ if } x > 0\\ \E[Y_i(0)|u_i'(0)=x] & \text{ if } x = 0 \end{cases} \quad - \quad \E[Y_i(0)|X_i=x^+].$$

The key assumptions on $X_i^*$ and $s(X_i^*)$ in Theorem \ref{thm:AMEid} can now be interpreted in terms of the joint distribution of $Y_i(0)$ and $u_i'(0)$, and how it relates to the joint distribution of $Y_i(0)$ and $X_i$. For instance, part (iii) of Assumption \ref{as:bunchingcontinuousnew1} requires $s(x)$ to be right continuous at $x=0$. This requires that $\lim_{x \downarrow 0} \E[Y_i(0)|X_i=x] = \E[Y_i(0)|u'_i(0)=0].$ In terms of the example of our application, we require that the bunchers that are indifferent between not smoking and smoking a marginal amount (i.e., the ``marginal nonsmokers'') are similar to those that choose to smoke a marginal amount (the ``marginal smokers''), in terms of their mean untreated potential outcome.

Part (ii) of Assumption \ref{as:deconvregularity} says that $Y_i(0)|X_i=x \rightarrow_{d} Y_i(0)|u_i'(0)=0$ as $x \downarrow 0$. Again, this has the interpretation that the marginal nonsmokers are similar to the marginal smokers, now in terms of the entire distribution of their untreated outcomes.

The existence of $f_{s(x^*)}(0)$ in part (ii) of Assumption \ref{as:bunchingcontinuousnew1} requires that
\begin{align*}
    &\lim_{h \uparrow 0} \frac{P(\E[Y_i(0)|u_i'(0)] \le h + y_{0})-P(\E[Y_i(0)|u_i'(0)] \le y_{0})}{h}\\
    & \hspace{2.5in}= \lim_{h \downarrow 0} \frac{P(\E[Y_i(0)|X_i] \le h + y_{0})-P(\E[Y_i(0)|X_i] \le y_{0})}{h}.
\end{align*}
Here the interpretation would be that the ``close-to-marginal nonsmokers'' are similar to the ``close-to-marginal smokers'' in terms of mean untreated outcomes.

Finally, in this context Assumption \ref{as:smono} says that if selection is positive just above $0$, then $\E[Y_i(0)|u'_i(0)= x] < \E[Y_i(0)|u'_i(0)=0]$ for all $x < 0$. In other words, there are no negative values of marginal utility with the property that individuals having that level of $u'_i(0)$ have larger values of $Y_i(0)$ than do the marginal nonsmokers (who have $u'_i(0)=0$). However it does not require that the conditional mean of $Y_i(0)$ be increasing globally in $u'_i(0)$, or even for $Y_i(0)$ and $u'_i(0)$ to be positively correlated overall.

We note that for generality in our setup, we have here defined $X_i^*$ in terms of the marginal utility of $x$. This contrasts with our use of the marginal rate of substitution between $x$ and $r$ in Proposition \ref{prop:transformationexistence}, where the setting was one in which individuals choose $x$ and $r$ subject to a budget constraint. Since marginal utility is not invariant to different cardinalizations of a given individual's preferences, one might worry that applying different arbitrary monotonic transformations to $u_i(\cdot)$ for different individuals might affect the plausibility of Assumptions \ref{as:smono}-\ref{as:deconvregularity} for the construction \eqref{eq:defxstar}. However, note that in the discussion above, one only needs to make assumptions about marginal ($u_i'(0)=0$) and close-to-marginal ($u_i'(0)$ small) bunchers (i.e., nonsmokers). These categories are indeed invariant to smooth monotonic transformations of utility, and thus the quantitative magnitudes of $u_i'(0)$ are not important for defending Assumptions \ref{as:smono}-\ref{as:deconvregularity}.

\subsection{Defining \texorpdfstring{$X_i^*$}{Xi*} by extending the support of treatment} \label{sec:noxstar}

In this section, we show that in a setting with boundary bunching at $\bar{x}=0$, the random variable $X_i^*$ can be defined in the absence of a choice model as an extension from the positive part of the support of $X_i$ into negative values, under suitable conditions. This construction has the important property of satisfying Assumption \ref{as:deconvregularity} automatically.

For any $e \in [0,1]$, $x \ge \bar{x}$ and random variable $A$, define where $Q_A(a) := \inf\{a: F_A(a) \ge e\}$ and $F_A$ is the CDF function of $A$. Given a conditioning variable $X_i$, we can write $A=Q_{A|X}(E)$ with probability one, for a random variable $E \sim \text{Unif}[0,1]$ that satisfies $E \indep X$. See Lemmas 3 and 4 of \citet{goff2024testingidentifyingassumptionsparametric} for a proof of this property, which holds regardless of whether $A$ is discrete or continuously distributed.

Consider in particular the conditional quantile function $g(x,x',e) = Q_{Y(x)|X=x'}(e)$. Then, using that $Y_i=Y_i(X_i)$ we can write, with probability one:
\begin{equation} \label{eq:quantileoutcome}
	Y_i = g(X_i,X_i,E_i),
\end{equation}
where $E_i := F_{Y(X)|X}(Y_i) = F_{Y|X}(Y_i)$. Note that with $Y_i$ continuously distributed conditional on $X_i$, then $E_i|X_i\sim \text{Unif}[0,1],$ and thus $E_i \indep X_i$.\footnote{If $Y_i$ exhibits mass points (e.g. $Y_i$ is discrete), then we can define $E_i|Y_i,X_i \sim \text{Unif}[\lim_{y \uparrow Y_i}F_{Y|X}(y),F_{Y|X}(Y_i)],$ and \eqref{eq:quantileoutcome} still holds with $E_i|X_i \sim \text{Unif}[0,1]$ (Cf. Lemma 4 of \citealt{goff2024testingidentifyingassumptionsparametric}).}  

 For notational simplicity, we consider in this section a setting in which $\bar{x}=0$, and assume only that $X_i$ is defined on the positive side of the real line. Accordingly, consider any $x \ge 0$. Assume that $g$ is differentiable. By the fundamental theorem of calculus, we can write:
\begin{align*}
	g(x,x,e) &= \underbrace{g(0,0,e)+\int_0^{x} g_2(0,v,e)dv}_{:=s(x,e)}+\underbrace{\int_0^x g_1(x,v,e)dv}_{:=m(x,e)},
\end{align*}
where $g_1$ and $g_2$ represent derivative functions of $g$, and the path of integration is from $(x,x')=(0,0)$ to $(0,x)$ and then from $(0,x)$ to $(x,x)$. Note that differentiability of $g$ in $x,x',e$ also implies that $Y_i$ is continuously distributed, conditional on any value $X_i$ (implying part (i) of Assumption \ref{as:deconvregularity}).

We can write
\begin{equation*}
	s(e,x) = g(0,0,e)+\int_0^{x} g_2(0,v,e)dv = Q_{Y(0)|X=x}(e),
\end{equation*}
where the second term above $s(x,e)$ is a pure ``endogeneity term'', capturing how the distribution of the untreated potential outcome $Y_i(0)$ varies across groups with different treatment levels $X_i$. On the other hand $m(x,e):=\int_0^x g_1(x,v,e)dv$ is a pure causal term, summarizing how the distribution of $Y_i(x)$ changes with $x$ with a fixed conditioning group $X_i=x$. Note that $m(0,e)=0$ for all $e$.

By Equation \eqref{eq:quantileoutcome}, we have that, with probability one,
\begin{equation*} 
	Y = m(X,E_i) + s(X,E_i).
\end{equation*}
By totally differentiating $Q_{Y|X=x}(e)=Q_{Y(x)|X=x}(e)$ with respect to $x$, we note that for any $x>0$, it follows that we can identify
\begin{equation} \label{eq:quantilederivative}
	\frac{d}{dx} Q_{Y|X=x}(e) = m'(x,e)+s'(x,e),
\end{equation}
where we define $m'(x,e):=\frac{d}{dx} m(x,e)=g_1(x,x,e),$ and $s'(x,e):=\frac{d}{dx} s(x,e)=g_2(x,x,e)$. As above, $m'$ captures a causal effect, and $s'$ is the selection bias  term.

Let $m'(x):=\int_{0}^1 m'(x,e) de$ and $s'(x):=\int_{0}^1 s'(x,e) de$. Under regularity conditions, the expectation analog of Equation \eqref{eq:quantilederivative} satisfies:
\begin{equation*} 
	\frac{d}{dx} \mathbbm{E}[Y_i|X_i=x] = m'(x)+s'(x),
\end{equation*}
with $m'(x)=\mathbbm{E}[Y_i'(x)|X_i=x]$, where $Y_i'(x)=\frac{d}{dx} Y_i(x)$.

Recall that the parameter $\text{AME}_{\bar{x}}^+$ is well-defined given Assumption \ref{as:continuoussupport} from Section \ref{sec:approach}. However, we can give it an economic interpretation without assuming $X_i^*$ exists ex ante, by supposing that a subset of the bunchers having $X_i=0$ are ``marginal'', indicated by $M_i=1$ (e.g. they satisfy a FOC at $X_i=0$). Then, suppose that all of the marginal bunchers bunch (i.e. $P(X_i=0|M_i=1)=1$), and that the distribution of the slope $Y_i'(0^+)$ of the treatment response function $Y_i(x)$ as $x \downarrow 0$ is the same as for the non-bunchers that have very small values of $X_i$ (i.e. $Y_i'(0^+)|X_i=x \stackrel{d}{\rightarrow} Y_i'(0^+)|M_i=1$, 
where convergence in distribution is as $x \downarrow 0$). Our parameter of interest $\text{AME}_{\bar{x}}^+$ is then the average derivative effect of increasing $x$ from zero among marginal bunchers. This yields part (ii) of Assumption \ref{as:deconvregularity}.

To identify the function $f_{s(X)}(\cdot)$, we leverage the following additional assumptions.
\begin{assumption} \label{as:analyticxstar}
        There exist functions $s,\phi:\mathbb{R}\rightarrow \mathbb{R}$ such that
	\begin{enumerate}[(i)]
		\item For all $x>0$ and $e\in [0,1],$ $(x,e)\mapsto s(x,e) = s(x)+\phi(e)$. 
		\item For $x>0,$ $s(x)$ is an analytic function.
		\item $\phi(\cdot)$ is strictly increasing, and there exists a continuous solution $h$ satisfying the integral equation
		$$\int_{-\infty} ^\infty \phi^{-1}\left(y-s^*(x)\right)\cdot h(x) \cdot dx = F_{Y(0)}(y),$$
        where $s^*(x)$ is an analytic continuation of $s(\cdot)$ to the real line.
	\end{enumerate}
\end{assumption}
\noindent Recall that the function $s$ is defined as $s(x,e)=Q_{Y(0)|X=x}(e)$. To resolve an arbitrary additive normalization in the decomposition between $s$ and $\phi$, we let the $x$-dependent term $s(x)$ capture the conditional expectation of $Y_i(0)$ given $X_i=x$, as compared with its right limit at zero, i.e. $s(x) = \mathbbm{E}[Y_i(0)|X_i=x]-y_{\bar{x}}$ where $y_0:=\mathbbm{E}[Y_i(0)|X_i=x^+]$, recovering the function $s(x).$  Then, since
$$\mathbbm{E}[Y_i(0)|X_i=x]=\int_0^1 Q_{Y(0)|X=x}(e)\cdot de = \int_0^1 s(x,e) de = s(x) + \int_0^1 \phi(e) de,$$ this normalization implies that $\int_0^1 \phi(e) \cdot de = y_0$.

To motivate part (i) of Assumption \ref{as:analyticxstar}, observe the following 
\begin{proposition} \label{prop:additive}
    $Q_{Y(0)|X=x}(e)=s(x)+\phi(e)$ for some functions $s,\phi$ $\iff$ $\{Y_i(0) - \mathbbm{E}[Y_i(0)|X_i]\} \indep X_i$.
\end{proposition}
\noindent Thus part (i) of Assumption \ref{as:analyticxstar} is analagous to part (iii) of Assumption \ref{as:deconvregularity}, but for positive $X_i^*$.\\

The assumption of additive separability (i) cannot be directly verified from the data, because $s(x,e)=Q_{Y(0)|X=x}(e)$ is only identified in the limit as $x \downarrow 0$ and not for multiple values of $x$. For $x>0$, we can instead only identify $Q_{Y(x)|X=x}(e) = g(x,x,e)=m(x,e)+s(x,e)$. However, additive separability between $x$ and $e$ in $Q_{Y(x)|X=x}(e)$ for $x>0$ may be construed as indirect evidence in favor of part (i). For example, if $Y_i(x)-Y_i(0)$ is the same for all $i$ (homogeneous treatment effects), then additive separability of the observable quantile function $Q_{Y|X=x}(e)$ (i.e. $g(x,x,e)$) holds if and only if additive separability of $s(x,e)$ holds. We see this in Figure \ref{fig:condition_kdensities} in our application, where the distribution of $Y|X=x$ only differs substantially across different values of $x$ by a location shift: it is approximately normal with nearly identical variance across $x$. 

Item (ii) of Assumption \ref{as:analyticxstar} echoes Assumption \ref{as:analytic} from the main text, and amounts to imposing a high degree of smoothness on the function $x \mapsto \E[Y_i(0)|X_i=x]$. Item (iii) of Assumption \ref{as:analyticxstar} is high-level, but appears to be mild. The integral equation takes the form of a Fredholm Integral of the First Kind. As an analytic function, $s^*(x)$ is continuously differentiable, and if $s^*(x)$ is furthermore strictly monotonic with inverse $x(\cdot)$, then by a change of variables,
$$\int_{-\infty} ^\infty \phi^{-1}\left(y-t\right)\cdot \frac{h(x(t))}{s^{*'}(x(t))} \cdot dt = F_{Y(0)}(y),$$
which takes the form of a convolution equation, which typically has a solution.\\

Assumption \ref{as:analyticxstar} is useful because it allows us to define a new probability space in which $X_i$ is extended to take negative values, and such that $f_{s(X)}(\cdot)$ is identified through a deconvolution operation on that probability space. In particular, because the function $s: \mathbbm{R}^+ \rightarrow \mathbbm{R}$ is analytic on the positive part of the real line, there exists a unique function $s^*: \mathbbm{R}^+ \rightarrow \mathbbm{R}$ such that $s^*(x)=s(x)$ for all $x \ge 0$, referred to as the \textit{analytic continuation} of $s$. Now define $s^*(x,e) = s^*(x)+\phi(e)$.

The initial probability space has a measure $P$ defined over $(X_i,\{Y_i(x)\}_{x \ge 0})$. We now define a new probability measure $P^*$ over random variables $(X_i^*,Y_i^*(0))$ using $s^*(x,e)$. In particular, (1) we let the conditional distribution of $Y^*_i(0)$ given $X_i^*$ be described by the quantile function $Q^*_{Y^*(0)|X^*=x}(e) = s^*(x,e)$ for all $e \in [0,1]$ and $x \in \mathbbm{R}$; and (2)
 we let the marginal distribution of $X_i^*$ under $P^*$ be described by CDF $F^*_{X^*}(x)= \int_{\infty}^x h(x)$ for $x < 0$ and $H(x) = F_X(x)$ if $x \ge 0$, where $h$ is a solution to the equation in part (iii) of Assumption \ref{as:analyticxstar}.

Under this construction, the following holds with probability one under $P^*$: \begin{equation} \label{eq:starquantile}
	Y_i^*(0)=Q^*_{Y^*(0)|X^*}(E_i^*)=s^*(X_i^*)+\phi(E_i^*),
\end{equation}
where $E_i:=F^*_{Y(0)|X^*}(Y_i(0))$ satisfies $E_i^* \indep X_i^* $ with $E_i^* \sim \text{Unif}[0,1]$ under $P^*$. 

We note that the function $s^*(x,e)$ can be defined constructively from $s(x,e)$ provided that the radius of convergence of its Taylor series about $x=0$ is infinite. In this case, the Taylor series of $s^*(x)$ converges and $s_e(x)$ can be expressed as $s^*(x) = \sum_{k=0}^\infty \frac{x^k}{k!} \cdot s^{(k)}(0)$. However this stronger condition is not needed for what follows.

A key implication is that part (iii) of Assumption \ref{as:deconvregularity} holds with probability one under $P^*$: 
\begin{proposition} \label{prop:indep}
	Under Assumption \ref{as:analyticxstar}, $\{Y^*_i(0)-\mathbbm{E}^*[Y^*_i(0)|X_i^*]\} \indep X_i^*$ under $P^*$.
\end{proposition}
Finally, to unlock the ability to leverage Lemma \ref{lem:u(D*)} using part (iii) of Assumption \ref{as:analyticxstar}, we can use the following result:
\begin{proposition} \label{prop:bunchers}
	Given Assumption \ref{as:analyticxstar}, the distribution of $Y^*_i(0)|X_i^* \le 0$ under $P^*$ is the same as the distribution of $Y_i|X_i=0$ under $P$.
\end{proposition}

\noindent By Proposition \ref{prop:bunchers} and Equation \eqref{eq:starquantile}, we have that
$Y_i|X_i=0 \sim Y_i^*(0) | X^*_i \le 0 \sim s^*(X^*)+\phi(E_i^*) | X^*_i \le 0$. Thus the distribution of $s(X^*)+\phi(E_i^*)$ conditional on $X_i^* \le 0$ is pinned down from the observable distribution of $Y_i|X_i=0$.

Note furthermore that $Y_i|X_i=0^+ \sim s(0^+)+\phi(E_i^*)$, so $\phi(E_i^*) \sim \{Y_i-\mathbbm{E}[Y_i|X_i=0^+]\}|X_i=0^+$. Since $\phi(E_i^*)|X_i^*\le 0 \sim \phi(E_i^*)$, we have that $\phi(E_i^*)|X_i^*\le 0\sim \{Y_i-\mathbbm{E}[Y_i|X_i=0^+]\}|X_i=0^+$. It follows from Proposition \ref{prop:indep} that $\{(Y^*_i(0)-\mathbbm{E}^*[Y^*_i(0)|X_i^*]) \indep X_i^*\}|X_i^* \le 0$, so we can then work out the distribution of $s(X_i^*)$ conditional on $X_i^* \le 0$ via deconvolution as in Section \ref{sec:idfrombunching}. 


