\section{Proofs for Appendix \texorpdfstring{\ref{sec:xstarappendix}}{B}} 
\label{sec:xstarproofs}

\subsection{Proof of Proposition \texorpdfstring{\ref{prop:transformationexistence}}{B.1}}
    We can write the optimization problem as
    $$X(\theta):= \text{argmax}_x\{V(x,W-px;\theta) \text{ subject to } x \ge 0, r\ge 0\}.$$
    Given the convexity of $V$, we have by the first order condition that $MRS(X(\theta),\theta) = 1$ if and only if there is an interior maximum $X(\theta) \in (0,W)$. In this case, differentiating with respect to $\theta$,
    $$ MRS_x(X(\theta),\theta)\cdot X'(\theta) = -MRS_{\theta}(X(\theta),\theta),$$
    where $X'(\theta)$ exists by the implicit function theorem. By assumption $MRS_{\theta}(x,\theta):=\frac{\partial}{\partial \theta} MRS(x,\theta) > 0$ for all $x \in (0,\bar{W}), \theta \in \Theta$. Since $MRS_x(x,\theta):=\frac{\partial}{\partial x} MRS(x,\theta) < 0$ for all $x \in (0,W), \theta \in \Theta$, we must then have that $X'(\theta)>0$ given that $X(\theta) \in (0,W)$: optimal choices are strictly increasing in $\theta$ for any $\theta$ such that $0< X(\theta) < W$. Let $\bar{\theta} = \lim_{x \downarrow 0} X^{-1}(x)$. If $\theta = \bar{\theta}$, then $X(\theta)=0$ by continuity and if $\theta < \bar{\theta}$, we must have $X(\theta(\rho_i)) \notin (0,W)$.

    Meanwhile, since $MRS_{\theta}(x,\theta)>0$, $MRS(x,\theta)$ is strictly increasing in $\theta$ for each $x \ge 0$, the function $\rho(\theta):=MRS(0,\theta)$ is also strictly increasing in $\theta$. Let $\theta(\rho)$ be the inverse function of $\rho(\theta)$, which is also strictly increasing and differentiable in $\rho$ (given that these properties hold for $\rho(\cdot)$). 
   Given the assumption that $P(X_i=W)=0$, we have, combining cases, that with probability one:
    $$X_i = \begin{cases}
        0 &\text{ if } \theta(\rho_i) \le \bar{\theta}\\
        X(\theta(\rho_i)) & \text{ if } \theta(\rho_i) > \bar{\theta}
    \end{cases} \;\;= \;\max\{X(\theta(\rho_i)), 0\}.$$
    The result of the Proposition then holds with the strictly increasing and differentiable function $h(\rho) = X(\theta(\rho))$.

\subsection{Proof of Proposition \ref{prop:transformation}}
    Rewriting Equation \eqref{eq:xbarmax} as $X_i = \max\{h(\rho_i),h(\bar{\rho})\}$ where $\bar{\rho} = h^{-1}(\bar{x})$, we have, given Theorem \ref{thm:AMEid}, that    \begin{equation}\label{eq:u'transformation}
    \widetilde{\text{AME}}_{\bar{\rho}}^+=\lim_{\rho\downarrow \bar{\rho}}\frac{d}{d\rho}\E[Y_i|\rho_i=\rho]-\frac{\text{sgn}\left(\E[Y_i|\rho_i=\bar{\rho}^+]-\E[Y_i|\rho_i=\bar{\rho}]\right) \cdot f_\rho(\bar{\rho}^+)}{F_\rho(\bar{\rho})\cdot \frac{1}{2\pi}\int \frac{\E[e^{\textbf{i}\xi Y_i}|\rho_i=\bar{\rho}]}{\E[e^{\textbf{i}\xi Y_i}|\rho_i=\bar{\rho}^+]}d\xi},
    \end{equation}
    where $\widetilde{\text{AME}}_{\bar{\rho}}^+:=\lim_{\rho\downarrow \bar{\rho}}\E[(\tilde{Y}_i(\rho)-\tilde{Y}_i(\bar{\rho}))/(\rho-\bar{\rho})|\rho_i=\rho]$, and $\tilde{Y}_i(\rho)$ indicate potential outcomes with respect to $\rho$: $\tilde{Y}_i(\rho) = Y_i(h(\rho))$ for any $\rho \ge \bar{\rho}$. Equivalently, $Y_i(x) = \tilde{Y}_i(h^{-1}(x))$ for any $x \ge \bar{x}$.

    First, notice that under the maintained assumptions
    \begin{align*}
    \widetilde{\text{AME}}_{\bar{\rho}}^+ &= \E[\tilde{Y}'(\bar{\rho})|\rho_i = \bar{\rho}] = \E\left[\left.\frac{d}{d\rho}\tilde{Y}(\bar{\rho})\right|\rho_i = \bar{\rho}\right] =  \E\left[\left.\left.\frac{d}{d\rho}Y_i(h(\rho))\right|_{\rho=\bar{\rho}}\right|X_i^* = \bar{x}\right]\\%\bar{\rho}] = \E\left[\left.\left.\frac{dx}{d\rho}\frac{d}{dx}\tilde{Y}(h^{-1}(x))\right|_{x=h(\bar{\rho})}\right|\rho_i = \bar{\rho}\right]\\
    &=h'(\bar{\rho}) \cdot \E[Y_i'(\bar{x})|X^*_i = \bar{x}]=h'(\bar{\rho}) \cdot \text{AME}_{\bar{x}}^+,
    \end{align*}
using the chain rule and defining $X_i^* = h(\rho_i)$. Meanwhile, all of the terms on the right-hand side of \eqref{eq:u'transformation} remain invariant under the substitution of $\rho_i$ by $X_i^*$ and $\bar{\rho}$ by $\bar{x}$, except that, similarly,
$$\lim_{\rho\downarrow \bar{\rho}}\frac{d}{d\rho}\E[Y_i|\rho_i=\rho]=\lim_{\rho\downarrow \bar{\rho}}\left.\frac{dx}{d\rho}\frac{d}{dx}\E[Y_i|X_i=x]\right|_{x=\bar{\rho}} = h'(\bar{\rho}) \cdot \lim_{\rho\downarrow \bar{\rho}}\frac{d}{dx}\E[Y_i|X_i=x], $$
while also $f_\rho(\bar{\rho}^+) = h'(\bar{\rho}) \cdot f_X(\bar{x}^+)$. Equation \eqref{eq:u'transformation} thus implies $\eqref{eq:u'}$, provided that $h'(\bar{\rho}) \ne 0$.

\subsection{Proof of Proposition \ref{prop:additive}}
In one direction, observe that if $Q_{Y(0)|X=x}(e) = s(x)+\phi(e)$, then $Y_i(0) - s(X_i) = Q_{Y(0)|X_i}(E_i)-s(X_i)=\phi(E_i)+s(X_i)-s(X_i) = \phi(E_i)$, and $E_i \indep X_i$. To see the other direction, define $s(x):=\mathbbm{E}[Y_i(0)|X_i=x]$ and $\mathcal{E}_i := Y_i(0)-s(X_i)$. Then, by definition, we can write $Q_{Y(0)|X_i}(E_i)=Y_i(0)=s(X_i)+\mathcal{E}_i = s(X_i)+Q_{\mathcal{E}_i|X_i}(\mathcal{E}_i)$. The condition $(Y_i(0)-\mathbbm{E}[Y_i(0)|X_i]) \indep X_i$ implies that $\mathcal{E}_i \indep X_i$, so we can replace $Q_{\mathcal{E}_i|X_i}(\mathcal{E}_i)$ with the unconditional $Q_{\mathcal{E}_i}(\mathcal{E}_i)$. Note that for any $e \in [0,1]$, $Q_{Y(0)|X=x}(e) = s(x) + Q_{\mathcal{E}_i}(e),$ since $Q_{\mathcal{E}_i}(\cdot)$ is strictly increasing. Now define $\phi(e) = Q_{\mathcal{E}_i}(e)$.

\subsection{Proof of Proposition \ref{prop:indep}}
Given \eqref{eq:starquantile}, we have that, with probability one under $P^*,$ $$Y^*_i(0)-\mathbbm{E}^*[Y^*_i(0)|X_i^*] = \{s^*(X_i^*)+\phi(E_i^*)\} - s^*(X_i^*)=\phi(E_i^*).$$
Then, since $E_i^* \sim \text{Unif}[0,1]$ under $P^*,$ and $Y^*_i(0)-\mathbbm{E}^*[Y^*_i(0)|X_i^*]$ is a measurable function of $E_i^*,$ it follows that $\{Y^*_i(0)-\mathbbm{E}^*[Y^*_i(0)|X_i^*]\} \indep X_i^*$ under $P^*$.

\subsection{Proof of Proposition \ref{prop:bunchers}}
	\begin{align*}
	P^*(Y^*_i(0)\le y|X_i^* \le 0) &= \frac{1}{P^*(X_i^* \le 0)}\cdot \int_{-\infty}^0 dx \cdot h(x)\cdot P^*(Y^*_i(0)\le y|X_i^* =x)\\
	&= \frac{1}{P^*(X_i^* \le 0)}\cdot \int_{-\infty}^0 dx \cdot h(x)\cdot P^*(s^*(x)+\phi(E_i^*)\le y|X_i^* =x)\\
	&= \frac{1}{P^*(X_i^* \le 0)}\cdot \int_{-\infty}^0 dx \cdot h(x)\cdot P^*(E_i^*\le \phi^{-1}(y-s^*(x)))\\
	&= \frac{1}{P^*(X_i^* \le 0)}\cdot \int_{-\infty}^0 dx \cdot h(x)\cdot P^*(E_i^*\le \phi^{-1}(y-s^*(x)))\\
	&=\frac{1}{P(X_i = 0)}\cdot \int_{-\infty}^0 dx \cdot h(x)\cdot  \phi^{-1}(y-s^*(x)),
	%P(Y_i \le y|X_i=0)
\end{align*}
using that $E_i^* \indep X_i^*,$ and that $E_i^* \sim \text{Unif}[0,1]$.

By the same steps, and using that $h(x)=f_X(0)$ and $Q_{Y(0)|X=x}(e)=Q^*_{Y^*(0)|X^*=x}(e)$ for all $x>0$,
\begin{align*}
	P(Y_i(0)\le y|X_i > 0) &= \frac{1}{P(X_i > 0)}\cdot \int_0^{\infty} dx \cdot f_X(x)\cdot P(Y_i(0)\le y|X_i =x)\\
	&= \frac{1}{1-P(X_i = 0)}\cdot\int_0^{\infty} dx \cdot h(x)\cdot P^*(s^*(x)+\phi(E_i^*)\le y|X_i^* =x)\\
	&=\frac{1}{1-P(X_i = 0)}\cdot \int_0^{\infty} dx \cdot h(x)\cdot  \phi^{-1}(y-s^*(x)).
	%P(Y_i \le y|X_i=0)
\end{align*}
Using both of these results, we have, by part (iii) of Assumption~\ref{as:analyticxstar}, that
\[
\begin{aligned}
F_{Y(0)}(y) 
&= \int_{-\infty}^0 \phi^{-1}\left(y - s^*(x)\right) \cdot h(x)\, dx 
+ \int_{0}^\infty \phi^{-1}\left(y - s^*(x)\right) \cdot h(x)\, dx \\
&= P(X_i = 0) \cdot P^*(Y^*_i(0) \le y \mid X_i^* \le 0) 
+ (1 - P(X_i = 0)) \cdot P(Y_i(0) \le y \mid X_i > 0).
\end{aligned}
\]
Meanwhile, by the law of iterated expectations, we also have that
$$F_{Y(0)}(y) = P(X_i = 0) \cdot P(Y_i(0)\le y|X_i = 0)+ (1-P(X_i = 0))\cdot P(Y_i(0)\le y|X_i > 0),$$
and therefore $P(Y_i\le y|X_i = 0) = P(Y_i(0)\le y|X_i = 0) = P^*(Y^*_i(0)\le y|X_i^* \le 0)$ for all $y$.

