\begin{document}



\begin{abstract}
    Let $\mu$ be a non-atomic self-similar measure on $\R$, and let $\nu$ be its pushforward to a non-degenerate curve in $\R^d, d\geq 1$. We show that for every $\e>0$ there is $p>1$, so that $\norm{\hat{\nu}}_{L^p(B(R))}^p = O_\e(R^\e)$ for all $R>1$, where $B(R)$ is the $R$-ball about the origin.  As a corollary, we show that convolution with $\nu$ quantitatively improves $L^2$-dimension.
\end{abstract}

\maketitle


\section{Introduction}
\subsection{Statement of Main results}
Let $U\subseteq \mathbb{R}$ be an open interval. We call a $C^{d+1}$ curve  $Q:U\r \R^d $  \textit{non-degenerate} if
\begin{align}\label{eq:nondegenerate}
        \det [Q^{(1)}(x) Q^{(2)}(x) \cdots Q^{(d)}(x)] \neq 0 \text{ for all } x\in U.
\end{align}
 When $Q$ is real analytic, we call it \textit{non-trapped} if the determinant above has at most finitely many zeros in any compact interval; this is equivalent to the trace of $Q$  not being  contained in a proper affine hyperplane of $\mathbb{R}^d$ (Lemma \ref{lem:good intervals higher dimensions}).
 Such curves have become standard objects in harmonic analysis, see e.g. \cite{fassler2014restricted, gan2022restricted} for some discussion and applications in modern projection theory.




The purpose of this paper is to study the $L^p$-norm of the Fourier transform of  self-similar measures on $\mathbb{R}$, when they are pushed-forward by either a non-trapped or a   non-degenerate curve.



\begin{thm} \label{main theorem general}
Let $\mu \in \mathcal{P}(\mathbb{R})$ be a non-atomic  self-similar measure, and let $d\geq 2$. Let  $U$ be an open interval containing  $\supp(\mu)$, and let $Q:U\r \R^{d} $ be either a non-trapped analytic curve, or a $C^{d+1}$ non-degenerate curve. 
    Let $\nu =Q\mu$ be the pushforward of $\mu$ via $Q$.
Then,
\begin{equation}\label{eq:main thm flattening}
\forall \e>0\quad \exists p>1 \quad \forall R >0:\, \norm{ \hat{\nu} }^p_{L^p (B(R))} = O_\e(R^\e),
\end{equation}
where $B(R)$ is the $R$-ball around $0$ in $\R^d$.
\end{thm}
Recall that a self-similar measure $\mu$ on the line is a Borel probability measure satisfying the stationarity condition, for some strictly positive probability vector $\mathbf{p}$,
$$\mu = \sum_{i=1} ^n \mbf{p}_i \cdot f_i \mu,\, \text{ where all } f_i\in \text{Aff}(\mathbb{R)} \text{ are s.t. } |f_i'|\in (0,1), \text{ and }  f_i\mu \text{ is the push forward of } \mu \text{ by } f_i.$$
See Section \ref{Section self-similar prel.} for  more discussion about them. Also, the notation $O_\e$ means the implicit constant may depend on $\e$; it may also depend on $\mu,d,Q$ and the maps $f_i$. Next, we note that the non-degeneracy condition \eqref{eq:nondegenerate}, and the non-trapped condition, cannot be relaxed from the Theorem. Indeed, \eqref{eq:main thm flattening} cannot hold for any measure $\nu$ living on a proper affine subspace, since then $|\hat{\nu}(\xi)|\sim 1 $ for all frequencies $\xi$ that are nearly orthogonal to the subspace supporting $\nu$. In particular, such frequencies contribute non-trivially to the $L^p$-norm of $\hat{\nu}$.


Finally, let us explain the relation between the title of the paper and our main result.
For $m\in \N$, let $\Dcal_m$ be the dyadic partition of $\R^d$ given by translates of $2^{-m}[0,1)^d$ by $2^{-m}\Z^d$. Given $q\geq 1$, we define the moment sum corresponding to $m,q,$ and a Borel probability measure $\nu$, by
\begin{align*}
    s_m(\nu,q) \stackrel{\mrm{def}}{=} \sum_{Q\in \Dcal_m} \nu(Q)^q. 
\end{align*}
For $q=\infty$, we set
\begin{align*}
    s_m(\nu,\infty) \stackrel{\mrm{def}}{=} \max \set{\nu(Q): Q\in \Dcal_m}.
\end{align*}
A standard computation (Lemma \ref{lem:Fourier vs moment sum}) shows that if $\nu$ is compactly supported, then for every $R>1$, letting $m = [\log_2 R]\in \N$ be the integer part of $\log_2 R$, we have
    \begin{align*}
         s_m(\nu,2)  
        \asymp 2^{-dm} \norm{\hat{\nu}}^2_{L^2(B(R))}.
    \end{align*}
    Thus, the conclusion of Theorem \ref{main theorem general} is equivalent to the following flattening phenomenon of moment sums:
for every $\e>0$ there exists $p\in\N$ such that for all $m$ large enough,
\begin{equation} \label{eq: flattening}
s_m(\nu^{\ast p},2) =  O_\e\left( 2^{m(\e-d)} \right).    
\end{equation}
Here $\mu\ast\nu$ means the usual Euclidean convolution of measures (pushforward of $\mu\times \nu$ by $(x,y)\mapsto x+y$), and $\nu^{\ast p}$ means the $p$-fold self-convolution of $\nu$.

Theorem~\ref{main theorem general} has the following consequences. Recall that   for a Borel probability  $\nu$ on $\mathbb{R}^d$ and $1<q<\infty$, one defines its $L^q$-dimension via
$$\dim_q (\nu)=\frac{\tau_q(\nu)}{q-1}, \quad \text{ where } \tau_q (\nu) = \liminf_{m\rightarrow \infty} \frac{-\log s_m(\nu,q)}{m}.$$
For $q=\infty,$ we set $\dim_\infty(\nu) = \t_\infty(\nu)$. The $L^\infty$-dimension is also known as the \textit{Frostman exponent} of $\nu$.
With this notation, we have the following corollary of Theorem~\ref{main theorem general}.
\begin{cor} \label{main corollary}
    Let $\nu$ be as in Theorem~\ref{main theorem general}. Then,
    \begin{enumerate}
        \item For all $q\in [2,\infty]$ we have $\lim_{n\rightarrow \infty} \dim_q(\nu^{\ast n})= d$.

        \item For every $\g>0$, there is $\eta=\eta(\g)>0$ and $m_0 = m_0(\g,\eta)>1$ such that the following holds for all integers $m\geq m_0$:
        For every Borel probability measure $\th$, 
        \begin{align}\label{eq:L2 improving}
      s_m(\th,2) > 2^{m(\g-d)} \quad \Longrightarrow  \quad s_m(\theta * \nu) 
        \leq 2^{-\eta m} s_m(\th,2).
        \end{align}
    \end{enumerate}
    Indeed, both statements hold true for any measure $\nu$ satisfying~\eqref{eq:main thm flattening}.
\end{cor}
\begin{proof}
Part (1) follows directly for $q=2$ from Theorem \ref{main theorem general}, in its equivalent form \eqref{eq: flattening}. 
Hence, the case $q=\infty$ then follows by Young's inequality; cf.~\cite[Lemma 5.2]{MosqueraShmerkin}, which then yields the claim for all other values of $q$.
Part (2) follows from Theorem \ref{main theorem general} similarly to the proof of~\cite[Theorem 4.1]{MosqueraShmerkin}.    
\end{proof}






We proceed now to discuss some prior results in harmonic analysis, fractal geometry, and dynamical systems, and how Theorem \ref{main theorem general} and its proof compare to them. 

\subsection{Prior results} We begin by comparing Theorem \ref{main theorem general} to recent results in harmonic analysis. Recall that a probability measure $\nu$ on $\mathbb{R}^d$ is called an $s$-Frostman measure, where $s\in [0,d]$, if $\mu(B(x,r))\leq r^s$ for all $x\in \mathbb{R}^d$ and $r>0$. In \cite{Orponen2023para}, Orponen proved that if $\nu$ is an $s$-Frostman measure on the truncated parabola $\mathbb{P}:=\lbrace (x,x^2):\,[-1,1]\rbrace$, then $\norm{\hat{\nu}}_{L^4 (B(R))} ^4 \ll R^{2-2s}$ for all $R\geq 1$. For $s\in (0,1)$ and $p>4$  he was able to obtain an $\e=\e(p,s)$ improvement $\norm{\hat{\nu}}_{L^p (B(R))} ^p \ll R^{2-2s-\e}$. Orponen also related this problem to the sum-product phenomenon and the Borel subring problem \cite[Section 1.2]{Orponen2023para}. He conjectured that for every $s\in [0,1]$ and $\e>0$ there exists some $p=p(\e,s)\geq 1$ such that for every $s$-Frostman measure on $\mathbb{P}$, $\norm{\hat{\nu}}_{L^p (B(R))} ^p \ll R^{2-\min \lbrace 3s, 1+s \rbrace+p\e }$, see \cite[Conjecture 1.6]{Orponen2023para}. Furthermore, exploiting the relation with iterated sum-sets, it was shown in \cite[Example 1.8]{Orponen2023para} that the threshold $\min \lbrace 3s, 1+s \rbrace$ cannot be further improved in this generality.  Dasu and Demeter \cite{Dasu2024demeter} later extended these results for $s$-Frostman measures $\nu$  that are supported on the graph of a $C^3( [-1,1],\, \mathbb{R)}$ function $\gamma$ such that $\min_{x\in [-1,1]} |\gamma''(x)|>0$; they established an Orponen-like bound of the form $\norm{\hat{\nu}}_{L^6 (B(R))} ^p \ll R^{2-2s-\beta}$ where $\beta=\beta(s), s\in (0,1)$. The conjectured bound from \cite[Conjecture 1.6]{Orponen2023para} was then established by Orponen, Puliatti, and Py{\"o}r{\"a}l{\"a} \cite{orponen2024fourier2}, along with further applications and analogies with the dimensions of iterated sum-sets on $\mathbb{P}$; some problems in this direction, however,   still remain open \cite[Questions 1 and 2]{orponen2024fourier2}. Finally, for measures $\nu$ supported on graphs of functions as in the work of Dasu and Demeter \cite{Dasu2024demeter}, it was very recently shown by Demeter and Wang \cite{Demeter2025Wang} that if $\nu$ is $s$-Frostman where $s\in (0,\frac{1}{2})$ then $\norm{\hat{\nu}}_{L^6 (B(R))} ^6 \ll R^{2-2s-\frac{s}{4}+\e}$ for all $\e>0$. See also \cite{yi2024bounded} for further research in this direction.

To compare Theorem \ref{main theorem general} to these results, we first note that all non-atomic self-similar measures are $s$-Frostman; this was first proved by Feng and Lau \cite{Feng2009Lau} (Proposition \ref{prop:mu is Frostman}). The precise computation of the best possible $s$ given the generating IFS is a subtle problem, that is still open in general; see Shmerkin's work \cite{shmerkin2016furstenberg} for some recent progress on it. Nonetheless, Theorem \ref{main theorem general} dramatically improves upon the results in \cite{Orponen2023para, Dasu2024demeter, orponen2024fourier2, Demeter2025Wang} as it shows optimal flattening regardless of the precise value of $s$,  for arbitrary non-trapped or non-degenerate curves in every dimension. In particular, we show that for self-similar measures the general threshold \cite[Example 1.8]{Orponen2023para} can be  substantially improved. However, unlike  \cite{Orponen2023para, orponen2024fourier2} where the key step involves a reduction to a problem about Furstenberg sets, or \cite{Dasu2024demeter, Demeter2025Wang} that use various decoupling arguments, the stationary structure of self-similar measures allows for a wider array of tools. It is thus interesting to ask how much regularity the measure  should enjoy so that it can break the   general threshold given in \cite[Example 1.8]{Orponen2023para}. In the same spirit, one may ask whether Theorem \ref{main theorem general} holds true for non-atomic Ahlfors-David regular measures (note, though, that not all self-similar measures have this property). 


Let us now place Theorem \ref{main theorem general} within recent literature on fractal geometry and dynamical systems. It can be considered a variant of the Fourier decay problem, which asks about optimal \textit{pointwise} estimates for the decay rate of $\hat{\nu}(\xi)$ when $\nu$ is a stationary measure. For self-similar measures, it is of central importance to understand when have polynomial decay ($\hat{\nu}(\xi)=O(\norm{\xi}^{-\alpha})$ for some $\alpha>0$) due to e.g. the relation between this property and the absolute continuity of $\nu$ \cite{Shmkerin2014Abs}. Solomyak \cite{solomyak2019fourier}, extending the classical Erd\Horig{o}s-Kahane argument,  had shown that polynomial decay is generic among self-similar measures, and a full characterization of the Rajchman property for them had been given by Li-Sahlsten \cite{li2018fourier}, Br\'{e}mont \cite{bremont2019rajchman} (see also Varj{\'u}-Yu \cite{varju2020fourier}), and Rapaport \cite{rapaport2021rajchman}. However, the only known \textit{explicit} examples of self-similar measures with polynomial  decay are due to Dai, Feng, and Wang \cite{Dai2007Feng}, a work that was recently extended by Streck \cite{streck2023absolute}. We remark that there are many explicit examples of measures with logarithmic decay ($\hat{\nu}(\xi)=O((\log |\xi|)^{-\alpha})$ for some $\alpha>0$) under various Diophantine conditions, see e.g. \cite{li2018fourier, varju2020fourier,  algom2021decay, khalil2024polynomial}. 


Another closely related direction concerns pointwise decay rates for non-linear push-forwards of self-similar measures. It was first observed by Kaufman \cite{Kaufman1984ber} that, among other things, if $g$ is any $C^2$ diffeomorphism on $[0,1]$ such that $g''>0$ then the pushforward of the Cantor-Lebesgue measure on the middle thirds Cantor set does have polynomial Fourier decay (even though the original measure is not even Rajchman). This was extended to all uniformly contracting self-similar measures by Mosquera and Shmerkin \cite{MosqueraShmerkin}, and then to all non-atomic self-similar measures by Algom, Chang, Meng Wu, and Yu-Liang Wu \cite{Algom2023Wu}, and simultaneously and independently by Baker and Banaji \cite{baker2024polynomial}. We note that, combined with the earlier works of Algom, Rodriguez Hertz, and Wang \cite{algom2023polynomial} and Baker and Sahlsten \cite{Baker2023Sahl}, this shows that all self-conformal  measures with respect to non-affine real analytic IFSs have polynomial Fourier decay. These results were extended to higher dimensions in various directions by Algom, Rodriguez Hertz, and Wang \cite{algom2024plane}, Baker, Khalil, and Sahlsten \cite{khalil2024polynomial}, and Banaji and Yu \cite{BanajiYu}. 


The proof of Theorem \ref{main theorem general} is related to the approach of \cite{Algom2023Wu,khalil2024polynomial}, where
the main tool exploited is the following large deviations estimate for the Fourier transform. Let $\mu$ be a non-atomic self-similar measure on $\mathbb{R}$. Then,
\begin{equation} \label{eq: Tsujii into}
\forall \e>0\, \exists \delta>0\text{ s.t. } \forall T\gg 1, \text{ we can cover } \lbrace|\xi|\leq T:\, |\hat{\mu}(\xi)|\geq T^{-\delta}\rbrace \text{ by } O_\e(T^\e) \text{ intervals of size } 1.    
\end{equation}
This was first observed by Kaufman \cite{Kaufman1984ber} for some Bernoulli convolutions. Tsujii \cite{Tsujii2015self} proved \eqref{eq: Tsujii into} for all non-atomic self-similar measures. Mosquera and Shmerkin \cite{MosqueraShmerkin} proved effective (quantitative) versions of \eqref{eq: Tsujii into}; these in turn allow one to give explicit lower bounds on the Fourier dimension of non-linear images of self-similar measures; see also \cite{BanajiYu} for related results.
Note that large deviation estimates of the form \eqref{eq: Tsujii into} are equivalent to the $L^p$-norm bounds in \eqref{eq:main thm flattening}.



A general criterion implying that \eqref{eq: Tsujii into} holds for arbitrary Borel probability measures (not necessarily self-similar) was established in \cite{khalil2023exponential}.
Namely, it is shown that $\nu$ satisfies \eqref{eq:main thm flattening} if for all $\e>0$, there is $\d>0$ such that for all proper affine subspaces $W$, we have
\begin{align}\label{eq:anc}
    \nu(W(\d r)\cap B(x,r)) \leq \e \, \nu\left(B(x,O(r))\right),
\end{align}
for all $x\in \supp(\nu)$ outside an exponentially small exceptional set, and all but a small proportion of scales $r>0$; cf. \cite[Cor. 1.7 and 6.4]{khalil2023exponential} for precise statements.
Here, $W(\d r)$ and $B(x,r)$ denote the $\d r$-neighborhood of $W$ and the $r$-ball around $x$ respectively.

The proof this result involves producing conditions on measures that are \textit{not} $L^2$-improving in the sense of \eqref{eq:L2 improving}, generalizing Shmerkin's $1$-dimensional inverse theorem \cite{shmerkin2016furstenberg} to higher dimensions; cf.~\cite[Prop. 11.10]{khalil2023exponential}. 
In particular, it is shown that large subsets in the supports of such measures must locally concentrate near proper subspaces at many scales.
A similar result was recently obtained by Shmerkin in \cite{shmerkin2025inverse}, where the local structure of the non-improved measure $\th$ in \eqref{eq:L2 improving} was also described. In both instances, the proof relies on Hochman's inverse theorem for entropy \cite{Hochman-InverseEntropy} and the asymmetric Balog-Szemer\'edi-Gowers Lemma \cite{TaoVu-book}.
To obtain \eqref{eq:main thm flattening}, this multi-scale concentration is ruled out using \eqref{eq:anc} through induction on scales \cite[Cor. 6.4]{khalil2023exponential}.



A natural question is to find weaker non-concentration conditions than \eqref{eq:anc} under which \eqref{eq: Tsujii into} (and hence \eqref{eq:main thm flattening}) can be shown to hold.
This question served as one of the major motivations of this work.
In this vein, Theorem \ref{main theorem general} provides a natural class of examples where the local non-concentration estimate \eqref{eq:anc} fails on large sets at every scale (due to local concentration of curves along their tangent lines), while the flattening estimate \eqref{eq:main thm flattening} holds.
In particular, such local concentration is a serious obstacle to carrying out the approach of \cite{khalil2023exponential}, and indeed, our proof of Theorem \ref{main theorem general} uses different techniques.












\subsection{On the proof of Theorem~\ref{main theorem general}} 
\label{sec:proof outline}
The proof of Theorem \ref{main theorem general} consists of two main parts, corresponding to two ranges of frequencies which we now introduce.
For $R\geq 1$ and $\e>0$,
    let 
    \begin{align*}
        C_{R,\e} &\stackrel{\mrm{def}}{=} \set{(\th,\zeta)\in \R\times \R^{d-1}: |\th|^\e \leq \norm{\zeta}\leq R},
        \nonumber\\
        E_{R,\e} & \stackrel{\mrm{def}}{=}\set{(\th,\zeta)\in \R\times \R^{d-1}: \norm{\zeta}\leq |\th|^\e \leq  R^\e}.
    \end{align*}
In particular, we have the following decomposition of $B(R)$:
\begin{align}\label{eq:decompose B(R)}
    B(R)  = C_{R,\e} \bigcup E_{R,\e}.
\end{align}
To describe the first ingredient, let $d\geq 1$ and define the moment curve 
$$V_d(x)\stackrel{\mrm{def}}{=} (x,x^2,\dots , x^d) \text{ if } d\geq 2, \qquad \text{ and }\qquad  V_1(x)=x \text{ otherwise}. $$
\begin{thm}\label{thm: case 1}
    Let $\mu$ be a non-atomic self-similar measure  on $\R$. 
    Let $d\geq 2$ and assume that
    \begin{align}\label{eq:flattening of moment d-1}
        \forall \e>0\quad \exists p>1 \quad \forall R >0:\, \norm{ \widehat{V_{d-1}\mu} }^p_{L^p (B(R))} = O_\e(R^\e).
    \end{align}
    Let $g:U\r \R^{d-1} $ be a map defined on an open neighborhood $U$ of $\supp(\mu)$, such that $Q(x)=(x,g(x))$ is either a non-trapped analytic curve, or a $C^{d+1}$ non-degenerate curve.
    Let $\nu =Q\mu$ be the pushforward of $\mu$ to the graph of $g$.
    Then, for every $\e>0$, there is $p_0=p_0(\mu,g,\e)>1$ such that for all $p\geq p_0$, we have
    \begin{align*}
        \int_{C_{R,\e}} |\widehat{\nu}(\xi)|^p\;d\xi =O_{\e}(R^\e).
    \end{align*}
\end{thm}
The following is the second main ingredient in our proof which handles the region $E_{R,\e}$.
\begin{prop} \label{prop: Case 2}
Let $\mu \in \mathcal{P}(\mathbb{R})$ be a non-atomic  self-similar measure and $d\geq 2$. 
Let $g:U\r \R^{d-1} $ be a  $C^1$-map defined on an open neighborhood $U$ of $\supp(\mu)$.
    For $Q(x)=(x,g(x))$, 
    let $\nu =Q\mu$ be the pushforward of $\mu$ to the graph of $g$.
Then, for every $\e >0$, there exists  $p=p(\e, \mu)>1$ such that for all $R\geq 1$, we have
\begin{align*}
    \int_{E_{R,\e}}\left| \widehat{\nu} (\xi) \right|^{p} \, d\xi = O_{\e,\mu}(R^\e).
\end{align*}
\end{prop}


First, let us show how Theorem \ref{main theorem general} follows quickly from Theorem \ref{thm: case 1} and Proposition \ref{prop: Case 2}.


\begin{proof}
    [\textbf{Proof of Theorem \ref{main theorem general} assuming Theorem \ref{thm: case 1} and Prop.~\ref{prop: Case 2}}]

    We proceed by induction on the ambient dimension $d$.
    By Tsujii's Theorem (Corollary \ref{Coro Tsujii}) for $d=2$, and by induction for $d>2$, we may assume that Hypothesis~\eqref{eq:flattening of moment d-1} holds for $\nu=V_{d-1}\mu$, where $V_{d-1}$ is the moment curve in $\R^{d-1}$.
    By replacing $\mu$ with an affine image of smaller diameter, and replacing $U$ with a smaller neighborhood if necessary, we may assume, after an affine change of coordinates, that $Q(x)$ takes the form $(x,g(x))$, for a map $g:U\r\R^{d-1}$ as in Theorem~\ref{thm: case 1}.
    Hence, in view of~\eqref{eq:decompose B(R)}, Theorem \ref{thm: case 1} and Proposition \ref{prop: Case 2} together imply Theorem \ref{main theorem general}.
\qedhere
\end{proof}



Next, we describe the ideas behind the above two intermediate results, beginning with Proposition \ref{prop: Case 2}.
Here, the main observation is that, via the coordinate relation in $E_{R,\e}$ and the Lipchitz continuity of $\hat{\nu}$, we can fully reduce it to an estimate about the Fourier transform of $\mu$ itself (Lemma \ref{lem:annular partition of Case 2}). This estimate is then obtained in Lemma \ref{Lemma 3 rewrite}, where the end-game step follows from Tsujii's large deviations estimate \eqref{eq: Tsujii into} (Corollary \ref{Coro Tsujii}). The details are given in Section \ref{Section:decay near first coordinate}.



The key to the proof of Theorem \ref{thm: case 1} is the following proposition providing \textit{polynomial pointwise decay} in a large region of of frequencies, from which Theorem \ref{thm: case 1} follows immediately; cf.~Corollary \ref{cor:integrate Case 1 bound} for this deduction.

 \begin{prop}\label{prop:Case 1 general curves}
     Let $\mu$ be a non-atomic self-similar measure  on $\R$. 
    Let $d\geq 2$ and assume that the flattening estimate~\eqref{eq:flattening of moment d-1} holds for $V_{d-1}\mu$.
    Let $g:U\r \R^{d-1} $ be as in Theorem~\ref{thm: case 1}. 
    For $Q(x)=(x,g(x))$, 
    let $\nu =Q\mu$ be the pushforward of $\mu$ to the graph of $g$. Then, there exists $\g=\g(\mu,g)>0$ such that for every $\xi =(\th,\zeta)\in \R\times \R^{d-1}$ with $\zeta\neq \mathbf{0}$, we have $|\hat\nu(\xi)|\ll \norm{\zeta}^{-\g}$.        
    \end{prop}

Proposition \ref{prop:Case 1 general curves} is closely related to the aforementioned pointwise Fourier decay results for non-linear pushforwards of self-similar measures obtained in \cite{Algom2023Wu,baker2024polynomial}, as well as to forthcoming work of Banaji and Yu for pushforwards of self-similar measures on $\R^k$ to graphs of analytic maps $g:\R^k\r \R^{k+d}$. 
We give a somewhat different proof of this result here, which we believe will be useful for future generalizations of Theorem \ref{main theorem general}.

It remains to explain the proof of Proposition \ref{prop:Case 1 general curves}.  
First, via Taylor expansion and a change of coordinates, we will deduce Proposition~\ref{prop: Case 2} from the special case $Q(x)=V_d(x)$, where $V_d(x)$ is the moment curve.
This deduction is carried out in Section \ref{sec:case 1 general curves}.

The special case of the moment curve is carried out in Proposition \ref{prop:Case 1 Veronese all dims multiple contractions}. 
The key observation in the proof of the latter,  which is based upon a construction of Feng and K{\"a}enm{\"a}ki   \cite[Lemma 3.1]{feng2018self}, is that the pushed self-similar measure $\nu =V_d\mu$ is, in fact, self-affine: that is, there exist $A_i \in \mrm{GL} (\mathbb{R}^d)$ with $\norm{A_i}<1$, and $b_i\in \R^d$, such that for $F_i(\mbf{x})=A_i\mbf{x}+b_i$, we have
$$\nu = \sum_{i=1} ^n \mbf{p}_i \cdot F_i \mu.$$
See Lemma \ref{Lemma self affine} below for the precise statement.
Note that the probability vector $\mathbf{p}$ is the same one that is used to define $\mu$.


This observation is then used to express the Fourier coefficient $\hat{\nu}(\xi)$ as an \textit{average} over many Fourier coefficients of the original measure $\mu$.
Roughly speaking, since the derivative of $V_d$ is essentially given by a copy of $V_{d-1}$, the set of frequencies we average over arise from a \textit{projection} of $V_{d-1}\mu$ in a suitable direction determined by the original frequency $\xi$. 

We then take advantage of our inductive flattening hypothesis \eqref{eq:flattening of moment d-1} to ensure that \textit{all} projections admit a uniform lower bound on their \textit{upper Frostman exponent}.
Indeed, the latter property in fact holds for any measure satisfying \eqref{eq:flattening of moment d-1}; cf.~Theorem \ref{prop:flattening implies friendly}. 
    It is likely that such Frostman bounds could be verified directly without appealing to~\eqref{eq:flattening of moment d-1}; cf.~\cite[Theorems 2.1(b) and 2.3]{KleinbockLindenstraussWeiss} for special cases of this statement.



The Frostman bound on the projections of $V_{d-1}\mu$ in turn ensures that
our average is sampled along a well-separated set of frequencies, thus enabling us to apply Tsujii's large deviations estimate \eqref{eq: Tsujii into} to conclude the proof.







\subsection{Notation} 
Throughout the article, given two quantities $A$ and $B$, we use the Vinogradov notation $A\ll B$ to mean that there exists a constant $C\geq 1$, possibly depending on the self-similar measure $\mu$, ambient dimension $d$, and the analytic map $g$,  such that $|A|\leq C B$. In particular, we suppress these dependencies except when we wish to emphasize them.
We write $A\ll_{x,y} B$ to indicate that the implicit constant depends on parameters $x$ and $y$.
We also write $A=O_x(B)$ to mean $A\ll_x B$.
Finally, we write $A \asymp_x B$ to mean $A\ll_x B$ and $B\ll_x A$.
For $x\in \R$, 
    \begin{align*}
        e(x) \stackrel{\mrm{def}}{=} e^{2\pi i x}.
    \end{align*}
 Finally, for $v\in\R^n$, $\norm{v}$ denotes the $\max$ norm.








