\subsection{A Term Structure of Predictors and their Sensitivities}
Let $a_{i,t+k}$ be the predicted value for asset $i$ at future time $t+k$, $\mathbf{D}_{\tau}$ represents the common drivers set at $t=\tau$ with $\tau<t$, and $f_{\boldsymbol{\theta}}^{\tau \rightarrow t+k}$ is the the model, parameterized by $\boldsymbol{\theta}^{\tau \rightarrow t+k}$ that predicts the asset return at time $t+k$ with input, the common drivers at time $t=\tau$ so that:
\begin{equation}
 a_{i,t+k} = f_{\boldsymbol{\theta}}^{\tau \rightarrow t+k}(\mathbf{D}_{\tau})   
\end{equation}


The following grid represents the predictors for different horizons \(k=1,\ldots,T\), with inputs \(\mathbf{D}_{\tau_j}\) at \(t=\tau_j\) for \(j=1,\ldots,T\), ensuring that \(\tau_j < t\). In this grid, \(a_{i,t+k}\) is the predicted value for entity \(i\) at future time \(t+k\). The inputs \(\mathbf{D}_{\tau_j}\) represent the data or features up to time \(\tau_j\). The function \(f_{\boldsymbol{\theta}}^{\tau_j \rightarrow t+k}\) defines the model, parameterized by \(\boldsymbol{\theta}^{\tau_j \rightarrow t+k}\), indicating the prediction from time \(\tau_j\) to \(t+k\).

\[
\begin{array}{c|cccc}
 & k=1 & k=2 & \cdots & k=T \\
\hline
t=1 & f_{\boldsymbol{\theta}}^{\tau_1 \rightarrow 2}(\mathbf{D}_{\tau_1}) & f_{\boldsymbol{\theta}}^{\tau_1 \rightarrow 3}(\mathbf{D}_{\tau_1}) & \cdots & f_{\boldsymbol{\theta}}^{\tau_1 \rightarrow T}(\mathbf{D}_{\tau_1}) \\
t=2 & f_{\boldsymbol{\theta}}^{\tau_2 \rightarrow 3}(\mathbf{D}_{\tau_2}) & f_{\boldsymbol{\theta}}^{\tau_2 \rightarrow 4}(\mathbf{D}_{\tau_2}) & \cdots & f_{\boldsymbol{\theta}}^{\tau_2 \rightarrow T}(\mathbf{D}_{\tau_2}) \\
t=3 & f_{\boldsymbol{\theta}}^{\tau_3 \rightarrow 4}(\mathbf{D}_{\tau_3}) & f_{\boldsymbol{\theta}}^{\tau_3 \rightarrow 5}(\mathbf{D}_{\tau_3}) & \cdots & f_{\boldsymbol{\theta}}^{\tau_3 \rightarrow T}(\mathbf{D}_{\tau_3}) \\
\vdots & \vdots & \vdots & \ddots & \vdots \\
t=T & f_{\boldsymbol{\theta}}^{\tau_T \rightarrow T}(\mathbf{D}_{\tau_T}) & f_{\boldsymbol{\theta}}^{\tau_T \rightarrow T}(\mathbf{D}_{\tau_T}) & \cdots & f_{\boldsymbol{\theta}}^{\tau_T \rightarrow T}(\mathbf{D}_{\tau_T}) \\
\end{array}
\]






\subsection{Derivation of Sensitivities Term Structure}
For each time step \(t\) and prediction horizon \(i\), the sensitivities \(\mathbf{S}_{t+i}\) with respect to the inputs \(\boldsymbol{D}_{\tau_j}\) are given by:

\begin{itemize}
    \item Sensitivities for Single-Step Ahead Predictions
\[
\mathbf{S}_{t+i} = \frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_i})}{\partial \boldsymbol{D}_{\tau_i}}, \quad \text{for } i=1,\ldots,T
\]
    \item Sensitivities for Multi-Step Ahead Predictions
\[
\mathbf{S}_{t+i} = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_j \rightarrow t+i)}}(\boldsymbol{D}_{\tau_j})}{\partial \boldsymbol{D}_{\tau_j}}, \quad \text{for } j=0,\ldots,T, \quad i=1,\ldots,T
\] 
\end{itemize}



For each time step \(t\) and prediction horizon \(i\), the sensitivities \(\mathbf{S}_{t+i}\) are structured in a grid. The first array of sensitivities (Single-Step and Multi-Step coincide at \(i=j-1\)), $i,j=1,\dots,T$:
\[
\begin{aligned}
&\mathbf{S}_{t+1} = \frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_0})}{\partial \boldsymbol{D}_{\tau_0}} = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+1)}}(\boldsymbol{D}_{\tau_0})}{\partial \boldsymbol{D}_{\tau_0}}, \\
&\mathbf{S}_{t+2} = \frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_1})}{\partial \boldsymbol{D}_{\tau_1}} =  \frac{\partial f_{\boldsymbol{\theta}^{(\tau_1 \rightarrow t+2)}}(\boldsymbol{D}_{\tau_1})}{\partial \boldsymbol{D}_{\tau_1}}, \\
&\mathbf{S}_{t+3} = \frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_2})}{\partial \boldsymbol{D}_{\tau_2}} =  \frac{\partial f_{\boldsymbol{\theta}^{(\tau_2 \rightarrow t+3)}}(\boldsymbol{D}_{\tau_2})}{\partial \boldsymbol{D}_{\tau_2}}, \\
&\dots \\
&\mathbf{S}_{t+T} = \frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_{T-1}})}{\partial \boldsymbol{D}_{\tau_{T-1}}} = 
 \frac{\partial f_{\boldsymbol{\theta}^{(\tau_{T-1} \rightarrow t+T)}}(\boldsymbol{D}_{\tau_{T-1}})}{\partial \boldsymbol{D}_{\tau_{T-1}}}
\end{aligned}
\]

so that $\boldsymbol{\theta}\equiv\boldsymbol{\theta}^{(\tau_{j} \rightarrow t+i)}$. The overall sensitivities across all horizons and input times can be described by combining the arrays into a structured grid. For \(j=0\), \(i=1,\ldots,T\):
\[
\mathbf{S}_{t+1}^1 = \frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_0})}{\partial \boldsymbol{D}_{\tau_0}} = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+1)}}(\boldsymbol{D}_{\tau_0})}{\partial \boldsymbol{D}_{\tau_0}},\mathbf{S}_{t+2}^2 = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+2)}}(\boldsymbol{D}_{\tau_0})}{\partial \boldsymbol{D}_{\tau_0}},\dots,\mathbf{S}_{t+T}^T = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+T)}}(\boldsymbol{D}_{\tau_0})}{\partial \boldsymbol{D}_{\tau_0}}
\]

For \(j=1\), \(i=1,\ldots,T\):
\[
\mathbf{S}_{t+2}^1 = \frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_1})}{\partial \boldsymbol{D}_{\tau_1}} = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_1 \rightarrow t+2)}}(\boldsymbol{D}_{\tau_1})}{\partial \boldsymbol{D}_{\tau_1}},\mathbf{S}_{t+3}^2 = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_1 \rightarrow t+3)}}(\boldsymbol{D}_{\tau_1})}{\partial \boldsymbol{D}_{\tau_1}},\dots,\mathbf{S}_{t+T}^{T-1} = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_1 \rightarrow t+T)}}(\boldsymbol{D}_{\tau_1})}{\partial \boldsymbol{D}_{\tau_1}}
\]

For \(j=2\), \(i=1,\ldots,T\):
\[
\mathbf{S}_{t+3}^1 = \frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_2})}{\partial \boldsymbol{D}_{\tau_2}} = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_2 \rightarrow t+3)}}(\boldsymbol{D}_{\tau_2})}{\partial \boldsymbol{D}_{\tau_2}},\mathbf{S}_{t+4}^2 = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_2 \rightarrow t+4)}}(\boldsymbol{D}_{\tau_2})}{\partial \boldsymbol{D}_{\tau_2}},\dots,\mathbf{S}_{t+T}^{T-2} = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_2 \rightarrow t+T)}}(\boldsymbol{D}_{\tau_2})}{\partial \boldsymbol{D}_{\tau_2}}
\]

\[
\vdots
\]

For \(j=T-2\), \(i=1,\ldots,T\):
\[
\mathbf{S}_{t+T-1}^1 = \frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_{T-2}})}{\partial \boldsymbol{D}_{\tau_{T-2}}} = \frac{\partial f_{\boldsymbol{\theta}^{({\tau_{T-2}} \rightarrow t+T-1)}}(\boldsymbol{D}_{\tau_{T-2}})}{\partial \boldsymbol{D}_{\tau_{T-2}}},\mathbf{S}_{t+T}^2 = \frac{\partial f_{\boldsymbol{\theta}^{(\tau_{T-2} \rightarrow t+T)}}(\boldsymbol{D}_{\tau_{T-2}})}{\partial \boldsymbol{D}_{\tau_{T-2}}}
\]

For \(j=T-1\), \(i=1,\ldots,T\):
\[
\mathbf{S}_{t+T}^1 = \frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_{T-1}})}{\partial \boldsymbol{D}_{\tau_{T-1}}} = \frac{\partial f_{\boldsymbol{\theta}^{({\tau_{T-1}} \rightarrow t+T)}}(\boldsymbol{D}_{\tau_{T-1}})}{\partial \boldsymbol{D}_{\tau_{T-1}}}
\]

This formulation allows for the calculation of sensitivities at each prediction horizon \(t+i\) using the corresponding neural network parameters and input drivers.

\[
\mathbf{S}_{t+i}^{i-j} = \begin{cases}
\frac{\partial f_{\boldsymbol{\theta}}(\boldsymbol{D}_{\tau_i})}{\partial \boldsymbol{D}_{\tau_i}}, & \text{for single-step ahead predictions} \quad \text{for }  i=0,\ldots,T,\\
\frac{\partial f_{\boldsymbol{\theta}^{(\tau_j \rightarrow t+i)}}(\boldsymbol{D}_{\tau_j})}{\partial \boldsymbol{D}_{\tau_j}}, & \text{for multi-step ahead predictions}, \quad \text{for } i,j=0,\ldots,T,
\end{cases}
\]


