\subsection{Combined Manifold Representation}
Let $T$ neural networks $f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+i)}}(\boldsymbol{D}_{\tau_0})$ for $k=1,\dots,T$ be the $k-th$ step ahead predictors of the portfolio contituent $a_{i}^{t+k}$ given the input $\boldsymbol{D}_{\tau_0}$ as common causal drivers. The combined $L_2$ loss is:
\begin{equation}
\mathcal{L}=\frac{1}{2}\sum_{k=1}^{T}\left(a_{i}^{t+k}-f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}}(\boldsymbol{D}_{\tau_0})\right)^2
\end{equation}
For each network, the gradient of the loss with respect to the parameters \(\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}\) is:
\begin{equation}
\nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}} \mathcal{L}_i = \sum_{k=1}^{T} \left( f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}}(\boldsymbol{D}_{\tau_0}) - a_{i}^{t+k} \right) \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}} f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}}(\boldsymbol{D}_{\tau_0})
\end{equation}
The combined gradient in the parameter space is:
\begin{equation}
\nabla_{\boldsymbol{\theta}} \mathcal{L} = \left( \begin{array}{c}
\nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+1)}} \mathcal{L} \\
\nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+2)}} \mathcal{L} \\
\vdots \\
\nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+T)}} \mathcal{L}
\end{array} \right) = \left( \begin{array}{c}
\mathbf{J}_1^T (\mathbf{F}_1 - a_{i}^{t+1}) \\
\mathbf{J}_2^T (\mathbf{F}_2 - a_{i}^{t+2}) \\
\vdots \\
\mathbf{J}_T^T (\mathbf{F}_T - a_{i}^{t+T})
\end{array} \right)
\end{equation}
with $\mathbf{J}_k^T=\nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}} f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}}(\boldsymbol{D}_{\tau_0})$ and $\mathbf{F}_k=f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}}(\boldsymbol{D}_{\tau_0})$. For each network, the gradient of the loss with respect to the inputs $(\boldsymbol{D}_{\tau_j})$, $j=1,\dots,T$ is:
\begin{equation}
\nabla_{\boldsymbol{D}_{\tau_j}} \mathcal{L}_k = \sum_{j=1}^{T}\sum_{t=1}^{T} \left( f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}}(\boldsymbol{D}_{\tau_j}) - a_{i}^{t+k}\right) \nabla_{\boldsymbol{D}_{\tau_j}} f_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}}(\boldsymbol{D}_{\tau_j})
\end{equation}

The combined gradient in the input space is:
\begin{equation}
\begin{split}
 \nabla_{\boldsymbol{D}_{\tau_j}} \mathcal{L} = \left( \begin{array}{c}
\nabla_{\boldsymbol{D}_{\tau_1}} \mathcal{L}_1\quad\dots\quad \nabla_{\boldsymbol{D}_{\tau_1}} \mathcal{L}_T\\
\nabla_{\boldsymbol{D}_{\tau_2}} \mathcal{L}_1\quad\dots\quad\nabla_{\boldsymbol{D}_{\tau_2}} \mathcal{L}_T\\
\vdots \\
\nabla_{\boldsymbol{D}_{\tau_T}} \mathcal{L}_1\quad\dots\quad \nabla_{\boldsymbol{D}_{\tau_T}} \mathcal{L}_T
\end{array} \right) =\\
\left( \begin{array}{c}
\mathbf{J}_1^T(\boldsymbol{D}_{\tau_1}) (\mathbf{F}_1(\boldsymbol{D}_{\tau_1}) - a_{i}^{t+1}) \quad \dots\quad\mathbf{J}_T^T(\boldsymbol{D}_{\tau_2}) (\mathbf{F}_T(\boldsymbol{D}_{\tau_1}) - a_{i}^{t+1}) \\
\mathbf{J}_1^T(\boldsymbol{D}_{\tau_2}) (\mathbf{F}_1(\boldsymbol{D}_{\tau_2}) - a_{i}^{t+2})\quad \dots\quad\mathbf{J}_T^T(\boldsymbol{D}_{\tau_1}) (\mathbf{F}_T(\boldsymbol{D}_{\tau_2}) - a_{i}^{t+2}) \\
\vdots \\
\mathbf{J}_1^T(\boldsymbol{D}_{\tau_T}) (\mathbf{F}_1(\boldsymbol{D}_{\tau_T}) - a_{i}^{t+T})\quad\dots\quad\mathbf{J}_T^T(\boldsymbol{D}_{\tau_T}) (\mathbf{F}_T(\boldsymbol{D}_{\tau_T}) - a_{i}^{t+T})
\end{array} \right)   
\end{split}
\end{equation}

Combining the gradients in both the parameter and input space, the tangent vector at each point $((\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}, \boldsymbol{D}_{\tau_j})$ can be written as:
\begin{equation}
\mathbf{T}_{(\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}, \boldsymbol{D_{\tau_j}})} \mathcal{M} = \left\{ \left( \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}} \mathcal{L}, \nabla_{\boldsymbol{D}_{\tau_j}} \mathcal{L} \right) \bigg| (\boldsymbol{\boldsymbol{\theta}}^{(\tau_0 \rightarrow t+k)}, \boldsymbol{D}_{\tau_j}) \in \mathcal{M} \right\}
\end{equation}

\subsection{Combined Causal Time System Manifold}
The combined manifold is composed of a static and dynamic components. The static manifold \(\mathcal{M}_{\text{static}}\) depends on the parameters of the $T$ multi-step ahead neural networks  $\boldsymbol{\boldsymbol{\theta}}^{(\tau_0 \rightarrow t+k)}$, $k=1,\dots,T$. It is static because it does not depend on a time-dependent input but a set of parametric models for different forecasting horizons from \(\tau_o\) to \(t+T\). The static manifold is defined as:
\[ \mathcal{M}_{\text{static}} = \left\{ \left( \theta^{(\tau_0 \rightarrow t+1)}, \theta^{(\tau_0 \rightarrow t+2)}, \ldots, \theta^{(\tau_0 \rightarrow t+T)} \right) \right\} \]
The dynamic manifold \(\mathcal{M}_{\text{dynamic}}\) depends on the time-dependent input variables \(\boldsymbol{D}_{\tau_j}\), $j=1,\dots,T$, and is defined as:
\[ \mathcal{M}_{\text{dynamic}} = \left\{ \boldsymbol{D}_{\tau_1}, \boldsymbol{D}_{\tau_2}, \ldots, \boldsymbol{D}_{\tau_T} \right\} \]
The combined manifold \(\mathcal{M}_{\text{combined}}\) integrates both static and dynamic components in a causal time system manifold:
\[ \mathcal{M}_{\text{combined}} = \mathcal{M}_{\text{static}} \times \mathcal{M}_{\text{dynamic}} \]
The static manifold tangent vectors:
\[ \mathbf{T}_{(\boldsymbol{\theta}^{(\tau_0 \rightarrow t+1)}, \boldsymbol{\theta}^{(\tau_0 \rightarrow t+2)}, \ldots, \boldsymbol{\theta}^{(\tau_0 \rightarrow t+T)})} \mathcal{M}_{\text{static}} = \left( \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+1)}} \mathcal{L}, \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+2)}} \mathcal{L}, \ldots, \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+T)}} \mathcal{L} \right) \]
Dynamic manifold tangent vectors:
\[ \mathbf{T}_{(\boldsymbol{D}_{\tau_0}, \boldsymbol{D}_{\tau_1}, \ldots, \boldsymbol{D}_{\tau_T})} \mathcal{M}_{\text{dynamic}} = \left( \nabla_{\boldsymbol{D}_{\tau_0}} \mathcal{L}, \nabla_{\boldsymbol{D}_{\tau_1}} \mathcal{L}, \ldots, \nabla_{\boldsymbol{D}_{\tau_T}} \mathcal{L} \right) \]

The combined tangent vectors for the causal time system manifold are:
\begin{equation}
    \begin{split}
\mathcal{T}_{\text{combined}} = \mathcal{T}_{\text{static}} \times \mathcal{T}_{\text{dynamic}}=\\
\left(\begin{matrix}
\nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+1)}}\nabla_{\boldsymbol{D}_{\tau_0}} & \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+2)}}\nabla_{\boldsymbol{D}_{\tau_0}} & \begin{matrix}\dots & \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+T)}}\nabla_{\boldsymbol{D}_{\tau_0}} \\ \end{matrix} \\
\nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+1)}}\nabla_{\boldsymbol{D}_{\tau_1}} & \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+2)}}\nabla_{\boldsymbol{D}_{\tau_1}} & \begin{matrix}\dots & \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+T)}}\nabla_{\boldsymbol{D}_{\tau_1}} \\ \end{matrix} \\
\vdots & \vdots & \begin{matrix}\ddots & \vdots \\ \end{matrix} \\
\nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+1)}}\nabla_{\boldsymbol{D}_{\tau_T}} & \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+2)}}\nabla_{\boldsymbol{D}_{\tau_T}} & \begin{matrix}\dots & \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+T)}}\nabla_{\boldsymbol{D}_{\tau_T}} \\ \end{matrix} \\
\end{matrix}\right)
    \end{split}
\end{equation}




\subsection{Sensitivities as Functions of the Tangent Space to the Combined Manifold}
\label{experiemntssenspath}

The tangent vectors to the combined manifold can be represented as:

\[
\mathbf{T}_{(\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}, \boldsymbol{D}_{\tau_j})} \mathcal{M} = \left( \nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}} \mathcal{L}, \nabla_{\boldsymbol{D}_{\tau_j}} \mathcal{L} \right)
\]

where \(\nabla_{\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}} \mathcal{L}\) are the gradients with respect to the model parameters and \(\nabla_{\boldsymbol{D}_{\tau_j}} \mathcal{L}\) are the gradients with respect to the input data.

The sensitivities \(\frac{\partial f_{\boldsymbol{\theta}}^{\tau_j \rightarrow t+k}(\mathbf{D}_{\tau_j})}{\partial \mathbf{D}_{\tau_j}}\) can be expressed as components of the tangent vectors to the combined manifold. Specifically, for each prediction step \(k\), the sensitivity can be written as:

\[
S_{\boldsymbol{\theta}}^{\tau_j \rightarrow t+k} = \frac{\partial f_{\boldsymbol{\theta}}^{\tau_j \rightarrow t+k}(\mathbf{D}_{\tau_j})}{\partial \mathbf{D}_{\tau_j}} = \nabla_{\boldsymbol{D}_{\tau_j}} f_{\boldsymbol{\theta}}^{\tau_j \rightarrow t+k}(\mathbf{D}_{\tau_j})
\]

Therefore, the sensitivity at each point \(((\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}, \mathbf{D}_{\tau_j}))\) in the combined manifold can be represented as:

\[
S_{\boldsymbol{\theta}}^{\tau_j \rightarrow t+k} = \mathbf{T}_{(\boldsymbol{\theta}^{(\tau_0 \rightarrow t+k)}, \mathbf{D}_{\tau_j})} \mathcal{M} \cdot \mathbf{e}_{\mathbf{D}_{\tau_j}}
\]

where \(\mathbf{e}_{\mathbf{D}_{\tau_j}}\) is the unit vector in the direction of the input data \(\mathbf{D}_{\tau_j}\).

The sensitivities \(\frac{\partial f_{\boldsymbol{\theta}}^{\tau_j \rightarrow t+k}(\mathbf{D}_{\tau_j})}{\partial \mathbf{D}_{\tau_j}}\) are projections of the tangent vectors to the combined manifold onto the directions of the input data \(\mathbf{D}_{\tau_j}\). These projections capture how small changes in the input data affect the outputs of the prediction models, thus reflecting the sensitivity of the predictors with respect to their inputs.

By expressing the sensitivities as functions of the tangent space to the combined manifold, we can leverage the geometric properties of the manifold to analyze and interpret the behavior of the prediction models and their dependencies on the input data.


The trajectory of the function \( f \) in the manifold as a function of time \( t \) describes how the function value evolves over time due to changes in both the model parameters \(\boldsymbol{\theta}\) and the input data \(\mathbf{D}_{\tau}\). The changes in the function value are influenced by the sensitivities (gradients) of the function with respect to the parameters and the inputs.

The trajectory is given by:

\begin{equation}
f_{\boldsymbol{\theta}(t)}(\mathbf{D}_{\tau}(t)) = f_{\boldsymbol{\theta}(0)}(\mathbf{D}_{\tau}(0)) + \int_0^t \left( \nabla_{\boldsymbol{\theta}} f_{\boldsymbol{\theta}(\tau)}(\mathbf{D}_{\tau}(\tau)) \cdot \frac{d\boldsymbol{\theta}(\tau)}{d\tau} + \nabla_{\mathbf{D}_{\tau}} f_{\boldsymbol{\theta}(\tau)}(\mathbf{D}_{\tau}(\tau)) \cdot \frac{d\mathbf{D}_{\tau}(\tau)}{d\tau} \right) d\tau
\end{equation}

This equation shows that the function \( f \) at time \( t \) is equal to its initial value at time \( 0 \) plus the integral of the sum of the products of the sensitivities with respect to the parameters and inputs and their respective rates of change over time.

To derive the expression for the trajectory of the function \( f \) with minimal loss as a function of the sensitivities of the predictors with respect to the inputs \(\mathbf{D}_{\tau}\), we start with the simplified assumption that the gradients \(\nabla_{\mathbf{D}_{\tau}} f\) are constant over time. Let \(\bar{e}_i\) represent the average error between the predicted and true values over the integration interval. Additionally, \(\eta_{\mathbf{D}_{\tau}}\) denotes the learning rate for the inputs.

Given these assumptions, the trajectory of \( f \) up to time \( t \) can be expressed by integrating the sensitivities over time. The initial value of the function is \( f_{\boldsymbol{\theta}(0)}(\mathbf{D}_{\tau}(0)) \), and it evolves based on the average error, the learning rate, and the constant sensitivity.

The function's trajectory is given by:

\[
f_{\boldsymbol{\theta}(t)}(\mathbf{D}_{\tau}(t)) \approx f_{\boldsymbol{\theta}(0)}(\mathbf{D}_{\tau}(0)) + \int_0^t \left( \eta_{\mathbf{D}_{\tau}} \sum_{i} \bar{e}_i \nabla_{\mathbf{D}_{\tau}} f \right) d\tau
\]

Since the integral of a constant over time is simply the product of the constant and the integration limit, this simplifies to:

\[
f_{\boldsymbol{\theta}(t)}(\mathbf{D}_{\tau}(t)) \approx f_{\boldsymbol{\theta}(0)}(\mathbf{D}_{\tau}(0)) + t \left( \eta_{\mathbf{D}_{\tau}} \sum_{i} \bar{e}_i \nabla_{\mathbf{D}_{\tau}} f \right)
\]

Therefore, the trajectory of the function \( f \) with minimal loss, as a function of the sensitivities of the predictors with respect to the input \(\mathbf{D}_{\tau}\), is:

\[
f_{\boldsymbol{\theta}(t)}(\mathbf{D}_{\tau}(t)) \approx f_{\boldsymbol{\theta}(0)}(\mathbf{D}_{\tau}(0)) + t \left( \sum_{i} \bar{e}_i \right) \eta_{\mathbf{D}_{\tau}} \nabla_{\mathbf{D}_{\tau}} f
\]

This expression illustrates that the function \( f \) evolves over time \( t \), starting from its initial value and increasing linearly based on the average error, the learning rate for the inputs, and the constant sensitivity of the predictor with respect to the inputs.





This new framework, which conceptualizes common causal manifolds as causal time systems with tangent spaces, and which is approximated using manifold learning theory and sensitivity modeling, constitutes a natural and logical extension of the framework introduced in \citep{RODRIGUEZDOMINGUEZ2023100447} and developed throughout the previous chapters of this monograph. It enables the integration of a broad range of methodologies, including various predictive models, causal driver identification techniques, sensitivity estimation tools, and convex optimization strategies, offering a highly flexible and robust foundation for advanced portfolio optimization.


