\subsubsection{Modeling Choice for the Sensitivity Process}
Sensitivities are modeled in future states of the causal manifold using Stochastic Differential Equations (SDEs). In this section some examples that are a good fit are discussed.


Consider the state variable \( \mathbf{D}_{t-k} \) following an SDE with a mean-reverting drift term:
\[
d\mathbf{D}_{t-k} = \kappa(\theta - \mathbf{D}_{t-k}) dt + \sqrt{f_{t-k}} d\mathbf{Z}_t
\]
where \( f_{t-k} \) is a function of the state variable \( \mathbf{D}_{t-k} \). The asset price \( a_t \) follows an SDE with stochastic volatility:
\[
da_t = \mu_{t-k, t} dt + \sqrt{g_{t-k, t}} dW_{a, t}
\]
where \( g_{t-k, t} \) is a function of both the state variable \( \mathbf{D}_{t-k} \) and the asset price \( a_t \). We are interested in the sensitivity \( S_t \) defined as:
\[
S_t = \frac{\partial a_t}{\partial \mathbf{D}_{t-k}}
\]

Using Itô's Lemma, the dynamics for the sensitivity \( S_t \) are derived:

\begin{equation}
    \begin{split}
dS_t = \left( \frac{\partial \mu_{t-k, t}}{\partial \mathbf{D}_{t-k}} + S_t \frac{\partial (\kappa(\theta - \mathbf{D}_{t-k}))}{\partial \mathbf{D}_{t-k}} +\right.\\
+\left.\frac{1}{2} \frac{\partial^2 a_t}{\partial \mathbf{D}_{t-k}^2} f_{t-k} \frac{\partial f_{t-k}}{\partial \mathbf{D}_{t-k}} \right) dt + S_t \frac{\partial f_{t-k}}{\partial \mathbf{D}_{t-k}} d\mathbf{Z}_t        
    \end{split}
\end{equation}
The discretize expression of the SDE using the Euler-Maruyama method is:
\begin{equation}
    \begin{split}
S_{t_{n+1}} = S_{t_n} + \left( \frac{\partial \mu_{t-k, t_n}}{\partial \mathbf{D}_{t-k}} + S_{t_n} \frac{\partial (\kappa(\theta - \mathbf{D}_{t-k, t_n}))}{\partial \mathbf{D}_{t-k}} +\right.\\
+\left.\frac{1}{2} \frac{\partial^2 a_{t_n}}{\partial \mathbf{D}_{t-k}^2} f_{t-k, t_n} \frac{\partial f_{t-k, t_n}}{\partial \mathbf{D}_{t-k}} \right) \Delta t + S_{t_n} \frac{\partial f_{t-k, t_n}}{\partial \mathbf{D}_{t-k}} \sqrt{\Delta t} \zeta_n   
    \end{split}
\end{equation}

The partial derivative of \( \mu_{t-k, t} \) with respect to \( \mathbf{D}_{t-k} \), with $\mu_{t-k, t} = \kappa_a (\theta_a - a_t)$, is $\frac{\partial \mu_{t-k, t}}{\partial \mathbf{D}_{t-k}} = 0$ as \( \mu_{t-k, t} \) does not explicitly depend on \( \mathbf{D}_{t-k} \). The partial derivative of the mean-reverting term \( \kappa(\theta - \mathbf{D}_{t-k}) \) is $\frac{\partial (\kappa(\theta - \mathbf{D}_{t-k}))}{\partial \mathbf{D}_{t-k}} = -\kappa$. The second-order partial derivative of \( a_t \) with respect to \( \mathbf{D}_{t-k} \) is $\frac{\partial^2 a_t}{\partial \mathbf{D}_{t-k}^2} \approx 0$. The partial derivative of the local stochastic volatility \( f_{t-k} \) with respect to \( \mathbf{D}_{t-k} \) is $\frac{\partial f_{t-k}}{\partial \mathbf{D}_{t-k}}$. The partial derivative of the local stochastic volatility \( g_{t-k, t} \) with respect to \( \mathbf{D}_{t-k} \) and \( a_t \) are $\frac{\partial g_{t-k, t}}{\partial \mathbf{D}_{t-k}}$ and $\frac{\partial g_{t-k, t}}{\partial a_t}$ respectively. Substituting these derivatives into the discretized update rule:
\[
S_{t_{n+1}} = S_{t_n} + \left( 0 + S_{t_n} (-\kappa) + \frac{1}{2} \cdot 0 \cdot f_{t-k, t_n} \cdot \frac{\partial f_{t-k, t_n}}{\partial \mathbf{D}_{t-k}} \right) \Delta t + S_{t_n} \frac{\partial f_{t-k, t_n}}{\partial \mathbf{D}_{t-k}}\sqrt{\Delta t} \zeta_n
\]

Simplifying, the discretized update for the sensitivity \( S_t \) is:
\[
S_{t_{n+1}} = S_{t_n} (1 - \kappa \Delta t) + S_{t_n} \frac{\partial f_{t-k, t_n}}{\partial \mathbf{D}_{t-k}} \sqrt{\Delta t} \zeta_n
\]

\subsubsection{Example with Specific SDEs for \( f \) and \( g \)}

Consider the state variable \( \mathbf{D}_{t-k} \) following the SDE:
\[
d\mathbf{D}_{t-k} = \kappa(\theta - \mathbf{D}_{t-k}) dt + \sqrt{\nu_{t-k}} d\mathbf{Z}_t
\]
where \( \nu_{t-k} \) is given by:
\[
\nu_{t-k} = \alpha \mathbf{D}_{t-k} + \beta \int_0^{t} \mathbf{D}_s ds
\]

The asset price \( a_t \) follows the SDE:
\[
da_t = \mu_{t-k, t} dt + \sqrt{\sigma_{t-k, t}} dW_{a, t}
\]
where \( \sigma_{t-k, t} \) is given by:
\[
\sigma_{t-k, t} = \gamma a_t + \delta \int_0^{t} a_s ds + \rho \mathbf{D}_{t-k}
\]

We define the sensitivity \( S_t \) as:
\[
S_t = \frac{\partial a_t}{\partial \mathbf{D}_{t-k}}
\]

Using Itô's Lemma, the dynamics for the sensitivity \( S_t \) are:
\[
dS_t = \left( \frac{\partial \mu_{t-k, t}}{\partial \mathbf{D}_{t-k}} + S_t \frac{\partial (\kappa(\theta - \mathbf{D}_{t-k}))}{\partial \mathbf{D}_{t-k}} + \frac{1}{2} \frac{\partial^2 a_t}{\partial \mathbf{D}_{t-k}^2} \nu_{t-k} \frac{\partial \nu_{t-k}}{\partial \mathbf{D}_{t-k}} \right) dt + S_t \frac{\partial \nu_{t-k}}{\partial \mathbf{D}_{t-k}} d\mathbf{Z}_t
\]

Using the Euler-Maruyama method to discretize the SDE:

\begin{equation}
    \begin{split}
    S_{t_{n+1}} = S_{t_n} + \left( \frac{\partial \mu_{t-k, t_n}}{\partial \mathbf{D}_{t-k}} + S_{t_n} \frac{\partial (\kappa(\theta - \mathbf{D}_{t-k, t_n}))}{\partial \mathbf{D}_{t-k}} +\right.\\
    +\left.\frac{1}{2} \frac{\partial^2 a_{t_n}}{\partial \mathbf{D}_{t-k}^2} \nu_{t-k, t_n} \frac{\partial \nu_{t-k, t_n}}{\partial \mathbf{D}_{t-k}} \right) \Delta t + S_{t_n} \frac{\partial \nu_{t-k, t_n}}{\partial \mathbf{D}_{t-k}} \sqrt{\Delta t} \zeta_n    
    \end{split}
\end{equation}


The partial derivative of \( \mu_{t-k, t} = \kappa_a (\theta_a - a_t)\) with respect to \( \mathbf{D}_{t-k} \) is $\frac{\partial \mu_{t-k, t}}{\partial \mathbf{D}_{t-k}} = 0$ since Since \( \mu_{t-k, t} \) does not explicitly depend on \( \mathbf{D}_{t-k} \). The partial derivative of the mean-reverting term \( \kappa(\theta - \mathbf{D}_{t-k}) \) is $\frac{\partial (\kappa(\theta - \mathbf{D}_{t-k}))}{\partial \mathbf{D}_{t-k}} = -\kappa$. The second-order partial derivative of \( a_t \) with respect to \( \mathbf{D}_{t-k} \) is $\frac{\partial^2 a_t}{\partial \mathbf{D}_{t-k}^2} \approx 0$. The partial derivative of the local stochastic volatility \( \nu_{t-k} \) with respect to \( \mathbf{D}_{t-k} \):
\[
\nu_{t-k} = \alpha \mathbf{D}_{t-k} + \beta \int_0^{t} \mathbf{D}_s ds
\]
\[
\frac{\partial \nu_{t-k}}{\partial \mathbf{D}_{t-k}} = \alpha + \beta t
\]

The partial derivative of the local stochastic volatility \( \sigma_{t-k, t} \) with respect to \( \mathbf{D}_{t-k} \) and \( a_t \):
\[
\sigma_{t-k, t} = \gamma a_t + \delta \int_0^{t} a_s ds + \rho \mathbf{D}_{t-k}
\]
\[
\frac{\partial \sigma_{t-k, t}}{\partial \mathbf{D}_{t-k}} = \rho
\]
\[
\frac{\partial \sigma_{t-k, t}}{\partial a_t} = \gamma + \delta t
\]

Substituting these derivatives into the discretized update rule:
\[
S_{t_{n+1}} = S_{t_n} + \left( 0 + S_{t_n} (-\kappa) + \frac{1}{2} \cdot 0 \cdot \nu_{t-k, t_n}(\alpha + \beta t) \right) \Delta t + S_{t_n} (\alpha + \beta t) \sqrt{\Delta t} \zeta_n
\]

Simplifying, the discretized update for the sensitivity \( S_t \) is:
\[
S_{t_{n+1}} = S_{t_n} (1 - \kappa \Delta t) + S_{t_n} (\alpha + \beta t) \sqrt{\Delta t} \zeta_n
\]

\subsubsection{Vasicek}


Consider the state variable \( \mathbf{D}_{t-k} \) following an SDE with a mean-reverting drift term:
\[
d\mathbf{D}_{t-k} = \kappa(\theta - \mathbf{D}_{t-k}) dt + \sigma_D d\mathbf{Z}_t
\]

The asset price \( a_t \) follows an SDE with stochastic volatility:
\[
da_t = \mu_a dt + \sigma_a dW_{a, t}
\]

To match the Vasicek sensitivity formula, we choose \( f \) and \( g \) as functions of the asset's and state's drifts and volatilities. Let:
\[
f_{t-k} = \left( \frac{\sigma_D^2}{2 \kappa} \right) \left(1 - e^{-2\kappa (t-k)} \right)
\]
\[
g_{t-k, t} = \left( \frac{\sigma_a^2}{2 \kappa_a} \right) \left(1 - e^{-2\kappa_a t} \right)
\]
Using Itô's Lemma, the dynamics for the sensitivity \( S_t = \frac{\partial a_t}{\partial \mathbf{D}_{t-k}} \) are:
\[
dS_t = \left( \frac{\partial \mu_a}{\partial \mathbf{D}_{t-k}} + S_t \frac{\partial (\kappa(\theta - \mathbf{D}_{t-k}))}{\partial \mathbf{D}_{t-k}} + \frac{1}{2} \frac{\partial^2 a_t}{\partial \mathbf{D}_{t-k}^2} f_{t-k} \frac{\partial f_{t-k}}{\partial \mathbf{D}_{t-k}} \right) dt + S_t \frac{\partial f_{t-k}}{\partial \mathbf{D}_{t-k}} d\mathbf{Z}_t
\]
with $\frac{\partial \mu_a}{\partial \mathbf{D}_{t-k}} = 0$, $\frac{\partial (\kappa(\theta - \mathbf{D}_{t-k}))}{\partial \mathbf{D}_{t-k}} = -\kappa$ and $\frac{\partial^2 a_t}{\partial \mathbf{D}_{t-k}^2} \approx 0$.  The partial derivative of the local stochastic volatility \( f_{t-k} = \left( \frac{\sigma_D^2}{2 \kappa} \right) \left(1 - e^{-2\kappa (t-k)} \right) \) with respect to \( \mathbf{D}_{t-k} \) is $\frac{\partial f_{t-k}}{\partial \mathbf{D}_{t-k}} = 0$. The partial derivative of the local stochastic volatility \( g_{t-k, t} = \left( \frac{\sigma_a^2}{2 \kappa_a} \right) \left(1 - e^{-2\kappa_a t} \right) \) with respect to \( \mathbf{D}_{t-k} \) and \( a_t \) are $\frac{\partial g_{t-k, t}}{\partial \mathbf{D}_{t-k}} = 0$ and $\frac{\partial g_{t-k, t}}{\partial a_t} = 0$ respectively. Substituting these derivatives into the dynamics of the sensitivity \( S_t \):
\[
dS_t = \kappa (\theta - S_t) dt + \sigma_S dW_t
\]
where \( \sigma_S \) is the combined volatility term. Using the Euler-Maruyama method to discretize the SDE, the discretized form is:
\[
S_{t_{n+1}} = S_{t_n} + \kappa (\theta - S_{t_n}) \Delta t + \sigma_S \sqrt{\Delta t} \zeta_n
\]
where \( \zeta_n \) is a standard normal random variable.




