\end{equation}

\begin{equation}
 \left[\begin{matrix}E\left[r_{a_X}|D_X\right]\\E\left[r_{a_Y}|D_Y\right]\\\end{matrix}\right]=\left[\begin{matrix}\beta_{X_1},\ldots,\beta_{X_M},000,\ldots,0\\000,\ldots0,\beta_{Y_1},\ldots,\beta_{Y_M}\\\end{matrix}\right]\left[\begin{matrix}D_X\\D_Y\\\end{matrix}\right]
 \label{eqapend3}
\end{equation}
Case I focuses on examples where drivers are not common. In this case, conditional expected returns are orthogonal in the embedded space of sensitivities with respect to drivers’ constituents, as seen in (\ref{eqapend1})-(\ref{eqapend3}), which is not a valid case.
    \item 	Case II: Common Non-Casual Drivers \begin{equation}
        \theta_{XY}=f(t,\ E\left[r_{a_X}|D\right],E[r_{a_Y}|D])
    \end{equation} 
