\section{Temporal Position Encoding}

\textbf{Temporal Position Encoding (TPE)} is designed to capture the coarse temporal location of each segment within the entire video. To achieve this, we divide the video into $B$ equal-frequency temporal bins and assign each segment to one of them based on its position in the sequence. Each bin is associated with a learnable embedding vector, which is used to represent the temporal context of segments assigned to that bin. This encoding helps the model understand whether a segment is located at the beginning, middle, or end of the video, which can be crucial for modeling temporal editing patterns.


\begin{algorithm}
\caption{Temporal Position Encoding (TPE)}
\label{alg:tpe}
\begin{algorithmic}[1]
\REQUIRE Number of segments $n$, number of bins $B$, embedding dimension $d$
\ENSURE Temporal position embeddings $\{TPE^1, \dots, TPE^n\}$

\STATE $s \leftarrow \left\lfloor \frac{n}{B} \right\rfloor$
\STATE Initialize embedding matrix $E \in \mathbb{R}^{B \times d}$

\FOR{$i = 1$ \TO $n$}
    \STATE $b_i \leftarrow \min\left(\left\lfloor \frac{i-1}{s} \right\rfloor, B - 1\right)$
    \STATE $TPE^i \leftarrow E[b_i]$
\ENDFOR

\RETURN $\{TPE^1, \dots, TPE^n\}$
\end{algorithmic}
\end{algorithm}



\section{Duration Encoding}

\textbf{Duration Encoding (DE)} encodes the fine-grained temporal position of each segment using a fixed sinusoidal scheme, similar to the original positional encoding used in Transformers. This method ensures that each segment has a unique continuous representation based on its position index. For each segment $i$, and for each embedding dimension $j$, the encoding alternates between sine and cosine functions of different frequencies. This encoding provides precise temporal cues, enabling the model to capture temporal dependencies and alignment across modalities.


\begin{algorithm}
\caption{Duration Encoding (DE)}
\label{alg:de}
\begin{algorithmic}[1]
\REQUIRE Number of segments $n$, encoding dimension $d$
\ENSURE Duration encodings $\{DE^1, \dots, DE^n\}$

\STATE Initialize $DE \in \mathbb{R}^{n \times d}$ with zeros

\FOR{$i = 0$ \TO $n-1$}
    \FOR{$j = 0$ \TO $d-1$}
        \STATE $\theta \leftarrow \frac{i}{10000^{\frac{2 \cdot \lfloor j / 2 \rfloor}{d}}}$
        \IF{$j$ is even}
            \STATE $DE^{i+1}[j] \leftarrow \sin(\theta)$
        \ELSE
            \STATE $DE^{i+1}[j] \leftarrow \cos(\theta)$
        \ENDIF
    \ENDFOR
\ENDFOR

\RETURN $\{DE^1, \dots, DE^n\}$
\end{algorithmic}
\end{algorithm}

\section{Predication}

\begin{algorithm}
\caption{Prediction via Feature Diffusion and Distillation Fusion}
\begin{algorithmic}[1]
\STATE \textbf{Input:} Time feature $X_{\text{time}}$, Spatial feature $X_{\text{spa}}$, \newline
\hspace*{2.5em} Semantic feature $X_{\text{sem}}$, Emotional feature $X_{\text{emo}}$, \newline
\hspace*{2.5em} Video feature $X_{\text{video}}$, Audio feature $X_{\text{audio}}$
\STATE \textbf{Output:} Final prediction score $\hat{Y}_{\text{final}}$

\STATE \COMMENT{\textbf{Step 1: Feature fusion and diffusion}}
\STATE $X_{\text{all}} \leftarrow \text{Concatenate}(X_{\text{time}}, X_{\text{spa}}, X_{\text{sem}}, X_{\text{emo}})$
\STATE $X_{\text{diffused}} \leftarrow \text{ApplyDiffusion}(X_{\text{all}})$

\STATE \COMMENT{\textbf{Step 2: Time and space prediction branch}}
\STATE $X_{\text{ts}} \leftarrow \text{Extract}(X_{\text{diffused}}, [\text{time}, \text{spa}])$
\STATE $\hat{Y}_{\text{st}} \leftarrow \text{MLP}_{\text{TS}}(X_{\text{ts}})$

\STATE \COMMENT{\textbf{Step 3: Semantic and emotional prediction branch}}
\STATE $X_{\text{se}} \leftarrow \text{Extract}(X_{\text{diffused}}, [\text{sem}, \text{emo}])$
\STATE $\hat{Y}_{\text{es}} \leftarrow \text{MLP}_{\text{SE}}(X_{\text{se}})$

\STATE \COMMENT{\textbf{Step 4: Video-Audio distillation output}}
\STATE $\hat{Y}_{\text{dis}} \leftarrow \text{Distill}(X_{\text{video}}, X_{\text{audio}})$

\STATE \COMMENT{\textbf{Step 5: Late fusion to get final prediction}}
\STATE $\hat{Y}_{\text{fusion}} \leftarrow \hat{Y}_{\text{st}} \times \tanh(\hat{Y}_{\text{es}})$
\STATE $\hat{Y}_{\text{final}} \leftarrow \hat{Y}_{\text{fusion}} \times \hat{Y}_{\text{dis}}$

\STATE \textbf{return} $\hat{Y}_{\text{final}}$
\end{algorithmic}
\end{algorithm}

To generate the final prediction, we design a multi-branch architecture that integrates temporal, spatial, semantic, and emotional features through a diffusion-enhanced fusion mechanism. As illustrated in Algorithm~4, the input features $X_{\text{time}}$, $X_{\text{spa}}$, $X_{\text{sem}}$, and $X_{\text{emo}}$ are first concatenated and passed through a diffusion process to enhance inter-feature dependencies and latent structure alignment. The diffused representation $X_{\text{diffused}}$ is then split into two branches:

Time-Spatial Branch: We extract the time and spatial-related features to form $X_{\text{ts}}$, which is passed through a dedicated MLP$_\text{TS}$ to yield an intermediate prediction $\hat{Y}{\text{st}}$.

Semantic-Emotional Branch: Similarly, semantic and emotional components are extracted as $X_{\text{se}}$, which is processed via another MLP$_\text{SE}$ to produce $\hat{Y}{\text{es}}$.

In parallel, we distill information from both video and audio modalities using a specialized distillation module, resulting in $\hat{Y}_{\text{dis}}$.

For final prediction, we adopt a late fusion strategy where the time-spatial output is modulated by the nonlinear activation of the semantic-emotional output: $\hat{Y}{\text{fusion}} = \hat{Y}{\text{st}} \cdot \tanh(\hat{Y}{\text{es}})$. This fusion is then further modulated by the distilled multi-modal prediction: $\hat{Y}{\text{final}} = \hat{Y}{\text{fusion}} \cdot \hat{Y}{\text{dis}}$. This design effectively captures complementary information from all feature domains and ensures robustness through multi-modal consistency.

