\section{Introduction}

\noindent
In \cite{E-E-76} we reported a set of 3rd-order fully-nonlinear symmetry-intergable equations that are invariant under a projective transformation in $u$  and in \cite{E-E-FN-2022} we reported
some results on 3rd-order fully-nonlinear symmetry-integrable equations
with rational functions in the third derivative. In the current paper we report further results on fully-nonlinear equations whereby we now focus on two special cases, namely a class of 3rd-order evolution equations and a 5th-order evolution equation, both  with algebraic nonlinearities in their highest derivative. In particular, we establish the semi-linearisations of the equations by systematically applying the procedure of multipotentialisation, hodograph transformations and, in some cases, generalised hodograph transformations. We refer to \cite{B-A-Book-2002},  \cite{B-A-C-Book-2010} and \cite{Euler-book-2018} for details on the potentialisation of evolution equations by the use of adjoint symmetries, whereas further details on generalised hodograph tranformations can be found in \cite{E-E-Tree-2001} and  \cite{P-E-E-2004}. 

The Schwarzian derivative $S$ plays an important role in our discussion and is defined in terms of the dependent variable $u$ by
 \begin{gather}
 \label{Schwarzian}
 S[u]:=\frac{u_{xxx}}{u_x}-\frac{3}{2}\frac{u_{xx}^2}{u_x^2},
 \end{gather}
% This notation is used to denote the Schwarzian derivative 
 which is applied throughout this paper.
 See for example \cite{Ovsienko} for a discussion on the Schwarzian derivative.

The paper is organised as follows: In Section 2 we consider a class of fully-nonlinear 3rd-order equations, identify those equations that admit local Lie-Bäcklund symmetries and map the obtained equations to known semilinear 3rd-order equations. Recursion operators are found for these equations which provide the associated symmetry-integrable hierarchies. In Section 3 we consider a single 5th-order fully-nonlinear evolution equation and establish its Lie-Bäcklund symmetries as well as its mapping to a known 5th-order semilinear integrable equation. In Section 4 we draw our conclusions of the reported results and mention some related open problems.


\section{A class of third-order fully-nonlinear evolution equations}
When seeking symmetry-integrable 3rd-order evolution equations the following statement \cite{E-E-FN-2022} is useful to determine the possible nonlinearities in the highest derivative $u_{xxx}$ \cite{E-E-76}:

\strut\hfill

\noindent
{\bf Lemma 1:} {\it
If a 3rd-order evolution equation of the form
\begin{gather}
u_t=F(x,t,u,u_x,u_{xx},u_{xxx})
\end{gather}
is symmetry-integrable for a given function $F$ then this function must satisfy the following condition:
\begin{gather}
\label{4th-order-cond}
9\left(\pde{F}{u_{xxx}}\right)^2\frac{\p^4F}{\p u_{xxx}^4}
-45\pde{F}{u_{xxx}}\frac{\p^2F}{\p u_{xxx}^2}\frac{\p^3F}{\p u_{xxx}^3}
+40\left(\frac{\p^2F}{\p u_{xxx}^2}\right)^3=0.
\end{gather}
}

%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\strut\hfill


\noindent
In 
\cite{E-E-FN-2022} we have reported the general solution of (\ref{4th-order-cond}), namely
\begin{gather}
\label{4th-order-cond-GS}
F(x,t,u,u_x,u_{xx},u_{xxx})=\frac{P_3\left(u_{xxx}+P_2\right)}
{\left[(u_{xxx}+P_2)^2+P_1\right]^{1/2}}+P4,
\end{gather}
where $P_j=P_j(x,t,u,u_x,u_{xx})$, $j=1,2,3,4$, are arbitrary and smooth functions of their arguments. 
We listed several singular solutions of (\ref{4th-order-cond}) that are not included in the general solution 
(\ref{4th-order-cond-GS}) and used the rational solutions in the classification of fully-nonlinear symmetry-integrable equations with rational nonlinearities of order three \cite{E-E-FN-2022}. 

An additional singular solution of 
(\ref{4th-order-cond}) that has not been reported in \cite{E-E-FN-2022} is
\begin{gather}
\label{SS-1}
F(x,t,u,u_x,u_{xx},u_{xxx})=\frac{P_1(x,t,u,u_x,u_{xx})}{\sqrt{u_{xxx}}}+P_2(x,t,u,u_x,u_{xx}),
\end{gather}
which is the form of $F$ that we will focus on in the current paper. Here $P_1$ and $P_2$ are arbitrary and smooth functions.
We furthermore restrict ourselves to evolution equations that do not depend explicitly on their independent variables $x$ and $t$ and apply the standard condition for Lie-Bäcklund symmetries for evolution equations, namely
%Lie-Bäcklund invariance condition 
\begin{gather}
\label{LB-inv}
\left.
\vphantom{\frac{DA}{DB}}
L_E[u]Q\right|_{E=0}=0,
\end{gather}
where $E:=u_t-F(u,u_x,u_{xx},u_{xxx})$, and $Q=Q(u,u_x,u_{xx},\ldots ,u_{nx})$ is the characteristic of the Lie-Bäcklund symmetry generator 
\begin{gather}
\label{IC-LB}
Z_{LB}=Q(u,u_x,u_{xx},\ldots ,u_{nx})\pde{\ }{u},\quad n>3.
\end{gather}
Here $L_E[u]$ denotes the linear operator
\begin{gather}
\label{Lin-Op}
L_E[u]:=\pde{E}{u}+\pde{E}{u_t}D_t+\pde{E}{u_x}D_x+\pde{E}{u_{xx}}D_x^2+\pde{E}{u_{xxx}}D_x^3.
\end{gather}
This leads to 

\strut\hfill

\begin{proposition}
Equation 
\begin{gather}
\label{Eq3-NC}
u_t=
\frac{P_1(u,u_x,u_{xx})}{\sqrt{u_{xxx}}}+P_2(u,u_x,u_{xx})
\end{gather}
is symmetry-integrable if and only if $P_1=\Psi(u_{xx})$ and $P_2=0$, so that 
(\ref{Eq3-NC}) is of the form
\begin{subequations}
\begin{gather}
\label{Main-3rd-EQ}
u_t=\frac{\Psi(u_{xx})}{\sqrt{u_{xxx}}},
\end{gather}
where $\Psi(u_{xx})$ must satisfy the following condition:
\begin{gather}
\label{3rd-Cond}
\Psi\frac{d^2\Psi}{du_{xx}^2}
-\frac{1}{3}\left(\frac{d\Psi}{du_{xx}}\right)^2
+\frac{3\beta}{4}\Psi^{-2/3}=0
\end{gather}
\end{subequations}
with $\beta$ an arbitrary constant.
A hierarchy of symmetry-integrable equations of odd order $n\geq 5$ is generated by
\begin{gather}
\label{hier-3rd-order}
u_{t_j}=R^j[u]u_t,\qquad j=1,2,3,\ldots,
\end{gather}
where  $u_t$ is given by (\ref{Main-3rd-EQ}) and 
$R[u]$ is the following recursion operator 
%for equation (\ref{Main-3rd-EQ}):
%given by (\ref{R-3rd-order-EQ}) and $u_t$ by (\ref{Main-3rd-EQ}).
%Here $\beta$ is an arbitrary constant. Under condition (\ref{3rd-Cond}), equation (\ref{Main-3rd-EQ}) admits the following 2nd-order recursion operator:
\begin{gather}
\label{R-3rd-order-EQ}
R[u]=G_2D_x^2+G_1D_x+G_0+I_1D_x^{-1}\circ \Lambda_1+I_2D_x^{-1}\circ \Lambda_2
\end{gather}
with
\begin{subequations}
\begin{gather}
G_2=\frac{\Psi^{2/3}}{u_{xxx}}\\[0.3cm]
G_1=\frac{\Psi^{2/3}}{2}\frac{u_{4x}}{u_{xxx}^2}
-\frac{5}{3\Psi^{1/3}}
\frac{d\Psi}{du_{xx}}
\\[0.3cm]
G_0=-\frac{\Psi^{2/3}}{2}
\frac{u_{5x}}{u_{xxx}^2}
+\frac{3\Psi^{2/3}}{4}
\frac{u_{4x}^2}{u_{xxx}^3}
+\frac{1}{3\Psi^{1/3}}
\frac{d\Psi}{du_{xx}}\frac{u_{4x}}{u_{xxx}}
-\frac{8}{9\Psi^{4/3}}
\left(\frac{d\Psi}{du_{xx}}\right)^2
u_{xxx}\nn\\[0.3cm]
\qquad
+\frac{5}{3\Psi^{1/3}}
\frac{d^2\Psi}{du_{xx}^2}
u_{xxx}
+k_0\\[0.3cm]
I_1=\beta\\
%%%
\Lambda_1=\frac{u_{4x}}{\Psi^2}
-\frac{2}{\Psi^3}
\frac{d\Psi}{du_{xx}}\\[0.3cm]
I_2=\frac{\Psi}{(u_{xxx})^{1/2}}\\[0.3cm]
%%%
\Lambda_2=
\frac{1}{2\Psi^{1/3}}
\frac{u_{6x}}{u_{xxx}^{3/2}}
-\frac{9}{4\Psi^{1/3}}
\frac{u_{4x}u_{5x}}{u_{xxx}^{5/2}}
-\frac{1}{2\Psi^{4/3}}
\frac{d\Psi}{du_{xx}}
\frac{u_{5x}}{u_{xxx}^{1/2}}
-\frac{13}{6\Psi^{4/3}}
\frac{d^2\Psi}{du_{xx}^2}
u_{xxx}^{1/2}u_{4x}\nn\\[0.3cm]
\qquad
+\frac{14}{9 \Psi^{7/3}}
u_{xx}^2u_{xxx}^{1/2}u_{4x}
+\frac{15}{8\Psi^{1/3}}
\frac{u_{4x}^3}{u_{xxx}^{7/2}}
+\frac{5}{12\psi^{4/3}}
\frac{d\Psi}{du_{xx}}
\frac{u_{4x}^2}{u_{xxx}^{3/2}}
+\frac{76}{27\Psi^{7/3}}
\frac{d\Psi}{du_{xx}}
\frac{d^2\Psi}{du_{xx}^2}
u_{xxx}^{5/2}\nn\\[0.3cm]
\qquad
+\frac{41}{27\Psi^{4/3}}
\frac{d^3\Psi}{du_{xx}^3}
u_{xxx}^{5/2}
-\frac{404}{243\Psi^{10/3}}
\left(\frac{d\Psi}{du_{xx}}\right)^3
u_{xxx}^{5/2}
+\frac{2\beta}{\Psi^4}
\frac{d\Psi}{du_{xx}}
u_{xxx}^{5/2}\nn\\[0.3cm]
\qquad
-\frac{\beta}{\Psi^3}u_{xxx}^{1/2}u_{4x}.
%
\end{gather}
\end{subequations}
Here $k_0$ is an arbitrary constant, and $\Psi(u_{xx})$ and $\beta$ must satisfy condition (\ref{3rd-Cond}).
%
%The hierarchy of symmetry-integrable equations of odd order is generated by
%\begin{gather}
