%\end{gather}
%where $R[u]$ is given by (\ref{R-3rd-order-EQ}) and $u_t$ by (\ref{Main-3rd-EQ}).
\end{proposition}

\strut\hfill

\noindent
{\bf Proof:} Using the Ansatz (\ref{R-3rd-order-EQ}) with the standard recursion operator condition
(see for example \cite{Euler-book-2018})
\begin{gather}
\left.\vphantom{\frac{DA}{DB}}
\left[L_E[u],\, R[u]\right]=D_tR[u]\right|_{E=0},
\end{gather}
where $E$ defines the equation (\ref{Eq3-NC}) and $L_E$ the linear operator (\ref{Lin-Op}), we find that 
$P_1=\Psi(u_{xx})$, $P_2=0$ with $\Psi$ and $\beta$ that satisfy equation (\ref{3rd-Cond}). This establishes that equation (\ref{Main-3rd-EQ}) is symmetry-integrable under these conditions.
\strut\hfill$\Box$

\smallskip

\noindent
Applying Proposition 1 we find that the second member of the hierarchy (\ref{hier-3rd-order}) is given by the following 5th-order equation:
\begin{gather}
%\label{Order-5-Eq-Psi}
u_{t_1}=-\frac{\Psi^{5/3}}{2}\frac{u_{5x}}{u_{xxx}^{5/2}}
+\frac{5\Psi^{5/3}}{8}\frac{u_{4x}^2}{u_{xxx}^{7/2}}
+\frac{5\Psi^{2/3}}{6}\frac{d\Psi}{du_{xx}}\frac{u_{4x}}{u_{xxx}^{3/2}}
+\frac{4\Psi^{2/3}}{3}
\frac{d^2\Psi}{du_{xx}^2}
u_{xxx}^{1/2}\nn\\[0.3cm]
\qquad
\label{Order-5-Eq-Psi}
-\frac{23}{18\Psi^{1/3}}
\left(\frac{d\Psi}{du_{xx}}\right)^2
u_{xxx}^{1/2}
+\frac{\beta}{\Psi}u_{xxx}^{1/2}
+\frac{k_0\Psi}{u_{xxx}^{1/2}}
\end{gather}

