\noindent
For solutions of (\ref{3rd-Cond}) we state the following 

\strut\hfill

\begin{proposition}
Equation (\ref{3rd-Cond}), viz.
\begin{gather*}
%\label{3rd-Cond}
\Psi\frac{d^2\Psi}{du_{xx}^2}
-\frac{1}{3}\left(\frac{d\Psi}{du_{xx}}\right)^2
+\frac{3\beta}{4}\Psi^{-2/3}=0,
\end{gather*}
admits the following three solutions:
\begin{enumerate}
\item
For any constant $\beta$ the general solution for (\ref{3rd-Cond})  is
\begin{gather}
\label{Psi-sol-gen}
\Psi(u_{xx})
%=\frac{1}{72^{3/4}c_1^{3/4}}\left[32c_1^2(u_{xx}+c_2)^2-81\beta\right]^{3/4}
=(2c_0)^{-3/8}\left[(u_{xx}+c)^2-\beta c_0\right]^{3/4},
\end{gather}
%
%
