where $c$ and $c_0$ are arbitrary constants with $c_0\neq 0$. 
\item
For $\beta\neq 0$ an additional solution for (\ref{3rd-Cond}), besides (\ref{Psi-sol-gen}),  is
\begin{gather}
\label{Psi-sol-2}
\Psi(u_{xx})=(2\beta)^{3/8}\left(u_{xx}+c\right)^{3/4},
\end{gather}
where $c$ is an arbitrary constant.
\item
For $\beta=0$ an additional solution for (\ref{3rd-Cond}), besides (\ref{Psi-sol-gen}) with $\beta=0$, is
\begin{gather}
\label{Psi-sol-3}
\Psi(u_{xx})=c,
\end{gather}
where $c$ is an arbitrary constant.
\end{enumerate}

\end{proposition}

\strut\hfill

\noindent
{\bf Remark 1:} {\it 
Equation (\ref{3rd-Cond}) can easily be linearised in a 1st-order ordinary differential equation via a Bernoulli equation. }
