\section{A fifth-order fully-nonlinear evolution equation}
When seeking symmetry-integrable 5th-order evolution equations, the following statement \cite{E-E-FN-2022} is useful to determine the possible nonlinearities in the highest derivative $u_{5x}$ \cite{E-E-1-2025}:

\strut\hfill

\noindent
{\bf Lemma 2:} {\it 
If a 5th-order evolution equation of the form
\begin{gather}
\label{Cond-5th-order-eq}
u_t=F(x,t,u,u_x,\ldots,u_{5x})
\end{gather}
is symmetry-integrable for a given function $F$ then this function must satisfy the following condition:
\begin{gather}
5\pde{F}{u_{5x}}\frac{\p^3 F}{\p u_{5x}^3}-8\left(\pdd{F}{u_{5x}}\right)^2=0.
\end{gather}
}

\strut\hfill

\noindent
The general solution (\ref{Cond-5th-order-eq}) is 
\begin{gather}
F(x,t,u,u_x,\ldots,u_{5x})=\frac{F_1}{(u_{5x}+F_2)^{2/3}}+F_3,
\end{gather}
where $F_j=F_j(x,t,u,u_x,\ldots,u_{4x})$ $(j=1,2,3)$ are arbitrary and smooth functions of their arguments. In the current paper we consider the special case where $F_1=1,$ $F_2=F_3=0$. Applying  now the Lie-Bäcklund symmetry invariance condition (\ref{LB-inv}) leads to the following

\strut\hfill

\begin{proposition}
The fully-nonlinear 5th-order equation
\begin{gather}
\label{Main-5th-EQ-u}
u_t=\frac{1}{u_{5x}^{2/3}}
\end{gather}
is symmetry-integrable and admits Lie-Bäcklund symmetries of order $1+6n$ and order $5+6n$, for every natural number $n$, so the symmetries are of order $\{7,11,13,17,19, \ldots\}$. 

\end{proposition}


\strut\hfill

\noindent
Let us give the first two equations in this hierarchy explicitly:
The symmetry-integrable evolution equation associated with the 7th-order Lie-Bäcklund symmetry of equation
 (\ref{Main-5th-EQ-u}) is 
%By the Lie-Bäcklund symmetries of (\ref{Main-5th-EQ-u}) the 7th-order member of the symmetry-integrable hierarchy associated with this equation is
\begin{gather}
\label{7th-Eq-u}
u_{t}=\frac{u_{7x}}{u_{5x}^{7/3}}-\frac{7}{6}\frac{u_{6x}^2}{u_{5x}^{10/3}}
\end{gather}
and the associated 11th-order symmetry-integrable equation is
\begin{gather}
u_t=\frac{1}{u_{5x}^{11/3}}\left(u_{11x}
-\frac{11u_{6x}u_{10x}}{u_{5x}}
-\frac{77 u_{7x}u_{9x}}{3u_{5x}}
%-\frac{33 u_{8x}^2}{2u_{5x}}
+\frac{682 u_{6x}^2u_{9x}}{9u_{5x}^{2}}
-\frac{33 u_{8x}^2}{2u_{5x}}
-\frac{374 u_{6x}^3u_{8x}}{u_{5x}^{3}}\right.\nn\\[0.3cm]
\qquad
\left.
+\frac{286u_{6x}u_{7x}u_{8x}}{u_{5x}^2}
+\frac{1892 u_{7x}^3}{27u_{5x}^{2}}
-\frac{22066 u_{6x}^2u_{7x}^2}{27 u_{5x}^{3}}
+\frac{107525 u_{6x}^4u_{7x}}{81u_{5x}^{4}}
-\frac{752675 u_{6x}^6}{1458u_{5x}^{5}}\right).
\end{gather}

\noindent
We now turn to the task to semi-linearise equation (\ref{Main-5th-EQ-u}): We apply the multipotentialisation procedure systematically on equation (\ref{Main-5th-EQ-u}), which leads to the quasilinear equation
\begin{gather}
\label{5th-EQ-w}
w_t=\frac{w_{5x}}{w_x^5}-\frac{10w_{xx}w_{4x}}{w_x^6}
-\frac{10w_{xxx}^2}{w_x^6}
+\frac{60w_{xx}^2w_{xxx}}{w_x^7}
-\frac{45w_{xx}^4}{w_x^8},
\end{gather}
where
\begin{gather}
w_x^3=-\frac{3}{2}u_{5x}.
\end{gather}
Equation (\ref{5th-EQ-w}) then takes the quasilinear form
\begin{gather}
\label{5th-EQ-V}
V_t=V^5V_{5x}+5V^4V_xV_{4x}+10V^4V_{xx}V_{xxx},
\end{gather}
with the following change of variables:
\begin{gather}
V(x,t)=\frac{1}{w_x}.
\end{gather}
%so that the relation between the variables $V(x,t)$ and $u(x,t)$ is
%\begin{gather}
%V(x,t)=-\left(\frac{2}{3}\right)^{1/5}\frac{1}{u_{5x}^{1/3}}.
%\end{gather}
Using generalised hodograph transformations we conclude that
%following
%
%\strut\hfill
%
%\begin{proposition}
the fully-nonlinear 5th-order equation (\ref{Main-5th-EQ-u})
%, viz.
%\begin{gather*}
%\label{Main-5th-EQ-u}
%u_t=\frac{1}{u_{5x}^{2/3}},
%\end{gather*}
maps to the semilinear 5th-order equation
\begin{gather}
\label{3rd-Pot-Kuper}
\boxed{\vphantom{\frac{DA}{DB}}
U_T=U_X\left(\frac{\p^2 S[U]}{\p X^2}+4S^2[U]\right)
}
\end{gather}
by the generalised hodograph transformation
\begin{gather}
{\cal GHT}: 
\left\{
\ba{l}
\displaystyle{
dX=f_1(x,V)  dx+f_2(x,V,V_x,V_{xx},V_{xxx},V_{4x})dt  
}\\
\\
\displaystyle{ dT=dt   }\\
\\
\displaystyle{ U(X,T)=x,}\\
\ea
\right.
\end{gather}
where
\begin{subequations}
\begin{gather}
f_1=\frac{1}{V}\\[0.3cm]
f_2=-V^3V_{4x}-2V^2V_xV_{xxx}-4V^2V_{xx}^2+4VV_{x}^2V_{xx}-V_x^4
\end{gather}
and 
\begin{gather}
V(x,t)=-\left(\frac{2}{3}\right)^{1/5}\frac{1}{u_{5x}^{1/3}}.
\end{gather}
\end{subequations}

%\end{proposition}

\strut\hfill

\noindent
Some remarks are in order:


\strut\hfill

\noindent
{\bf Remark 2:} {\it
We find  that equation (\ref{Main-5th-EQ-u}) does not admit a recursion operator of the form
\begin{gather}
\label{6th-R-ansatz}
R[u]=\sum_{j=0}^6 G_jD_x^j+\sum_{j=1}^3 I_jD_x^{-1}\circ \Lambda_j,
\end{gather}
whereby we assumed the following dependencies: for the integrating factors $\Lambda_k=\Lambda_k(u,u_x,$ $u_{xx},\ldots,u_{12x})$; for the symmetry coefficients $I_j=I_j(u,u_x,u_{xx},\ldots,u_{5x})$, and for the coefficients of $D_x^j$ we assumed that there are no restrictions in the number of derivatives, i.e. $G_j=G_j(u,u_x,$ $u_{xx},\ldots)$. Since a recursion operator of this form does not exist, we expect that the recursion operator is of a nonlocal type.
%which aught to generate the higher-order local Lie-Bäcklund symmetries and hence the associated hierarchy of symmetry-integrable equations, should be a nonlocal operator. 
We will not explore this further here.}


\strut\hfill


\noindent
{\bf Remark 3:}
{\it The semilinear equation (\ref{3rd-Pot-Kuper}) is the third potentialisation  (see equation (2.6) \cite{Euler-book-2018})  in the chain of multipotentialisations of the Kupershmidt equation 
\begin{gather}
K_t=K_{5x}-5K_xK_{xxx}-5K_{xx}^2-5K^2K_{xxx}
-20KK_xK_{xx}
-5K_x^3+5K^4K_x.
\end{gather}
A recursion operator of order six has been reported for equation (\ref{3rd-Pot-Kuper}) in \cite{Euler-book-2018}, where some solution-generating formulas are also given for (\ref{3rd-Pot-Kuper}).

}

\strut\hfill

\noindent
{\bf Remark 4:}
{\it Let us furthermore point out that equation (\ref{5th-EQ-V}), viz.
\begin{gather*}
%\label{5th-EQ-V}
V_t=V^5V_{5x}+5V^4V_xV_{4x}+10V^4V_{xx}V_{xxx},
\end{gather*}
just like equation (\ref{Main-5th-EQ-u}), does not admit a recursion operator of the form (\ref{6th-R-ansatz}) although (\ref{5th-EQ-V}) is of course symmetry-integrable and hence admits Lie-Bäcklund symmetries of the same order as equation (\ref{5th-EQ-w}) which generates a hierarchy of symmetry-integrable equations. For example, the 7th-order symmetry-integrable equation in this hierarchy is
\begin{gather}
%\label{7th-Eq-V}
V_t=V^7V_{7x}
+14V^6V_xV_{6x}
+49V^5V_x^2V_{5x}
+28V^6V_{xx}V_{5x}
+35V^4V_x^3V_{4x}
+140V^5V_xV_{xx}V_{4x}\nn\\[0.3cm]
\label{7th-Eq-V}
\qquad
+35V^6V_{xxx}V_{4x}
+70V^5V_xV_{xxx}^2
+70V^5V_{xx}^2V_{xxx}
+70V^4V_x^2V_{xx}V_{xxx}.
\end{gather}
Furthermore, the 7th-order equation (\ref{7th-Eq-u}) maps to the 7th-order equation (\ref{7th-Eq-V}) by the following change of variable:
\begin{gather}
V(x,t)=u_{5x}^{-1/3}.
\end{gather}
}

\noindent
{\bf Remark 5:}
{\it Quite remarkably, equation (\ref{5th-EQ-w}), viz.
\begin{gather*}
%\label{5th-EQ-w}
w_t=\frac{w_{5x}}{w_x^5}-\frac{10w_{xx}w_{4x}}{w_x^6}
-\frac{10w_{xxx}^2}{w_x^6}
+\frac{60w_{xx}^2w_{xxx}}{w_x^7}
-\frac{45w_{xx}^4}{w_x^8},
