G_3=-\frac{27w_{4x}}{w_x^7}
+\frac{354 w_{xx}w_{xxx}}{w_x^8}
-\frac{600w_{xx}^3}{w_x^9}\\[0.3cm]
G_2=-\frac{19w_{5x}}{w_x^7}
+\frac{271w_{xx}w_{4x}}{w_x^8}
+\frac{232w_{xxx}^2}{w_x^8}
-\frac{2040w_{xx}^2w_{xxx}}{w_x^9}
+\frac{1980w_{xx}^4}{w_x^{10}}\\[0.3cm]
G_1=-\frac{4w_{6x}}{w_x^7}
+\frac{79w_{xx}w_{5x}}{w_x^8}
+\frac{149w_{xxx}w_{4x}}{w_x^8}
-\frac{754w_{xx}^2w_{4x}}{w_x^9}
+\frac{4440w_{xx}^3w_{xxx}}{w_x^{10}}\nn\\[0.3cm]
\qquad
+\frac{1126w_{xx}w_{xxx}^2}{w_x^9}
-\frac{3060w_{xx}^5}{w_x^{11}}\\[0.3cm]
G_0=-\frac{3w_{7x}}{w_x^7}
+\frac{63w_{xx}w_{6x}}{w_x^8}
-\frac{690w_{xx}^2w_{5x}}{w_x^9}
+\frac{145 w_{xxx}w_{5x}}{w_x^8}
-\frac{2494 w_{xx}w_{xxx}w_{4x}}{w_x^9}\nn\\[0.3cm]
\qquad
+\frac{4794 w_{xx}^3w_{4x}}{w_x^{10}}
