\qquad
+\frac{11340 w_{xx}^6}{w_x^{12}}+k_0\\[0.3cm]
\Lambda_1=-\frac{w_{4x}}{w_x^3}+\frac{6w_{xx}w_{xxx}}{w_x^4}-\frac{6w_{xx}^3}{w_x^5}\\[0.3cm]
\Lambda_2=\frac{w_{8x}}{w_x^7}
-\frac{28w_{xx}w_{7x}}{w_x^8}
+\frac{396w_{xx}^2w_{6x}}{w_x^9}
