\begin{equation*}
    \E H_{n + 1} = \frac12 \E( L_n' + 1 + H_n + H_n' + |L_n' + 1 + H_n - H_n'|) = \frac12\left(\frac32\right)^n + \E H_n + \frac12 \E |L_n' + 1 + H_n - H_n'|.
\end{equation*}
Using  $\E|Y| \ge |\E Y|$ and \eqref{eq: 1st moment Ln}, we have
$$
\E|L_n ' + 1 + H_n - H_n'| \ge |\E L_n' + 1 + \E H_n - \E H_n'| = |\E L_n' + 1| = \left(\frac32\right)^n.
$$
This yields further then the lower bound
\begin{equation*}
    \E H_{n + 1} \ge \left(\frac32\right)^n + \E H_n,
\end{equation*}
which simplifies to
\begin{equation}\label{eq: lower bd}
    \E H_n \ge \sum_{k = 0}^{n-1} \left(\frac32\right)^k = 2 \left(\frac32\right)^n - 2.
\end{equation}
\begin{remark}
This lower bound on the mean height of uniform nonsimple butterfly trees matches exactly the mean height for uniform simple butterfly trees (cf. \Cref{thm: sbt}). A similar phenomenon appears for the LIS, where the average LIS under uniform simple butterfly permutations serves as a lower bound for the nonsimple case (cf. \Cref{thm: old sbt,thm: old bsbt}).
\end{remark}





