using the triangle and Cauchy-Schwarz inequalities. Hence, we have
\begin{align*}
    \operatorname{Var}(H_{n+1}) &\le \operatorname{Var}(H_n) + \frac14 (4\E L_n^2 + 4(\E L_n + 1) - (\E L_n+1)^2) + \frac12(\E H_n)(\E L_n + 2) \\
    &\hspace{2pc} + \frac12 \sqrt{(\operatorname{Var}(H_n) + (\E H_n)^2)(\E L_n^2)} + \sqrt{2(\operatorname{Var}(H_n) + (\E H_n)^2)\operatorname{Var}(H_n)}\\
    &\hspace{2pc} + \frac12\sqrt{2\E L_n^2 \operatorname{Var}(H_n)} + \frac12 \sqrt{2 \operatorname{Var}(H_n)}.
\end{align*}
Let $\lambda = 3/2$. Note then obviously $\lambda^n - 1 = \E L_n \le \lambda^n$ while $\E L_n^2  = \frac43 \lambda^{2n} - (\frac73 \lambda^n - 1) \le \frac43 \lambda^{2n}$. It follows
\begin{align*}
    \operatorname{Var}(H_{n+1}) &\le \operatorname{Var}(H_n) + \frac14 \left(4  \cdot \frac43 \lambda^{2n} + 4 \lambda^n - \lambda^{2n}\right)+ \frac12(\E H_n)(\lambda^n + 1) \\
    &\hspace{2pc} + \frac12 \sqrt{\frac43\lambda^{2n}} \sqrt{\operatorname{Var}(H_n) + (\E H_n)^2} + \sqrt{2(\operatorname{Var}(H_n) + (\E H_n)^2)\operatorname{Var}(H_n)}\\
    &\hspace{2pc} + \frac12\sqrt{\frac83 \lambda^{2n}} \sqrt{\operatorname{Var}(H_n)} + \frac12 \sqrt{2 \operatorname{Var}(H_n)}\\
    &\le \operatorname{Var}(H_n) + \frac{13}{12} \lambda^{2n} + \lambda^n + \frac12(\E H_n)(\lambda^n + 1) \\
    &\hspace{2pc} + \sqrt{\frac13} \lambda^n \sqrt{\operatorname{Var}(H_n) + (\E H_n)^2} + \sqrt 2 \cdot \sqrt{(\operatorname{Var}(H_n) + (\E H_n)^2)\operatorname{Var}(H_n)}\\
    &\hspace{2pc} + \sqrt{\frac23} \lambda^n \sqrt{\operatorname{Var}(H_n)} + \frac12 \sqrt{2 \operatorname{Var}(H_n)}.
\end{align*}

Let $a_n, b_n\ge 0$ with $a_0 = b_0 = 0$ such that
\begin{align*}
    a_{n+1} &= \lambda^n + a_n + \frac12 \sqrt{ 2b_n}\\
    b_{n+1} &= b_n + \frac{13}{12} \lambda^{2n} + \lambda^n + \frac12 (\lambda^n + 1)a_n + \sqrt{\frac13} \lambda^n\sqrt{b_n + a_n^2} \\
    &\hspace{2pc}+ \sqrt{(b_n + a_n^2)2b_n} + \left(\sqrt{\frac13} \lambda^n + {\frac12}\right)\sqrt{2b_n} .
\end{align*}
Our goal is to bound both $\E H_n$ and $\operatorname{Var}(H_n)$ in terms of $a_n,b_n$. 
By construction and induction, we have 
$$\E H_n \le a_n \  \mbox{and} \ \operatorname{Var}(H_n) \le b_n \qquad  \mbox{for all } n.$$ 
Next, observe that
$$
a_{n+1}^2 = \lambda^{2n} + a_n^2 + \frac12 b_n + 2\lambda^n a_n + (\lambda^n + a_n)\sqrt{2 b_n}.
$$
We aim to find a constant $C \ge 0$ such that $b_n \le C a_n^2$. This allows us to bound $$a_{n+1} \le \lambda^n + \xi a_n,$$ which has general upper bound recursion solution \begin{equation*}
    a_n \le A \lambda^n + B \xi^n,
\end{equation*} for $\xi = 1 + \sqrt{2C}/2$. Moreover, if $\frac12 < C < 2$ then $\lambda < \xi < 2$, which would thus yield a sub-linear upper bound on $a_n$ and hence $\E H_n$, with exponent $\log_2 \xi < 1$. 

The remainder of this section will verify that this bound holds with the choice 
\begin{equation}\label{eq: C*}
    C^* := 1 + \sqrt{8\sqrt 2 - 11} \approx 1.5601.
\end{equation}
This in turn yields the desired sublinear upper bound on $\E h(\mathcal T(\pi_n))$ for $\pi_n \sim \Unif(\B_n)$, as stated in \Cref{thm: nsbt}, with exponent $\beta = \log_2 \xi \approx 0.913189$.

\begin{lemma}\label{l: bn<Can^2}
    Let $C \ge C^*$. Then $b_n \le C a_n^2$ for all $n \ge 0$.
\end{lemma}
\begin{proof}
    Now this trivially holds for any $C$ when $n=0$, while by above we have $a_1=\frac32$ and $b_1=\frac{13}{12}+1=\frac{25}{12}$, so this holds as long as $C\ge\frac{25}{27}$. Now assume the result holds for $n\ge1$.  Recall by above $ a_n \ge \E H_n \ge 2 \lambda^n - 2$, so $\lambda^n \le \frac12 a_n + 1 \le \frac32 a_n$ for all $n\ge1$. Using the triangle inequality, we have $\sqrt{b_n + a_n^2} \le \sqrt{b_n} + a_n$, and so
\begin{align*}
    b_{n+1} &\le (1 + \sqrt 2) b_n + \frac{13}{12} \lambda^{2n} + \left(\left(\frac12 + \sqrt{\frac13}\right) \lambda^n +  2\right) a_n \\ %+ \sqrt{\frac16} \alpha^n \sqrt{2b_n}\\
    &\hspace{2pc} + \left(\left(\sqrt{\frac16} + \sqrt{\frac13}\right) \lambda ^n  + a_n +   {\frac12}\right) \sqrt{2b_n} .
\end{align*}
To get a potential value of $C$, we next compute
\begin{align}
    b_{n+1} - Ca_{n+1}^2 &\le -2\left(\left(C - \frac12\left(\frac12 + \sqrt{\frac13}\right)\right) \lambda^n - 1 \right) a_n - \left(\left(C - \left(\sqrt{\frac16} + \sqrt{\frac13}\right)\right) \lambda^n - \frac12 \right) \sqrt{2 b_n}\nonumber\\
    &\hspace{2pc} - \left(C-\frac{13}{12}\right) \lambda^{2n}+\left[\left(1 + \sqrt 2 - \frac{C}2\right) b_n-Ca_n^2 -(C-1)a_n \sqrt{2 b_n}\right] \nonumber\\    &=:\fbox{I}+\fbox{II}+\fbox{III}+\fbox{IV}.\label{eq:ind upper bound}
\end{align}
One way to ensure $b_{n+1} \le C a_{n+1}^2$ is if $C$ is chosen such that the upper bound has non-positive coefficients for each of the three terms using $a_n$, $\sqrt{2 b_n}$ and $\lambda^{2n}$, i.e.,  \fbox{I} through \fbox{III}, along with ensuring the term inside the square brackets \fbox{IV} is also non-positive. This will be our approach here. Future refinements can allow some positive values across the four terms as long as the overall sum remains non-positive.  

Note   $\frac12(\frac12 + \sqrt{\frac13}) + 1 \approx 1.5387$, $\sqrt{\frac16} + \sqrt{\frac13} + \frac12 \approx 1.48560$, and $\frac{13}{12} \approx 1.08333$ yield lower bounds on potential values of $C$ so that each respective term \fbox{I} through \fbox{III} is non-positive for all $n$. Hence, ensuring $C$ exceeds the maximum $\frac12(\frac12 + \sqrt{\frac13}) + 1$ then serves as a sufficient value to make sure all of these three terms  are non-positive. 

To further refine our choice of $C$, we can find the best bound to ensure the remaining term \fbox{IV} is non-positive. Using the inductive hypothesis for $b_n \le C a_n^2$ for all $n$, then 
\begin{equation*}
    b_n \le \sqrt{C} a_n \sqrt{b_n} \le C a_n^2.
\end{equation*}
It follows then the remaining term satisfies the bound
\begin{equation*}
    \fbox{IV} = \left(1 + \sqrt 2 - \frac{C}2\right) b_n-Ca_n^2 -(C-1)a_n \sqrt{2 b_n} \le f(C) \cdot  b_n
\end{equation*}
for $$f(x) = \sqrt 2 - \frac{x}2 - \sqrt {\frac 2x} \cdot (x-1).$$ We now show $f(x) \le 0$ iff $x \ge C^*$ for $C^*\approx 1.5601$ from \eqref{eq: C*}. This follows since $f'(x) < 0$ for $x > 0$ with $f(x) \to +\infty$ as $x \to 0+$ and $f(x) \to -\infty$ as $x \to \infty$ yields $f$ has a unique 0, which can be directly verified to be $C^*$ using Cardano's formula to keep the (unique) positive root of the associated cubic polynomial $yf(y^2)$ in $y = \sqrt x$ (and uniqueness for such a positive root follows from Descartes rule of signs). Hence, \fbox{IV} is non-positive if $C \ge C^*$. Since $1.5601 \approx C^*> \frac12(\frac12 + \sqrt{\frac13}) \approx 1.5387$, then this choice also ensures \fbox{I} through \fbox{III} are each non-positive. Applying this to \eqref{eq:ind upper bound} then yields $b_{n+1} \le C a_{n+1}^2$. This completes the inductive step.

\end{proof}


\Cref{l: bn<Can^2} now establishes $b_n \le C a_n^2$ for any $C \ge C^*$. In particular, this holds for $C = C^*$, which we will now assume to be the case going forward. Now we have
\begin{equation*}
    a_{n+1} = \lambda^n + a_n + \frac12 \sqrt{2 b_n} \le \lambda^n + \xi a_n, \qquad \xi=1 + \frac{\sqrt {2C^*}}2 =\frac12\left(1 + \sqrt 2 + \sqrt{2 \sqrt 2 - 1}\right)
    \approx 1.88320.
\end{equation*}
Solving the upper bound recursion $a_{n+1} \le \lambda^n + \xi a_n$ with $a_0 = 0$ yields the bound
\begin{equation}\label{eq:upper bound}
    \E H_n \le a_n \le  \frac{\xi^n-\lambda^n}{\xi - \lambda} .
    %\left(1 + \frac1{\xi - \lambda}\right)\xi^n - \frac{\lambda^n}{\xi - \lambda}, 
\end{equation}
Hence, noting $1.88320 \approx \xi>\lambda=1.5$, we have thus  the desired sub-linear upper bound
\begin{equation*}
    \E H_n \le d N^\beta \cdot (1 + o(1)), \qquad \beta = \log_2\xi \approx 0.913189, \qquad \quad 
    d = \frac1{\xi-\lambda}=\frac{2}{\sqrt{2C^*}-1} %= \frac2{\sqrt{2\sqrt 2-1} + \sqrt 2 - 1} 
    \approx 2.60958.
\end{equation*}
This  completes the proof of \Cref{thm: nsbt}.


