Similarly, we perform a second transformation by multiplying \( Y \) by \( W_{\text{col}} \):
\[
MC = YW_{\text{col}} \in \mathbb{R}^{(n+1)(m+1)}. 
\]

We then apply the column-wise softmax function to \( C \). For each column \( j \) in \( C \), the softmax is defined as:
\[
DC_{ij} = \frac{\exp(MC_{ij})}{\sum_{k=1}^{n} \exp(MC_{k,j})}, \quad \forall j \in \{1, \ldots, m+1\}.
\]

Finally, to ensure consistency in the allocation, we take the element-wise minimum of the two resulting matrices to obtain the final allocation matrix \( A \), where:
$$
A_{ij} = \min(DR_{ij}, DC_{ij}) ,\quad \forall i \in \{1, \ldots, n\}, j \in \{1, \ldots, m\}.
$$



In the \textbf{Payment Network}, to ensure that the auction satisfies ex-post IR, we generate normalized payments for each bundle corresponding to the retailer and supplier, denoted as \( \tilde{p}^i_{r} \) and \( \tilde{p}^i_{s} \in [0, 1] \). We employ an MLP with a Sigmoid activation function in the final layer to represent this mapping:
\[
\tilde{p} = \text{Sigmoid}(\text{MLP}(DB^E)) \in \mathbb{R}^{2n}.
\]

Subsequently, we derive the corresponding payments as follows:
\[
p^{e_i}_r = \tilde{p}^{e_i}_{r} \sum_{j=1}^{m} A_{ij} X_{r}[j],
\]
\[
p^{e_i}_s = \tilde{p}^{e_i}_{s} \sum_{j=1}^{m} A_{ij} X_{s}[j].
\]
Finally, we can determine the payment for each participating bidder in the advertising auction using the equations defined in Equation~\eqref{eq:p}.
\subsection{Optimization and Training}\label{Optimization and Training}

We optimize the constrained objective (\ref{optimize}) by introducing the augmented Lagrangian method. Our loss function is formulated as follows:
\begin{align*}
& \mathcal{L}_{\rho}(w; \mu) =\\
&-\frac{1}{L} \sum_{\ell=1}^{L} \sum_{e \in E} p^e(v^{(\ell)}) 
+ \sum_{e \in E} \mu_e \widehat{rgt}^e(w) 
+ \frac{\rho}{2} \sum_{e \in E} \left(\widehat{rgt}^e(w)\right)^2.
\end{align*}
% \begin{align*}
% & \mathcal{L}_{\rho}(w; \lambda) = \\
% &-\frac{1}{L} \sum_{\ell=1}^{L} \sum_{e \in E} p^e(v^{(\ell)}) + \sum_{e \in E} \lambda_e \widehat{r g t}^e(w) + \frac{\rho}{2} \sum_{e \in E} \left(\widehat{r g t}^e(w)\right)^2.
