\section{Optimization and Training Procedures}

\begin{algorithm}[h]
   \caption{BundleNet Training}
   \label{alg:BundleNet}
\begin{algorithmic}
\small
   \STATE {\bfseries Input:} Minibatches $\mathcal{B}_1, \ldots, \mathcal{B}_T$ of size $C$
   \STATE {\bfseries Parameters:} $\forall t, \rho_t > 0$, $\gamma > 0$, $\eta > 0$, $\Gamma \in \mathbb{N}$, $K \in \mathbb{N}$
   \STATE {\bfseries Initialize:} $w^0 \in \mathbb{R}^{d}, \lambda^0 \in \mathbb{R}^{m}$
   \FOR{$t=0$ {\bfseries to} $T$}
   \STATE Receive $\mathcal{B}_t = \{G^{(1)}, \ldots, G^{(B)}\}$
   \STATE Initialize $v_r^{'(\ell)} \in V_r, v_s^{'(\ell)} \in V_s, \forall \ell \in [B], r \in R, s \in S$
   \FOR{$r=0$ {\bfseries to} $\Gamma$}
   \FOR{$\ell=1$ {\bfseries to} $B$}
   \STATE $\forall \ell \in [C], i \in R \cup S:$
    \STATE \quad $v_i'^{(\ell)} \leftarrow v_i'^{(\ell)} + \gamma \nabla_{v_i'}[u_i^w(v_i^{(\ell)};(v_i', v_{-i}^{(\ell)}))]\big|_{v_i' = v_i'^{(\ell)}}$

   \ENDFOR
   \ENDFOR
   \STATE Compute Lagrangian gradient and update $w^t$
   \STATE $w^{t+1} \leftarrow w^{t} - \eta \nabla_{w} \mathcal{L}_{\rho_{t}}(w^{t}, \mu^{t})$
   \IF{$t$ is a multiple of $H$}
   \STATE $\mu_{e}^{t+1} \leftarrow \mu_{e}^{t} + \rho_t \widehat{rgt}^{e}(w^{t+1}), \forall e \in E$
   \ELSE
   \STATE $\boldsymbol{\lambda}^{t+1} \leftarrow \boldsymbol{\lambda}^t$
   \ENDIF
   \ENDFOR
\end{algorithmic}
\end{algorithm}
\section{Proof of Theorem \ref{thm:optimal_joint_auction}}\label{proof:optimal}

The joint auction with single slot remains a single-parameter auction, with the primary distinction from traditional auctions lying in the allocation and payment rules. As a result, the necessary and sufficient conditions for a feasible auction, as established in Myerson’s work \cite{myerson1981optimal}, still hold in this setting.Before presenting the proof, we first introduce an assumption: suppose \( a_i \) and \( b_i \) are the lower and upper bounds of the domain of the probability density function \( f_i \) for bidder \( i \). That is, \( v_i \in [a_i, b_i] \).
Given a joint auction mechanism, we define \( Q_i(v_i) \) as:
\[
Q_i(v_i) = \mathbb{E}_{\mathbf{v}_{-i} \sim F_{-i}} [x_i(v_i)] ,\quad \forall i \in R \cup S,
\]
where represents the expected probability that bidder \( i \) wins, given their value estimate \( v_i \).
\begin{lemma}[\cite{myerson1981optimal}]\label{IC}
    In the single-slot setting, a joint auction mechanism \( (x, p) \) is feasible if and only if the following conditions hold:
    \begin{itemize}
    \item[(a)] $\text{If }v_i^* \le v_i,\text{  then } Q_i(v_i^*) \le Q_i(v_i)  ,\quad \forall i \in R\cup S,v_i,v_i^*\in V_i $.
    \item[(b)] $U_i(v_i,v_i)=U_i(a_i,a_i)+\int_{a_i}^{v_i}Q(z)dz,\quad \forall i \in R\cup S $.
    \item[(c)] $U_i(v_i,v_i)\ge 0,\quad \forall i \in R\cup S$.
    \item[(d)] $\sum_{e \in  E}x^e(\mathbf{v})\le 1$,\quad $x^e(\mathbf{v})\ge 0$
\end{itemize}
\end{lemma}
\( \mathcal{M} = (x, p) \) is an optimal joint auction mechanism if and only if it maximizes \( U_0 \) while ensuring the feasibility of the auction.  We provide a simpler condition to characterize optimality.

\begin{lemma}\label{or1}
    Suppose that the function \( x: V \to 2^n \) maximizes the following objective:
\begin{equation}
    \begin{aligned}
        \max_{ \mathcal{M} } \quad & \int_{V} \sum_{e=(r,s)\in E} \left( v_r + v_s - \frac{1 - F_r(v_r)}{f_r(v_r)} - \frac{1 - F_s(v_s)}{f_s(v_s)} - v_0 \right) x^e(v) f(v) dv \\
        \text{s.t.} \quad & p_i(v) = v_i x_i(\mathbf{v}) - \int_{a_i}^{v_i} x_i(z, v_{-i}) dz, \quad \forall i \in R\cup S\\
        & \text{If }v_i^* \le v_i,\text{  then } Q_i(v_i^*) \le Q_i(v_i)  ,\quad \forall i \in R\cup S,v_i,v_i^*\in V_i,\\
        &\sum_{e \in  E}x^e(\mathbf{v})\le 1,\quad x^e(\mathbf{v})\ge 0
    \end{aligned}
\end{equation}

Then, the pair \(  \mathcal{M} = (x, p) \) represents an optimal joint auction.
\end{lemma}
\begin{proof}

To prove that the pair \( \mathcal{M} = (x, p) \) represents an optimal joint auction, we analyze the expected revenue function \( U_0 \) and show that it maximizes the given objective function while satisfying feasibility and incentive compatibility constraints.
The expected revenue \( U_0 \) is given by:
\begin{equation}\label{eq6}
    \begin{aligned}
        U_0 &= \mathbb{E}_{\mathbf{v} \sim F} \left[ v_0 \left( \mathbf{1} - \sum_{e \in E} x^e(\mathbf{v}) \right) + \sum_{e \in E} p^e(\mathbf{v}) \right],\\
        & = \int_{V} v_0f(v)dv +\sum_{e \in E}(\int_T[p_r^e(v)-v_rx_r^e(v)]f(v)dv +\int_V[p_s^e(v)-v_sx_s^e(v)]f(v)dv)\\
        &+\sum_{e \in E}\int_{V}x^e(v)(v_s+v_r-v_0)f(v)dv\\
    \end{aligned}
\end{equation}
Using the conclusion of Lemma \ref{IC}, we can simplify the following equation.
\begin{equation}\label{eq7}
    \begin{aligned}
        \sum_{e \in E}\int_V[p_r^e(v)-v_rx_r^e(v)]f(v)dv& =\sum_{r \in R}\int_V[p_r(v)-v_rx_r(v)]f(v)dv\\
& = -\sum_{r \in R}\int_{a_r}^{b_r}[U_r(v_r,v_r)]f_r(v_r)dv_r\\
& = -\sum_{r \in R}\int_{a_r}^{b_r}[U_r(a_r,a_r)+\int_{a_r}^{v_r}Q_r(z)dz]f_r(v_r)dv_r\\
& = -\sum_{r \in R}[U_r(a_r,a_r)+\int_{a_r}^{b_r}\int_{z}^{b_r}Q_r(z)f_r(v_r)dv_rdz]\\
& = -\sum_{r \in R}[U_r(a_r,a_r)+\int_{a_r}^{b_r}(1-F_r(z))Q_r(z)dz]\\
& = -\sum_{r \in R}[U_r(a_r,a_r)+\int_{a_r}^{b_r}(1-F_r(v_r))x_r(v_r)f_{-r}(v_{-r})dv]\\
& = -\sum_{e \in E}[U_r^e(a_r,a_r)+\int_{a_r}^{b_r}(1-F_r(v_r))x_r^e(v_r)f_{-r}(v_{-r})dv]\\
    \end{aligned}
\end{equation}
Substituting Equation \ref{eq7} into Equation \ref{eq6} gives us:
\begin{equation}\label{eq8}
    \begin{aligned}
        U_0 = &\int_{V} v_0f(v)dv+\sum_{e=(r,s) \in E}\int_{V}x^e(v)(v_s+v_r-\frac{1-F_r(v_r)}{f_r(v_r)}-\frac{1-F_s(v_s)}{f_s(v_s)}-v_0)f(v)dv\\
        +&\sum_{r \in R}U_r(a_r,a_r)+\sum_{s \in S}U_s(a_s,a_s)\\
    \end{aligned}
\end{equation}
The first term in Equation \ref{eq8} is a constant, while the third and fourth terms are always non-negative due to the IR property of the auction. When these terms are equal to zero, the objective function reaches its maximum value without affecting the value of the first and second terms. Thus, by setting the third and fourth terms to zero, we obtain:
\begin{equation}\label{eq9}
    \begin{aligned}
        p_r(v)=v_rx_r(v)-\int_{a_r}^{v_{r}}x_r(z,v_{-r})dz\\
    p_s(v) =v_sx_s(v)-\int_{a_s}^{v_s}x_s(z,v_{-s})dz\\
    \end{aligned}
\end{equation}

\end{proof}

Next, we proceed with the proof of Theorem \ref{thm:optimal_joint_auction}:
\begin{proof}[Proof of Theorem \ref{thm:optimal_joint_auction}]
In this paper, we consider distributions that are regular. Since distributions in the regular class ensure the monotonicity required by Lemma \ref{or1}, they guarantee the IC property of the joint auction. As a result, we can simplify the objective function as follows:
$$
\sum_{e=(r,s) \in E}(c^e(v_r,v_s)-v_0)x^e(v)
$$
This implicitly indicates that the slot will be allocated to the bundle with the highest virtual value. For a single-slot joint auction, each bidder's bidding strategy depends solely on the neighbor node with the highest virtual value. This is because any bundle formed with other neighbors has no chance of winning the auction. Therefore, for each bidder, their critical value is given by:
\begin{itemize}
        \item For \( i \in R \), the critical value \(\hat{v}_r(v_{-r})\) is:
        \[
        \hat{v}_r(v_{-r}) = \inf\left\{ b_r \mid c^{e_r^M}(b_r, v_{s_r^M}) \geq v_0, \text{ and } c^{e_r^M}(b_r, v_{s_r^M}) \geq c^{\hat{e}}(v_{\hat{r}}, v_{\hat{s}}), \forall \hat{e}=(\hat{r},\hat{s}) \in E_{-r} \right\}
        \]

        \item For \( i \in S \), the critical value \(\hat{v}_s(v_{-s})\) is similarly:
        \[
        \hat{v}_s(v_{-s}) = \inf\{b_s|c^{e_s^M}(v_{r_s^M},b_{s})\ge v_0,\text{ and } c^{e_s^M}(v_{r_s^M},b_{s})\ge c^{\hat{e}}(v_{\hat{r}}, v_{\hat{s}}),\forall \hat{e}=(\hat{r},\hat{s}) \in E_{-s}\}
        \]
    \end{itemize}
We take a node \( r \in R \) as an example. The allocation of all bundles connected to \( r \) is given by:

\[
x^{e_r^M}(b_r, v_{-r}) = 
\begin{cases} 
1 & \text{if } b_r \geq \hat{v}_r(v_{-r}) \\
0 & \text{if } b_r < \hat{v}_r(v_{-r})
\end{cases}
\]
\[
x^{e^*}(b_r, v_{-r})= 0, \quad \forall e^* \in E_r \setminus \{e_r^M\}
\]

Thus, we can derive the allocation result for \( r \) as follows:
\[
x_r(b_r,v_{-r}) = x^{e_r^M}(b_r,v_{-r})+\sum_{e^*\in E_r/\{e_r^M\}}x^{e^*}(b_r,v_{-r})=\begin{cases} 
1 & \text{if } b_r \geq \hat{v}_r(v_{-r}) \\
0 & \text{if } b_r < \hat{v}_r(v_{-r})\\
\end{cases}\\
\]
We can derive the final payment result by solving the payment formula based on the Equation \ref{eq9}. We integrate the allocation rule to determine the payment function. Thus, the final payment for bidder \( r \) is given by:

\[
p_r(b_r,v_{-r}) = \begin{cases}z_r(v_{-r}) & \text{if } b_r \geq \hat{v}_r(v_{-r}) \\0 & \text{if } b_r < \hat{v}_r(v_{-r})\\\end{cases}\
\]

For a node \( s \in S \), the conclusion follows similarly. The allocation and payment rules apply symmetrically due to the structure of the joint auction mechanism, where each participant's strategy depends on their highest virtual value neighbor.  

Thus, the proof is complete. 


\end{proof}
