\section{Proof of Lemma \ref{lemma}}\label{proof:lemma}
\begin{proof}
    \begin{small}
    \begin{equation}
    \begin{aligned}
        \sum_{i \in R\cup S}rgt_i&=\sum_{i \in R\cup S} \mathbb{E}_{v \sim F} \left[ \max_{v'_i \in V_i} u_i(v_i; (v'_i, v_{-i}); w) - u_i(v_i; (v_i, v_{-i}); w) \right]\\
        &= \sum_{r \in R} \mathbb{E}_{v \sim F} \left[ \max_{v'_r \in V_r} u_r(v_r; (v'_r, v_{-r}); w) - u_r(v_r; (v_r, v_{-r}); w) \right]\\
        &+\sum_{s \in S} \mathbb{E}_{v \sim F} \left[ \max_{v'_s \in V_s} u_s(v_s; (v'_s, v_{-s}); w) - u_s(v_s; (v_s, v_{-s}); w) \right]\\
        &= \sum_{r \in R} \mathbb{E}_{v \sim F} \left[ \max_{v'_r \in V_r} \sum_{e \in E_r} u_r^e(v_r; (v'_r, v_{-r}); w) - \sum_{e \in E_r}u_r^e(v_r; (v_r, v_{-r}); w) \right]\\
        &+\sum_{s \in S} \mathbb{E}_{v \sim F} \left[ \max_{v'_s \in V_s} \sum_{e \in E_s} u_s^e(v_s; (v'_s, v_{-s}); w) - \sum_{e \in E_s}u_s^e(v_s; (v_s, v_{-s}); w) \right]\\
        &\le \sum_{e \in E} \mathbb{E}_{v \sim F} \left[ \max_{v'_r \in V_r} u_r^e(v_r; (v'_r, v_{-r}); w) - u_r^e(v_r; (v_r, v_{-r}); w) \right]\\
        &+\sum_{e \in E} \mathbb{E}_{v \sim F} \left[ \max_{v'_s \in V_s} u_s^e(v_s; (v'_s, v_{-s}); w) - u_s^e(v_s; (v_s, v_{-s}); w) \right]\\
        &= \sum_{e=(r,s)\in E} rgt^e(w) 
    \end{aligned}
\end{equation}
\end{small}
\end{proof}


