\section{Algebraic structure generated by curved Dunkl momenta on $\bS^N$  and   $\bH^N$ with Dunkl angular momenta and reflection operators}
\label{AA}

 \noindent 
 Let us consider the set of   $N(N-1)/2+N+N=N(N+3)/2$ quantum operators   $\big\{\hat{\Lambda}_{ij} , \hat{R}_i, \hat{\Gamma}_i^{(\kappa)}\big\}$ with $1\le i<j\le   N$,  formed by  the $N(N-1)/2$ Dunkl angular momenta (\ref{eq:angmomdunkl}), $N$ reflections (\ref{reflections}) along with the   $N$ curved  Dunkl momenta (\ref{eq:operator}). For the sake of completeness, we recall  their explicit realization:
 \be
\begin{aligned}
\hat{\Lambda}_{ij} &   = \hx_i \hpi_j - \hx_j \hpi_i \, ,  \quad \hr_i\Psi(\bx) =\Psi(\sigma_i (\bx))  \\[2pt]
\hat{\Gamma}_i^{(\kappa)}&=\big(1-\kappa \hbx^2\big)\hpi_i+2 \kappa  \hat{x}_i \left((\hbx \cdot \hbpi)-\imath \hbar \sum_{j=1 }^N \mu_j \hat{R}_j\right)\, ,
 \end{aligned}
 \label{A1}
\ee
where  $\kappa$ is the curvature of $N$D sphere $\bS^N$ and hyperbolic space  $\bH^N$. It can be shown that these  $N(N+3)/2$ operators close on a quadratic algebra with commutation relations given by
\begin{align}
 \big[\hat{\Lambda}_{ij}, \hat{\Lambda}_{kl} \big]&  =\imath \hbar \left(\delta_{ik}\big(\hat{\mathds{1}}+2\mu_k \hr_k \big) \hat{\Lambda}_{jl}+\delta_{jl}\big(\hat{\mathds{1}}+2\mu_l \hr_l \big) \hat{\Lambda}_{ik}-\delta_{il}\big(\hat{\mathds{1}}+2\mu_i \hr_i \big) \hat{\Lambda}_{jk}-\delta_{jk}\big(\hat{\mathds{1}}+2\mu_j \hr_j \big) \hat{\Lambda}_{il}\right) \label{A2} \\[2pt]
\big[ \hat{\Lambda}_{ij} ,\hat{\Gamma}_k^{(\kappa)} \big] &=\imath \hbar \left( \delta_{ik}\big(\hat{\mathds{1}}+2\mu_i\hat{R}_i \big)\hat{\Gamma}_j^{(\kappa)} - \delta_{jk} \big(\hat{\mathds{1}}+2\mu_j\hat{R}_j \big)\hat{\Gamma}_i^{(\kappa)}\right)\label{A3}\\[2pt]
\big[\hat{\Gamma}_i^{(\kappa)}, \hat{\Gamma}_j^{(\kappa)} \big]&=4 \imath \hbar \kappa \hat{\Lambda}_{ij} \label{A4} \\[2pt]
 \big[\hat{\Gamma}_i^{(\kappa)}, \hr_{j} \big]&=2 \delta_{ij}\hat{\Gamma}_j^{(\kappa)} \hr_{j} \label{A5} \\[2pt]
 \big[\hat{\Lambda}_{ij}, \hr_{k} \big]&=2 \delta_{ik}\hat{\Lambda}_{ij}\hr_k+2 \delta_{jk}\hat{\Lambda}_{ik}\hr_j \label{A6}\\[2pt]
 \big[ \hr_{i}, \hr_{j} \big]&=0 \, . \label{A7}
\end{align}
The non-zero commutators  in (\ref{A5}) and  (\ref{A6}) can alternatively be expressed in terms of anticommutators (see Remark~\ref{rem1}):
\be
\begin{aligned}
\big\{ \hat{\Gamma}_i^{(\kappa)}, \hr_i  \big\}&= 0 \, , \quad   \big[\hat{\Gamma}_i^{(\kappa)}, \hr_{j} \big] =0\, , \quad i\ne j \\[2pt]
\big\{ \hat{\Lambda}_{ij}, \hr_i  \big\}&=\big\{ \hat{\Lambda}_{ij},\hr_j  \big\}=0\, , \quad \big[ \hat{\Lambda}_{ij} ,\hr_k \big]=0\, ,\quad i\ne j\ne k\, .
\end{aligned}
\label{A8}
 \ee 

 \noindent The striking point is that the commutators (\ref{A2})--(\ref{A4}) show that the $N$ operators $\hat{\Gamma}_i^{(\kappa)}$ are proper (curved) momenta on $\bS^N$ and  $\bH^N$. In fact, 
 in the reflection-free  situation, all the commutators (\ref{A2})--(\ref{A7})   simply reduce  to
 \begin{align}
 \big[\hat{\Lambda}_{ij}, \hat{\Lambda}_{kl} \big]&  =\imath \hbar \left(\delta_{ik} \hat{\Lambda}_{jl}+\delta_{jl}  \hat{\Lambda}_{ik}
 -\delta_{il}  \hat{\Lambda}_{jk}-\delta_{jk} \hat{\Lambda}_{il}\right) \nonumber \\[2pt]
  \big[ \hat{\Lambda}_{ij} ,\hat{\Gamma}_k^{(\kappa)} \big] &=\imath \hbar \left( \delta_{ik} \hat{\Gamma}_j^{(\kappa)} - \delta_{jk} \hat{\Gamma}_i^{(\kappa)}\right)\label{A9}\\[2pt]
\big[\hat{\Gamma}_i^{(\kappa)}, \hat{\Gamma}_j^{(\kappa)} \big]&=4 \imath \hbar \kappa \hat{\Lambda}_{ij}   \, ,
\nonumber
\end{align}
which determine the Lie algebra $\mathfrak{so}(N+1)$ for $\kappa>0$, $\mathfrak{so}(N,1)$ for $\kappa<0$, and the (inhomogeneous) Euclidean algebra $\mathfrak{e}(N)\equiv \mathfrak{iso}(N)$ when $
\kappa=0$. Recall that, in this algebraic context, the curvature $\kappa$  plays the role of a graded contraction parameter coming from the $\mathbb Z_2$-grading of (\ref{A9}), provided by the following involutive automorphism (see, e.g.,~\cite{BHSZG} for details) 
\be
\Theta\big(\hat{\Lambda}_{ij},\hat{\Gamma}_i^{(\kappa)}  \big)\to \big(\hat{\Lambda}_{ij},-\hat{\Gamma}_i^{(\kappa)}  \big)\, ,\quad \forall i, j\, .
  \ee
  The change of the sign of $\kappa$ in (\ref{A9}) entails a change of real form of the Lie algebra, while    $\kappa=0$ corresponds to an In\"on\"u--Wigner contraction, which  in this case  leads to the contraction around the origin in the underlying space,  $\bS^N\rightarrow \bE^N\leftarrow \bH^N$. Hence, 
   the set of these three Lie algebras is denoted $\mathfrak{so}_\kappa(N+1)$. Likewise, the automorphism $\Theta$ can be extended to cover the complete quadratic algebra (\ref{A2})--(\ref{A7})
 as
 \be
\Theta\big(\hat{\Lambda}_{ij},\hat{\Gamma}_i^{(\kappa)} ,\hr_i \big)\to \big(\hat{\Lambda}_{ij},-\hat{\Gamma}_i^{(\kappa)}  ,\hr_i \big) \, ,\quad \forall i, j\, ,
 \ee
  and, consistently, the curvature  $\kappa$ only appears in the commutators (\ref{A4}), which  are therefore the only ones that vanish under the flat contraction $\kappa=0$. As far as the realization  (\ref{A1})  is concerned, the curved momenta (\ref{A1}) collapse to the usual (flat) Dunkl momenta $\hat{\Gamma}_i^{(0)}=\hpi_i$.


\noindent Consequently,  by taking into account the  discussion above and  the
    notation introduced in \cite{Ghaz2021} for the subalgebra spanned by the $N(N+1)$ operators  $ \hat{\Lambda}_{ij} $ and $ \hat{R}_i$, we denote by
 \be
 \mathfrak{so}_{\kappa}^{\mu_1, \dots, \mu_N}(N+1):=\mathfrak{so}_{\kappa}\big(N+1; \mu_1 \hat{R}_1, \dots,  \mu_N \hat{R}_N\big) 
 \label{A12}
 \ee
the family of the three quadratic algebras  (\ref{A2})--(\ref{A7}), thus comprising the spherical $(\kappa>0)$, Euclidean $(\kappa=0)$ and hyperbolic cases $(\kappa<0)$, namely
\begin{align}
&\mathfrak{so}_{+}^{\mu_1, \dots, \mu_N}(N+1):=\mathfrak{so}\big(N+1; \mu_1 \hat{R}_1, \dots,  \mu_N \hat{R}_N \big) \nonumber  \\
&\mathfrak{so}_{0}^{\mu_1, \dots, \mu_N}(N):=\mathfrak{e}\big(N; \mu_1 \hat{R}_1, \dots,  \mu_N \hat{R}_N \big)  \label{A13}\\
 &\mathfrak{so}_{-}^{\mu_1, \dots, \mu_N}(N,1):=\mathfrak{so} \big(N,1; \mu_1 \hat{R}_1, \dots,  \mu_N \hat{R}_N \big)  \, .
 \nonumber
\end{align}
Then, the quadratic algebra (\ref{A12}) is an extension by reflections of the  $N(N+1)/2$-dimensional Lie algebra $\mathfrak{so}_{\kappa}(N+1)$ (\ref{A9}). Finally, note that the three particular cases (\ref{A13}) contain the same  $N(N+1)/2$-dimensional subalgebra  $\mathfrak{so}\big(N, \mu_1 \hr_1, \dots, \mu_N  \hr_N\big)$  in \cite{Ghaz2021}, 
 fulfilling the commutation rules (\ref{A2}),  (\ref{A6}) and  (\ref{A7}).




