\subsubsection*{Pseudocode of INR algorithm}

% \textbf{Pseudocode of INR algorithm}: Complete code and scripts necessary to reproduce the results shown in the manuscript can be obtained from the public repository listed under the Data Availability section.

% Add some text here that references the Algorithm table. 

\begin{algorithm}[H]
    \caption{INR Interpolation Pipeline for Brain Gene Expression Analysis}
    \begin{algorithmic}[1]
    \Require $\mathbf{A}$: Allen Human Brain Atlas data
    \Require $\mathbf{G} = \{g_1, g_2, ..., g_k\}$: Set of AD-related gene names
    \Function{GenerateEmbeddings}{$\mathbf{G}$}
        \State $c \gets$ ClassifyMatter($\mathbf{G}$) \Comment{$c \in \{-1, 0, 1\}$}
        \State $\phi \gets$ ComputeSpectralEmbedding($\mathbf{G}$) \Comment{$\phi \in \mathbb{R}^d$} 
        \State $\mathbf{f} \gets$ $[c; \phi]$ \Comment{Feature concatenation}
        \State \Return $\mathbf{f}$
    \EndFunction
    \Function{PreprocessData}{$\mathbf{A}, \mathbf{G}$}
        \State $\mathbf{X} \in \mathbb{R}^{k \times n}$ $\gets$ FilterGenes($\mathbf{A}, \mathbf{G}$) \Comment{n $\approx$ 62000 probes}
        \State $\mathbf{X} \gets$ NormalizeData($\mathbf{G}, \mathbf{X}$)
        \State $\mathbf{X} \gets$ GenerateEmbeddings($\mathbf{X}$)
        \State \Return $\mathbf{X}$
    \EndFunction

    \Function{Training}{$\mathbf{X}$}
        \State $\theta \gets$ InitializeParameters() \Comment{Neural network parameters}
        \State $L \gets 0$ \Comment{Loss initialization}
        \For{$t = 1$ to $T$} \Comment{Training iterations}
            \ForAll{$\mathbf{x} \in \mathbf{X}$} \Comment{$\mathbf{R}$: set of brain regions}
                \State $\mathbf{e} \gets$ PositionalEmbedding($\mathbf{x}$)
                \State $(x, y, z, c, \phi, \mathbf{e}) \gets \mathbf{x}$ \Comment{$\mathbf{e}$: embedding features}
                \State $v_{true} \gets$ GetActualGeneExpression($\mathbf{x}$)
                \State $v_{pred} \gets \text{INR}_\theta(\mathbf{x})$ \Comment{Forward pass}
                \State $L \gets L + \|v_{pred} - v_{true}\|_2^2$
            \EndFor
            \State $\theta \gets \theta - \eta\nabla_\theta L$ \Comment{Parameter update}
        \EndFor
        \State \Return $\text{INR}_\theta$
    \EndFunction

    \Function{Inference}{$\text{INR}_\theta, c, \phi$}
        \State $X, Y, Z \gets$ NiftiShape() \Comment{Get 3D volume dimensions}
        \State $V \gets \text{zeros}(X, Y, Z)$ \Comment{Initialize output volume}
        \For{$x = 1$ to $X$}
            \For{$y = 1$ to $Y$}
                \For{$z = 1$ to $Z$}
                    \State $\mathbf{e} \gets$ PositionalEmbedding($x, y, z$)
                    \State $\mathbf{x} \gets [x, y, z, c, \phi, \mathbf{e}]$ \Comment{Construct input feature}
                    \State $v \gets \text{INR}_\theta(\mathbf{x})$ \Comment{Predict gene expression}
                    \State $V[x,y,z] \gets v$ \Comment{Store prediction}
                \EndFor
            \EndFor
        \EndFor
        \State \Return $V$ \Comment{Return 3D volume of gene expression values}
    \EndFunction

    \Procedure{Main}{}
        \State $\mathbf{X} \gets$ PreprocessData($\mathbf{A}, \mathbf{G}$)
        \State $\text{INR}_\theta \gets$ Training($\mathbf{X}$)
        \For{$g$ in $\mathbf{G}$}
            \State $V_g \gets$ Inference($\text{INR}_\theta, \phi_g, c$)
        \EndFor
    \EndProcedure
    \end{algorithmic}
\label{algo:flow}
\end{algorithm}

\end{samepage}

