\section{Preliminaries}\label{sec:2}

Let $(R,\frakm,\Bbbk)$ be a local ring and $M$ a finitely generated $R$-module.  It is known that any two minimal sets of generators of $M$ have the same cardinality, as can also be seen in the following version of Nakayama's lemma.

\begin{lemma}\label{lem:NAK}(Nakayama's lemma)
    Elements $m_1,\dots, m_q$ of $M$, for some integer $q$, form a part of a minimal set of generators  of $M$ if and only if their images $\overline{m_1},\dots, \overline{m_q}$ in $M/\frakm M$ are linearly independent over $R/\frakm=\Bbbk$.
\end{lemma}

Therefore, the number of minimal generators of $M$, which we denote by $\mu_R(M)$, is well-defined. This version of Nakayama's lemma is not the popular one, but is the version we need, as we will only construct parts of a minimal free resolution of $M$, i.e., we will need to show that certain sets of elements form a part of a minimal set of generators of the syzygy modules.

A \emph{free resolution} of $M$ over $R$ is a complex of $R$-modules 
\[
\mathcal{F}\colon \cdots \to F_n\xrightarrow{\partial_n} F_{n-1}\to \cdots \to F_1\xrightarrow{\partial_1} F_0\xrightarrow{\partial_0} M\xrightarrow{\partial_{-1}}   0
\]
where $F_i$ is a free $R$-module and $\ker \partial_{i-1} = \im \partial_{i}$ for any $i\geq 0$. Moreover, $\mathcal{F}$ is called \emph{minimal} if $\partial_i(F_i)\subseteq \frakm F_{i-1}$ for any $i\geq 1$. The module $\Omega_i(M)\coloneqq \im \partial_i=\ker \partial_{i-1}$, for each $i\geq 0$, is called the \emph{$i$-th syzygy module} of $M$. Note that $\Omega_0(M)=M$. 

Let $\calF$ be a minimal free resolution of $M$. The numbers $\beta_i^R(M)\coloneqq \rank F_i$, where $i\geq 0$, are called the \emph{betti numbers} of $M$ (over $R$). The length of the minimal free resolution of $M$, denoted by $\pd_RM\coloneqq \sup\{i\in \mathbb{Z}\colon F_i\neq 0\}$, is called the \emph{projective dimension} of $M$ (over $R$).

We recall the inductive process to construct a minimal free resolution of $M$ as follows:
\begin{enumerate}
    \item[\textbf{Step 1:}] set $i=0$ and $\partial_{-1}\colon M\to 0$;
    \item[\textbf{Step 2:}] take a minimal set of generators of $\Omega_i(M)$, and construct the $R$-modules homomorphism $\phi_i\colon F_i\coloneqq R^{\mu_R(\Omega_i(M))}\twoheadrightarrow  \Omega_i(M)$ that maps the standard basis of  $F_i$ to the considered minimal set of generators of $\Omega_i(M)$ correspondingly; let $\partial_i$ denote the composition $F_i\xtwoheadrightarrow{\phi_i} \Omega_i(M)\hookrightarrow F_{i-1}$ (here $F_{-1}\coloneqq M$);
    \item[\textbf{Step 3:}] if $\ker \partial_i\neq 0$, set $i=i+1$.
\end{enumerate}
The output is a minimal free resolution of $M$. 
\begin{remark}\label{rem:syzygies}
    \begin{enumerate}
        \item In Step 2, any minimal set of generators of $\Omega_i(M)$ would work. In other words, one can manipulate this set of generators of $\Omega_i(M)$, and in turn, the representation matrices of the differentials in the minimal free resolution of $M$.
        \item For any integers $n,i\geq 0, r\geq 1$, we have $\bI_{n+i}^r(M)=\bI_{n}^r(\Omega_i(M))$. This follows from the inductive nature of the process.
    \end{enumerate}
\end{remark}


\section{Proof of Main Theorem}\label{sec:3}

We recall the explicit characterization of artinian stretched Goresntein rings by Sally.

\begin{theorem}[\protect{\cite[Corollary 1.2]{Sal79}}]\label{thm:Sally}
    Let $(S,\mathfrak n)$ be a regular local ring of dimension $e\geq 2$. Assume that $\characteristic S/\mathfrak n\neq 2$ and $R=S/I$ is an artinian stretched Gorenstein ring, where $I\subseteq \mathfrak{n}^2$. Then 
    \[
    R\cong S/(z_iz_j,yz_i,y^k-u_iz_i^2\colon i,j\in [e-1], i\neq j)
    \]
    where $\mathfrak{n}=(y,z_1,\dots, z_{e-1})$ and the $u_i$ are units in $S$.
\end{theorem}

For the rest of the article, $(R,\frakm,\Bbbk)$ denotes the artinian stretched Gorenstein ring as in Theorem~\ref{thm:Sally}. We will still refer to  Theorem~\ref{thm:Sally} in the statements of our results for completion. 

\begin{remark}\label{rem:properties}
    Let $(R,\frakm,\Bbbk)$ be an artinian stretched Gorenstein ring as in Theorem~\ref{thm:Sally}. The following are straightforward, thus we will state them without proofs:
    \begin{enumerate}
        \item $\edim(R)=\edim(S)=e$ and $\frakm=(y,z_1,\dots, z_{e-1})$, or more precisely, its image in $R$ (here $\edim$ denotes the embedding dimension);
        \item $\frakm^i= (y^i)$ for any $i\geq 2$; in particular, $\frakm^i$ is nonzero if and only if $i\in [2,k]$;
        \item $\length_R(R) = e+k$.
    \end{enumerate}
\end{remark}

The hard part of the Main Theorem is when $e\geq 3$, which we prove separately. Before doing so, we need a small lemma.

\begin{lemma}\label{lem:starting-gen}
    Let $(R,\frakm,\Bbbk)$ be an artinian stretched Gorenstein ring as in Theorem~\ref{thm:Sally} and assume that $e\geq 3$. Let $M$ be a finitely generated $R$-module such that $\pd_R M =\infty$. Then there exists a minimal generator $f$ of $\Omega_{\mu_R(M)}(M)$ such that $z_1f=0$.
\end{lemma}

\begin{proof}
    Set $n=\mu_R(M)$. Since $R$ is artinian, by \cite[Proposition~2.2]{GP90}, we have
    \begin{align*}
        \beta_{n+1}^R(M)&\geq (2e-\length_R(R)+k-1)\beta_n^R(M)\\
        &= (e-1)\beta_n^R(M) \tag{Remark~\ref{rem:properties} (3)}\\
        &\geq 2\beta_n^R(M) \\
        &> \beta_n^R(M). \tag{$\pd_R(M)=\infty$}
    \end{align*}
    Let $A$ be the representation matrix, using standard bases, of $\partial_{n+1}\colon F_{n+1}\to F_n$ in a minimal free resolution $(F,\partial)$ of $M$. Observe that $\dim_{\Bbbk} \frakm F_n/(y,z_1^2,z_2,\dots, z_{e-1})F_n = \rank F_n$ (a possible basis is $(z_1,0,\dots,0),(0,z_1,\dots, 0),\dots, (0,0,\dots, z_1)$). Thus, using a change of the basis of $F_n$, we can assume that the last 
    \[\rank F_{n+1}-\rank F_n=\beta_{n+1}^R(M)-\beta_{n}^R(M) >0\]
    columns of $A$ are zeros in $R/(y_1,z_1^2,z_2,\dots, z_{e-1})$, i.e., those entries are in $(y_1,z_1^2,z_2,\dots, z_{e-1})$. Now consider the element $f\coloneqq \partial_{n+1}((0,\dots, 0,1)^T)$. This is a minimal generator of $M$ since $(F,\partial)$ is a minimal resolution. Finally, we have
    \[
    z_1f = z_1A(0,\dots, 0,1)^T=z_1\bv\in z_1(y,z_1^2,z_2,\dots, z_{e-1})F_{n}=(0),
    \]
    as desired, where $\bv$ denotes the last column of $A$.
\end{proof}

\begin{proposition}\label{prop:e>=3}
    Let $(R,\frakm,\Bbbk)$ be an artinian stretched Gorenstein ring as in Theorem~\ref{thm:Sally} and assume that $e\geq 3$. Then for any finitely generated $R$-module $M$ and any integer $r\geq 1$, we have \[
    \bI^r_n(M)=\begin{cases}
        \frakm^r &\text{if }\pd_RM=\infty,\\
        0 &\text{otherwise.}
    \end{cases}
    \]for $n\gg 0$.
\end{proposition}

\begin{proof}
    The result follows trivially if $\pd_R(M)$ is finite. Thus we can assume that $\pd_R(M)=\infty$. By Remark~\ref{rem:syzygies} (2), without loss of generality, we can replace $M$ with $\Omega_{\mu(M)}(M)$, and therefore by Lemma~\ref{lem:starting-gen}, we can assume that there exists a minimal generator $f$ of $M$ such that $z_1f=0$.  

    We have the following claim.

    \begin{claim}\label{clm:syzygies}
        One can construct a minimal free resolution $(F,\partial)$ of $M$ such  that for any $n\geq 3$, the set
        \[
        \{y\be_{n,i_1},z_1\be_{n,i_2},z_2\be_{n,i_3}\colon i_1\in [1,2\times 2^{n-3}], i_2\in (2^{n-3},3\times 2^{n-3}], i_3\in [1,2^{n-3}]\cup (2\times 2^{n-3},3\times 2^{n-3}] \}
        \]
        is a part of a minimal set of generators of $\Omega_{n+1}(M)$, where $\{\be_{n,1},\dots, \be_{n,\beta_n(M)}\}$ is the standard basis of $F_n$. In particular, this means that $\beta_n(M)\geq 3\times 2^{n-3}$.
    \end{claim}
    Assume the claim. Let $n$ be an integer such that $2^{n-2}\geq r$. Then Claim~\ref{clm:syzygies} implies that the representation matrix of $\partial_n\colon F_n\to F_{n-1}$ using their standard bases contains $y\mathbf{Id}_{r\times r}$ as a submatrix,  where $\mathbf{Id}_{r\times r}$ denotes the $r\times r$ identity matrix. Thus $y^r\in \bI_{n}^r(M) \subseteq \frakm^r = (y^r)$ where the last equality is by Remark~\ref{rem:properties} (2). This concludes the proof.
\end{proof}

\begin{proof}[Proof of Claim~\ref{clm:syzygies}]
    First we inspect the first syzygy module $\Omega_1(M)$. Let $\partial_0\colon F_0\coloneqq R^{\beta_0(M)}\twoheadrightarrow \Omega_0(M)=M$ be a surjective map where $\partial_0(\be_1)=f$, where $\{\be_{0,1},\dots. \be_{0,\beta_0^R(M)}\}$ is the standard basis of $F_0$. We then have $\Omega_1(M)=\ker \partial_0$. Since $\partial_0(z_1\be_{0,1})=z_1f=0$, we have $z_1\be_{0,1}\in \Omega_1(M)$. Moreover, since $z_1\be_{0,1}\notin\frakm^2F_0$ and $\Omega_1(M)\subseteq \frakm F_0$, we have $z_1\be_{0,1}\notin\frakm \Omega_1(M)$. By Lemma~\ref{lem:NAK}, $z_1\be_{0,1}$ is a minimal generator of $\Omega_1(M)$. 

    Next, we inspect the syzygy module $\Omega_2(M)$. Let $\partial_1\colon F_1\coloneqq R^{\beta_1^R(M)}\to F_0$ be a map onto $\Omega_1(M)$ where $\partial_1(\be_{1,1})=z_1\be_{0,1}$, such that $\{\be_{1,1},\dots. \be_{1,\beta_1^R(M)}\}$ is the standard basis of $F_1$. Then $\Omega_2(M)=\ker \partial_1$.  By similar arguments to those for $\Omega_1(M)$, we have that $y\be_{1,1}$ and $z_2\be_{1,1}$ are in $\Omega_2(M)\setminus \frakm \Omega_2(M)$. Moreover, these two elements are linear independent over $\Bbbk$ by the structure of $R$ in Theorem~\ref{thm:Sally}. By Lemma~\ref{lem:NAK}, $\{y\be_{1,1},z_2\be_{1,1}\}$ is part of a minimal set of generators of $\Omega_2(M)$.

    Next, we inspect the syzygy module $\Omega_3(M)$. Let $\partial_2\colon F_2\coloneqq R^{\beta_2^R(M)}\to F_1$ be a map onto $\Omega_2(M)$ such that $\partial_2(\be_{2,1})=z_2\be_{1,1}$ and $\partial_2(\be_{2,2})=y\be_{1,1}$, where $\{\be_{2,1},\dots. \be_{2,\beta_2^R(M)}\}$ is the standard basis of $F_2$. Then $\Omega_3(M)=\ker \partial_2$.  By similar arguments to those for $\Omega_2(M)$, the set $\{y\be_{2,1},z_1\be_{2,1},z_2\be_{2,2}\}$  is part of a minimal set of generators of $\Omega_3(M)$.

    We now know enough about syzygy modules of $M$ to continue inductively, which is the nature of the claim.  Let $\partial_3\colon F_3\coloneqq R^{\beta_3^R(M)}\to F_2$ be a map onto $\Omega_3(M)$ such that
    \begin{align*}
        \partial_{3}(\be_{3,1})&=z_1\be_{2,1},\\    
        \partial_{3}(\be_{3,2})&=z_2\be_{2,2},\\    
        \partial_{3}(\be_{3,3})&=y\be_{2,1},    
    \end{align*}
    where $\{\be_{3,1},\dots. \be_{3,\beta_3^R(M)}\}$ is the standard basis of $F_3$. Then $\Omega_4(M)=\ker \partial_3$.  By similar arguments to those for $\Omega_2(M)$, the set \[
    \{y\be_{3,1},\ y\be_{3,2},\ z_1\be_{3,2},\ z_1\be_{3,3},\ z_2\be_{3,1},\ z_2\be_{3,3}\}\]
    is part of a minimal set of generators of $\Omega_4(M)$. This confirms the base case $n=3$. Now assume that $n>3$. By induction, we can assume that
    \begin{multline*}
        \{y\be_{n-1,i_1},z_1\be_{n-1,i_2},z_2\be_{n-1,i_3}\colon i_1\in [1,2\times 2^{n-4}], i_2\in (2^{n-4},3\times 2^{n-4}], \\
        i_3\in [1,2^{n-4}]\cup (2\times 2^{n-4},3\times 2^{n-4}] \}
    \end{multline*}
    is a part of a minimal set of generators of $\Omega_{n}(M)$. Let $\partial_n\colon F_n\coloneqq R^{\beta_n^R(M)}\to F_{n-1}$ be a map onto $\Omega_n(M)$ such that
    \begin{align*}
        \partial_{n}(\be_{n,i_1})&=z_1\be_{n-1,i_1+2^{n-4}}, \text{for each } i_1\in [1,2^{n-3}],\\    
        \partial_{n}(\be_{n,i_2})&=\begin{cases}
            z_2\be_{n-1,i_2-2^{n-3}} \text{ if } i_2\leq 2^{n-3}+2^{n-4}\\
            z_2\be_{n-1,i_2-2^{n-4}} \text{ otherwise}
        \end{cases}, \text{for each } i_2\in (2^{n-3},2\times 2^{n-3}],\\    
        \partial_{n}(\be_{n,i_3})&=y\be_{n-1,i_3-2^{n-2}}, \text{for each } i_3\in (2\times 2^{n-3},3\times 2^{n-3}].   
    \end{align*}
    Then $\Omega_{n+1}(M)=\ker \partial_n$.  By similar arguments to those for $\Omega_2(M)$, the set
    \[
        \{y\be_{n,i_1},z_1\be_{n,i_2},z_2\be_{n,i_3}\colon i_1\in [1,2\times 2^{n-3}], i_2\in (2^{n-3},3\times 2^{n-3}], i_3\in [1,2^{n-3}]\cup (2\times 2^{n-3},3\times 2^{n-3}] \}
    \]
    is a part of a minimal set of generators of $\Omega_{n+1}(M)$. This concludes the proof.
\end{proof}

We are now in a position to prove Theorem~\ref{thm:main}.

\begin{proof}[Proof of Theorem~\ref{thm:main}]
    If $\edim(R)\leq 2$, then $R$ is either a Golod ring or a complete intersection (\cite{Scheja64}, see also, \cite[Proposition 5.3.4]{infinite}). In fact, in this case $R$ must be a complete intersection as Gorenstein + Golod = hypersurface (see, e.g., \cite[page 47]{infinite}). The result then follows from \cite[Theorem 1.2]{BDS25}. Now we can assume that $\edim(R)\geq 3$. The result then follows from Proposition~\ref{prop:e>=3}.
\end{proof}

