	\section{Proof of Theorem~\ref{Theorem:UB-fresh}} \label{proof:theorem-1}
	The proof is a simple modification of method used by \cite{bansal2015} to derive upper bounds in this setting. Let $x_t$ and $x_t^{OPT}$ represent the actions chosen by A-OBD$(\delta_1)$ and OPT, respectively, at time $t$. Define the potential function as $\phi(x_t,x_t^{OPT}):=\gamma|x_t-x_t^{OPT}|$.   
	Define $\mathcal{H}_t:=f_t(x_t)$ and $\mathcal{H}_t^{OPT}:=f_t(x_t^{OPT})$, $\mathcal{M}_t:=|x_t-x_{t-1}|$ and $\mathcal{M}_t^{OPT}:=|x_t^{OPT}-x_{t-1}^{OPT}|$, and $\Delta\phi_t:=\phi(x_t,x_t^{OPT})-\phi(x_{t-1}, x_{t-1}^{OPT})$.\\	
	By applying the triangle inequality, the following two inequalities are obtained.
	\begin{equation}
		\begin{gathered}
			\begin{aligned}
				\phi(x_{t-1},x_{t}^{OPT})-\phi(x_{t-1},x_{t-1}^{OPT}) \leq \gamma|x_t^{OPT}-x_{t-1}^{OPT}|
				\label{ineq:i1}
			\end{aligned}
		\end{gathered}
	\end{equation}

	\begin{equation}
		\begin{gathered}
			\begin{aligned}
				\phi(x_{t},x_{t}^{OPT})-\phi(x_{t-1},x_{t}^{OPT}) \leq \gamma|x_t-x_{t-1}|
				\label{ineq:i2}
			\end{aligned}
		\end{gathered}
	\end{equation}
	Combining inequalities \eqref{ineq:i1} and \eqref{ineq:i2}, we derive the following bound for $\Delta \phi_t$.
	\begin{equation}
		\begin{gathered}
			\begin{aligned}
				\Delta \phi_t \leq \gamma \mathcal{M}_t + \gamma \mathcal{M}_t^{OPT}
				\label{ineq:delphi_gen}
			\end{aligned}
		\end{gathered}
	\end{equation}
