			\begin{aligned}
				\mathcal{H}_t+\mathcal{M}_t+\Delta \phi_t &\stackrel{(d)}\leq \mathcal{H}_t + \frac{\mathcal{H}_t}{\delta}+\Delta \phi_t\\
				&\stackrel{(e)}\leq \mathcal{H}_t \left(1+\frac{1}{\delta}\right)+\gamma \mathcal{M}_t + \gamma \mathcal{M}_t^{OPT}\\
				&\stackrel{(f)}\leq \mathcal{H}_t^{OPT}\left(1+\frac{1}{\delta}+\frac{\gamma}{\delta}\right)+\gamma \mathcal{M}_t^{OPT}\\
				&\leq \max \left\{\left(1+\frac{1}{\delta}+\frac{\gamma}{\delta}\right),\gamma\right\}\left(\mathcal{H}_t^{OPT}+\mathcal{M}_t^{OPT}\right)
			\end{aligned}
		\end{gathered}
	\end{equation}
	where (d) follows from Lemma \ref{lemma:lb-cost}, (e) is derived using \eqref{ineq:delphi_gen} obtained above, and (f) holds because \( \mathcal{H}_t \leq \mathcal{H}_t^{OPT} \).\\
	Combining the bounds derived for both cases, we have
	\begin{equation}\nonumber
		\begin{gathered}
			\begin{aligned}
				\mathcal{H}_t + \mathcal{M}_t + \Delta \phi_t \leq \max\left\{\delta + 1 + \frac{M}{2}, 2 + \frac{2}{\delta} + \frac{M}{2\delta}\right\}(\mathcal{H}_t^{OPT} + \mathcal{M}_t^{OPT}). \label{eq:ub-fresh}
			\end{aligned}
		\end{gathered}
	\end{equation} 
	Finally, noting that \( \sum_{t=1}^T \Delta \phi_t \geq 0 \), we establish an upper bound on the competitive ratio as follows. $C_{\text{A-OBD}(\delta_1)}$
	\begin{equation}\nonumber
		\begin{gathered}
			\begin{aligned}
				&= \sum_{t=1}^T \left(\mathcal{H}_t + \mathcal{M}_t\right) \\
				&\leq \sum_{t=1}^T \left(\mathcal{H}_t + \mathcal{M}_t + \Delta \phi_t\right) \\
				&\stackrel{\eqref{eq:ub-fresh}}\leq \sum_{t=1}^T \max\left\{\delta + 1 + \frac{M}{2}, 2 + \frac{2}{\delta} + \frac{M}{2\delta}\right\} \left(\mathcal{H}_t^{OPT} + \mathcal{M}_t^{OPT}\right) \\
				&= \max\left\{\delta + 1 + \frac{M}{2}, 2 + \frac{2}{\delta} + \frac{M}{2\delta}\right\} \sum_{t=1}^T \left(\mathcal{H}_t^{OPT} + \mathcal{M}_t^{OPT}\right) \\
				&= \max\left\{\delta + 1 + \frac{M}{2}, 2 + \frac{2}{\delta} + \frac{M}{2\delta}\right\} C_{OPT}.
			\end{aligned}\
		\end{gathered}
	\end{equation}

	Hence, the competitive ratio is bounded by
	\begin{align*}
		\mu_{\text{A-OBD}(\delta_1)} \leq \max\left\{\delta + 1 + \frac{M}{2}, 2 + \frac{2}{\delta} + \frac{M}{2\delta}\right\}.
	\end{align*}
	We can now obtain an optimal choice of  $\delta$  to minimize the derived upper bound. Choosing  $\delta = {\hat \delta} = \frac{1}{2} \sqrt{\left(\frac{M}{2} + 1\right)^2 + 7} - \frac{M}{4} + \frac{1}{2}$ gives us the following result.
	\begin{equation}\nonumber
		\begin{gathered}
			\begin{aligned}
				\mu_{\text{A-OBD}( {\hat \delta} )} \leq \frac{M}{4}+\frac{3}{2}+\frac{1}{2}\sqrt{\left(\frac{M}{2}+1\right)^2+7}.
			\end{aligned}
		\end{gathered}
	\end{equation}
	This completes the proof of Theorem \ref{Theorem:UB-fresh}.

