			&\stackrel{\eqref{eq:ub-stale}}\leq \sum_{t=1}^T \max \left\{ \delta + L + 1 + \frac{M}{2}, 2 + \frac{2(L+1)}{\delta} + \frac{M}{2\delta} \right\} \left(\mathcal{H}_t^{OPT} + \mathcal{M}_t^{OPT}\right) \\
			&= \max \left\{ \delta + L + 1 + \frac{M}{2}, 2 + \frac{2(L+1)}{\delta} + \frac{M}{2\delta} \right\} \sum_{t=1}^T \left(\mathcal{H}_t^{OPT} + \mathcal{M}_t^{OPT}\right) \\
			&= \max \left\{ \delta + L + 1 + \frac{M}{2}, 2 + \frac{2(L+1)}{\delta} + \frac{M}{2\delta} \right\} C_{OPT}.
		\end{aligned}
