	This completes the proof of Theorem \ref{Theorem:UB-stale}.

	\section{Rationale behind A\ref{asm:a4}} \label{sec:a4}
    Assumption \ref{asm:a4} requires that the noise tolerance $\alpha$ is strictly less than the magnitude of the true gradient, i.e., $\alpha < |\nabla_t|$. This condition ensures that $\nabla_t^{avl}$ reflects the correct descent direction for $f_t$. If $\alpha$ were to exceed $|\nabla_t|$, the noise could be large enough to reverse the intended update direction. In such a case, the noisy gradient could point away from the optimum causing the algorithm to update in the opposite direction and increase \ref{eq:total-cost}. By imposing $\alpha < |\nabla_t|$, we ensure that the deviation introduced by the noise is bounded, so that even in extreme scenario, $\nabla_t^{avl}$ remains aligned with $\nabla_t$. This guarantees that the algorithm consistently moves in a direction of minimizing \ref{eq:total-cost}.

	\section{Proof of Theorem~\ref{Theorem:UB-noisy} }\label{proof:Theorem-4} 
	Theorem \ref{Theorem:UB-noisy} establishes an upper bound on the competitive ratio for \ALGone ($\delta_t$) when the gradient information($\nabla_t^{avl}$) is noisy. We cannot use the same method as Appendix~\ref{proof:theorem-1} because Lemma~\ref{lemma:lb-cost}, \ref{lemma:ub-cost} do not hold necessarily. Hence, we derive new bounds $\hat{a} \mathcal{M}_t \leq \mathcal{H}_t \leq \hat{b} \mathcal{M}_t$ for some $\hat{a},\hat{b}>0.$ Our approach is to use extremal cases ($\nabla=\nabla_t - \alpha, \nabla_t + \alpha$) to obtain the values of $\hat{a},\hat{b}$ for any noisy gradient such that $|\nabla_t^{avl}-\nabla_{t}|\leq \alpha.$


	%[XXX: why are you writing Algorithm definition again as a subroutine. We wont have that much space. Use the definition of Algorithm]
	%\hs{The way we have defined the algorithm, it directly outputs using the function and gradient information. So need to define this kind of subroutine.}
	\begin{algorithm}[H]  
	\caption{Subroutine({$f^{\text{val}}, \nabla, \hat{x}, \delta$})} \label{alg:subroutine-AOBD}
	\begin{algorithmic}[1]
		\Function{Subroutine}{$f^{\text{val}}, \nabla, \hat{x}, \delta$}
		\State $L_1(x) \gets f^{\text{val}} + \nabla \cdot (x - \hat{x})$ 
		\State $L_2(x) \gets \delta \cdot \text{sign}(-\nabla) \cdot (x - \hat{x})$ 
		\State Find $x$ such that $L_1(x) = L_2(x)$ 
		\State \Return $x$ 
		\EndFunction
	\end{algorithmic}
	\end{algorithm}
	Let $x_t^{true}$ be the output of Subroutine({$f_t^{\text{avl}}, \nabla_t, x_{t-1}, \delta_t$}) with the choice of $\delta_t$ specified in the statement of Theorem~\ref{Theorem:UB-noisy}.

	Define $\underline{\nabla_t} := \nabla_t - \alpha, \overline{\nabla}_t := \nabla_t + \alpha$. Let $\underline{x_t}, \overline{x_t}$ be the output of Subroutine({$f_t^{\text{avl}}, \nabla, x_{t-1}, \delta_t$}) with $\nabla=\underline{\nabla_t},\overline{\nabla}_t$ as the input respectively with same $\delta_t$ as specified in Theorem~\ref{Theorem:UB-noisy}. We similarly define hitting and switching cost associated with $\underline{x_t},\overline{x_t}$ as $(\underline{\mathcal{H}_t}, \underline{\mathcal{M}_t})$ and $(\overline{\mathcal{H}_t}, \overline{\mathcal{M}_t})$ respectively.

	We will take $\sign(\nabla_{t})<0$ (similar proof can be done for $\sign(\nabla_{t})>0$). The sign of $\nabla_t$ determines the direction of movement of $x_t$ relative to $x_{t-1}$. Specifically $x_{t-1} \leq x_t \leq x_t^*$ when  $\nabla_t < 0,$ and $x_{t-1} \geq x_t \geq x_t^*$ when $\nabla_t > 0.$ For simplicity, we take $\nabla_t = |\nabla_t|$ and omit the absolute value notation throughout the analysis.

    From the above definitions, the following is immediate
	\begin{align}
	\underline{\mathcal{M}_t} &\leq \mathcal{M}_t \leq \overline{\mathcal{M}_t}, \label{ineq:UB-LB-Mt} \\
	\overline{\mathcal{H}_t}  &\leq \mathcal{H}_t \leq  \underline{\mathcal{H}_t}. \label{ineq:UB-LB-Ht}
	\end{align}
	%	Suppose there exist $a,b>0$ such that $\underline{\mathcal{H}_t} \leq b\underline{\mathcal{M}_t}$ and $\overline{\mathcal{H}_t} \geq a\overline{\mathcal{M}_t}$, we get the following bounds on $\mathcal{H}_t$.
	%	$$a\overline{\mathcal{M}_t} \leq \mathcal{H}_t \leq  b\underline{\mathcal{M}_t} \\ \Rightarrow a \mathcal{M}_t \leq \mathcal{H}_t \leq b \mathcal{M}_t.$$
	%	
	%	Our next step is to determine the values of $a$ and $b$.\\ From \eqref{eq:ulbhtmt}, we get
	%	%As the $\nabla_t$ also lies in between $(\underline{\nabla},\overline{\nabla})$ we have the following.
	%	\begin{equation}\nonumber
	%		\begin{gathered}
		%			\begin{aligned}
			%				%\underline{\mathcal{M}_t} &\leq \mathcal{M}_t^{true} \leq \overline{\mathcal{M}_t}\\ 
			%				%\overline{\mathcal{H}_t} &\leq \mathcal{H}_t^{true} \leq \underline{\mathcal{H}_t}\\
			%				\overline{\mathcal{H}_t} &\leq \left(\delta + \frac{M}{2}\right)\mathcal{M}_t^{true} \leq \left(\delta + \frac{M}{2}\right)\overline{\mathcal{M}_t}\\
			%				\Rightarrow \underline{\mathcal{H}_t} &\geq \delta \mathcal{M}_t^{true} \geq \delta \underline{\mathcal{M}_t}
			%			\end{aligned}
		%		\end{gathered}
	%	\end{equation}
	We can express the values of $\underline{\mathcal{M}_t},\overline{\mathcal{M}_t}$ using their definition in terms of $\mathcal{M}_t^{true},\nabla_{t},\delta_{t}$ and $\alpha,$ as shown below 
	\begin{equation}
	\overline{\mathcal{M}_t} = \mathcal{M}_t^{true} \frac{|\nabla_t|+\delta_t}{|\nabla_t|-\alpha+\delta_t}
	\label{eq:Mupline}
	\end{equation}
	\begin{equation}
	\underline{\mathcal{M}_t} = \mathcal{M}_t^{true} \frac{|\nabla_t|+\delta_t}{|\nabla_t|+\alpha+\delta_t}.
	\label{eq:Mundline}
	\end{equation}
	% \begin{remark} The sign of $\nabla_t$ determines the direction of movement of $x_t$ relative to $x_{t-1}$. Specifically, $x_t$ moves to the right [XXX: can you not say towards $x^\star$ or something more precise?] if $\nabla_t < 0$ and to the left if $\nabla_t > 0$. In this case we consider $\nabla_t < 0$. For simplicity, we take $\nabla_t = |\nabla_t|$ and omit the absolute value notation throughout the analysis.
	% \end{remark}
	\begin{lemma} \label{lemma:overline-UB}
	Lower bound of $\overline{\mathcal{H}_t}$ in terms of $\overline{\mathcal{M}_t}$ is given by the following
	\begin{equation}
		\overline{\mathcal{H}_t} \geq \left(\delta_t-\frac{\alpha L}{\nabla_t+\delta_t-\alpha}\right)
		\left(\frac{\nabla_t+\delta_t-\alpha}{\nabla_t+\delta_t}\right)\overline{\mathcal{M}_t}
	\end{equation}
	\end{lemma}
	\begin{proof}
	Using $L$-Lipschitzness of $f_t$ from  A.\ref{asm:a2} we get
	\begin{equation} \nonumber
		\begin{split}
			|f_t(x_{true})-f_t(\overline{x_t})| &\leq L|x_{true}-\overline{x_t}| \\ 
			\Rightarrow \mathcal{H}_t^{true} - \overline{\mathcal{H}_t} &\stackrel{(a)}\leq L\frac{\alpha \mathcal{M}_t^{true}}{\nabla_t+\delta_t-\alpha}\\
			\Rightarrow \overline{\mathcal{H}_t} &\geq \mathcal{H}_t^{true} - L\frac{\alpha \mathcal{M}_t^{true}}{\nabla_t+\delta_t-\alpha} \\
			&\stackrel{(b)}\geq \delta_t \mathcal{M}_t^{true} - \frac{\alpha L \mathcal{M}_t^{true}}{\nabla_t+\delta_t-\alpha} \\
			&\stackrel{\ref{eq:Mupline}}\geq \left(\delta_t-\frac{\alpha L}{\nabla_t+\delta_t-\alpha}\right)
			\left(\frac{\nabla_t+\delta_t-\alpha}{\nabla_t+\delta_t}\right)\overline{\mathcal{M}_t} 
		\end{split} 
	\end{equation}
	where (a) follows from \eqref{eq:Mupline} since $|x_t^{true}-\overline{x_t}|=\overline{\mathcal{M}_t}-\mathcal{M}_t^{true}$ and (b) follows from Lemma \ref{lemma:lb-cost}.
	\end{proof}

	\begin{lemma} \label{lemma:underline-LB}
	Lower bound of $\underline{\mathcal{H}_t}$ in terms of $\underline{\mathcal{M}_t}$ is given by the following
	\begin{equation*}
		\underline{\mathcal{H}_t} \leq \left(\delta_t+ \frac{M}{2}+\frac{\alpha L}{\nabla_t+\delta_t+\alpha}\right) \left(\frac{\nabla_t+\delta_t+\alpha}{\nabla_t+\delta_t}\right)\underline{\mathcal{M}_t}.
	\end{equation*}
	\end{lemma}
	\begin{proof}
	Using $L$-Lipschitzness of $f_t$ from A.\ref{asm:a2} we get $|f_t(x_{true})-f_t(\underline{x_t})| \leq L|x_{true}-\underline{x_t}|$
	\begin{equation} \nonumber
		\begin{gathered}
			\begin{aligned}
				\Rightarrow \underline{\mathcal{H}_t} - \mathcal{H}_t^{true} &\stackrel{(a)}\leq L\frac{\alpha \mathcal{M}_t^{true}}{\nabla_t+\delta_t+\alpha}\\
				\Rightarrow \underline{\mathcal{H}_t} &\leq \mathcal{H}_t^{true} + L\frac{\alpha \mathcal{M}_t^{true}}{\nabla_t+\delta_t+\alpha}\\
				&\stackrel{(b)}\leq \left(\delta_t + \frac{M}{2}\right)\mathcal{M}_t^{true} + \frac{\alpha L \mathcal{M}_t^{true}}{\nabla_t+\delta_t+\alpha}\\
				&\stackrel{(\ref{eq:Mundline})}\leq \left(\delta_t+ \frac{M}{2}+\frac{\alpha L}{\nabla_t+\delta_t+\alpha}\right) \left(\frac{\nabla_t+\delta_t+\alpha}{\nabla_t+\delta_t}\right)\underline{\mathcal{M}_t},
			\end{aligned}
		\end{gathered}
	\end{equation}
	where (a) follows from \eqref{eq:Mundline} because $|x_t^{true}-\overline{x_t}|=\mathcal{M}_t^{true}-\underline{\mathcal{M}_t}$ and (b) follows from Lemma \ref{lemma:ub-cost}.
	\end{proof}

	\begin{lemma}\label{lemma:received-LB-noisy}
	Under  A\ref{asm:a2} and A\ref{asm:a4}, $\mathcal{H}_t$ and $\mathcal{M}_t$ satisfies
	\begin{equation}\nonumber
		\begin{gathered}
			\begin{aligned}
				\mathcal{H}_t \geq \left(\delta_t - \frac{\alpha L}{\nabla_t+\delta_{t}-\alpha}\right)\left(\frac{\nabla_t+\delta_{t}-\alpha}{\nabla_t+\delta_{t}}\right)\mathcal{M}_t
			\end{aligned}
		\end{gathered}
	\end{equation}
	\end{lemma}
	\begin{proof} From inequalities \eqref{ineq:UB-LB-Mt} and \eqref{ineq:UB-LB-Ht}, we know that $\overline{\mathcal{M}_t} \geq \mathcal{M}_t$ and $\mathcal{H}_t \geq \overline{\mathcal{H}_t}$. Substituting these bounds into Lemma~\ref{lemma:overline-UB}, we obtain the desired result. 
	\end{proof}

	\begin{lemma}\label{lemma:received-UB-noisy}
	Under  A\ref{asm:a2} and A\ref{asm:a4}, $\mathcal{H}_t$ and $\mathcal{M}_t$ satisfies
	\begin{equation}\nonumber
		\begin{gathered}
			\begin{aligned}
				\mathcal{H}_t \leq \left(\delta_t + \frac{M}{2} + \frac{\alpha L}{\nabla_t+\delta_{t}+\alpha}\right)\left(\frac{\nabla_t+\delta_{t}+\alpha}{\nabla_t+\delta_{t}}\right)\mathcal{M}_t.
			\end{aligned}
		\end{gathered}
	\end{equation}
	%where, $\underline{\mathcal{H}_t}$ and $\underline{\mathcal{M}_t}$ are the hitting and movement cost incurred when $\underline{\nabla} = \nabla_t-\alpha$ is received by the algorithm.
	\end{lemma}
	\begin{proof} From  \eqref{ineq:UB-LB-Mt} and \eqref{ineq:UB-LB-Ht}, we know that $\underline{\mathcal{M}_t} \leq \mathcal{M}_t$ and $\mathcal{H}_t \leq \underline{\mathcal{H}_t}$. Substituting these bounds into Lemma~\ref{lemma:underline-LB}, we obtain the desired result. 
	\end{proof}

	In this noisy gradient setting, Lemmas \ref{lemma:received-LB-noisy} and \ref{lemma:received-UB-noisy} are analogues to Lemma \ref{lemma:lb-cost} and \ref{lemma:ub-cost} in the fresh gradient setting respectively. Using  Lemmas \ref{lemma:received-LB-noisy}, \ref{lemma:received-UB-noisy} we can derive our required $a,b$ as described above. However this choice of $a,b$ depends on $\nabla_{t}$ or the true gradient value whose quantity is unknown to the algorithm. We can remove this dependence by using the inequality $\nabla_{t}^{avl}-\alpha \leq \nabla_{t} \leq \nabla_{t}^{avl}+\alpha$ which is shown below. 
	\begin{lemma}\label{lemma:noisy-bounds}
	In the noisy fresh gradient setting, $\mathcal{H}_t$ and $\mathcal{M}_t$ satisfies : $a\mathcal{M}_t \leq \mathcal{H}_t \leq b\mathcal{M}_t$
	% [XXX: is this for underline or overline $M_t, H_t$????]
	where,
	\begin{equation}\nonumber
		\begin{gathered}
			\begin{aligned}
				a &=  \left(\delta_t - \frac{\alpha L}{\nabla_{t}^{avl}+\delta_{t}-2\alpha}\right)\left(1-\frac{\alpha}{\nabla_{t}^{avl}+\delta_{t}-\alpha}\right)\\
				b &= \left(\delta_t + \frac{M}{2} + \frac{\alpha L}{\nabla_{t}^{avl}+\delta_{t}}\right)\left(1+\frac{\alpha}{\nabla_{t}^{avl}+\delta_{t}-\alpha}\right)
			\end{aligned}
		\end{gathered}
	\end{equation}
	\end{lemma}

	% Note that $a,b$ are not constant terms, rather are dependent on $\delta_t$ and $\nabla_t^{avl}$. We observe that the $\nabla_{t}^{avl}$ in the denominator of $a,b$ always appears in additive relation with $\delta_{t}.$ If we choose $\nabla_{t}+\delta_{t}=\beta$ where $\beta$ is a constant, we can remove the dependence of $\nabla_t$ in the denominator. For the $\delta_{t}$ terms in numerator which can be written as $\beta-\nabla_{t}^{avl},$ we can use assumption~\ref{asm:a3}, \ref{asm:a4} to prove our Theorem~\ref{Theorem:UB-stale}.  
	% \hs{Will finish the below part afterwards.}
    \begin{proof}
    Combining Lemma~\ref{lemma:received-LB-noisy},\ref{lemma:received-UB-noisy} we obtain
	\begin{equation} 
    \left(\delta_t - \frac{\alpha L} {\nabla_t+\delta_t-\alpha}\right) \left(1-\frac{\alpha}{\nabla_t+\delta_t}\right)\mathcal{M}_t 
    \leq \mathcal{H}_t \nonumber \\ \leq 
    \left(\delta_t+ \frac{M}{2}+\frac{\alpha L}{\nabla_t +\delta_t+\alpha}\right) \left(1+\frac{\alpha}{\nabla_t+\delta_t}\right)\mathcal{M}_t \label{eq:noisy_grad}
\end{equation}
	Using $\nabla_t^{avl}-\alpha \leq \nabla_t \leq \nabla_t^{avl}+\alpha$ we can write \eqref{eq:noisy_grad} as
	\begin{equation}
				\left(\delta_t-\frac{\alpha L} {\nabla_t^{avl}+\delta_t-2\alpha}\right) \left(1 - \frac{\alpha}{\nabla_t^{avl}+\delta_t-\alpha}\right)\mathcal{M}_t \leq \mathcal{H}_t \nonumber \\ \leq \left(\delta_t+ \frac{M}{2}+\frac{\alpha L}{\nabla_t^{avl} +\delta_t}\right) \left(1+\frac{\alpha} {\nabla_t^{avl}+\delta_t-\alpha}\right)\mathcal{M}_t
				\label{eq:noisy_grad1}
	\end{equation}
    This completes the proof of Lemma~\ref{lemma:noisy-bounds}
    \end{proof}
	%	\hs{Write the above as a theorem}\\
\vspace{-0.15in}
    \begin{remark}[Choice of $\delta_t$]\label{remark:beta}
		We note that constants $a,b$ depend on both $\delta_t$ and $\nabla_t^{avl}$. In particular, the term $\nabla_t^{avl}$ appears additively with $\delta_t$ in the denominators of $a,b$. This is problematic as $\nabla_t^{avl}$ is controlled by the adversary, making any bounds depending on it non-robust. To eliminate this dependence, we choose $\delta_t$ such that $\nabla_{t}+\delta_{t}=\beta$ ($\beta$ is a constant), equivalently we set $\delta_t = G +L  - \nabla_t^{avl}$. Although this substitution induces $\delta_t$-dependent terms in the numerator of $a,b$. We can simplify these constants $a,b$ further by writing $\delta_t$ as $\beta - \nabla_t^{avl}$ and use assumptions A \ref{asm:a3} and A \ref{asm:a4} to obtain simplified bounds for $\mathcal{H}_t$.
	\end{remark}

    Combining the Lemma~\ref{lemma:noisy-bounds} with above mentioned choice of $\delta_t$ we obtain these new bounds  
	\begin{equation}
    \hat{a}\mathcal{M}_t \leq \mathcal{H}_t \leq \hat{b}\mathcal{M}_t \label{eq:new-ab} \\
		\hat{a} =	\left(L-\frac{\alpha L} {G+L-2\alpha}\right) \left(1-\frac{\alpha}{G+L-\alpha}\right) \nonumber\\
            \hat{b} =  \left(G+L+ \frac{M}{2}+\frac{\alpha L}{G+L}\right) \left(1+\frac{\alpha}{G+L-\alpha}\right) \nonumber
	\end{equation}

    Next, we use the same potential function method as in previous settings, with the key modification being the use of bounds from \eqref{eq:new-ab} that account for gradient noise. By employing this method, we establish that an upper bound on competitive ratio is given by
	$\mu_{\text{A-OBD}(\delta_t)} \leq \max\left\{1+\frac{2+\hat{b}}{\hat{a}}, 1+\hat{b}\right\},$
    where the constants $\hat{a}$ and $\hat{b}$ are defined as in \eqref{eq:new-ab}. This completes the proof of Theorem \ref{Theorem:UB-noisy}.
